  -- ---------------------------------------------------------------
  -- Introdução  (aula ordem = 2)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 2;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Introdução$t$,
      2,
$conteudo$Em tempos de reavivamento da Igreja, obtém-se claramente um enriquecimento nas Escrituras Sagradas.

Por detrás dos apelos cotidianos e das palavras de ordem, necessários no debate eclesiástico, surge uma busca mais decidida a respeito do único a quem realmente importa encontrar, a saber, o próprio Jesus. O

que Jesus quis nos dizer? O que espera de nós hoje? Como ele nos ajuda a sermos cristãos fiéis em nosso tempo? Para nós, é menos importante o que requer este ou aquele indivíduo da Igreja, mas sim o que deseja Jesus, é isso o que queremos saber. Quando vamos ao culto e ouvimos a pregação, é a palavra de Jesus que queremos ouvir — e não apenas por nosso próprio interesse, mas por causa dos muitos para os quais a Igreja e sua mensagem se tornaram estranhas. Também somos da opinião de que, se o próprio Jesus, e somente ele com sua palavra, estivesse entre nós no momento da pregação, seriam outras pessoas as que ouviriam a palavra, e outras ainda que, por sua vez, a evitariam. Não é que a pregação de nossa Igreja não seja mais a Palavra de Deus, mas que som estranho é esse! Quantas leis humanas e duras, quantas falsas esperanças e consolos enganosos continuam a turvar a mensagem cristalina de Jesus, dificultando assim a verdadeira decisão! Não se pode simplesmente culpar aqueles que consideram nossa pregação, que certamente deseja ser apenas a pregação de Cristo, dura e difícil de compreender, sobrecarregada de formas e conceitos que lhes são estranhos. Contudo, não é verdade que toda palavra que hoje se levanta contra nossa pregação seja já uma negação de Cristo, isto é, anticristianismo. Será que, de fato, queremos negar a comunhão àqueles que atualmente vêm em grande número à nossa pregação, que desejam ouvi-la e muitas vezes têm de reconhecer, tristes, que nós lhes dificultamos o acesso a Jesus? Eles não acham que seja da palavra do próprio Jesus que desejem se esquivar, mas que entre eles e Jesus existem demasiadas interferências humanas, institucionais e doutrinárias. Quem de nós já não teria de imediato à mão todas as respostas a serem dadas nesse contexto, com as quais se eximiria facilmente da responsabilidade por todas aquelas pessoas? Não seria também uma resposta, se nos perguntássemos se não somos nós mesmos que dificultamos o caminho a Jesus apegando-nos excessivamente a determinadas formulações ligadas a certo tipo de sermão próprio apenas para sua época, seu lugar e sua estrutura social, pregando de forma demasiado dogmática e pouco orientada à vida, proclamando alegre e repetidamente certos pensamentos das Escrituras e, com isso, propagando nossas próprias opiniões e convicções e pouco de Jesus Cristo? Não haveria nada mais profundamente contrário à nossa intenção e, ao mesmo tempo, mais prejudicial à nossa mensagem que sobrecarregar com leis pesadas os cansados e oprimidos que Jesus chama a ele, afastando-os dele mais uma vez. Como o amor de Jesus Cristo seria, dessa forma, achincalhado por cristãos e pagãos! Uma vez que, nesse caso, de

nada ajudam questionamentos generalizados ou autoacusações, voltemos para as Escrituras, para a Palavra e para o chamado do próprio Jesus Cristo. Neles buscamos, a partir da pobreza e da insignificância de nossas convicções e questionamentos, a riqueza e o esplendor que nos são dados em Jesus.

Queremos falar do chamado para ser discípulo de Jesus. Será que assim não sobrecarregamos o ser humano com um jugo novo e ainda mais pesado? Acaso acrescentaremos a todas essas leis, sob as quais já sofrem a alma e o corpo, outras ainda mais duras e implacáveis? Desferiremos, partindo da lembrança do discipulado de Jesus, um golpe ainda mais agudo na consciência ferida e inquieta? Não estaríamos instituindo exigências estranhas, dolorosas e impossíveis como as já tantas vezes aplicadas na história da Igreja, cuja obediência provavelmente seria um luxo piedoso para poucos, mas que seria rejeitada como impiedosa tentação divina por aqueles que têm de cuidar da família, que trabalham por seu pão exercendo sua profissão? Deve a Igreja colocar um jugo de tirania espiritual sobre o ser humano, com o qual impõe e ordena autoritariamente em que ele deve crer e o que deve fazer a fim de ser salvo, e isso tudo sob a ameaça de punição terrena e eterna? Trará a mensagem da Igreja nova tirania e violência às almas? Pode até ser que algumas pessoas anseiem por tal servidão. Mas deveria a Igreja algum dia atender a essa exigência?

Quando as Escrituras Sagradas tratam do discipulado de Jesus, proclamam a libertação do ser humano de todos os preceitos humanos, de tudo que o oprime, de tudo que o sobrecarrega, de tudo que lhe suscita preocupação e dor na consciência. No discipulado, o ser humano deixa o duro jugo de suas próprias leis e vai para o jugo suave de Jesus Cristo. Não está se questionando, com isso, a seriedade do mandamento de Jesus? De maneira nenhuma. É somente na permanência total no mandamento de Jesus, no chamado ao discipulado incondicional, que se torna possível a plena libertação para a comunhão com Jesus. Quem segue integralmente o mandamento de Jesus, quem se permite sem relutância o jugo de Jesus, para esse o fardo a carregar torna-se leve e recebe, na suave pressão desse jugo, a força para percorrer o caminho certo com tranquilidade. O mandamento de Jesus é duro, implacavelmente duro para quem se opõe a ele.

Porém, o mandamento de Jesus é suave e leve para aquele que se lhe submete de bom grado. “Os seus mandamentos não são penosos” (1Jo 5.3) O mandamento de Jesus não consiste em um tipo de tratamento de choque emocional. Jesus nada nos exige sem nos dar a força para fazê-lo. Seu mandamento não visa jamais destruir a vida, mas conservá-la, fortalecê-la e curá-la.

Continuamos, todavia, a nos preocupar com a questão: o que poderia significar o chamado ao discipulado de Jesus para o trabalhador, para o comerciante, para o agricultor, para o soldado? Não se trata, afinal, de uma distância insuperável entre a existência do indivíduo como trabalhador, inserido no mundo, e sua existência como cristão? O cristianismo do discipulado de Jesus não seria algo para um número demasiado restrito de pessoas? Não significaria um afastamento da grande massa, o desprezo aos fracos e pobres? Com isso não estaria sendo negada justamente a grande misericórdia de Jesus Cristo, que veio para os pecadores e publicanos, para os pobres e fracos, para os loucos e desesperados? O que diremos quanto a isso? São poucos ou muitos os que pertencem a Jesus? Ele morreu na cruz, sozinho, abandonado por seus discípulos. Junto dele não estavam dois de seus fiéis seguidores, mas dois

assassinos. Sob a cruz, porém, estavam todos, inimigos e crentes, céticos e devotos, zombadores e convictos, e todos eles, com seus pecados, naquele momento foram abarcados pela oração de Jesus por perdão. O amor misericordioso de Deus vive entre seus inimigos. É o mesmo Jesus Cristo que, por sua graça, nos chama para sermos seus discípulos e cuja graça salva o ladrão na cruz em seu último momento.

Para onde será levado aquele que aceitar o chamado para ser discípulo? Que decisões e separações o chamado trará consigo? Temos de levar essa pergunta àquele somente que sabe a resposta. Só Jesus Cristo, que nos ordena que o sigamos, sabe para onde leva o caminho. Nós, porém, sabemos que esse será, com certeza, um caminho de misericórdia sem limites. Discipulado é alegria.

Hoje, parece tão difícil trilhar o caminho estreito da decisão eclesiástica com segurança e, ainda assim, permanecer em toda a amplitude do amor de Cristo para com todos os seres humanos, na paciência, misericórdia e “filantropia” de Deus (Tt 3.4) para com os fracos e os ímpios. E, no entanto, de algum modo ambos devem ficar lado a lado, do contrário segue-se o caminho humano. Que Deus nos dê a alegria, em toda a seriedade do discipulado, em todo o “não” ao pecado, em todo o “sim” ao pecador, em toda a resistência ao inimigo, na palavra triunfante e vencedora do evangelho. Vinde a mim, todos os que estais cansados e sobrecarregados, e eu vos aliviarei. Tomai sobre vós o meu jugo e aprendei de mim; porque sou manso e humilde de coração; e achareis descanso para a vossa alma. Porque o meu jugo é suave, e o meu fardo é leve.

Mateus 11.28-30$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer pergunta se o chamado ao discipulado seria mais um jugo pesado sobre quem já trabalha pelo pão e cuida da família, mas afirma que no discipulado o ser humano deixa o duro jugo das próprias leis pelo jugo suave de Jesus. Que 'lei sua própria', dura e implacável, você tem carregado que Jesus quer trocar pelo descanso d'Ele?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto diz que sob a cruz estavam todos — inimigos e crentes, zombadores e devotos, e até dois assassinos no lugar dos fiéis — todos abarcados pela oração de perdão de Jesus. Onde, na sua vida, você ainda acha que precisa estar 'limpo o bastante' antes de se aproximar desse amor que vive entre os inimigos?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer afirma que 'discipulado é alegria' e que seguir a Jesus é caminhar em misericórdia sem limites, não sobrecarga. Quando você pensa em seguir Jesus mais de perto, isso soa mais como peso ou como alívio — e o que esse sentimento revela sobre como você tem entendido o chamado d'Ele?$p$, 'reflexao', null);
