  -- ---------------------------------------------------------------
  -- Capítulo 1 — A graça preciosa  (aula ordem = 3)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 3;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 1 — A graça preciosa$t$,
      3,
$conteudo$A graça barata é a inimiga mortal de nossa Igreja. Hoje, nossa luta é pela graça preciosa.

A graça barata é graça como resto de estoque, perdão barateado, consolo barateado, sacramento barateado; é graça como riqueza inesgotável da Igreja, graça que mãos levianas gastam sem vacilo nem limite; é graça sem preço, sem custo. A essência da graça seria justamente esta: a fatura paga antecipadamente e para sempre. Se a fatura já está paga, pode-se obter tudo gratuitamente. Porque o custo é muito alto, também são incontáveis as possibilidades de uso e desperdício. O que seria a graça se não barata?

A graça barata é graça como doutrina, como princípio, como sistema; é perdão dos pecados como algo já dado por certo; é o amor de Deus como conceito cristão de Deus. Quem aceita o amor de Deus já está perdoado de seus pecados. A Igreja que segue esse tipo de doutrina da graça se vê automaticamente beneficiada por ela. Nessa Igreja, o mundo encontra cobertura barata para seus pecados, dos quais não se arrepende e, na verdade, não quer se libertar. Assim, a graça barata é a negação da Palavra viva de Deus, negação da encarnação da Palavra de Deus.

A graça barata, em vez de justificar o pecador, justifica o pecado. Desse modo, resolve tudo sozinha, nada precisa mudar e tudo pode permanecer como antes. “Nossos esforços são vãos.” O mundo continua mundo, e nós continuamos pecadores, “mesmo na vida mais piedosa”. O cristão pode, então, viver como toda gente, em pé de igualdade com todos, e não se atreve a, sob essa graça, ter uma vida diferente da que tinha sob o pecado, a fim de não ser acusado de herege fanático! Que ele se guarde de irritar-se contra a graça, de envergonhar tal grandiosa e barata graça e de instituir um novo culto do literalismo, na tentativa de levar uma vida obediente aos mandamentos de Jesus Cristo! Que ele viva como os demais, por causa da seriedade dessa graça e para que não haja resistência a essa graça insubstituível! Assim pode viver porque o mundo é justificado pela graça barata. Sim, ele gostaria de fazer algo extraordinário, e não poder fazê-lo é, sem dúvida, muito difícil para ele, tendo de continuar a viver no mundo real. Contudo, ele tem de aceitar viver desse modo, abrindo mão de sua vontade, renunciando viver de modo diferente dos demais. Tem de deixar a graça ser simplesmente graça, para que as pessoas não percam a fé nessa graça barata. O cristão, no entanto, deve, em sua vida mundana, nessa necessária renúncia que tem de assumir por amor ao mundo — não, por amor à graça! —, sentir-se confortado e seguro ( securus) na posse dessa graça, que tudo faz sozinha. Não é necessário, portanto, que o cristão seja um discípulo, mas que se conforte com a graça. Isso é a graça barata que justifica o pecado em vez de justificar o pecador que deixa o pecado e se arrepende; não é o perdão que separa do pecado. A graça barata é a graça que outorgamos a nós mesmos.

A graça barata é a pregação do perdão sem arrependimento do pecador, é o batismo sem disciplina eclesiástica, é a comunhão sem confissão de pecados, é a absolvição sem confissão pessoal. A graça barata é a graça sem discipulado, é a graça sem cruz, é a graça sem Jesus Cristo vivo e encarnado.

A graça preciosa é o tesouro oculto no campo, pelo qual o ser humano vende feliz tudo que possui; é a pérola preciosa, pela qual o mercador oferece todos os seus bens; é o domínio do reino de Cristo, pelo qual o ser humano arranca o olho que o faz tropeçar; é o chamado de Jesus Cristo, pelo qual o discípulo deixa suas redes para trás e o segue.

A graça preciosa é o evangelho que sempre se deve procurar, a dádiva que se deve pedir, a porta à qual se tem de bater.

Essa graça é preciosa porque chama ao discipulado; é graça porque chama ao discipulado de Jesus Cristo; é preciosa por custar a vida ao ser humano; é graça pois só assim dá vida ao ser humano; é preciosa porque condena o pecado; é graça porque justifica, perdoa o pecador. É preciosa sobretudo porque foi preciosa para Deus, porque lhe custou a vida de seu Filho — “Porque fostes comprados por preço” (1Co 6.20) — e portanto não pode ser barato para nós o que custou caro para Deus. É graça, sobretudo, porque Deus não considerou que seu próprio Filho custasse caro demais para pagar por nossa vida, e assim o deu por nós. A graça preciosa é a Encarnação de Deus.

A graça preciosa é a graça como templo de Deus, que deve ser protegido do mundo, que não pode ser lançado aos cães. Por isso, é graça como palavra viva, a Palavra de Deus, por ele próprio proferida, conforme lhe agrada. Chega até nós como o gracioso chamado ao discipulado de Jesus, como mensagem de perdão ao espírito angustiado e ao coração despedaçado. É preciosa porque submete o ser humano ao jugo do discipulado de Jesus Cristo; é graça porque Jesus afirma: “Meu jugo é suave, e meu fardo é leve”.

Pedro foi chamado duas vezes: “Vinde após mim”. Foram essas as primeiras e as últimas palavras de Jesus a seu discípulo (Mc 1.17; Jo 21.22). Toda uma vida se situa entre esses dois chamados. Na primeira vez, Pedro ouve o chamado de Jesus no lago de Genesaré e, deixando para trás suas redes e sua profissão, segue-o em completa obediência. Na última vez, é o Jesus ressurreto que o encontra em sua antiga profissão, novamente no lago de Genesaré. E, mais uma vez, diz-lhe: “Vinde após mim”. Nesse ínterim, entre um chamado e outro, houve toda uma vida no discipulado de Cristo. E, no meio dela, está a confissão de que Jesus é o Cristo de Deus. Três vezes a mensagem foi anunciada a Pedro, no início, no fim e em Cesareia de Filipe, a mensagem de que Cristo é seu Senhor e Deus. A mesma graça de Cristo que o chama, “Vinde após mim”, é a que se revela a Pedro em sua confissão do Filho de Deus.

Portanto, três vezes a graça interveio no caminho de Pedro, em três momentos diferentes a mesma graça foi proclamada; era, pois, a própria graça de Cristo e com certeza não uma graça que Pedro a si mesmo outorgava. Foi essa mesma graça de Cristo que o convenceu a tudo abandonar pelo discipulado; foi ela que o levou à confissão, que a todos deve ter soado como blasfêmia; foi essa graça que chamou o infiel Pedro à comunhão definitiva, à comunhão do martírio, e pela qual todos os seus pecados foram perdoados. A graça e o discipulado são uma única coisa na vida de Pedro. Ele havia recebido a graça preciosa.

Com a expansão do cristianismo e o crescimento da secularização da Igreja, a consciência da graça preciosa foi se perdendo. O mundo estava cristianizado, e a graça tornou-se propriedade de um mundo cristão. Com isso, tornou-se barata. A Igreja Romana, no entanto, preservou um resto dessa primeira consciência. Foi de fundamental importância a vida monástica não se ter separado da Igreja e esta ter tido a sabedoria de tolerar o monasticismo. Ali, às margens da Igreja, estava o lugar onde se mantinha viva a consciência de que a graça é preciosa e implica o discipulado. Por Cristo, pessoas abandonavam tudo que possuíam e procuravam seguir os rígidos mandamentos de Jesus na prática do cotidiano. Foi assim que a vida nos mosteiros se tornou um protesto vivo contra a secularização do cristianismo e o barateamento da graça. Mas, porque tolerou esse protesto e impediu a ruptura definitiva, a Igreja relativizou o barateamento da graça e, na verdade, por meio dele até mesmo ganhou a legitimação de sua própria vida mundana; pois, nesse momento, a vida monástica tornava-se comportamento especial de natureza individual, ao qual a massa popular não poderia ser submetida. A fatal limitação do mandamento de Jesus a determinado grupo de indivíduos especialmente qualificados para tal ocasionou uma diferenciação na esfera da obediência cristã entre um comportamento mais elevado e outro menos elevado. Assim, sempre que se desferiam novos ataques à secularização da Igreja, podia-se apontar para o caminho da vida monástica, ainda no seio da Igreja, ao lado da qual se podia legitimar plenamente a existência de outro caminho mais fácil para o resto da população. Desse modo, recorrer à compreensão que a Igreja primitiva tinha da graça preciosa, ideia que se preservava no monasticismo da Igreja Romana, por fim serviu, paradoxalmente, como justificação definitiva para a secularização da Igreja.

Nisso tudo, o grande problema da vida monástica, a despeito de todas as incompreensões quanto à vontade de Jesus, não consistia na escolha pelo caminho da graça do discipulado rigoroso. Antes, devia-se muito mais ao fato de a vida nos mosteiros ter tanto se distanciado da vida cristã fora deles que se transformou em comportamento excepcional de alguns poucos, reivindicando assim um tipo de mérito especial.

A fim de reavivar, durante a Reforma, o evangelho da graça pura e preciosa, Deus, em primeiro lugar, levou Martinho Lutero ao mosteiro. Lutero era monge. Abandonara tudo e decidira ser discípulo de Cristo em completa obediência. Renunciara ao mundo e se devotara à obra cristã. Aprendeu a obediência a Cristo e à sua Igreja, porque sabia que só o obediente é que pode crer. O chamado ao mosteiro lhe custou a consagração total de sua vida. Em sua caminhada, Lutero fracassou em relação ao próprio Deus.

Por meio das Escrituras, Deus lhe mostrou que o discipulado de Jesus não é a recompensa para alguns por um comportamento especial, mas sim que o mandamento divino abrange todos os cristãos. A humilde obra do discipulado se tornara, na vida monástica, atividade meritória para os santos. A abnegação revelouse, nesse contexto, a autoafirmação espiritual definitiva dos piedosos. Foi assim que o mundo se infiltrou no interior da vida monástica, voltando a causar estragos. A fuga do mundo se revelara, na verdade, uma maneira requintada de amor pelo mundo. Nesse fracasso da última possibilidade de uma vida piedosa, Lutero foi alcançado pela graça. No colapso da vida monástica, ele viu a mão salvadora de Deus estendida em Cristo. Agarrou-se a ela com a crença de que “nossos esforços são vãos, mesmo na vida mais piedosa”. Foi-lhe dada a graça preciosa, que despedaçou toda a sua existência. Mais uma vez,

viu-se obrigado a deixar para trás suas redes e seguir o Mestre. Na primeira vez, quando se dirigiu ao mosteiro, tinha abandonado tudo, menos a si próprio, seu eu piedoso. Desta vez, também isso lhe foi tirado. Não seguiu o Mestre por mérito próprio, mas pela graça de Deus. Ele não ouviu: “É verdade que você pecou, mas tudo já está perdoado; continue onde estava e console-se com o perdão!”. Lutero teve de abandonar o mosteiro e retornar ao mundo, não porque o mundo em si fosse bom e santo, mas porque o mosteiro nada mais era que o mundo.

O caminho de Lutero, do mosteiro para o mundo, representou o ataque mais forte contra o mundo desde o surgimento da Igreja primitiva. A renúncia do monge ao mundo, na vida monástica, foi brincadeira de criança comparada à renúncia que o mundo vivenciou por parte daquele que a ele retornava. O ataque era frontal. Agora, o discipulado de Jesus tinha de ser vivido em meio ao mundo. O que até então se praticara em circunstâncias e confortos especiais na vida monástica como sendo um comportamento excepcional, agora passava a ser necessário e ordenado a cada cristão no mundo. A obediência absoluta ao mandamento de Jesus deveria agora ser a norma na vida profissional diária. Assim, aprofundou-se de modo imprevisível o conflito entre a vida do cristão e a vida do mundo. O cristão estava novamente no mundo para atacar, em uma luta corpo a corpo.

Nada pode ser mais desastroso para a compreensão da doutrina de Lutero que considerar que ele tivesse proclamado ao mundo, a partir da descoberta do evangelho da graça pura, que o cristão estaria dispensado da obediência ao mandamento de Jesus, ou que a descoberta da Reforma tivesse sido a canonização, a justificação do mundo por meio da graça que tudo perdoa. Para Lutero, a vocação secular do cristão se justifica apenas pelo fato de que, nela, o protesto contra o mundo é anunciado com mais impacto. E é apenas na medida em que essa vocação secular do cristão seja praticada no discipulado de Jesus que ele receberá do evangelho esse novo direito. Não foi a justificação dos pecados, mas a do pecador que levou Lutero a abandonar o mosteiro. Ele tinha recebido a graça preciosa. Graça porque foi água para a terra sedenta, consolo para o medo, libertação da servidão da livre escolha, perdão de todos os pecados. Preciosa porque não dispensou ninguém da obra; ao contrário, acentuou definitivamente o chamado ao discipulado. Mas exatamente naquilo em que era preciosa é que era graça, e naquilo em que era graça é que era preciosa. Era esse o segredo do evangelho da Reforma, o segredo da justificação do pecador. Apesar disso, o grande vencedor da história da Reforma não é o reconhecimento de Lutero da graça pura e preciosa, mas o aguçado instinto religioso do ser humano para descobrir onde se pode obter a graça mais barata. Bastou apenas um leve deslocamento de ênfase, quase imperceptível, para se consumar a obra mais perigosa e nociva. Lutero ensinava que o ser humano, mesmo nos caminhos e obras mais piedosas, não poderia viver diante de Deus por estar, essencialmente, sempre à procura de si próprio. Diante dessa necessidade, ele próprio agarra-se, na fé, à graça do perdão livre e incondicional de todos os pecados. Assim fazendo, Lutero sabia que essa graça lhe custara a vida, e ainda lhe custava diariamente: pois a graça não o dispensara do discipulado pela graça; ao contrário, da consciência dela percebera que o discipulado se lhe tornara obrigatório. Ao falar da graça, Lutero sempre se referia à própria vida. Dizia ele que apenas mediante a graça sua vida fora colocada em completa obediência a

Cristo. Da graça ele não podia falar de outra forma. A graça opera sozinha, afirmava Lutero, e assim repetiam literalmente seus seguidores, com apenas uma diferença: muito rapidamente, excluíram, deixaram de pensar e de afirmar aquilo que para Lutero sempre constituiu a base de seu pensamento: exatamente o discipulado. Sim, porque ele já não precisava dizer, pois sempre tinha falado como alguém a quem a graça conduzira ao mais difícil discipulado de Jesus. Não se pode contestar que a doutrina de seus seguidores, portanto, se originava dos ensinamentos de Lutero, mas foi o ensino dessa doutrina que levou ao fim e à destruição a Reforma como revelação da graça preciosa de Deus na terra. A justificação do pecador no mundo tornou-se justificação do pecado e do mundo. Em consequência disso, da graça preciosa surgiu a graça barata, sem discipulado.

Quando Lutero afirmava que nossos esforços eram vãos mesmo na vida mais piedosa, e que por esse motivo aos olhos de Deus nada tinha importância “senão a graça e o favor do perdão aos pecados”, dizia isso como alguém que até então e naquele momento sentia-se chamado ao discipulado de Jesus e forçado a deixar para trás tudo que possuía. Para Lutero, o reconhecimento da graça foi a ruptura total e definitiva com o pecado de sua vida; nunca, porém, a justificação do pecado. Na aceitação do perdão, esse reconhecimento foi a renúncia radical definitiva a uma vida que se rege apenas pelos próprios caprichos; só assim, e exatamente por isso, tornou-se um chamado sincero ao discipulado. Para ele, a graça era um

“resultado” claramente divino, e não um resultado humano. Seus seguidores, no entanto, transformaram esse resultado em premissa fundamental para um cálculo próprio. Nisso consiste a calamidade. Mesmo sendo a graça o “resultado” da vida cristã, dado pelo próprio Cristo, essa vida não está, em nenhum momento, dispensada do discipulado. Mas, se a graça for a premissa fundamental para minha vida cristã, tenho nela, antecipadamente, a justificação dos pecados que eu vier a cometer durante minha vida no mundo. Contando com essa graça, posso pecar à vontade, pois o mundo está, em princípio, justificado pela graça. Portanto, permaneço como antes em minha existência burguesa mundana, tudo continua como antes e posso viver na certeza de que a graça de Deus me encobre. Sob a proteção dessa graça, o mundo todo tornou-se “cristão”, mas sob essa mesma graça o cristianismo secularizou-se como nunca. Assim, aboliu-se o conflito entre vida cristã e vida profissional secular. A existência cristã consiste justamente em viver no mundo e exatamente como o mundo, em nada diferenciar-me dele, e não posso mesmo me diferenciar dele em nada — por amor à graça! —, embora em determinados momentos eu me distancie do mundo secular e me dirija à Igreja a fim de me assegurar do perdão dos pecados. Estou dispensado do discipulado de Cristo — por meio da graça barata, que é, na verdade, não só o inimigo mais cruel do discipulado, mas também quem necessariamente odeia e afronta o discipulado verdadeiro. A graça como premissa inicial é graça da mais barata; a graça como resultado é graça preciosa. É assustador reconhecer quanto uma verdade evangélica depende de como ela é expressa e empregada no dia a dia. É

a mesma mensagem da justificação somente pela graça; porém, o uso inadequado dessa mensagem leva à completa destruição de sua essência. Quando o Dr. Fausto, já no final de toda uma vida dedicada à busca pelo conhecimento, diz: “Vejo que nada podemos saber”, tem-se um resultado, um sentido completamente diverso do que teria o mesmo enunciado caso utilizado no início do semestre por um estudante que quisesse meramente justificar sua

preguiça (Kierkegaard). Como resultado, o enunciado é verdadeiro, mas, como premissa, é uma ilusão.

Isso significa que o conhecimento não pode ser separado da existência em que foi adquirido. Somente aquele que abdica de tudo que possui no discipulado de Jesus pode dizer-se justificado apenas pela graça. Tal pessoa reconhece o próprio chamado ao discipulado como graça, e a graça, como esse chamado. Mas aquele que, com essa graça, deseja ser dispensado do discipulado, engana a si próprio.

Não teria, porém, o próprio Lutero se aproximado perigosamente dessa completa inversão da compreensão da graça? O que Lutero quer dizer com a frase Pecca fortiter, sed fortius fide et gaude in Christo — “Peque com coragem, mas creia com coragem ainda maior e alegre-se em Cristo!” (Enders III, p. 208, 118ss)? Isto é, você agora é um pecador e nunca mais se livrará do pecado; seja você monge, seja mundano, seja você piedoso, seja ímpio, não escapará da armadilha do mundo; cometerá pecado.

Portanto, peque com coragem, contando justamente com a graça já concedida! Seria essa a proclamação descarada da graça barata, da liberdade para pecar, da revogação do discipulado? É o convite absurdo de encorajamento para pecar à vontade contando com a graça? Existe afronta mais diabólica contra a graça que pecar contando com a graça que Deus nos concedeu? O Catecismo Católico não estaria correto ao reconhecer aí o pecado contra o Espírito Santo?

Para compreender isso, tudo depende da distinção entre resultado e premissa. Se o enunciado de Lutero for compreendido como premissa para uma teologia da graça, evoca-se a graça barata. Mas, se evocado não como princípio, mas exclusivamente como fim, como resultado, como pedra final, como última palavra, o enunciado de Lutero será corretamente entendido. Tido como premissa, pecca fortiter corresponde a um princípio ético; o princípio da graça tem de corresponder obrigatoriamente ao princípio de pecca fortiter. Isso é justificação do pecado, inversão do enunciado de Lutero. “Peque com coragem”, para Lutero, só podia ser a última informação, o encorajamento para aquele que, em seu caminho ao discipulado, reconhece que não se verá livre do pecado, que fatidicamente pecará e que, sob o temor do pecado, desespera-se diante da graça divina. Para ele, o enunciado “Peque com coragem” não é uma confirmação essencial de sua vida desobediente, mas é o evangelho da graça de Deus, perante o qual somos, em qualquer situação, sempre pecadores; é o evangelho que nos procura e nos justifica exatamente na condição de pecadores. Confesse seu pecado com coragem, não tente escapar dele, mas

“creia com coragem ainda maior”. Você é um pecador, seja então, neste momento, também um pecador; não queira ser aquilo que não é. Seja sempre e todos os dias um pecador, mas com a coragem de aceitar-se pecador. Isso, porém, só pode ser dito àquele que, diariamente, de coração, abdica do pecado, que diariamente abdica de tudo que lhe dificulta o discipulado de Cristo e que se vê desolado por seus pecados e infidelidades cotidianos. Que outro ser humano poderá ouvir isso sem pôr em perigo sua fé senão aquele que, lutando por tal consolo, sempre reconhece o chamado ao discipulado de Cristo? Dessa forma, o enunciado de Lutero, entendido como resultado, torna-se graça preciosa, a única graça verdadeira.

A graça como princípio, pecca fortirer como princípio, a graça barata é, afinal, somente uma nova lei que não liberta e de nada ajuda. A graça como palavra viva, por sua vez, pecca fortiter como consolo na

adversidade e como chamado ao discipulado, a graça preciosa, só essa é graça pura, que de fato perdoa os pecados e liberta o pecador. Como abutres, reunimo-nos ao redor do cadáver da graça barata e dela bebemos o veneno que provocou a morte do discipulado de Jesus em nosso meio. A doutrina da graça pura alcançou, na verdade, uma apoteose sem paralelos: a doutrina pura da graça tornou-se ela mesmo Deus, tornou-se a própria graça. Em toda parte são citadas as palavras de Lutero e, no entanto, a verdade foi convertida em ilusão. Se a Igreja possui pelo menos a doutrina da justificação, então é, certamente, uma Igreja justificada! Assim deve ser entendido. Com isso, reconhecer-se-ia a verdadeira herança luterana como sendo o maior barateamento possível da graça. Confessar-se luterano seria, portanto, deixar o discipulado de Jesus para os legalistas, para os reformados ou para os fanáticos, tudo por amor à graça; seria, pois, justificar o mundo e transformar em herege o cristão que segue o caminho do discipulado.

Cristianizou-se e luteranizou-se todo um povo, mas à custa do discipulado, e a um preço demasiado barato. A graça barata venceu.

Mas será que sabemos também que a graça barata foi muito cruel conosco? Acaso o preço que hoje temos de pagar com o colapso das igrejas organizadas não é a consequência inevitável do barateamento da graça? Ofertam-se a baixo preço a mensagem e os sacramentos, batiza-se, confirma-se, perdoa-se todo um povo sem que se faça perguntas nem se imponha condições. Outorga-se o santuário, por humanitarismo, a zombadores e incrédulos, gastam-se torrentes sem fim de graça, todavia o chamado ao discipulado inflexível de Cristo se ouve cada vez mais raramente. Onde foi parar a consciência da Igreja primitiva, que, na instituição da catequese, vigiava tão cuidadosamente a fronteira entre Igreja e mundo, vigiava a graça preciosa? Onde ficaram as advertências de Lutero contra a proclamação de um evangelho que garantia segurança até ao ser humano que não respeitava as coisas sagradas? Em que outra época o mundo foi tão pavorosa e monstruosamente cristianizado como nesta? Que significam os três mil saxões assassinados por Carlos Magno, comparados com os milhões de almas assassinadas hoje? Os filhos acabam pagando pelos pecados dos pais até a terceira e a quarta gerações. A graça barata foi muito cruel com nossa Igreja evangélica. Com certeza, a graça barata também foi cruel conosco, individualmente. Ela não nos abriu, ao contrário, bloqueou o caminho a Cristo. Não nos chamou ao discipulado, ao contrário, nos endureceu na desobediência. Ou acaso não foi dura e cruel quando, tendo nós ouvido inicialmente o chamado ao discipulado de Jesus e o entendido como sendo o chamado da graça de Deus, e até tendo ousado dar os primeiros passos ao discipulado na disciplina da obediência ao mandamento, exatamente ali nos confrontou com a mensagem da graça barata? Será que tivemos a oportunidade de ouvir essa mensagem de modo diferente desse que visava impedir nosso caminho no discipulado, que nos chamava a uma lógica mundana e sufocava a alegria do discipulado, sugerindo que tudo não passava de um caminho escolhido por nós mesmos, um gasto desnecessário, e até mesmo perigoso, de energia, esforço e disciplina? Pois com essa graça tudo já estaria pronto e consumado! O pavio aceso foi cruelmente apagado. Falar dessa forma com o ser humano foi cruel porque ele, desorientado por uma oferta tão barata, abandonou o caminho para o qual Cristo o havia chamado e, tendo se decidido pela graça barata,

para sempre se viu privado de conhecer a graça preciosa. Não poderia ser diferente: na posse da graça barata, o ser humano fraco e iludido sentiu-se forte, quando, na verdade, perdeu a força para a obediência e para o discipulado. A mensagem da graça barata vem arruinando mais cristãos que qualquer mandamento de obras.

No que vem a seguir, buscaremos falar em nome daqueles que estão atribulados e para os quais a palavra da graça soa assustadoramente vazia. Deve-se, em prol da verdade, proferir essa mensagem em nome daqueles entre nós que reconhecem que, por causa da graça barata, perderam o discipulado de Cristo e, com isso, a compreensão da graça preciosa. Deve-se mais uma vez tentar compreender e pôr a graça e o discipulado em sua justa relação mútua, simplesmente por não querermos negar que já não estamos no verdadeiro discipulado de Cristo, que de fato permanecemos membros de uma igreja ortodoxamente crente na doutrina da graça pura, mas não somos mais membros de uma Igreja do discipulado. Já não se pode evitar o problema. A necessidade de nossa Igreja consiste cada vez mais na pergunta: Como podemos viver uma vida cristã nos dias de hoje?

Bem-aventurados os que já se encontram no final do caminho que pretendemos percorrer e, surpresos, compreendem o que de fato parece incompreensível: que a graça é preciosa exatamente por ser graça pura, por ser a graça de Deus em Jesus Cristo. Bemaventurados os que, na simplicidade do discipulado de Jesus Cristo, estão tomados por essa graça e que, em humildade de espírito, podem louvar a graça de Cristo que tudo opera. Bem-aventurados os que podem viver no mundo, no conhecimento dessa graça, sem para ele se perder, e para os quais a certeza do lar celestial é tamanha que, no discipulado de Jesus Cristo, são livres de fato para a vida neste mundo. Bem-aventurados os que consideram o discipulado de Jesus Cristo nada mais que a vida fundamentada na graça, e a graça, nada mais que o discipulado. Bem-aventurados os que, neste sentido, se tornaram cristãos, para os quais a palavra da graça se revelou misericordiosa.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer descreve a graça barata como perdão sem arrependimento, comunhão sem confissão, graça que 'outorgamos a nós mesmos' e que nos deixa viver exatamente como o mundo. Em que área concreta da sua vida você tem usado a graça como cobertura para não mudar nada, em vez de deixá-la separar você do pecado?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$A graça preciosa é descrita como o tesouro escondido pelo qual a pessoa vende feliz tudo o que tem, e o chamado pelo qual o discípulo deixa as redes e segue. O que, hoje, seguir a Jesus já 'custou' a você de verdade — e se a resposta for 'quase nada', o que isso diz sobre qual graça você tem abraçado?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer mostra Lutero saindo do mosteiro de volta ao mundo, vivendo a obediência radical não num lugar separado, mas na profissão e na vida diária. Como seria, nesta semana, viver o discipulado dentro do seu trabalho e da sua casa, e não apenas reservado para os momentos 'religiosos'?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 2 — O chamado ao discipulado  (aula ordem = 4)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 4;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 2 — O chamado ao discipulado$t$,
      4,
$conteudo$Quando ia passando, viu a Levi, filho de Alfeu, sentado na coletoria e disselhe: Segue-me! Ele se levantou e o seguiu.

Marcos 2.14

O chamado é feito e, de imediato, aquele que o ouviu obedece. A resposta do discípulo não é uma confissão oral da fé em Jesus, mas um ato de obediência. Como é possível ocorrer essa obediência imediatamente após o chamado? Isso contraria a razão natural e, por isso, ela se esforça para separar esses fenômenos tão interdependentes; algo tem de estar intercalado entre eles, algo tem de ser esclarecido. Seja o que for que esteja acontecendo, é preciso encontrar uma explicação psicológica e histórica para essa sequência. Pode-se até levantar uma questão boba e perguntar se o publicano já não conhecia Jesus antes de ser chamado por ele e, portanto, já não estava predisposto a segui-lo. A esse respeito o texto nada revela, optando por enfatizar exatamente a sequência imediata da ação após o chamado. Não lhe interessa encontrar justificativas psicológicas para as decisões piedosas do indivíduo.

Por que não? Porque para essa sequência de chamado e ação só existe uma justificativa válida: o próprio Jesus Cristo. É ele quem chama e, por isso, o publicano o segue. Nesse encontro pode-se testemunhar a autoridade de Jesus, incondicional, imediata e que não demanda explicações. Nada é mais importante que o chamado, e nada ocorre além da imediata obediência daquele que foi chamado. O fato de Jesus ser o Cristo confere-lhe total poder para chamar e exigir obediência à sua palavra. Jesus chama ao discipulado, não como mestre sábio e exemplo de vida, mas sendo Cristo, o Filho de Deus. Assim, nessa breve passagem, anuncia-se Jesus Cristo e o que ele requer do ser humano, e nada mais. Ao discípulo não cabe elogios ou aplausos por seu cristianismo decidido. O olhar não deve recair sobre ele, mas somente sobre aquele que chama e sobre todo o seu poder. Tampouco se trata de indicar o caminho para a fé, para o discipulado, pois não há qualquer outro caminho para a fé senão o da obediência ao chamado de Jesus.

O que sabemos sobre o conteúdo do discipulado? “Segue-me! Vinde após mim!” Isso é tudo. Segui-lo parece algo sem conteúdo. Não é algo que de fato pode ser visto como programa de vida cuja realização faça sentido. Não é, igualmente, um objetivo ou um ideal a ser alcançado. Para os padrões humanos, não é algo que mereça sacrifício ou pela qual valha a pena investir a vida. E o que ocorre? O indivíduo que foi chamado deixa para trás tudo que possui não com o intuito de fazer algo especial, mas simplesmente por causa do chamado de Jesus, pois de outro modo não pode seguir seus passos. A esse ato não se atribui valor algum. É completamente sem sentido, insignificante. Pontes foram destruídas, e simplesmente segue-se em frente. Uma vez chamado, o ser humano tem de abandonar a existência que levava até então. Sua única tarefa passa a ser “existir”, no sentido estrito do termo. Tem de abrir mão de

tudo que viveu; o que é velho deverá ficar para trás. O discípulo deixa sua relativa segurança de vida e segue para a completa insegurança (isto é, na realidade, para a absoluta segurança e proteção da comunhão com Jesus); deixa uma situação aparentemente previsível e calculável (mas, na verdade, muito imprevisível) para a imprevisibilidade, para o acaso total (quer dizer, para a única coisa que é necessária e previsível); deixa o domínio das possibilidades limitadas (isto é, de fato, das possibilidades infinitas) para o domínio das possibilidades infinitas (ou seja, para a única realidade libertadora).

Novamente, não se trata de uma lei de caráter geral, e sim da subversão de todo legalismo. Novamente, nada mais é senão a pura ligação com Jesus, ou seja, exatamente o oposto de todo programa preestabelecido, de todo idealismo ou legalismo. Porque Jesus é o único conteúdo, não pode haver qualquer outro. Ao lado dele não existem outros conteúdos. Ele próprio é o único.

Portanto, o chamado ao discipulado é o compromisso exclusivo com a pessoa de Jesus Cristo, a subversão de todo legalismo por meio da graça daquele que chama. É o chamado da graça, e também o mandamento da graça. Vai além do antagonismo entre lei e evangelho. Cristo chama, o discípulo simplesmente o segue. Isso é graça e mandamento unidos em uma coisa só. “E andarei com largueza, pois me empenho pelos teus preceitos” (Sl 119.45).

O discipulado é compromisso com Cristo; porque Cristo existe, tem de haver discipulado. Uma ideia de Cristo, um sistema doutrinário, um conhecimento religioso geral da graça ou do perdão dos pecados não implicam, necessariamente, o discipulado; na verdade, isso tudo pode até excluí-lo e, aliás, tornar-se seu inimigo. A relação que se pode ter com essa ideia é de conhecimento, de entusiasmo, talvez até mesmo de realização, porém nunca a relação de discipulado pessoal e obediente. Cristianismo sem Jesus Cristo vivo permanece um cristianismo sem discipulado, e cristianismo sem discipulado é sempre um cristianismo sem Jesus Cristo; é apenas uma ideia, um mito. Um cristianismo em que exista apenas Deus Pai, mas não Cristo como seu Filho vivo, anula por completo o discipulado; nele existe a fé em Deus, mas não o discipulado. Somente porque o Filho de Deus se fez humano, e por ser Mediador, é que o discipulado se torna o relacionamento correto com ele. O discipulado está comprometido com o Mediador, e, onde quer que se fale adequadamente do discipulado, fala-se do Mediador Jesus Cristo, o Filho de Deus. Somente o Mediador, Deus que se fez humano, pode chamar ao discipulado.

O discipulado sem Jesus Cristo é escolha pessoal de um caminho talvez ideal, um caminho, quem sabe, de martírio, porém sem a promessa. Isso Jesus seguramente rejeitará.

Indo eles caminho fora, alguém lhe disse: Seguir-te-ei para onde quer que fores. Mas Jesus lhe respondeu: As raposas têm seus covis, e as aves do céu, ninhos; mas o Filho do Homem não tem onde reclinar a cabeça. A outro disse Jesus: Segue-me! Ele, porém, respondeu: Permite-me ir primeiro sepultar meu pai. Mas Jesus insistiu: Deixa aos mortos o sepultar os seus próprios mortos. Tu, porém, vai e prega o reino de Deus. Outro lhe disse: Seguir-te-ei, Senhor; mas deixa-me primeiro despedir-me dos de casa. Mas Jesus lhe replicou: Ninguém que, tendo posto a mão no arado, olha para trás é apto para o reino de Deus.

Lucas 9.57-62

O primeiro discípulo se oferece ele próprio para seguir Jesus; ele não foi chamado. A resposta de Jesus adverte o entusiasta de que ele não sabe o que faz. Não o pode, de fato, saber. É esse o sentido da resposta na qual se mostra ao seguidor a vida com Jesus como ela realmente é. Aqui fala aquele que está

a caminho da cruz, cuja vida inteira é descrita no Credo Apostólico numa única palavra: “padeceu”.

Ninguém pode desejar isso por escolha própria. Ninguém pode chamar a si mesmo, diz Jesus, e suas palavras ficam sem resposta. O abismo entre a oferta espontânea ao discipulado e o verdadeiro discipulado permanece aberto.

Mas, quando é o próprio Jesus que chama, ele constrói a ponte que transpõe o abismo mais profundo. O

segundo discípulo quer enterrar o pai antes de seguir Jesus. A lei humana o prende. Ele sabe o que quer e o que deve fazer. Antes, porém, deve cumprir a lei, e só então poderá seguir Jesus. Interpõese aqui, entre a pessoa chamada e Jesus, um mandamento patente da lei. A isso o chamado de Jesus se contrapõe veementemente, não admitindo que, logo naquele momento, algo se interponha entre Jesus e aquele que foi chamado, mesmo que seja o que exista de maior e de mais sagrado, mesmo que seja a lei. Naquele momento, por causa de Jesus, a lei que visava impedir a concretização do chamado tem de ser violada, pois esta já não tem o direito de se interpor entre Jesus e a pessoa chamada. Assim, Jesus opõe-se à lei e ordena o discipulado. Só Cristo pode falar desse modo. É dele a última palavra; o outro não pode contestar. Esse chamado, essa graça, é irresistível.

O terceiro entende o discipulado como o primeiro, como oferta que só ele próprio pode fazer, como programa de vida por ele mesmo escolhido. Mas, ao contrário do primeiro, julga-se no direito de impor condições. Com isso, entra em total contradição. Quer pôr-se à disposição de Jesus, ao mesmo tempo que interpõe algo entre Jesus e si mesmo: “mas deixa-me primeiro...”. Quer segui-lo, porém quer criar ele próprio as condições para o discipulado. É, para ele, uma possibilidade de cuja realização faz parte o cumprimento de exigências e condições preestabelecidas. Assim, o discipulado tornase algo acessível e compreensível para o ser humano. Primeiro, fazse uma coisa, depois, faz-se outra. Tudo tem seu tempo apropriado. O discípulo mesmo se põe à disposição, mas achando-se, por isso, no direito de impor condições. Fica claro que, nesse momento, o discipulado deixa de ser discipulado; transforma-se em programa humano a ser realizado segundo meu próprio julgamento e que posso justificar por meio da razão e da ética. O terceiro discípulo, portanto, deseja ingressar no discipulado, porém no momento em que o aceita condicionalmente mostra não desejar mais ser discípulo. O modo como fez a própria oferta anula o discipulado, pois este não tolera quaisquer condições que possam se interpor entre Jesus e o que obedece. Entra em contradição não apenas com Jesus, mas também consigo. Não quer o que Jesus quer, e também não quer o que ele mesmo quer. Julga a si próprio, discorda de si mesmo, e tudo isso se expressa em “mas deixa-me primeiro...”. A resposta de Jesus confirma figurativamente esse conflito interior, que acaba por excluir o discipulado: “Ninguém que, tendo posto a mão no arado, olha para trás é apto para o reino de Deus”.

Ser discípulo significa dar determinados passos. Já o primeiro passo, que é consequência imediata do chamado, separa o discípulo de sua existência anterior. Assim, o chamado ao discipulado cria imediatamente uma nova situação. É absolutamente impossível conciliar a existência anterior com o discipulado. A princípio, isso era bem visível. O publicano teve de abandonar a coletoria; Pedro teve de deixar as redes para trás, a fim de seguir Jesus. Segundo nosso modo de entender, poderia ter havido, já naquela época, outras possibilidades. Por exemplo, Jesus poderia ter disponibilizado ao publicano um

novo conhecimento de Deus e permitido que ele continuasse em sua antiga situação. Isso teria sido possível, se Jesus não fosse o Filho de Deus que se fez humano. Uma vez que Jesus, todavia, é o Cristo, tudo tinha de ficar evidente desde o início, isto é, que sua mensagem não é uma nova doutrina, mas a criação de uma nova maneira de ser. Tratava-se de realmente caminhar com Jesus. Estava claro para a pessoa que era chamada que, para ela, só havia uma possibilidade de fé em Jesus: abandonar tudo e seguir o Filho de Deus que se fez humano.

A partir do primeiro passo, o discípulo se vê na situação em que a fé se torna possível. Se não seguir o Mestre, ficará para trás e, assim, não aprenderá a crer. Aquele que recebe o chamado deve deixar a situação em que se encontra, impossibilitado de crer, para outra em que, acima de tudo, possa crer. Esse passo não tem em si qualquer valor programático; justifica-se somente pela comunhão com Cristo, estabelecida no momento da decisão. Enquanto Levi continuasse na coletoria, e Pedro, junto às redes no lago, poderiam seguir exercendo honrada e fielmente sua profissão, e poderiam ter o antigo ou o novo conhecimento de Deus; mas, se quisessem aprender a ter fé em Deus, deveriam seguir o Filho de Deus que se fez humano e caminhar com ele.

Antes, era diferente. Podiam viver na reclusão e no anonimato do campo, realizando suas tarefas, cumprindo as leis e esperando o Messias. Agora, porém, ele já estava lá, e seu chamado era anunciado.

Crer, nesse momento, já não significava ficar em silêncio e aguardar, mas sim ir com ele no discipulado. Agora, seu chamado ao discipulado destruía quaisquer vínculos anteriores e os transformava em união exclusiva com Jesus Cristo, por amor a ele. Agora, era necessário derrubar todas as pontes, dar o passo para a insegurança infinita, a fim de reconhecer o que Jesus exige e o que ele oferece. Se Levi continuasse em seu trabalho na alfândega, poderia ter sido aproveitado por Jesus como seu ajudante para o que fosse necessário, porém não o teria reconhecido como único Senhor em cujas mãos deveria depositar toda a sua vida; não teria, portanto, aprendido a ter fé. É necessário criar a situação em que se pode crer em Jesus, o Deus que se fez humano, o tipo de situação impossível, em que tudo se volta para uma única coisa, isto é, a palavra de Jesus. Pedro tem de saltar do barco e andar sobre as águas revoltas a fim de vivenciar isso e, assim, perceber sua impotência diante da onipotência de seu Senhor. Se não tivesse descido daquele barco, não teria aprendido a ter fé. A situação completamente impossível e eticamente irresponsável — no caso essa sobre o mar revolto — teve de ser criada para que a fé se tornasse possível. O caminho para a fé passa pela obediência ao chamado de Cristo. Esse passo é fundamental, do contrário o chamado de Jesus se perde no vazio e, com ele, todo suposto discipulado; sem esse passo ao qual Jesus chama, torna-se entusiasmo enganoso.

É grande a dificuldade para se diferenciar uma situação em que a fé é possível de outra em que ela não o é. Em primeiro lugar, é preciso ficar muito claro que nunca se pode reconhecer ou descobrir na própria situação de que natureza ela é. Somente o chamado de Jesus a classifica como situação em que a fé é possível. Em segundo lugar, a situação em que a fé é possível nunca é criada pelo ser humano. O

discipulado não é uma oferta criada pelo ser humano; apenas o chamado é capaz de criar essa situação.

Em terceiro lugar, essa situação nunca contém em si um valor próprio; ela se justifica somente pelo chamado. Por último e principalmente, também essa situação em que a fé é possível sempre e somente se torna possível na fé.

O conceito de situação em que a fé se torna possível nada mais é que a paráfrase da circunstância em que os dois enunciados seguintes não só têm validade, como são igualmente verdadeiros: Só o que crê é obediente, e Só o obediente é que crê.

Trata-se de uma perda significativa da fidelidade à Bíblia quando se expressa o primeiro enunciado sem o segundo. Só o que crê é obediente — é assim que queremos entender. Dizemos que a obediência resulta da fé, assim como todo bom fruto vem de uma árvore boa. Primeiro é a fé, e só então a obediência. Caso se queira comprovar que a justificação vem pela fé somente, sem a necessidade do ato de obediência, estaríamos, na verdade, diante da premissa necessária e irrefutável de tudo o mais. Se, com isso, queira se estabelecer alguma ordem cronológica em que primeiro se tem fé e só depois se exige obediência, estariam, portanto, fé e obediência separadas uma da outra, e isso daria margem à pergunta de natureza patentemente prática: quando devemos começar a obedecer? Assim, a obediência fica separada da fé. Por causa da justificação, a fé e a obediência devem ficar separadas uma da outra, mas essa separação não deve jamais destruir a unidade de ambas, que reside no fato de a fé só existir na obediência, e nunca sem a obediência, e de que a fé é tão somente fé no ato da obediência.

Por causa da impropriedade do discurso da obediência como consequência da fé, e para chamar a atenção à unidade indissolúvel entre fé e obediência, deve-se acrescentar à ideia “Só o que crê é obediente” um segundo enunciado: “Só o obediente é que crê”. Se, na primeira, a fé é premissa da obediência, na segunda, a obediência é premissa da fé. Exatamente da mesma forma que a obediência é considerada consequência da fé, também deve ser considerada premissa da fé.

Só o obediente é que crê. É preciso praticar a obediência a uma ordem concreta, a fim de que possa haver fé. Um primeiro passo no caminho da obediência tem de ser dado, para que a fé não se transforme em ilusão piedosa imposta pelo próprio indivíduo, ou seja, em graça barata. Tudo depende do primeiro passo, que se diferencia qualitativamente de todos os que vêm na sequência. O primeiro passo de obediência exige que Pedro deixe as redes para trás e salte do barco; exige que o jovem abandone sua riqueza. A fé só se torna possível nessa nova existência que a obediência criou.

Esse primeiro passo, portanto, deve ser visto como a obra externa que consiste na troca de um modo de existência por outro. Tal passo qualquer um pode dar; o ser humano é livre para isso. É um ato possível no âmbito da justitia civilis [justiça civil], em que o ser humano é livre. Pedro não pode converter a si mesmo, mas pode deixar as redes para trás. Essencialmente, exige-se, nos Evangelhos, com o primeiro passo, um ato que comprometerá o resto da vida do indivíduo. A Igreja Romana ordenava esse passo apenas como possibilidade extraordinária da vida monástica, enquanto para os demais crentes bastaria a disposição de se submeter incondicionalmente à Igreja e a seus preceitos. A importância desse primeiro passo também é reconhecida de modo significativo nos escritos confessionais luteranos: uma vez afastado fundamentalmente o perigo de um mal-entendido sinergístico, podese e deve-se dar espaço àquele primeiro ato externo que não se pode deixar de fazer no caso da fé, isto é, o passo em direção à Igreja, onde a mensagem da salvação é proclamada. Esse passo pode ser dado com toda a liberdade.

Venha para a Igreja! É por meio de sua liberdade humana que você pode fazê-lo. Pode sair de casa aos domingos e ir para o culto. Se não o fizer, por livre vontade afasta-se do local onde a fé é possível.

Assim, os escritos confessionais luteranos revelam ter conhecimento de que existe uma situação em que a fé é possível, e outra em que ela não o é. Embora fique bem escondido esse conhecimento, quase como se fosse motivo de vergonha, ele continua disponível como conhecimento sobre o significado do primeiro passo na qualidade de ato externo. Assegurado esse conhecimento, é necessário dizer, em segundo lugar, que o primeiro passo, ato de todo externo, é e continuará a ser obra inútil da lei e que, em si, jamais conduz a Cristo. Como ato externo, a nova existência permanece tal qual a anterior; na melhor das hipóteses, tornar-se-á uma nova lei existencial, um novo estilo de vida, mas que nada tem a ver com a nova vida em Cristo. O bêbado que renuncia ao álcool e o rico que distribui seu dinheiro libertam-se do álcool e do dinheiro, mas não de si mesmos. Não conseguem livrar-se da escravidão de si próprios, e provavelmente continuam mais escravos que antes. O que foi feito anteriormente ainda exerce poder sobre eles. Embora seja inegociável essa renúncia ao que se fez antes, ela não basta para afastar o discípulo da morte, da desobediência e da impiedade. Se, por acaso, entendermos nosso primeiro passo como premissa da graça, da fé, então já seremos declarados culpados por nossas próprias obras e totalmente excluídos da graça. Assim, tudo que costumamos chamar de convicção, boa intenção, tudo que a Igreja Romana chama de facere quod in se est [faça o que está ao seu alcance], está incluído na obra externa. Se dermos o primeiro passo com a intenção de nos colocarmos numa situação em que a fé se torna possível, então essa possibilidade de crer nada mais é que uma obra, uma nova possibilidade de vida no âmbito da antiga existência; desse modo, por ser completamente mal entendida, continuamos na descrença.

Todavia, é necessário que essa obra externa seja realizada, e temos de nos colocar na situação em que a fé se torna possível. Precisamos dar esse passo. O que isso significa? Significa que só daremos esse passo corretamente se o encararmos não como obra nossa que desejamos ver praticada, mas somente como aquilo que é praticado em obediência à palavra de Jesus Cristo, que para isso nos chama. Pedro sabe que não pode saltar do barco por sua vontade; seu primeiro passo já significaria seu afogamento, e portanto ele diz: “Mandame ir ter contigo, por sobre as águas”, ao que Cristo responde: “Vem”. Assim, Cristo deve ter antes chamado, e só com base em sua palavra é que o passo pode ser dado. Esse chamado é sua graça, que chama da morte para a nova vida de obediência. Agora, porém, que Cristo chamou, cabe a Pedro saltar do barco para ir até ele. Na realidade, portanto, o primeiro passo da obediência já é um ato de fé na palavra de Cristo. Mas a fé seria completamente mal entendida como fé se, a partir disso, se chegasse à conclusão de que o primeiro passo não é mais necessário, pois a fé já está ali, de qualquer modo. Em contraponto a isso, deve-se ousar dizer o enunciado: primeiro, é preciso dar o passo da obediência, antes mesmo que possa haver fé. O desobediente não pode crer.

Você se queixa de não poder ter fé? Ninguém deve se surpreender de não poder crer enquanto deliberadamente se recusar ou se opuser, em alguma circunstância, a aceitar o mandamento de Jesus. Não quer submeter a esse mandamento uma paixão pecaminosa, uma inimizade, uma esperança, os planos de sua vida, a razão? Não se surpreenda se não receber o Espírito Santo, se não conseguir orar, se suas

preces por fé caírem no vazio! Vá, antes, a seu irmão e faça as pazes com ele, abandone o pecado que o mantém cativo, e poderá crer novamente! Se rejeitar a palavra de ordem de Deus, também não receberá sua palavra de graça. Como é que quer encontrar a comunhão daquele de quem você propositadamente foge e com quem evita tratar de qualquer assunto? O desobediente não pode crer; só o obediente é que crê.

É assim que o chamado da graça de Jesus Cristo ao discipulado torna-se lei severa: Faça isto!

Abandone aquilo! Salte do barco e venha até Jesus! Àquele que usa sua fé ou sua falta de fé como desculpa de sua desobediência efetiva ao chamado, Jesus diz: Primeiro, seja obediente, pratique o ato externo, deixe para trás o que o prende, abandone o que o separa da vontade de Deus! Não diga que não tem fé para isso; você não a terá enquanto permanecer na desobediência, enquanto não quiser dar o primeiro passo. Não diga: Eu já tenho fé, portanto não preciso mais dar o primeiro passo. Você não tem fé enquanto não der esse primeiro passo e porque não quer dá-lo; além disso, porém, também porque persiste na falta de fé que se esconde detrás da aparência de uma fé humilde. É maldosa artimanha responsabilizar a falta de obediência pela falta de fé, e a falta de fé, pela falta de obediência. A desobediência do “crente” ocorre justamente ao confessar sua falta de fé no instante mesmo em que a obediência lhe é exigida, e ao barganhar sutilmente com essa confissão (Mc 9.24). Se você crê, dê o primeiro passo; ele conduz a Jesus Cristo! Se não crê, dê igualmente o passo; é assim que lhe foi ordenado! Não se aplica a você a questão sobre fé ou falta de fé, mas sim a obediência que lhe foi ordenada e de imediato deve ser cumprida. Nela está a situação em que a fé se torna possível e existe de fato.

Portanto, não existe algo em que você pode crer, mas é Jesus Cristo que cria para você a situação em que a fé se lhe torna possível. É necessário chegar a essa situação, para que a fé seja fé verdadeira, e não ilusão autoimposta. Justamente por se tratar só da verdadeira fé em Jesus Cristo, por só a fé ser o único objetivo, agora e sempre (“de fé em fé”, Rm 1.17), é que essa situação é indispensável. Quem contestar isso de modo rápido e demasiado protestante deve perguntar a si próprio se não é a graça barata que ele defende; pois, na realidade, os dois enunciados, se postos lado a lado, não se tornarão obstáculo para a fé verdadeira; mas, se compreendidos separadamente, tornam-se impedimento ainda maior para ela. Só o que crê é obediente — diz-se ao obediente em situação de fé. Só o obediente é que crê — diz-se ao crente em situação de obediência. Isolando o primeiro enunciado, o crente será entregue à graça barata, isto é, à condenação. Isolando o segundo enunciado, o crente será entregue às obras, ou seja, também à condenação.

A partir deste ponto, abordemos um pouco do trabalho pastoral. É extremamente importante, para quem exerce esse ofício, que suas palavras sejam fundamentadas no conhecimento dos dois enunciados. Para ele, deve estar claro que a queixa sobre a falta de fé resulta, muitas vezes, da desobediência consciente, ou já inconsciente, e que a essa desobediência corresponde facilmente o consolo da graça barata.

Contudo, a desobediência permanece intacta, e a mensagem da graça serve de consolo com o qual o próprio desobediente alivia seu sofrimento e torna-se o perdão dos pecados que ele outorga a si mesmo.

A pregação, porém, torna-se vazia, e ele já não a ouve. E, mesmo que perdoe os próprios pecados

milhares de vezes, não poderá crer no perdão verdadeiro, pois este, na verdade, nunca lhe foi dado. A falta de fé alimenta-se da graça barata porque deseja persistir na desobediência. É essa uma situação frequente no trabalho pastoral de nossos dias. Resulta daí que, ao outorgar a si mesmo o perdão dos pecados, o indivíduo persiste na desobediência e, desse modo, alega não poder conhecer o bem e o mandamento de Deus, por considerá-los questões ambíguas, que permitem interpretações diversas. A consciência da desobediência, a princípio muito clara, turva-se cada vez mais, até finalmente tornar-se pura obstinação. Nesse ponto, o próprio desobediente enredou-se e emaranhou-se de tal modo que já não pode ouvir a Palavra. Com efeito, a fé se torna impossível. Ocorrerá, então, entre o obstinado e o pastor o provável diálogo: “Não consigo ter fé.” “Escute a palavra, ela lhe é anunciada!” “Eu a escuto, mas ela nada significa para mim, parece-me vazia, entra por um ouvido e sai pelo outro.” “Você não quer ouvir.”

“Claro que quero.” Chega-se, assim, ao ponto em que o diálogo é interrompido, porque o pastor já não sabe o que dizer. Conhece apenas aquele enunciado: só o que crê é obediente. E esse enunciado não é suficiente para ajudar o desobediente obstinado que não tem nem pode ter essa fé. O pastor parece estar diante do maior dos enigmas: Deus dá a fé a alguns, e a nega a outros. Com isso, desiste de curar a alma do obstinado, que acaba por isolar-se e, conformado, lamenta sua aflição. Mas é justamente esse o ponto mais importante da conversa, em que deve haver uma mudança radical. Nesse momento, abandona-se a argumentação, e as perguntas e aflições do descrente passam a não ser mais levadas tão a sério. Agora, o que se levará cada vez mais a sério é aquele que tenta se esconder detrás de suas perguntas e aflições. Oportunidade, portanto, para destruir a fortaleza que o obstinado construiu para defender-se, usando o enunciado “só o obediente é que crê”. Assim, a conversa é interrompida, e o pastor prossegue dizendo:

“Você é desobediente, recusa a obediência a Cristo, quer preservar para si um pouco de controle. Não consegue ouvir a Cristo porque é desobediente, não consegue ter fé na graça porque não quer obedecer.

Você se agarra a algum lugar de seu coração contra o chamado de Cristo. Sua aflição é seu pecado”.

Agora, o próprio Cristo entra em cena e ataca o demônio que se alojava no outro e que, até então, se escondia por detrás da graça barata. Agora, tudo depende de o pastor ter engatilhado, para uso imediato, os dois enunciados: só o obediente é que crê, e só o que crê é obediente. Em nome de Jesus, o pastor tem de chamar à obediência, ao ato, à realização do primeiro passo. “Abandone o que o prende e siga-o!”

Nesse momento, tudo depende desse passo. A posição assumida pelo desobediente tem de ser derrubada, pois nela Cristo não pode ser ouvido. O fugitivo tem de sair do esconderijo que construiu para si próprio; somente lá fora ele pode ver, ouvir, crer novamente como um ser humano livre. É verdade que, diante de Cristo, nada se ganhe por a obra ter sido realizada, pois, em si, é apenas obra inócua. Mesmo assim, Pedro teve de saltar do barco e andar sobre o mar revolto para que pudesse crer.

Em resumo, a verdade é esta: por meio do enunciado “só o que crê é obediente”, o ser humano envenenou-se com a graça barata. Persiste na desobediência e consola-se no perdão que ele a si mesmo outorga, fechando-se assim à Palavra de Deus. O ataque à fortaleza fracassa enquanto se continuar a repetir esse enunciado atrás do qual ele se esconde. Tem de haver uma mudança; o outro, o obstinado, tem de ser chamado à obediência: só o obediente é que crê! Será que, assim, alguém pode acabar desencaminhado para o caminho das obras? De maneira nenhuma: mostrando-lhe que sua fé não é fé, ele será liberto do emaranhado em que se encontra. Ele tem de ser liberto para poder tomar a decisão e, assim, o chamado de Jesus à fé e ao discipulado tornar-se audível novamente para ele.

Com essa discussão, entramos no âmago da história do jovem rico.

E eis que alguém, aproximando-se, lhe perguntou: Mestre, que farei eu de bom, para alcançar a vida eterna? Respondeu-lhe Jesus: Por que me perguntas acerca do que é bom? Bom só existe um. Se queres, porém, entrar na vida, guarda os mandamentos. E ele lhe perguntou: Quais? Respondeu Jesus: Não matarás, não adulterarás, não furtarás, não dirás falso testemunho; honra a teu pai e a tua mãe e amarás o teu próximo como a ti mesmo. Replicou-lhe o jovem: Tudo isso tenho observado; que me falta ainda? Disselhe Jesus: Se queres ser perfeito, vai, vende os teus bens, dá aos pobres e terás um tesouro no céu; depois, vem e segue-me. Tendo, porém, o jovem ouvido esta palavra, retirou-se triste, por ser dono de muitas propriedades.

Mateus 19.16-22

A pergunta do jovem sobre a vida eterna é a pergunta sobre a salvação, a única pergunta séria que se pode fazer. Mas não é fácil fazê-la corretamente. Isso se comprova no fato de que o jovem, ao fazer essa pergunta decisiva, desejava, na verdade, perguntar algo bem diferente e que efetivamente foge do verdadeiro problema. Sim, ele dirige sua indagação ao “Mestre”. Deseja ouvir a opinião, o conselho, o juízo do “Mestre”, do grande doutrinador, a respeito dessa pergunta. Com isso, revela duas coisas: primeiro, que, a seu ver, a pergunta é extremamente importante, e Jesus deve ter algo de significativo a dizer sobre isso. Em segundo lugar, porém, espera que o “Mestre”, o grande doutrinador, faça uma declaração importante, mas não espera por uma ordem divina que imponha uma ação. Para o jovem, a pergunta sobre a vida eterna é algo sobre o que ele deseja conversar e discutir com o “Mestre”. Mas, logo de início, as palavras de Jesus desarticulam suas intenções: “Por que me perguntas acerca do que é bom? Bom só existe um”. A pergunta já revelou seu coração. Ele viera para conversar sobre a vida eterna com o bom rabino, mas, na verdade, percebe, com essa pergunta, que não se encontra diante de um

“Mestre” humano, mas perante o próprio Deus. Portanto, não receberá resposta alguma do Filho de Deus que não aponte um caminho claro para o mandamento do Senhor Único. Não receberá a resposta de algum

“Mestre” que meramente acrescente uma opinião pessoal à vontade já revelada de Deus. Jesus remete ao único bom Deus, demonstrando assim ser o Filho perfeitamente obediente do Pai. Se, portanto, aquele que pergunta está ele próprio diante de Deus, está sendo imediatamente desmascarado como quem foge ao mandamento revelado, do qual já tinha conhecimento. O jovem conhece os mandamentos; mas, não se satisfazendo com eles, tenta deles se esquivar. Sua pergunta revela uma piedade fantasiosa que ele mesmo escolheu para si. Por que não se dá por satisfeito com o mandamento revelado? Por que age como se já não soubesse, há muito, qual é a resposta à sua pergunta? Por que pretende culpar Deus por sentir-se deixado na ignorância com relação a essa questão decisiva da vida? Assim, o jovem já está preso e a ponto de ser julgado perante o tribunal. Partindo dessa pergunta descompromissada sobre a salvação, ele é chamado de volta à obediência aos mandamentos revelados.

Segue uma segunda tentativa de fuga. A resposta do jovem é outra pergunta: “Quais?”. Nela oculta-se o próprio Satanás. Era a única possibilidade de fuga para quem se via assim preso. Claro que o jovem

conhecia os mandamentos; mas quem poderia dizer qual deles lhe seria o mais adequado naquele momento? A revelação dos mandamentos é ambígua e obscura, diz o jovem. Ele não vê os mandamentos; vê apenas a si próprio, seus problemas, seus conflitos. Dá às costas ao mandamento patente de Deus e volta-se para o âmbito interessante, inegavelmente humano, do “conflito ético”. Não que seja falso seu conhecimento desse conflito, mas é errado fazer uso dele para contrariar os mandamentos de Deus. Os mandamentos, aliás, foram revelados exatamente para pôr fim ao conflito ético. O conflito ético como consequência ética primordial do ser humano após a queda representa, ele próprio, a oposição do ser humano a Deus. Foi a serpente que, no Paraíso, plantou esse conflito no coração do primeiro ser humano.

“É assim que Deus disse?” (Gn 3.1). O ser humano é afastado do mandamento claro e da obediência simples e infantil pela dúvida ética que insinua que o mandamento ainda carece de explanação e interpretação. “É assim que Deus disse?” O próprio ser humano teria de decidir o que é bom, embasado em seu conhecimento do bem e do mal e ouvindo a voz da consciência. O mandamento teria, assim, múltiplos sentidos, e a vontade de Deus seria que o ser humano o interpretasse e o explicasse e decidisse em liberdade.

Desse modo, já se recusou a obediência ao mandamento. Em lugar da ação simples, surgiu o pensamento dúplice. O ser humano de consciência livre gloria-se contra o filho da obediência. O apelo ao conflito ético é a recusa da obediência; é o retorno da realidade divina para a possibilidade humana, da fé para a dúvida. Assim, ocorre o inesperado: a pergunta mesma pela qual o jovem procura mascarar sua desobediência desvenda-o como ele verdadeiramente é: um indivíduo sob o pecado. Essa revelação consuma-se por meio da resposta de Jesus. Ao enumerar os mandamentos revelados de Deus, ele os atualiza, confirmando-os, portanto, como mandamentos de Deus. Uma vez mais, o jovem é revelado no confronto. Esperava escapar por meio de uma conversa sem compromisso a respeito da vida eterna, na esperança de que Jesus lhe oferecesse uma solução para os conflitos éticos. Em vez disso, não se discute mais a pergunta; o assunto agora é o próprio jovem. A única resposta ao problema do conflito ético é o próprio mandamento de Deus e, com ele, a exigência, agora indiscutível, da obediência. O diabo somente tem uma solução a oferecer para o conflito ético, que é a seguinte: continue perguntando e, desse modo, estará desobrigado de obedecer. Jesus não tem como alvo o problema do jovem, mas o próprio jovem.

Tampouco leva tão a sério o conflito ético que, para o jovem, é dos mais preocupantes. Para Jesus, só uma coisa importa, a saber, que o jovem finalmente ouça o mandamento e obedeça. É exatamente aí, onde o conflito ético requer ser levado a sério, onde atormenta e subjuga o ser humano, porque o impede de chegar ao ato libertador da obediência, é precisamente nesse ponto que toda a sua incrédula impiedade deve ser desmascarada como desobediência definitiva. Séria é apenas a ação obediente que põe fim ao conflito e o destrói, libertando-nos para sermos filhos de Deus. É a esse diagnóstico divino que o jovem é apresentado.

Por duas vezes o jovem foi confrontado com a verdade da Palavra de Deus. Não pode mais fugir do mandamento de Deus; está claro, o mandamento é evidente, e deve ser obedecido! Porém — isso ainda não é suficiente! “Tudo isso tenho observado; que me falta ainda?” Ao responder dessa forma, o jovem se mostra convencido de sua sinceridade, como estivera a respeito de suas preocupações anteriores. É

justamente aí que reside sua obstinação contra Jesus. Ele conhece os mandamentos e os tem observado, mas põe em dúvida que constituam toda a vontade de Deus; deve haver algo mais, algo extraordinário, especial, e é isso que ele deseja cumprir. O mandamento revelado de Deus é incompleto, diz o jovem rico, na derradeira tentativa de fugir do verdadeiro mandamento, de afirmar sua autossuficiência e, portanto, de poder decidir por conta própria sobre o bem e o mal. O mandamento, então, é reafirmado, mas, ao mesmo tempo, é atacado frontalmente. “Tudo isso tenho observado; que me falta ainda?” Aqui, o evangelho de Marcos acrescenta: “E Jesus, fitando-o, o amou...” (Mc 10.21). Jesus reconhece que o jovem se fechou, desesperançado, à palavra viva de Deus, que ele, com toda a seriedade, com todo o seu ser, se revoltou contra o mandamento vivo, contra a obediência simples. Ele quer ajudar o jovem, pois o ama. Assim, dá-lhe uma última resposta: “Se queres ser perfeito, vai, vende os teus bens, dá aos pobres e terás um tesouro no céu; depois, vem e segue-me”.

Na resposta ao jovem, deve-se observar três circunstâncias. A primeira: agora é o próprio Jesus que ordena, o mesmo Jesus que havia pouco apontara ao jovem não o “Mestre”, mas o único que é bom, Deus; passa a fazer uso da autoridade de dizer a última palavra e mandamento. O jovem precisa reconhecer que diante dele está o Filho de Deus. Foi essa condição de Jesus, oculta ao jovem, que lhe permite apontar para o Pai, revelando a perfeita união entre o Filho e o Pai. É essa mesma união que dá legitimidade para que Jesus pronuncie o mandamento do Pai. Isso deve ter ficado muito claro para o jovem, quando ouviu o chamado de Jesus ao discipulado. Aí está a súmula de todos os mandamentos: o jovem deve viver em comunhão com Cristo, o Cristo que é a finalidade dos mandamentos, o Cristo que está diante dele e o chama. Já não é possível fugir para a ilusão do conflito ético. O mandamento é claro:

“Siga-me”.

A segunda circunstância: o chamado ao discipulado necessita ainda de esclarecimentos, a fim de haver total clareza. É preciso impedir que o jovem novamente procure interpretar o discipulado como uma aventura ética, como uma possibilidade, um estilo de vida extremamente interessante, mas revogável, se a ocasião assim exigir. O discipulado, portanto, continuaria mal interpretado se o jovem o visse como o desfecho de suas ações e questionamentos, um acréscimo ao que veio antes, um complemento e acabamento, uma melhoria do que se realizara até então. Para que não reste dúvidas, é necessário criar uma situação que impossibilite o voltar atrás, isto é, uma situação irrevogável que, ao mesmo tempo, esclareça que não se trata, em hipótese alguma, de um mero acréscimo ao que já se havia feito. Essa situação da qual não se pode fugir foi criada com o chamado de Jesus à pobreza voluntária. É

a circunstância existencial, o aspecto pastoral do episódio. O objetivo é ajudar o jovem a enfim entender corretamente e a obedecer perfeitamente. A situação nasce do amor de Jesus por aquele jovem. É apenas o elo entre o caminho que o jovem até então percorrera e o discipulado. Mas atenção: ela não se equivale ao discipulado propriamente dito, e também não é o primeiro passo no discipulado, mas sim a obediência dentro da qual o discipulado pode efetivamente se realizar. Primeiro, o jovem deve sair e vender tudo que possui e doá-lo aos pobres, e apenas depois seguir para o discipulado. A finalidade é o discipulado, e o caminho para o discipulado, nesse caso, é o da pobreza voluntária.

A terceira circunstância: à pergunta do jovem sobre o que ainda lhe falta, Jesus assim responde: “Se queres ser perfeito...”. Isso poderia dar a impressão de que se trata, afinal, de um acréscimo ao que ele até então já havia realizado. E não deixa de ser um acréscimo, mas é um no qual já está incluída a anulação do que se realizara no passado. O jovem, até então, não era perfeito, pois não só entendera mal, como também cumprira mal os mandamentos. É só agora, no discipulado, que pode entender e cumpri-los corretamente, porque Jesus Cristo o chamou para isso. Ao responder à pergunta do jovem, Jesus a tira das mãos dele. O jovem lhe perguntara sobre o caminho para a vida eterna, e Jesus responde: Eu o chamo; isso é tudo.

O jovem procurava uma resposta à sua pergunta. A resposta é: Jesus Cristo. O jovem desejava ouvir a palavra do “Mestre” e, agora, reconhece que essa palavra é o próprio homem a quem perguntara. O

jovem está diante de Jesus, o Filho de Deus, e esse é o encontro pleno. Nessa situação, há apenas “sim”

ou “não”, obediência ou desobediência. A resposta do jovem é “não”. Triste, foi embora dali, desiludido e enganado em sua esperança, incapaz de desvencilhar-se do passado. Ele tinha muitos bens. O chamado ao discipulado não revela, aqui, nenhum outro significado além do próprio Jesus Cristo, o compromisso e a comunhão com ele. No entanto, a existência do discípulo não consiste na adoração entusiástica de um bom mestre, mas, isto sim, na obediência ao Filho de Deus. A história do jovem rico tem sua exata paralela na introdução à parábola do bom samaritano.

E eis que certo homem, intérprete da lei, se levantou com o intuito de pôr Jesus à prova e disselhe: Mestre, que farei para herdar a vida eterna? Então, Jesus lhe perguntou: Que está escrito na Lei? Como interpretas? A isto ele respondeu: Amarás o Senhor, teu Deus, de todo o teu coração, de toda a tua alma, de todas as tuas forças e de todo o teu entendimento; e: Amarás o teu próximo como a ti mesmo. Então, Jesus lhe disse: Respondeste corretamente; faze isto e viverás. Ele, porém, querendo justificar-se, perguntou a Jesus: Quem é o meu próximo?

Lucas 10. 25-29

A pergunta do intérprete da lei é idêntica à do jovem. Neste caso, porém, constata-se, desde o início, que na verdade se trata de uma armadilha. Para o ardiloso intérprete, a resposta já está clara antecipadamente; ela deveria culminar no dilema do conflito ético. A resposta de Jesus é igualmente idêntica àquela dada ao jovem. O homem que pergunta no fundo já sabe a resposta, mas, ao perguntar, quer esquivar-se à obediência ao mandamento de Deus. Resta-lhe somente a informação: “faze isto e viverás”.

Assim procedendo, Jesus desqualifica o intérprete da lei. Ainda há, porém, como na situação do jovem rico, a possibilidade de fuga para o conflito ético por meio de outra pergunta: “Quem é o meu próximo?”.

Desde então, ao longo dos tempos, a pergunta do ardiloso intérprete, aparentemente ingênua e ignorante mas de fato traiçoeira, vem sendo repetida inúmeras vezes, fazendo-se passar de pergunta séria e racional de um ser humano que busca o conhecimento. Verdade seja dita, seu contexto não foi adequadamente interpretado. Toda a história do bom samaritano constituí, de fato, uma ação de defesa de Jesus contra essa pergunta satânica, destruindo-a ao mesmo tempo. Trata-se de pergunta sem fim e sem resposta. Ela surge do indivíduo que “é enfatuado, nada entende, mas tem mania por questões e contendas de palavras, de que nascem inveja, provocação, difamações, suspeitas malignas” (1Tm 6.4). É uma pergunta dos

arrogantes “que aprendem sempre e jamais podem chegar ao conhecimento da verdade”, que “tendo forma de piedade, [negamlhe], entretanto, o poder” (2Tm 3.5). São os incapazes de crer, que fazem perguntas porque “têm cauterizada a própria consciência” (1Tm 4.2), porque não conseguem ser obedientes à Palavra de Deus. “Quem é o meu próximo?” Existe uma resposta a essa pergunta, se é meu irmão na carne, meu conterrâneo, meu vizinho ou meu inimigo? Não se poderia afirmar ou negar tanto uma coisa como outra, com o mesmo direito? O resultado de tal pergunta não é o dilema e a desobediência? Sim, essa pergunta é a revolta contra o próprio mandamento de Deus. É meu desejo ser obediente, mas Deus não me diz como fazê-lo. O mandamento de Deus é ambíguo, deixa-me em eterno conflito eterno. A pergunta: “O que devo fazer?” foi o primeiro engano. A resposta é: Obedeça ao mandamento que você conhece. Não fique perguntando, mas faça! A pergunta: “Quem é o meu próximo?”

é a pergunta derradeira do desespero ou da autoconfiança com a qual o desobediente se justifica. A resposta é: Você mesmo é seu próximo. Vá e seja obediente em seu ato de amor. Ser próximo não é qualidade do outro, mas é o direito que o outro tem sobre mim; nada mais que isso. A todo momento, em toda situação, sou chamado a agir; é de mim que se exige obediência. Literalmente, não resta tempo para questionar sobre a qualificação do outro. Tenho de agir e tenho de obedecer, sou eu quem deve ser o próximo para o outro. E, então, você pergunta mais uma vez, aterrorizado, se não deveria primeiro ter conhecimento e refletir sobre como agir — quanto a isso, só há uma resposta: Eu não posso saber e refletir a não ser na própria ação, pois já de início me reconheço como sendo aquele que foi chamado. Só posso aprender o que é obediência enquanto obedeço, e não ao fazer perguntas. É só na obediência que posso reconhecer a verdade. O chamado de Jesus atinge o conflito da consciência e do pecado e nos liberta para a simplicidade da obediência. O jovem rico foi chamado por Jesus à graça do discipulado; já o ardiloso intérprete da lei foi mandado de volta ao mandamento.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Levi se levanta da coletoria e segue no mesmo instante, sem confissão de fé, apenas em obediência — porque 'só o obediente é que crê, e só o que crê é obediente'. Existe algum primeiro passo concreto que Jesus já lhe mostrou e que você vem adiando, esperando 'sentir mais fé' antes de obedecer?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Bonhoeffer descreve os homens de Lucas 9 que dizem 'deixa-me primeiro...' — enterrar o pai, despedir-me dos meus — interpondo algo, mesmo sagrado, entre eles e o chamado. Qual é o seu 'mas deixa-me primeiro' hoje, aquela condição que você impõe antes de seguir de fato?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O jovem rico tenta escapar perguntando 'quais mandamentos?' e 'que me falta ainda?', fugindo para o conflito ético em vez de obedecer ao que já conhece, e vai embora triste por causa de seus bens. Que mandamento claro de Deus você já conhece bem, mas tem transformado em discussão e dúvida justamente para não ter de obedecer — e o que é o seu 'muitos bens' que dificulta dar o passo?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 3 — A obediência simples  (aula ordem = 5)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 5;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 3 — A obediência simples$t$,
      5,
$conteudo$Quando Jesus exigiu do jovem rico que se tornasse voluntariamente pobre, este se viu diante da escolha entre obedecer ou não obedecer. Não havia alternativa. Quando Jesus pediu a Levi que abandonasse a coletoria e a Pedro que deixasse as redes para trás, eles não tiveram dúvida da seriedade do chamado.

Tinham de abandonar tudo e segui-lo. Quando Pedro foi chamado para saltar do barco e andar sobre o mar revolto, ele teve de se levantar e ousar dar aquele passo. Em todos esses chamados, a única coisa que se exigia era que confiassem totalmente na palavra de Jesus e a considerassem terra mais firme que qualquer segurança do mundo. As forças que, na época, buscavam interporse entre a palavra de Jesus e a obediência eram tamanhas, como são hoje. A razão, a consciência, a responsabilidade, a devoção religiosa e, até mesmo, a lei e o princípio escriturístico se opunham, a fim de impedir tais atos extremos, tal “fanatismo”. Mas o chamado de Jesus a tudo superou e a tudo impôs a obediência. Era a própria palavra de Deus, e exigia-se obediência total.

Se, hoje, Jesus Cristo usasse as Escrituras Sagradas para falar assim com um de nós, provavelmente argumentaríamos: É verdade que a ordem de Jesus é muito clara, mas, quando Jesus ordena algo, entendo que ele nunca exige obediência legalista, mas apenas uma coisa, isto é, que eu tenha fé. Minha fé, contudo, não guarda relação com pobreza ou riqueza, nem com qualquer coisa semelhante; pelo contrário, tendo fé, posso ser tanto rico como pobre. A questão não é possuir bens; posso até possui-los, mas devo viver como se não os possuísse; tenho de sentir-me, em meu íntimo, livre de tais bens, não permitindo que meu coração se apegue a minha riqueza. Quando Jesus diz: “Vende os teus bens!”, é isto que quer dizer: Na verdade, você não tem que de fato cumprir essa ordem, mas sim, não deve ostentar os bens que possui. Pode até ficar com eles, mas viva como se não os possuísse. Não deixe que seu coração se apegue a eles. Assim, nossa obediência à palavra de Jesus consistiria na negação da obediência simples conforme prescrita, a fim de sermos obedientes “na fé”. Distinguimonos, com isso, do jovem rico. É

muito provável que ele, triste como está, não consiga se tranquilizar dizendo a si próprio: Prefiro continuar rico, apesar da palavra de Jesus, mas quero, em meu íntimo, libertar-me de meus bens e consolar-me, em toda a minha insuficiência, no perdão de meus pecados e, pela fé, ter comunhão com Jesus. Em vez de se tranquilizar, afastou-se entristecido, não obedeceu e, para completar, perdeu a fé.

Nisso tudo, o jovem foi muito sincero. Separou-se de Jesus e, de fato, sua sinceridade guardava uma promessa maior que qualquer comunhão aparente com Jesus fundamentada na desobediência. Percebe-se claramente, na opinião de Jesus, que o jovem não conseguiria se libertar, no íntimo, de sua riqueza. É

provável que, por ser um jovem sério e esforçado, já tivesse inúmeras vezes tentado se desfazer de seus bens. Seu fracasso se comprova no fato de que, no momento decisivo, ele se recusa a obedecer à palavra

de Jesus. Nota-se, portanto, a sinceridade do jovem. Em nossa argumentação, porém, distinguimo-nos totalmente do ouvinte bíblico da palavra de Jesus. Se Jesus disser a ele: “Deixe tudo para trás e siga-me; abandone profissão, família, nação e a casa de seu pai”, saberá ele que, para tal chamado, só há uma resposta: a resposta da obediência simples, a única resposta possível porque é exatamente na obediência que se dá a promessa da comunhão com Jesus. Nós, porém, diríamos: Embora o chamado de Jesus sem dúvida deva ser levado a sério, a verdadeira obediência consiste justamente em não abandonar a profissão, ficar junto à família e servir a Jesus onde estou, em verdadeira liberdade interior. Portanto, quando Jesus proclama: “Para fora!”, entendemos: Permaneça com a família, permaneça em seu trabalho! — e ali permanecemos, mas como se, no íntimo, tivéssemos saído. Ou então, quando Jesus diz: “Não andeis ansiosos”; entendemos: É claro que devemos nos preocupar e trabalhar para o sustento da família e o nosso próprio sustento; qualquer outra atitude seria uma irresponsabilidade. No íntimo, porém, temos de estar livres de tais preocupações. E, se Jesus dissesse: “A qualquer que te ferir na face direita, volta-lhe também a outra”; entenderíamos: É justamente na luta e no revide que o ser humano se engrandece no verdadeiro amor ao próximo. Por fim, se Jesus dissesse: “Buscai, pois, em primeiro lugar, o seu reino”, entenderíamos: É claro que, antes disso, devemos buscar uma infinidade de outras coisas. Afinal, como poderíamos sobreviver? O que se pretenderia dizer, portanto, é que temos de investir toda a boa vontade de nosso íntimo no reino de Deus. Nesses exemplos todos, pode-se perceber uma mesma coisa, a saber, a anulação consciente da obediência simples e literal.

Como é possível tamanha inversão da palavra de Jesus? O que ocorreu para que a palavra de Jesus se tornasse sujeita a esse tipo de distorção e ficasse a mercê do escárnio do mundo? Em qualquer outro contexto onde ordens são dadas, as relações são claras. Quando um pai diz ao filho: “Vá para cama!”, a criança entende muito bem o que ele quer dizer. Entretanto, uma criança instruída numa teologia equivocada começaria a argumentar: Se papai diz: Vá para a cama, está querendo dizer que estou com sono; como ele não quer que eu esteja com sono, posso superar meu sono se eu for brincar. Portanto, embora papai diga: Vá para a cama!, na verdade ele quer dizer: Vá brincar! Usando tal argumentação, tanto a criança, em relação ao pai, como o cidadão, em relação às autoridades, seriam confrontados com uma linguagem muito evidente, que é a linguagem da punição. Somente em relação às ordens de Jesus as coisas se passam de outra maneira. Nelas, a obediência simples acaba por se transformar em desobediência. Como isso é possível?

Tal inversão é possível porque a argumentação invertida se baseia, com efeito, em algo totalmente correto. A ordem de Jesus ao jovem rico, o chamado à situação em que a fé se torna possível, tem, de fato, um só objetivo: o de chamar o ser humano à fé em Jesus, ou seja, à comunhão com ele. Afinal, nada depende desta ou daquela ação humana; ao contrário, tudo depende da fé em Jesus como Filho de Deus e seu Mediador. Nada depende, na verdade, de pobreza ou riqueza, de casamento ou celibato, de ter uma profissão ou não; tudo depende da fé. Até aqui, nenhum problema; é possível crer em Cristo na riqueza e na posse de bens mundanos, crer de tal forma que possuamos os bens como se não os possuíssemos.

Todavia, essa é uma possibilidade última da existência cristã, uma possibilidade inserida na solene expectativa da volta iminente de Cristo, não sendo a possibilidade mais próxima nem a mais simples. A

interpretação contraditória dos mandamentos tem sua legitimidade cristã, mas jamais poderá servir à anulação da interpretação simples desses mandamentos. Só quem já se confrontou, em algum momento da vida, com a interpretação simples e que, assim, está na comunhão de Jesus, no discipulado e na expectativa do fim, é que possui tal direito e possibilidade. Essa é a possibilidade mais difícil de todas; além disso, é, do ponto de vista humano, uma possibilidade quase impossível essa de interpretar o chamado de Jesus de forma contraditória. Por isso, ela corre sempre o risco maior de tornar-se uma saída cômoda, uma fuga da obediência concreta. Quem não aceita que seria muito mais fácil interpretar com simplicidade e obedecer literalmente ao mandamento de Jesus — como, por exemplo, à ordem de Jesus, doar todos os bens em vez de mantê-los — não tem direito à interpretação contraditória da palavra de Jesus. É necessário, portanto, que a interpretação do mandamento de Jesus seja literal, isto é, a mais simples possível; apenas dessa maneira a interpretação contraditória é possível.

O chamado concreto de Jesus e a obediência simples têm um sentido irrevogável. Jesus chama a uma situação concreta em que a fé é possível; por isso, chama de forma tão concreta e assim também quer ser entendido, porque sabe que apenas na obediência concreta o ser humano se torna livre para crer.

Onde a obediência simples é, por princípio, eliminada, novamente a graça preciosa do chamado de Jesus se transforma em graça barata que serve à autojustificação. Cria-se aí, além disso, uma falsa lei, que dificulta para o ser humano ouvir o chamado concreto de Jesus. Essa falsa lei é a lei do mundo, à qual se opõe e corresponde a lei da graça. O mundo, neste caso, não é aquele que Cristo venceu e que, na comunhão com ele, temos de vencer diariamente; ao contrário, aqui o mundo torna-se lei rígida, irrevogável, torna-se um princípio. A graça, por sua vez, já não é dádiva do Deus vivo, pela qual somos separados do mundo e colocados na obediência a Cristo; ao contrário, passa a ser uma lei divina que se tornou vaga, aplicada apenas em casos especiais. A luta de princípios contra o “legalismo” da obediência simples cria, ela própria, a mais perigosa das leis, a lei do mundo e a lei da graça. A luta de princípios contra o “legalismo” da obediência simples é exatamente a que mais segue a lei à risca. As forças que atuam contra a obediência simples só são vencidas pela obediência verdadeira ao chamado gracioso de Jesus ao discipulado, no qual a lei é cumprida pelo próprio Cristo e por ele é anulada.

Onde a obediência simples é, por princípio, eliminada, introduz-se um princípio escriturístico não evangélico. O pré--requisito para a compreensão das Escrituras é a posse da chave que abre a porta de acesso a elas. A chave, no caso, não é o próprio Cristo vivo em julgamento e graça, e o uso dela não depende mais da vontade do Espírito Santo vivo; em vez disso, a chave para a compreensão das Escrituras é uma doutrina geral da graça, e nós mesmos fazemos uso dela à vontade. O problema do discipulado se revela aqui também como problema hermenêutico. Tem de ficar claro, para uma hermenêutica evangélica, que não é possível nos identificarmos diretamente com aqueles que foram chamados por Cristo; tais indivíduos das Escrituras pertencem à Palavra de Deus e, consequentemente, fazem parte do conteúdo da pregação. No sermão, não ouvimos apenas a resposta de Jesus à pergunta de um discípulo, pergunta que poderia ser a nossa, mas pergunta e resposta são, juntas, como palavra da Escritura, objeto da pregação. A obediência simples, portanto, estaria sendo mal compreendida do ponto de vista da hermenêutica, se nossa intenção é agir e obedecer como se fôssemos discípulos em pé de igualdade com aqueles que foram chamados pelo próprio Jesus. O Cristo anunciado nas Escrituras é aquele que, em toda a sua Palavra, oferece a fé apenas ao que obedece e a obediência apenas ao que crê.

Não devemos nem podemos ir além da palavra das Escrituras com o intuito de descobrir como os acontecimentos se deram; em vez disso, somos chamados ao discipulado pela palavra das Escrituras como um todo, exatamente porque não querermos que elas sejam violadas, no legalismo, por meio de um princípio, nem que se trate da doutrina da graça.

Continua válido, portanto, o fato de que a interpretação contraditória do mandamento de Jesus inclui a interpretação simples, justamente por não ser nosso intuito estabelecer uma lei, mas sim pregar a palavra de Cristo. Assim, torna-se quase desnecessário argumentar contra a suspeita de que talvez estivéssemos pensando que essa obediência simples fosse algum tipo de pré-requisito da fé, uma espécie de facere quod in se est, mérito especial do ser humano. A obediência ao chamado de Jesus não é, jamais, um ato dependente da vontade humana. Tampouco a doação de bens já é, em si, essa obediência exigida, mesmo porque poderia configurar um ato de desobediência a Jesus, ou seja, uma escolha de nossa própria vontade de um estilo de vida, de um ideal cristão, de um ideal franciscano de pobreza. Ao doar os bens, o ser humano poderia estar justamente afirmando a si próprio e a um ideal, e não ao mandamento de Jesus; isto é, não estaria se libertando, mas escravizando-se ainda mais. O passo para dentro dessa situação nunca é uma oferta do ser humano a Jesus; antes, é sempre a oferta graciosa de Jesus ao ser humano. Esse passo só é legítimo quando assim realizado, mas aí deixa de ser uma possibilidade de escolha da vontade humana.

Então, disse Jesus a seus discípulos: Em verdade vos digo que um rico dificilmente entrará no reino dos céus. E ainda vos digo que é mais fácil passar um camelo pelo fundo de uma agulha do que entrar um rico no reino de Deus. Ouvindo isto, os discípulos ficaram grandemente maravilhados e disseram: Sendo assim, quem pode ser salvo? Jesus, fitando neles o olhar, disselhes: Isto é impossível aos homens, mas para Deus tudo é possível.

Mateus 19.23-26

Nota-se, pelo espanto dos discípulos diante da palavra de Jesus e da pergunta deles sobre quem então poderia ser salvo, que consideravam o caso do jovem rico não um fato isolado, mas um caso geral. Não perguntam: “Qual rico?”, mas em termos bem amplos: “Quem pode ser salvo?”, exatamente porque todos, incluindo os discípulos, pertencem a esses ricos para os quais é tão difícil entrar no reino dos céus. A resposta de Jesus confirma que eles acertaram na interpretação de suas palavras. Ser salvo por meio do discipulado não é uma possibilidade ao alcance dos seres humanos, mas para Deus tudo é possível.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer mostra como invertemos a ordem clara de Jesus: quando ele diz 'vende os teus bens', ouvimos 'fique com eles, mas não se apegue no íntimo'. Onde, na sua vida hoje, você desconfia que está transformando um mandamento concreto e literal de Jesus nesse tipo de obediência só 'interior', que no fundo não custa nada?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O jovem rico foi sincero: preferiu afastar-se triste a fingir uma comunhão com Jesus fundada na desobediência. Bonhoeffer diz que essa sinceridade guardava mais promessa que uma falsa comunhão. Em que área você tem fingido para si mesmo uma intimidade com Cristo que, no concreto, repousa sobre uma desobediência que você ainda não encarou?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O texto distingue a 'graça preciosa' do chamado e a 'graça barata' que serve à autojustificação, e diz que só pode interpretar o mandamento de forma 'contraditória' quem antes se confrontou com a obediência simples e literal. Pensando em uma ordem específica de Jesus que você costuma 'reinterpretar', você já chegou a se confrontar honestamente com o sentido mais simples dela, ou pulou direto para a versão confortável?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 4 — O discipulado e a cruz  (aula ordem = 6)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 6;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 4 — O discipulado e a cruz$t$,
      6,
$conteudo$Então, começou ele a ensinar-lhes que era necessário que o Filho do Homem sofresse muitas coisas, fosse rejeitado pelos anciãos, pelos principais sacerdotes e pelos escribas, fosse morto e que, depois de três dias, ressuscitasse. E isto ele expunha claramente. Mas Pedro, chamando-o à parte, começou a reprová-lo. Jesus, porém, voltou-se e, fitando os seus discípulos, repreendeu a Pedro e disse: Arreda, Satanás! Porque não cogitas das coisas de Deus, e sim das dos homens. Então, convocando a multidão e juntamente os seus discípulos, disselhes: Se alguém quer vir após mim, a si mesmo se negue, tome a sua cruz e siga-me. Quem quiser, pois, salvar a sua vida perdê-la-á; e quem perder a vida por causa de mim e do evangelho salvá-la-á. Que aproveita ao homem ganhar o mundo inteiro e perder a sua alma?

Que daria um homem em troca de sua alma? Porque qualquer que, nesta geração adúltera e pecadora, se envergonhar de mim e das minhas palavras, também o Filho do Homem se envergonhará dele, quando vier na glória de seu Pai com os santos anjos.

Marcos 8.31-38

Aqui, o chamado ao discipulado aparece no contexto do anúncio da Paixão de Jesus. É necessário que Jesus Cristo sofra e seja rejeitado. É o imperativo da promessa de Deus, a fim de que se cumpram as Escrituras. Sofrer e ser rejeitado não significam a mesma coisa. Mesmo com todo o sofrimento que teve de enfrentar na cruz, Jesus poderia ter sido o Cristo festejado. Toda a compaixão e a admiração do mundo ainda poderiam estar voltadas para seu sofrimento. A Paixão como tragédia poderia ter trazido consigo valor próprio, honra e dignidade próprias. Contudo, Jesus é o Cristo que foi rejeitado mesmo na Paixão. Essa rejeição tira da Paixão toda dignidade e honra que nela poderia ter havido; tornou-se sofrimento sem honra. Sofrimento e rejeição são os sentimentos que expressam, em suma, a crucificação de Jesus. Morrer na cruz significa sofrer e morrer como rejeitado, proscrito. É necessário que Jesus sofra e seja rejeitado por força do imperativo divino. Qualquer tentativa de impedir o que deve ser feito é satânica, mesmo a tentativa que provém do círculo dos discípulos, ou exatamente porque daí provém, pois é um esforço para impedir Cristo de tornarse Cristo. O fato de ter sido justamente Pedro, a Rocha da Igreja, o culpado, e isso logo após ter confessado Jesus como o Cristo e ter sido por ele instituído, confirma que, já de início, a própria Igreja se escandalizou com o Cristo sofredor. Nota-se que, na qualidade de Igreja de Cristo, ela não quer aceitar tal Senhor, nem se submeter à lei do sofrimento. O

protesto de Pedro revela sua relutância em ser enviado para o sofrimento. Foi assim que Satanás entrou na Igreja, ele que almeja vê-la livre da cruz de seu Senhor.

Jesus, portanto, viu a necessidade de esclarecer a seus discípulos, com o máximo de objetividade, o imperativo do sofrimento. Assim como Cristo só é Cristo sendo aquele que sofre e é rejeitado, também o discípulo só é discípulo no sofrimento e na rejeição, como se com ele fosse crucificado. O discipulado como união com a pessoa de Jesus Cristo submete o discípulo à lei de Cristo, isto é, submete-o à cruz.

Contudo, ao comunicar essa verdade aos discípulos, verdade que não se pode transferir para outros, Jesus parte de um ponto curioso, oferecendo-lhes, mais uma vez, a liberdade de escolha. “Se alguém quer

vir após mim...”, diz ele. Não é algo evidente para ninguém, nem mesmo para os discípulos. Ninguém deve ser forçado a tal escolha, nem mesmo pode se esperar que alguém o faça. Ao contrário, o enunciado “Se alguém...” dirige-se àqueles que, a despeito de todo o sofrimento, queiram segui-lo independentemente de quaisquer outras ofertas que sejam feitas. Novamente, tudo depende da decisão do próprio discípulo; mesmo em meio ao discipulado, ele se vê livre para escolher, tudo é deixado em aberto, nada se espera e nada se impõe. O que se dirá agora é decisivo. Assim, mais uma vez, antes que a lei do discipulado vigore, o discípulo tem de sentir-se livre para escolher.

“Se alguém quer vir após mim, a si mesmo se negue.” Assim como Pedro negou a Cristo, dizendo:

“Não conheço tal homem” (Mt 26.72), o discípulo terá de dizer o mesmo a si próprio. A abnegação jamais pode consistir em uma série de atos isolados de automartirização ou de exercícios ascéticos; a abnegação não é suicídio, porque mesmo aí o discípulo pode tomar a própria decisão. A abnegação é conhecer apenas a Cristo, e não mais a si próprio; é ver somente a Cristo, que está à nossa frente, e não mais o caminho que nos impõe tantas dificuldades. A abnegação diz tão somente: “Ele vai à frente, apeguese a ele”.

“... tome a sua cruz.” Jesus, em sua graça, preparou os discípulos para essas palavras por meio do ensino da abnegação. Só estaremos preparados para carregar a cruz por causa dele quando de fato nos esquecermos de nós mesmos, quando já não nos reconhecermos. Se conhecermos apenas a ele, não conheceremos mais as dores de nossa cruz, pois Jesus é tudo que vemos. Se ele não tivesse nos preparado tão bondosamente para essas palavras, não poderíamos suportá-las. Foi assim, porém, que ele nos capacitou a aceitá-las, por mais duras que fossem, como graça. Elas nos encontram na alegria do discipulado e nele nos confirmam.

A cruz não é tragédia nem infortúnio; é o sofrimento resultante da união com Cristo. A cruz não é sofrimento casual, mas sofrimento necessário. A cruz não é sofrimento relacionado à existência mundana, mas sofrimento próprio da existência cristã. A cruz não é, em essência, apenas sofrimento, mas sofrimento e rejeição, e rejeição entendida no sentido mais rigoroso, isto é, rejeição por causa de Jesus Cristo, e não por qualquer outro tipo de atitude ou confissão. Um cristianismo que não vinha mais levando a sério o discipulado, que transformara o evangelho no consolo da graça barata e que já não conseguia diferenciar a existência cristã da existência mundana, inevitavelmente entenderia a cruz como tragédia diária, como a angústia e o medo da vida natural. Esqueceuse de que a cruz significa sempre rejeição, e que a humilhação da Paixão de Cristo é inerente à cruz. A característica básica do sofrimento da cruz, isto é, ser rejeitado, desprezado e abandonado pelos seres humanos no sofrimento, como tantas vezes se lastima o salmista, não é mais compreendida pelo cristianismo que não sabe diferenciar a existência mundana da existência cristã. A cruz é a compaixão com Cristo, é o sofrer com Cristo.

Somente aquele que está unido com Cristo, tal como se dá no discipulado, está de fato sob a cruz.

“... tome a sua cruz.” Ela já está preparada desde o início, só falta carregá-la. Mas, para que ninguém saia procurando alguma cruz onde quer que for, ou qualquer forma voluntária de sofrimento, Jesus já deixa avisado que, para cada um, já estaria preparada a sua cruz, talhada e designada por Deus. O ser humano tem de carregá-la e suportá-la de acordo com o sofrimento e a rejeição que lhe foram reservados.

Cada pessoa tem de carregar a própria cruz. A alguns Deus honra com grande sofrimento, dando-lhes até a graça do martírio; a outros, não permite que sejam tentados além de suas forças. No entanto, a cruz é uma só.

A cruz é imposta a cada cristão. O primeiro sofrimento com Cristo, que cada um tem de vivenciar, é o chamado que rompe nossa união com este mundo. É a morte do velho ser humano no encontro com Jesus Cristo. Desde sempre, quem entra no discipulado entrega-se à morte de Jesus, põe a vida à disposição da morte. A cruz não é o fim terrível de uma vida feliz e piedosa; ela se encontra no início da comunhão com Jesus Cristo. Todo chamado de Jesus leva à morte. Quer se dê à maneira dos primeiros discípulos, que deixaram casa e profissão para segui-lo, quer se dê à maneira de Lutero, que abandonou o mosteiro e retornou à vida civil, em qualquer situação essa morte nos espera, a morte em Jesus Cristo, a negação de nosso velho ser humano. Jesus Cristo é, com sua palavra, nossa morte e nossa vida; por isso o chamado de Jesus leva o jovem rico à morte, pois ele só pode seguir o chamado matando sua vontade própria, pois todo mandamento de Jesus é a morte de nossos desejos e vontades; e, não obstante, não nos é dada a autoridade sob a própria morte. O chamado ao discipulado de Jesus, o batismo em nome de Jesus Cristo, é morte e vida. O chamado de Cristo, o batismo, insere o cristão na luta diária contra o pecado e o diabo.

Por isso, cada dia, com suas tentações da carne e do mundo, traz consigo novos sofrimentos por Jesus Cristo. As feridas abertas e as cicatrizes que o cristão leva dessa luta são sinais concretos da comunhão na cruz de Jesus. Mas ainda há outro sofrimento e outra vergonha dos quais nenhum cristão é poupado, embora esteja certo que apenas a Paixão do próprio Cristo é sofrimento que realiza expiação. Contudo, porque Cristo sofreu pelos pecados do mundo, porque recaiu sobre ele todo o fardo da culpa, e porque ele partilha com seus discípulos o fruto de seu sofrimento, também têm de recair sobre os discípulos a tentação e o pecado, que os cobrem de grande vergonha e os expulsam, como bodes expiatórios, para fora dos portões da cidade. Dessa maneira, o cristão toma sobre si o pecado e a culpa de todos os seres humanos. O cristão não suportaria o peso desse fardo se não recebesse, ele próprio, a graça daquele que tomou sobre si todos os pecados. A única forma de o cristão suportar os pecados que recaem sobre ele é perdoando-os, mas só o poder da Paixão de Cristo torna isso possível. O cristão toma sobre si o fardo de outros — “Levai as cargas uns dos outros e, assim, cumprireis a lei de Cristo” (Gl 6.2). Assim como Cristo leva nosso fardo, levemos o fardo de nossos irmãos; essa lei de Cristo, que tem de ser cumprida, significa isto: carregar a cruz. O fardo do irmão que devo levar não são apenas sua aparência externa, sua maneira de ser ou seu temperamento, mas sobretudo seus pecados. E não há outro modo de fazê-lo a não ser perdoando-os no poder da cruz de Cristo, de que agora participo. Desse modo, o chamado de Jesus para tomarmos a cruz põe cada discípulo na comunhão do perdão dos pecados. O perdão dos pecados é o sofrimento de Cristo ordenado ao discípulo, e é imposto a todos os cristãos.

Como, porém, o discípulo saberá qual é sua cruz? Ele a receberá ao entrar no discipulado do Senhor sofredor; ele a reconhecerá na comunhão de Jesus.

Assim, o sofrimento torna-se a característica do discípulo de Cristo. Ele não está acima de seu Mestre.

O discipulado é passio passiva, é sofrimento obrigatório. Por isso Lutero pôde incluir o sofrimento entre os sinais da Igreja verdadeira. Em um esboço para a Confessio Augustana [Confissão de Augsburgo]

encontra-se a definição de Igreja como sendo a comunhão daqueles “que são perseguidos e torturados por causa do evangelho”. Quem não quer tomar sua cruz, quem não quer entregar a vida ao sofrimento e à rejeição por parte dos seres humanos, perde a comunhão com Cristo e não é discípulo. Mas, quem perde a vida no discipulado e carrega sua cruz, tornará a encontrá-la no próprio discipulado, na comunhão da cruz com Cristo. O contrário do discipulado é ter vergonha não só de Cristo, mas também da cruz; é ter raiva da cruz.

O discipulado é a união com o Cristo sofredor. Por isso, o sofrimento dos cristãos nada tem de estranho; antes, é muito mais graça e alegria pura. As histórias sobre os primeiros mártires da Igreja demonstram que Cristo confere um significado especial ao momento de maior sofrimento de seus discípulos com a certeza indescritível de sua proximidade e comunhão. Portanto, nos piores momentos do sofrimento que os mártires suportaram por causa de seu Senhor, foilhes concedida a máxima alegria e a bem-aventurança da comunhão com Cristo. Carregar a cruz comprovou ser a única possibilidade de vencer o sofrimento. Isso é válido para todos que seguem Cristo, porque foi válido para ele próprio. Adiantando-se um pouco, prostrou-se sobre o seu rosto, orando e dizendo: Meu Pai, se possível, passe de mim este cálice! Todavia, não seja como eu quero, e sim como tu queres. [...] Tornando a retirar-se, orou de novo, dizendo: Meu Pai, se não é possível passar de mim este cálice sem que eu o beba, faça-se a tua vontade.

Mateus 26.39,42

Jesus pede ao Pai que faça passar aquele cálice, e o Pai responde à prece do Filho. O cálice do sofrimento passará, mas somente após ser bebido. O próprio Jesus está ciente disso ao ajoelhar-se pela segunda vez no Getsêmani; sabe que o sofrimento passará, desde que o suporte até o final. Só será capaz de superar e vencer o sofrimento depois de tê-lo suportado. A cruz é sua vitória sobre o sofrimento.

Sofrer é ser afastado de Deus. Portanto, quem está em comunhão com Deus não pode sofrer. Jesus confirmou esse ensinamento do Antigo Testamento; por isso, ao tomar sobre si todo o sofrimento do mundo, vence-o. Ele carrega todo o peso do afastamento do mundo em relação a Deus. Somente ao beber do cálice do sofrimento é que Jesus pode vencê-lo. Ele quer vencer o sofrimento do mundo, e o único modo de fazê-lo é passar por toda a Paixão que lhe foi designada. E o sofrimento da humanidade por ela permanecer longe de Deus, agora, com a comunhão da Paixão de Jesus Cristo, é vencido com o próprio sofrimento, e a comunhão com Deus é dada justamente no sofrimento.

O sofrimento tem de ser suportado para que seja superado. Ou o mundo tenta suportá-lo e tomba sob seu peso, ou ele recai sobre Cristo e é vencido por ele. Assim, em vez de o mundo sofrer, Cristo sofre em seu lugar. Somente o sofrimento de Cristo é sofrimento que realiza expiação, mas, agora, a Igreja também sabe que o sofrimento do mundo está à procura de alguém que o carregue. Portanto, no discipulado de Cristo, esse sofrimento recai sobre a Igreja e ela tem de suportá-lo, sabendo-se, por sua vez, suportada por Cristo. A Igreja de Jesus Cristo, no discipulado da cruz, representa o mundo perante Deus.

Deus é um Deus que carrega. O Filho de Deus tomou sobre si nossa carne e, por isso, suportou a cruz, suportou todos os nossos pecados, trazendo a reconciliação. Do mesmo modo, o discípulo é chamado para carregar. Ser cristão é levar fardos. Assim como Cristo manteve a comunhão com o Pai ao levar

fardos, o discípulo, ao levar fardos, mantém a comunhão com Cristo. É certo que o ser humano também pode tentar livrar-se de seu fardo, mas, se o tentar, em vez de livrar-se passará a carregar um fardo muito mais pesado e insuportável; ele se submeterá a um jugo de sua própria escolha. Jesus convidou todos que levam fardos e sofrimentos de todo tipo para se submeterem a seu jugo, que é suave, e aceitarem seu fardo, que é leve. Seu jugo e seu fardo são a cruz. Submeter-se a essa cruz não é desgraça nem desespero, mas alívio e tranquilidade para a alma; é a máxima alegria. Já não se trata de leis e fardos que nós mesmos criamos, mas da submissão ao jugo daquele que nos conhece e que caminha conosco sob o mesmo jugo, onde certamente estamos junto dele e em sua comunhão. É a Cristo que o discípulo encontra ao tomar sobre si a sua cruz.

Você não deve agir de acordo com o seu entendimento, mas além dele; se você se atirar na insensatez, eu lhe darei meu entendimento. Não entender é o verdadeiro entender; não saber para onde vai, esse é o verdadeiro saber. Meu entendimento faz que você não entenda.

Abraão abandonou a terra natal sem saber para onde ia. Ele se entregou à minha sabedoria, abriu mão de sua própria e, dessa maneira, seguiu o caminho certo, chegando ao destino verdadeiro. Esse é o caminho da cruz, e você não consegue encontrá-lo sozinho; eu tenho de guiá-lo como se você fosse cego; por isso, nem você, nem ser humano algum, nem qualquer outra criatura, somente eu, eu mesmo, por meio de meu Espírito e de minha Palavra, posso ensinar o caminho a ser trilhado. Não é a obra que você escolher, nem o sofrimento que você preferir, mas é o caminho com que você depara não obstante sua escolha, seu pensamento e seu desejo — e é aí que eu chamo, é aí que você se torna discípulo; é a hora oportuna, o seu Mestre chegou. (Lutero)$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer insiste que sofrer e ser rejeitado não são a mesma coisa: a cruz de Jesus é sofrimento 'sem honra', e a nossa cruz é a rejeição 'por causa de Cristo', não o infortúnio comum da vida. Que sofrimentos você costuma chamar de 'minha cruz' que, examinados com sinceridade, são antes as angústias naturais da vida do que rejeição assumida por seguir Jesus?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Pedro tentou poupar Jesus da Paixão e ouviu 'Arreda, Satanás!' — e Bonhoeffer diz que assim Satanás entrou na Igreja, querendo vê-la 'livre da cruz de seu Senhor'. Onde você percebe, em si ou na sua comunidade, esse desejo bem-intencionado de ter um cristianismo sem cruz, que evita o sofrimento e a rejeição em nome do bom senso?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Para Bonhoeffer, a abnegação não é automartírio nem ascese escolhida, mas 'conhecer apenas a Cristo, e não mais a si próprio', a ponto de já não enxergar o peso da própria cruz porque só se vê a Ele. Na prática, o que mudaria nos seus dias se você parasse de olhar para as dificuldades do caminho e olhasse fixamente só para Cristo que vai à frente?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 5 — O discipulado e o indivíduo  (aula ordem = 7)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 7;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 5 — O discipulado e o indivíduo$t$,
      7,
$conteudo$Se alguém vem a mim e não aborrece a seu pai, e mãe, e mulher, e filhos, e irmãos, e irmãs e ainda a sua própria vida, não pode ser meu discípulo.

Lucas 14.26

O chamado de Jesus ao discipulado torna o discípulo um indivíduo. Querendo ou não, ele tem de se decidir, e tem de fazê-lo sozinho. Ser um indivíduo não é uma escolha própria; é Cristo que faz daquele que foi chamado um indivíduo. Cada qual é chamado individualmente, e sozinho deve seguir esse caminho. Com medo da solidão, o ser humano procura proteção junto às pessoas e às coisas que o rodeiam. De repente, dá-se conta de suas responsabilidades e apega-se a elas. Procura tomar sua decisão tentando esconder-se em suas obrigações, porque não quer se confrontar sozinho com Jesus, não quer ter de se decidir olhando fixamente para ele. Mas, nesse momento, nem pai nem mãe, nem esposa nem filhos, nem povo nem história podem ocultar aquele que foi chamado. Cristo quer que ele esteja só, que não veja ninguém, exceto aquele que o chama.

No chamado de Jesus, já está o rompimento do ser humano com as condições em que se acostumou a viver. Não é o discípulo que provoca esse rompimento, mas o próprio Cristo. Ao pronunciar o chamado, Cristo rompeu os laços do discípulo com o mundo, a relação direta com o mundo, e leva-o agora a relacionar-se diretamente com ele. Ninguém pode seguir a Cristo sem que reconheça e aceite esse rompimento. É uma ruptura que se realiza no chamado; não é a vontade de uma vida impulsiva que conduz a esse rompimento, mas apenas Cristo. Por que deve ser assim? Por que não poderia haver um crescimento gradual e contínuo, um processo lento e santificador das ordens naturais a fim de promover a comunhão com Cristo? Que poder inconveniente é esse que se intromete entre o ser humano e as ordens da vida natural que nos foram dadas por Deus? Acaso esse rompimento não resulta de um metodismo legalista? Não seria um lamentável desprezo dos bondosos dons de Deus que nada tem a ver com a liberdade cristã? O que é certo é que algo de fato se impõe como obstáculo entre aqueles chamados por Cristo e as circunstâncias da vida natural.

Não se trata, porém, de algo lamentável que revela desprezo à vida, não é uma lei de piedade; ao contrário, é a vida e o próprio evangelho, é o próprio Cristo. Com sua encarnação, Cristo se interpôs entre mim e as circunstâncias do mundo. Já não há volta; ele está no centro de tudo. Rompeu as relações diretas que aquele que foi chamado guardava com essas circunstâncias. Cristo quer ser o Mediador; tudo deve operar por seu intermédio. Ele não está apenas entre mim e Deus, mas também entre mim e o mundo, entre mim e os outros, entre mim e as coisas. Ele é o Mediador, não apenas entre Deus e o ser humano,

mas também entre um e outro ser humano, e entre o ser humano e a realidade. Porque todo o mundo foi criado por meio dele e para ele (Jo 1.3; 1Co 8.6; Hb 1.2), ele que é o único Mediador no mundo. Desde Cristo, já não existe relação direta entre o ser humano e Deus, entre o ser humano e o mundo; Cristo quer ser o Mediador. É bem verdade que muitos deuses se oferecem para garantir ao ser humano acesso direto, e também que o mundo procura, por todos os meios, obter acesso direto ao ser humano; mas justamente aí reside a inimizade com Cristo, o Mediador. Os deuses e o mundo querem tomar de Cristo o que ele lhes tomou, ou seja, a exclusividade da relação direta com o ser humano.

O rompimento dos laços diretos com o mundo nada mais é que o reconhecimento de Cristo como Filho de Deus e Mediador. Nunca é um ato de vontade própria, em que o indivíduo renuncia aos laços com o mundo por amor a um ideal, um ideal menor que se troca por outro maior. Isso seria puro entusiasmo, obstinação, sim, uma insistência na relação direta com o mundo. Somente o reconhecimento de um fato consumado, isto é, Cristo como Mediador, separa o discípulo de Jesus do mundo dos seres humanos e das coisas. Uma vez que o chamado de Jesus não seja entendido como um ideal, mas como a Palavra do Mediador, ele efetua em mim esse rompimento já consumado com o mundo. Se se tratasse de comparar ideias, seria necessário avaliar qual nos traria uma compensação; nesse caso, a balança talvez pendesse a favor de um ideal cristão, mas suas reivindicações jamais poderiam ser absolutas. Do ponto de vista do ideal, das “responsabilidades” da vida, não se justificaria uma radical desvalorização das ordens naturais da vida em benefício de um ideal de vida cristã. Ao contrário, poder-se-ia fazer uma avaliação inversa, e isso justamente do ponto de vista de um idealismo cristão, de uma responsabilidade e de uma ética de consciência cristã. Mas, visto que, nesse contexto, não se trata de modo algum de ideais, avaliações e responsabilidades, mas de fatos consumados e de seu reconhecimento, ou seja, da própria pessoa do Mediador que se interpõe entre nós e o mundo, por isso mesmo existe somente o rompimento da relação direta com o mundo, e por isso aquele que foi chamado deve se tornar indivíduo perante o Mediador.

Assim, o discípulo aprende que a relação que mantinha com o mundo era uma ilusão. Essa ilusão chama-se “relação direta, sem mediador, com o mundo”, e ela estorva o discípulo em questões de fé e obediência. Agora, porém, sabe que ele próprio já não pode manter relações diretas com o mundo, nem nas relações mais íntimas, aquelas que incluem responsabilidades familiares com pai, mãe e filhos, e também as relações amorosas e as responsabilidades sociais e históricas. Desde a vinda de Jesus, não existe mais para seus discípulos a possibilidade de relações sem o Mediador, quer sejam naturais e históricas, quer sejam cotidianas. Entre filho e pai, entre homem e mulher, entre indivíduo e sociedade, está Cristo, o Mediador, mesmo que não se saiba reconhecê-lo. Para nós, já não existe um caminho para o próximo que não seja Cristo, sua palavra e seu discipulado. A relação com o mundo sem o Mediador é pura ilusão. Por causa de Cristo, o Mediador, a relação direta com as situações naturais da vida deve ser tão odiada quanto a ilusão, que nos impede de ver a verdade. Qualquer comunhão que não nos permita ser um indivíduo perante Cristo, qualquer comunhão que reivindique autoridade sobre a relação direta com o

mundo, deve ser odiada por causa de Cristo, pois qualquer relação direta é, estejamos cientes disso ou não, ódio contra Cristo, o Mediador, mesmo e sobretudo quando se pretende cristã.

É um grave erro teológico usar a mediação de Jesus entre Deus e o ser humano para justificar as relações diretas com o mundo. Se Cristo é o Mediador, e assim se diz, então ele, portanto, carregou os pecados de nossas relações diretas com o mundo, justificando-nos nelas. Jesus é nosso Mediador perante Deus, a fim de que, com a consciência tranquila, possamos nos relacionar novamente com o mundo, este mesmo mundo que crucificou Jesus. Assim, o amor a Deus e o amor ao mundo são reduzidos a um mesmo amor. O rompimento com as circunstâncias do mundo passa a ser o malentendido “legalista” da graça de Deus que desejava livrar-nos justamente desse rompimento. As palavras de Jesus sobre o ódio às relações diretas com o mundo passam a ser entendidas como a jubilosa afirmação das “realidades do mundo dadas por Deus”. Da justificativa do pecador, mais uma vez surge a justificativa do pecado.

Para o discípulo, “as realidades do mundo dadas por Deus” só existem por meio de Jesus Cristo. O que não me é dado por Cristo, que se fez humano, não me foi dado por Deus. O que não me é dado por causa de Cristo não provém de Deus. A ação de graças pelas dádivas da criação ocorre por mediação de Jesus Cristo, e a prece pela preservação da graça desta vida se dá por causa de Cristo. Se não posso agradecer por Cristo, não o devo fazê-lo de modo algum, pois seria um pecado. O caminho do próximo, com quem convivo, para “as realidades do mundo dadas por Deus” também passa por Cristo, e se não passar por Cristo, é uma ilusão. Todas as nossas tentativas de superar o abismo que nos separa dos demais seres humanos, a distância intransponível até o outro, a diferença, a estranheza de nosso semelhante, por meio de relações naturais ou emocionais, todas essas tentativas estão fadadas ao fracasso. Não existe caminho direto entre os seres humanos. Não alcançamos nosso semelhante nem por meio da empatia mais amorosa, nem da psicologia mais elaborada, nem da franqueza mais natural; não há relação direta entre almas. Cristo é o Mediador. Apenas com sua mediação o caminho para o próximo se torna possível. Por isso, a intercessão é o melhor caminho para o outro, e a oração conjunta em nome de Cristo é a comunhão mais autêntica.

Não há conhecimento verdadeiro das dádivas de Deus sem o conhecimento de seu Mediador, e é somente por causa de Jesus que elas nos são dadas. Não há ação de graças verdadeira que seja feita para o povo, para a família, para a história ou para a natureza sem o arrependimento profundo que honre Cristo acima de tudo e de todos. Não há relação legítima com as circunstâncias do mundo criado, não há responsabilidades legítimas para com o mundo sem o reconhecimento do rompimento que dele já nos separou. Não há amor verdadeiro ao mundo a não ser o amor com que Deus amou este mundo em Jesus Cristo. “Não ameis o mundo” (1Jo 2.15), mas: “Deus amou ao mundo de tal maneira que deu o seu Filho unigênito, para que todo o que nele crê não pereça, mas tenha a vida eterna” (Jo 3.16).

Se o rompimento ocorre de maneira visível, no âmbito da família, do povo, quando somos chamados a exibir a todos a desonra de Cristo, quando somos chamados a assumir a acusação de misantropia ( odium generis humani [ódio ao gênero humano]), ou se ocorre ocultamente, quando só o indivíduo está ciente dele, embora sempre disposto a torná-lo visível a qualquer momento, isso ainda não constitui a diferença definitiva. Abraão é exemplo dos dois tipos de rompimento. Teve de romper amizades e deixar a casa

dos pais; Cristo se interpôs entre ele e sua família, entre ele e seus amigos. Nesse caso, o rompimento teve de se tornar visível. Abraão tornou-se estrangeiro por causa da terra prometida. Foi esse seu primeiro chamado. Mais tarde, é chamado novamente por Deus para sacrificar seu filho Isaque. Cristo se interpõe entre o pai da fé e o filho da promessa. O rompimento ocorre não apenas na relação direta natural, mas também na espiritual. Abraão tem de aprender que a promessa também não depende de Isaque, mas somente de Deus. Ninguém mais tem conhecimento desse segundo chamado de Deus, nem mesmo os servos que o acompanham ao sacrifício. Abraão se vê totalmente sozinho. Mais uma vez, é completamente um indivíduo, como quando deixou a casa dos pais. Aceita o chamado tal como lhe foi ordenado; não tenta interpretá-lo de maneira natural nem espiritual, mas aceita a palavra de Deus e se dispõe a obedecer. É obediente à ordem divina, contra toda relação direta natural, contra toda relação direta ética e religiosa. Leva o filho para o sacrifício. Quer que o rompimento, antes oculto, se torne visível, por causa do Mediador. E, naquele momento, tudo que ele ofereceu a Deus lhe é devolvido.

Abraão recebe seu filho de volta. O próprio Deus lhe providencia uma vítima melhor, que substituirá Isaque no sacrifício. É uma mudança completa. Abraão recebe Isaque de volta, mas agora, a partir do sacrifício, sua relação com o filho se dá por meio do Mediador, por causa do Mediador. Sendo aquele que estava pronto a ouvir a palavra de Deus e cumprir o que lhe fora ordenado, ele agora pode ter Isaque, mas de forma diferente; agora pode tê-lo pela mediação de Jesus Cristo. Ninguém mais sabe o que ocorreu. Abraão desce da montanha com Isaque exatamente como havia subido, mas agora tudo mudou.

Cristo se interpôs entre pai e filho. Abraão abandonara tudo e seguira a Cristo e, no meio do discipulado, recebe a permissão para viver novamente no mundo em que vivia antes. Aparentemente, tudo continua o mesmo, mas o mundo anterior passou; tudo se fez novo, tudo mudou. Tudo teve de passar por Cristo.

O episódio serve de exemplo para a outra possibilidade de tornar-se indivíduo, de tornar-se discípulo de Cristo no meio da comunidade, no meio do povo, na casa dos pais, junto aos bens e às posses. Mas é justamente Abraão quem foi chamado a essa existência, Abraão, que já havia tomado a decisão do rompimento visível, cuja fé se tornou padrão para o Novo Testamento. Bem que gostaríamos de generalizar essa possibilidade de Abraão, de entendê-la de maneira legalista, isto é, de transferi-la para nós mesmos sem maiores dificuldades. Essa seria também a nossa escolha na existência cristã, seguir Cristo, tornar-se indivíduo diante dele, sem nos desfazermos de nossos bens neste mundo. Mas uma coisa é certa: esse é o caminho mais fácil para o cristão, ou seja, é mais fácil ser levado ao rompimento externo que carregar em oculto esse rompimento na fé. Quem não sabe disso, quem não o aprendeu por meio das Escrituras nem da experiência, certamente se engana com o outro caminho. Será lançado de volta às relações diretas com o mundo e perderá a Cristo.

Não cabe a nós escolher esta ou aquela possibilidade; cabe a Jesus, é segundo a vontade dele que, de um modo ou de outro, seremos chamados para fora das relações diretas com o mundo, e aí então teremos de virar indivíduos, seja visivelmente, seja ocultamente

É, no entanto, exatamente o mesmo Mediador que nos torna indivíduos que também é o alicerce de toda a nossa nova comunhão. Ele está no centro, entre mim e os outros. Separa, mas também une. Assim, não

obstante estar fechado qualquer caminho direto até o outro, o caminho novo, o único e verdadeiro, até o outro nos será mostrado pelo Mediador.

Então, Pedro começou a dizer-lhe: Eis que nós tudo deixamos e te seguimos. Tornou Jesus: Em verdade vos digo que ninguém há que tenha deixado casa, ou irmãos, ou irmãs, ou mãe, ou pai, ou filhos, ou campos por amor de mim e por amor do evangelho, que não receba, já no presente, o cêntuplo de casas, irmãos, irmãs, mães, filhos e campos, com perseguições; e, no mundo por vir, a vida eterna. Porém muitos primeiros serão últimos; e os últimos, primeiros.

Marcos 10. 28-31 Nessa passagem, Jesus está falando àqueles que se tornaram indivíduos por causa dele, que tudo abandonaram quando ele chamou, que podem dizer sobre si mesmos: “Eis que nós tudo deixamos e te seguimos”. A eles é dada a promessa de uma nova comunhão. De acordo com as palavras de Jesus, receberão, já no presente, cem vezes mais do que deixaram para trás. Jesus referese à sua Igreja, que está nele. Quem abandona o pai por causa de Jesus com certeza encontra outro pai, encontra irmãos e irmãs, sim, até campos e casas lhe estão preparados. Cada qual entra sozinho no discipulado, porém nele ninguém fica só. A comunhão da Igreja é dada a quem ousa tornar-se indivíduo ao seguir as palavras de Jesus. Torna a encontrar-se numa irmandade visível, que o recompensa cem vezes por aquilo que perdeu com o rompimento. Cem vezes? Sim, porque agora ele tem tudo isso por meio de Jesus, o Mediador, o que significa igualmente “com perseguições”. “Cem vezes” — “com perseguições”, tal é a graça da Igreja que segue seu Senhor sob a cruz. Esta é, portanto, a promessa para os discípulos: tornarem-se membros da comunidade da cruz, povo do Mediador, povo sob a cruz.

Estavam de caminho, subindo para Jerusalém, e Jesus ia adiante dos seus discípulos. Estes se admiravam e o seguiam tomados de apreensões. E Jesus, tornando a levar à parte os doze, passou a revelar-lhes as coisas que lhe deviam sobrevir.

Marcos 10.32

Jesus sobe para Jerusalém, para a cruz, como que para confirmar três coisas: a seriedade de seu chamado ao discipulado, a impossibilidade de ser discípulo por vontade própria, e a promessa de pertencer a ele “com perseguições”. Os discípulos admiram-se e espantam-se com o caminho para o qual ele os chama.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer afirma que Cristo, o Mediador, se interpõe entre você e tudo — entre você e o pai, o cônjuge, o filho, o amigo — e que toda relação 'direta', sem essa mediação, é na verdade uma ilusão e até 'ódio contra Cristo', mesmo quando se pretende cristã. Que relação íntima sua você tem vivido como se fosse 'direta', sem deixar que Cristo esteja no centro dela?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto diz que ser indivíduo diante de Cristo não é escolha nossa, e que muitas vezes nos escondemos das nossas responsabilidades e afetos para não termos de nos decidir 'sozinhos, olhando fixamente para ele'. Em que obrigações ou laços você tem se escondido para evitar o confronto pessoal e solitário com o chamado de Jesus?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Abraão recebeu Isaque de volta, mas agora 'pela mediação de Cristo': desceu o monte com o mesmo filho, só que tudo havia mudado. Há algo ou alguém que você precisa primeiro entregar a Deus, no ponto de soltar de fato, para então receber de volta de um jeito novo — não mais como posse direta, mas pelas mãos de Cristo?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 6 — O "extraordinário" da vida cristã  (aula ordem = 8)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 8;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 6 — O "extraordinário" da vida cristã$t$,
      8,
$conteudo$Mateus 5

As bem-aventuranças

Jesus assentado no monte, a multidão, os discípulos. O povo vê: Jesus está com os discípulos que se reuniram em torno dele. Até bem pouco tempo, eles mesmos faziam parte daquela multidão. Em nada se distinguiam dos demais. Mas, quando ouviram o chamado de Jesus, deixaram tudo para trás e o seguiram.

Desde então, passaram a pertencer de corpo e alma a Jesus. Andam a seu lado, convivem com ele, seguem-no para onde quer que ele os leve. Aconteceu com eles algo que não aconteceu com os outros. É

um fato que o povo vê diante dos próprios olhos, uma realidade desconcertante e estranha.

Os discípulos veem: aquele é o povo do qual eles mesmos procedem, as ovelhas perdidas da casa de Israel. É a comunidade eleita de Deus. É a “igreja nacional”. Quando foram escolhidos dentre a multidão pelo chamado de Jesus, fizeram o que era evidente e necessário para as ovelhas perdidas da casa de Israel: seguiram a voz do Bom Pastor, pois a reconheciam. Porque seguiram esse caminho, pertencem ao povo, viverão no meio do povo, entrarão na vida dele e lhe proclamarão o chamado de Jesus e a glória do discipulado. Mas qual será o fim disso?

Jesus vê: aí estão seus discípulos. Deixaram abertamente o povo para juntar-se a ele. Ele chamou cada um deles, e tudo abandonaram diante de seu chamado. Agora, passam por privações e carências, dos pobres os mais pobres, dos tentados os mais tentados, dos famintos os mais famintos. Nada têm, senão ele. Sim, e com ele nada têm no mundo, em absoluto, mas têm tudo, tudo em Deus. A comunidade que ele encontrou é pequena, mas, olhando para o povo, é grande a comunidade que ele procura. Discípulos e povo formam uma só unidade. Os discípulos serão seus mensageiros; em toda parte, encontrarão quem ouça e creia. Apesar disso, sempre haverá inimizade entre eles. Toda ira contra Deus e sua palavra cairá sobre os discípulos e, como ocorreu com ele próprio, serão rejeitados. A cruz se aproxima. Cristo, os discípulos, o povo — aí está todo o cenário para a Paixão de Jesus e de sua Igreja.1

Por isso, Jesus dirige-se assim aos discípulos: Bem-aventurados (cf. Lc 6.20)! Fala aos que já estão sob o poder de seu chamado. Esse chamado fez deles pobres, aflitos e famintos. Ele os chama bemaventurados. Nem pobreza nem renúncia são, por si sós, motivo para bem-aventurança. Apenas o chamado e a promessa, pelos quais os discípulos vivem em pobreza e renúncia, são motivos suficientes.

Não se deve dar importância à observação de que, em algumas bem-aventuranças, fala-se expressamente de privação, em outras, de renúncia deliberada, ou ainda, de certas virtudes especiais dos discípulos. A

privação verdadeira e a renúncia pessoal têm uma origem comum; ambas partem do chamado e da promessa de Cristo. Nenhuma delas tem, sozinha, valor ou direito de reivindicar qualquer coisa. 2

Jesus declara seus discípulos bem-aventurados. O povo ouve o que ele diz e, espantado, testemunha o que está acontecendo; pois, de acordo com a promessa de Deus, a herança das bem-aventuranças, destinada a todo o povo de Israel, está sendo dada ao pequeno grupo de discípulos escolhidos por Jesus.

“Deles é o reino dos céus.” Mas discípulos e povo são um só; todos pertencem à comunidade eleita de Deus. Portanto, os votos de bemaventurança chamam todos a se decidirem e, desse modo, se salvarem. Todos são chamados a ser o que, na verdade, já são. Os discípulos são bem-aventurados por causa do chamado de Jesus, ao qual obedeceram. O povo todo é bem-aventurado por causa da promessa que lhe foi feita. Mas será que o povo de Deus aceitará a promessa crendo em Jesus Cristo e em sua palavra? Ou se afastará dele e de sua Igreja por não crer nele? É a pergunta que permanece sem resposta.

“Bem-aventurados vós, os pobres, porque vosso é o reino de Deus.” Os discípulos carecem de tudo.

Eles são “pobres” (Lc 6.20), não têm absolutamente nada, nenhuma segurança, nenhuma propriedade para chamar de sua, nenhum pedaço de terra para reclamar como pátria, nenhuma comunidade terrena com a qual partilhar a comunhão. Também, nenhuma força espiritual, nenhuma experiência, nenhum conhecimento que pudessem evocar para consolá-los. Por causa dele, haviam perdido tudo. Quando o seguiram, perderam a si próprios e, com isso, tudo que ainda pudesse torná-los ricos. Agora, estão tão pobres e sem experiência, tão ignorantes que já não podem esperar por nada senão por aquele que os chamou. Jesus também conhece aqueles outros, os representantes e pregadores da religião nacional, os poderosos e respeitados, enraizados firmemente na sociedade e em toda a tradição, no espírito da época, nos costumes e na piedade popular. Não é a eles que Jesus se dirige, mas apenas aos discípulos, dizendo:

“Bem-aventurados vós, porque vosso é o reino de Deus”. Para eles, que vivem em renúncia e privação por causa de Jesus, o reino dos céus se abrirá. Em meio à pobreza, são os herdeiros do reino dos céus.

Seu tesouro está muito bem escondido; está na cruz. O reino dos céus lhes é prometido na glória visível, e já lhes é dado na pobreza total da cruz.

Aqui, as bem-aventuranças de Jesus se distinguem completamente da caricatura que delas fazem na forma de programas políticos e sociais. O anticristo também declara os pobres bem-aventurados, mas não o faz por causa da cruz, que abrange toda a pobreza e na qual a pobreza é bem-aventurada, mas justamente para, mediante ideologias políticas e sociais, rejeitar a cruz. Pode, inclusive, chamar tal ideologia de cristã, e é exatamente o que o torna antagonista de Cristo.

“Bem-aventurados os que choram, porque serão consolados.” A cada nova declaração de bem-aventurança aumenta o abismo entre os discípulos e o povo. A separação do grupo de discípulos se torna mais visível. Os que choram são os que estão dispostos a viver na renúncia daquilo que o mundo considera felicidade e paz; são os que não dançam segundo a música do mundo, que não conseguem se acomodar a ele. Choram pelo mundo, por sua culpa, seu destino e sua felicidade. Enquanto o mundo festeja, ficam à parte; enquanto o mundo conclama: “Aproveitem a vida!”, estão se lamentando. Sabem que o navio em que se celebra a vida está afundando. O mundo sonha com o progresso, o poder, o futuro, mas os discípulos sabem do fim, do juízo final e da vinda do reino dos céus, para o qual o mundo não

está minimamente preparado. Por isso, os discípulos são estrangeiros no mundo, hóspedes indesejáveis, perturbadores da paz; logo, são rejeitados. Por que a Igreja de Jesus não pode tomar parte das festas celebradas no mundo? Acaso os discípulos deixaram de ter empatia por seus semelhantes? Será que caíram na tentação de odiá-los e desprezá-los? Não, ninguém entende melhor seu semelhante que a Igreja de Jesus. Ninguém o ama mais que seus discípulos — e é por isso mesmo que ficam de fora, é por isso que choram. É significativo e belo o termo usado por Lutero para traduzir o grego que aparece aqui como

“chorar”: Leidtragen [carregar o sofrimento]. Sim, “carregar”. A comunidade dos discípulos não lança fora o sofrimento de seu semelhante, como se nada tivesse a ver com ela; antes, o carrega consigo, chora por ele. É exatamente por meio dessa atitude que se comprova a solidariedade com seus semelhantes. Ao mesmo tempo, fica evidente que os discípulos não procuram caprichosamente o sofrimento nem dão as costas ao mundo por desprezo, mas carregam, por amor a Jesus Cristo e ao discipulado, o que lhes é imposto e tudo que lhes cabe. Por fim, é necessário dizer que o sofrimento não os enfraquece, não os consome, nem os torna amargurados ao ponto da exaustão. Pelo contrário, carregam o sofrimento que lhes é imposto na força daquele que os carrega, daquele que na cruz tudo suportou. Sendo aqueles que choram, que sofrem, estão na comunhão com o Crucificado. Estrangeiros são, estrangeiros permanecem, na força daquele tão estranho ao mundo que este acabou por crucificá-lo. Essa é a consolação deles, ou melhor, este é a consolação deles, o Consolador (cf. Lc 2.25). Portanto, a comunidade de estrangeiros no mundo também consolase na cruz, consola-se por ter sido lançada ao lugar onde o Consolador de Israel a aguarda. Assim, ela encontra seu verdadeiro lar junto ao Senhor crucificado, neste tempo e na eternidade.

“Bem-aventurados os mansos, porque herdarão a terra.” Não há direito inerente que proteja essa comunidade de estrangeiros no mundo. Tampouco exigem tal condição, pois são os mansos que, por causa de Cristo, vivem em renúncia a qualquer direito especial. Quando ofendidos, calam-se; quando agredidos, suportam; quando rejeitados, afastam-se. Não movem processos por seus direitos, não fazem alarde mesmo quando injustiçados. Nada reivindicam, mas entregam toda justiça nas mãos de Deus; non cupidi vindictae [sem desejo de vingança], assim interpretava a Igreja antiga. O que serve a seu Senhor igualmente lhes serve. Nada mais que isso. Em cada palavra, em cada gesto, deixam claro que não pertencem a este mundo. Deixemos-lhes o céu, diz o mundo em tom de piedade, o lugar deles é lá. 3 Jesus, porém, diz: “... herdarão a terra”. A terra pertence aos que não têm nenhum direito, nenhum poder. Os que agora a possuem mediante a violência e a injustiça tudo perderão, e os que aqui renunciaram a ela, os que foram mansos até a cruz, herdarão a nova terra. Não se trata de enxergar aqui uma teoria de punição divina para compensar injustiças no mundo (Calvino), mas, quando vier o reino dos céus, a terra será renovada e se tornará a terra da Igreja de Jesus. Deus não abandona o mundo; ele o criou. Enviou ao mundo seu próprio Filho e aqui construiu sua Igreja. Portanto, é nesta era que se inicia a Igreja de Cristo. Foi dado um sinal. Já agora, um pedaço de terra foi dado aos destituídos de poder: eles têm a Igreja, a comunhão com ela, seus bens, os irmãos e as irmãs — em meio à perseguição até a cruz. Mas também o Gólgota é um pedaço de terra. A partir do Gólgota, onde morreu o Manso, a terra será renovada. Quando vier o reino de Deus, os mansos herdarão a terra.

“Bem-aventurados os que têm fome e sede de justiça, porque serão fartos.” Os discípulos vivem não apenas a renúncia de seus direitos individuais, mas também a renúncia de sua justiça própria. Não esperam nenhuma glória para si mesmos no que fazem ou sacrificam. Para eles, a única justiça a que têm direito é ter fome e sede de justiça; sem direito nem à justiça própria nem à justiça divina sobre a terra, vivem na expectativa da justiça futura de Deus, mas não podem eles mesmos estabelecê-la. Os seguidores de Jesus sentem fome e sede ao longo do caminho. Anseiam pelo perdão de todos os pecados e por renovação completa, pela renovação da terra e pela justiça completa de Deus. No entanto, a maldição do mundo ainda está sobre eles, ainda recai sobre eles o pecado do mundo. Aquele a quem seguem tem de morrer amaldiçoado na cruz. Suas últimas palavras são um clamor desesperado por justiça: “Deus meu, Deus meu, por que me desamparaste?” (Mt 27.46). Mas os discípulos não estão acima de seu mestre; seguem-no. Por isso são bem-aventurados, pois têm a promessa de satisfação. Receberão justiça não apenas pelo ouvir, mas serão fartos corporalmente com justiça. Comerão o pão da vida verdadeira na Ceia futura, ao lado do Senhor. São bem-aventurados por causa do futuro pão, que já receberam no presente. Aquele que é o Pão da Vida está no meio dos que têm fome. Essa é a bem-aventurança dos pecadores.

“Bem-aventurados os misericordiosos, porque alcançarão misericórdia.” Esses desprovidos de posses, estrangeiros na terra, destituídos de poder, pecadores, esses discípulos de Jesus vivem com ele também na renúncia à própria dignidade, pois são misericordiosos. Não bastasse a própria privação e aflição, compartilham ainda a aflição, a humilhação e a culpa dos outros. Sentem amor irreprimível aos pobres, enfermos, miseráveis, humilhados e oprimidos, injustiçados e marginalizados, a todos que sofrem com angústia; procuram os que caíram no pecado e na culpa. Nenhuma aflição é grande demais, nenhum pecado é horrível demais para sua misericórdia. Concedem sua própria honra ao que caiu em desgraça, e tomam sobre si a desonra do outro. Saem à procura de publicanos e pecadores e aceitam abertamente a vergonha de sua companhia. Além de misericordiosos, renunciam ao maior bem que o ser humano pode possuir, isto é, a própria honra e dignidade. Conhecem apenas uma dignidade e honra: a misericórdia do Senhor, em função da qual vivem. Ele não se envergonha de seus discípulos, ele que se fez irmão dos seres humanos e carregou a vergonha deles até a morte na cruz. Essa é a misericórdia de Jesus, e é por ela que desejam viver os que estão ligados a ele; é a misericórdia do Crucificado. Ela faz que esqueçam a própria honra e dignidade e procurem a companhia dos pecadores. E, ainda que vergonha caia sobre eles, mesmo assim são bem-aventurados, pois receberão misericórdia. Um dia, Deus virá e tomará sobre si o pecado e a vergonha deles. Deus lhes concederá sua própria honra e tirará a desonra deles. Será a honra de Deus levar a vergonha dos pecadores e revesti-los com sua honra. Bem-aventurados os misericordiosos, porque têm o Misericordioso como Senhor.

“Bem-aventurados os limpos de coração, porque verão a Deus.” Quem é limpo de coração? Só aquele que o entregou inteiramente a Jesus, para que ele, somente ele, reine ali; só aquele não polui o coração nem pelo próprio mal, nem pelo próprio bem. O coração limpo é o coração simples da criança, que não conhece o bem nem o mal. É o coração de Adão antes da queda, o coração onde reina não a consciência, mas a vontade de Jesus. Quem vive na renúncia ao próprio bem e ao próprio mal, na renúncia ao

próprio coração, que vive em arrependimento e confia somente em Jesus, esse tem o coração limpo pela palavra de Jesus. A pureza de coração é diferente de toda pureza externa, incluindo a pureza da boa intenção. O coração limpo está isento do bem e do mal; pertence inteiramente a Jesus. É um coração que só vê Jesus, aquele que caminha à sua frente. Só verá a Deus quem, nesta vida, olhar exclusivamente para Jesus Cristo, o Filho de Deus. Seu coração é livre de imagens impuras, não vive oscilando na variedade de seus desejos e intenções; está totalmente voltado para a contemplação de Deus. Só verá a Deus aquele cujo coração se tornou espelho da imagem de Cristo.

“Bem-aventurados os pacificadores, porque serão chamados filhos de Deus.” Os discípulos de Jesus são chamados à paz. Ao serem chamados por Jesus, encontraram a paz. Jesus é sua paz. Agora, não só devem possuir essa paz, mas também fazer paz. 4 Desse modo, renunciam à violência e à rebelião. Nem esta nem aquela jamais serviram à causa de Cristo. O reino de Cristo é reino de paz, e a Igreja de Cristo saúda com votos de paz. Os discípulos de Jesus sempre conservam a paz. Preferem sofrer a fazer o mal.

Mantém a comunhão, mesmo quando o outro a rompe. Renunciam à autoafirmação e suportam, em silêncio, o ódio e a injustiça. Com isso, vencem o mal com o bem; praticam a paz de Deus em meio a um mundo de ódio e guerra. Contudo, em nenhum lugar haverá paz maior do que quando enfrentarem, em paz, os que praticam o mal, dispondo-se a sofrer nas mãos deles. Praticando a paz, carregarão a cruz com seu Senhor, pois na cruz se fez paz. Porque estão envolvidos na obra de paz de Cristo, porque são chamados à obra do Filho de Deus, receberão o nome de filhos de Deus.

“Bem-aventurados os perseguidos por causa da justiça, porque deles é o reino dos céus.” Não se trata aqui da justiça de Deus, mas do sofrimento por causa justa, 5 por causa do juízo e da ação legítimos por parte dos discípulos de Jesus. Os que seguem Jesus na renúncia a bens, felicidade, direito, justiça, honra e poder se distinguirão do mundo no modo de julgar e agir; serão, por isso, hóspedes indesejáveis. Por causa da justiça, os discípulos serão perseguidos. Em lugar de reconhecimento pela palavra e obra que realizarão no mundo, receberão apenas rejeição. Por isso é importante que Jesus declare seus discípulos bem-aventurados não só pelo sofrimento direto resultante de perseguições por terem confessado seu amor ao nome dele, mas também quando sofrem por causa justa. Eles compartilham a mesma promessa com os pobres. Na condição de perseguidos, equivalem-se a eles. No final das bem-aventuranças, surge a pergunta: ainda haveria de fato um lugar neste mundo para uma Igreja assim? Tornou-se claro que para ela só há um lugar possível, lá onde estão os mais pobres, os mais tentados, os mais mansos: a cruz do Gólgota. A Igreja dos bem-aventurados é a Igreja do Crucificado. Com ele, tudo perdeu e, ao mesmo tempo, tudo encontrou. A partir da cruz, tudo consiste em: Bem-aventurados, bem-aventurados! Agora, Jesus fala apenas aos que podem entendê-lo, seus discípulos, e por isso ele fala diretamente: “Bem-aventurados sois quando, por minha causa, vos injuriarem, e vos perseguirem, e, mentindo, disserem todo mal contra vós. Regozijai-vos e exultai, porque é grande o vosso galardão nos céus; pois assim perseguiram aos profetas que viveram antes de vós” (Mt 5.11-12). “Por minha causa” — os discípulos são rejeitados, mas a rejeição recairá sobre o próprio Jesus. Sobre ele recai tudo, pois é por sua causa que são rejeitados. Ele carrega a culpa. O insulto, a perseguição mortal e a calúnia maldosa confirmam a bemaventurança dos discípulos em sua comunhão com Jesus. Sem

dúvida, o mundo se voltará contra esses estrangeiros, esses mansos, por meio de palavras, violência e difamação. A voz desses humildes e mansos se faz ouvir e é ameaçadora, e seu sofrimento é por demais paciente e silencioso. Sim, também é impressionante o testemunho dos discípulos de Jesus, por meio da pobreza e do sofrimento, contra a injustiça no mundo. Isso é mortal. Enquanto Jesus declara: Bem-aventurados, bem-aventurados!, o mundo grita: Fora, fora! Sim, fora! Mas para onde? Para o reino dos céus. “Regozijai-vos e exultai, porque é grande o vosso galardão nos céus.” Lá os pobres estão nos salões de festa. O próprio Deus enxuga as lágrimas dos olhos dos que choravam, e serve sua Ceia aos que tinham fome. O corpo ferido e martirizado lá está em toda a sua glória, não revestido de pecado e de arrependimento, mas com o manto branco da justiça eterna. Dali, da alegria eterna, chega o chamado para a Igreja dos discípulos sob a cruz, o chamado de Jesus: Bem-aventurados, bem-aventurados!

A Igreja visível Vós sois o sal da terra; ora, se o sal vier a ser insípido, como lhe restaurar o sabor? Para nada mais presta senão para, lançado fora, ser pisado pelos homens. Vós sois a luz do mundo. Não se pode esconder a cidade edificada sobre um monte; nem se acende uma candeia para colocá-la debaixo do alqueire, mas no velador, e alumia a todos os que se encontram na casa. Assim brilhe também a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem a vosso Pai que está nos céus.

Mateus 5.13-16

Essas palavras são dirigidas aos que, nas bem-aventuranças, foram chamados à graça do discipulado do Crucificado. Até aqui, os bemaventurados eram tidos como dignos do reino dos céus, mas, para este mundo, inteiramente indignos e desnecessários. A partir de agora, porém, Jesus os têm como os mais imprescindíveis. Eles são o sal da terra. São os que têm maior valor, o bem mais precioso. Sem eles, a terra não consegue subsistir. É o sal que preserva a terra, e ela existe exatamente por causa desses pobres, indignos e fracos que o mundo despreza. Ao rejeitar os discípulos, a terra destrói sua própria vida e — milagre! — justamente por causa desses rejeitados pode continuar a existir. Esse “sal divino”

(Homero) conserva-se em seu poder de ação. Ele permeia toda a terra; é sua substância. Assim, os discípulos não pensam somente no reino dos céus, mas são constantemente lembrados de sua tarefa no mundo. Sendo aqueles que estão ligados apenas a Jesus, são enviados à terra de que são o sal. Jesus, ao chamar seus discípulos em vez de designar a si mesmo sal da terra, transfere a eles seu poder de ação.

Ele os inclui em sua tarefa no mundo. Ele próprio se mantém junto ao povo de Israel, mas a seus discípulos confia a terra inteira. A terra só poderá ser conservada pelo sal se o sal nunca deixar de ser sal e preservar sua força purificadora e temperante. Assim como o sal tem de permanecer sal, para o seu bem e para o bem da terra, a Igreja dos discípulos deve permanecer sendo o que é pelo chamado de Cristo. É nisso que consiste seu verdadeiro poder de ação e sua força de conservação. O sal não se deve deixar corromper, para, assim, ser um poder constante de purificação. Por isso recorre-se ao sal nos sacrifícios do Antigo Testamento, e por isso coloca-se sal na boca da criança no rito católico do batismo (Êx 30.35; Ez 16.4). A garantia da permanência da Igreja está no sal que não se deixa corromper.

Jesus não diz: “Vós deveis ser o sal da terra”, mas “Vós sois o sal da terra”. Não cabe aos discípulos escolher se querem ou não ser o sal da terra. Não há um apelo para que sejam o sal da terra. Eles o serão,

queiram ou não, no poder do chamado que lhes foi dirigido. “Vós sois o sal”, e não “Vós tendes o sal”.

Seria uma simplificação se, com os reformadores, quiséssemos considerar o sal a mensagem dos discípulos. É toda a existência deles, na medida em que é renovada pelo chamado de Cristo ao discipulado, é a vida de que falam as bem-aventuranças. Aquele que, chamado por Cristo, está no discipulado é, por meio do chamado, o sal da terra com toda a sua existência.

A outra possibilidade, porém, é o sal tornar-se insípido e, portanto, deixar de ser sal. Perde seu poder.

Sem dúvida, nesse caso para nada serve e deve ser lançado fora. Sua função é salgar. Mas o sal que se torna insípido já não servirá para salgar. Tudo pode ser salvo pelo sal, mesmo o elemento mais estragado; só não há esperança para o sal que perdeu o sabor. Esse é o outro lado da discussão. É o juízo ameaçador que paira sobre a Igreja dos discípulos. A terra deve ser salva pela Igreja dos discípulos, mas a Igreja que deixa de ser o que é está irrecuperavelmente perdida. O chamado de Jesus é ser o sal da terra ou ser destruído, é tornar-se discípulo ou ser destruído pelo próprio chamado. Não há outra possibilidade de salvação. Não pode haver. O chamado de Jesus não confere à comunidade dos discípulos apenas o poder invisível do sal, mas também o poder de iluminar, de ser o brilho visível da luz. Novamente, Jesus não diz: “Vós deveis ser a luz”, mas: “Vós sois a luz”. O próprio chamado transformou os discípulos em luz. Não há outra possibilidade: eles são uma luz que é vista; do contrário, o chamado não lhes teria sido dirigido. Que objetivo impossível, sem sentido, para os discípulos de Jesus, para esses discípulos, quererem ser a luz do mundo! Eles já se tornaram luz no momento em que houve o chamado ao discipulado. Mais uma vez, Jesus não fala: “Vós tendes a luz”, mas: “Vós sois a luz”. Também não diz que algo lhes foi dado, ou que sua mensagem é a luz, mas que eles mesmos são a luz. O mesmo Jesus que diz: “Eu sou a luz do mundo”, diz a seus discípulos: “Vós sois a luz em toda a sua vida, enquanto permanecerdes no chamado. E, mesmo que o quisésseis, não podeis mais ficar escondidos, pois vós sois a luz”. A luz brilha, e “não se pode esconder a cidade edificada sobre o monte”. É impossível! Seja como cidade segura, castelo fortificado, seja à beira da ruína, a cidade edificada sobre o monte é visível de longe. Essa cidade é a comunidade dos discípulos — que israelita não pensou em Jerusalém, a cidade edificada sobre o monte? Assim, os discípulos nada mais precisam decidir: a única decisão possível já foi tomada. Agora eles têm de ser o que são, ou então não são seguidores de Jesus. Os discípulos são a Igreja visível, seu discipulado é a ação visível pela qual se destacam do mundo — ou então, definitivamente, não são discípulos. E, de fato, o discipulado é tão visível como a luz na noite, como o monte que se levanta na planície.

A fuga para a invisibilidade é a negação do chamado. Igreja de Jesus que queira ser invisível não é mais Igreja do discipulado. “Nem se acende uma candeia para colocá-la debaixo do alqueire, mas no velador.” Eis a outra possibilidade: ocultar a luz propositadamente colocando-a debaixo de um alqueire, isto é, não aceitar o chamado. O alqueire sob o qual a Igreja visível oculta sua luz pode ser tanto o medo do ser humano como a tentativa de conformar-se com o mundo visando a algum outro objetivo — um propósito missionário, por exemplo, ou mesmo um amor equivocado pelo ser humano! Pode ser, também, e então ainda mais perigoso, uma suposta teologia reformada que ousa se apresentar como theologia crucis [teologia da cruz] e que propõe, em lugar de uma visibilidade “farisaica”, uma invisibilidade

“humilde”, de modo que a Igreja acabe assim mesmo se conformando com o mundo. Tal Igreja se caracterizaria não pela visibilidade extraordinária, mas por estar de acordo com a justitia civilis. Nesse contexto, o critério para ser cristão é exatamente que a luz não brilhe. Jesus, porém, afirma: “Assim brilhe também a vossa luz diante dos homens”. Em todo caso, o que brilha é a luz do chamado de Cristo.

Mas que tipo de luz é essa em que devem brilhar os seguidores de Jesus, os discípulos das bem-aventuranças? Que espécie de luz deve brilhar do lugar reservado unicamente aos discípulos? O que a invisibilidade e a obscuridade da cruz de Jesus, sob a qual vivem os discípulos, têm a ver com a luz que deve brilhar? Essa obscuridade não significaria que os discípulos têm de se manter ocultos na vida de discipulado, em vez de viverem na luz? É um perigoso sofisma, esse de defender a conformação da Igreja com o mundo justamente com base na cruz de Jesus. Acaso não está evidente, mesmo para o ouvinte comum, que na cruz algo muito extraordinário se tornou visível? Ou tudo não passaria de justitia civilis, isto é, a cruz significando nada mais que adequação ao mundo das leis civis? Será que a cruz não foi algo espantoso à vista de todos, claramente visível em meio à total escuridão? Não é visibilidade suficiente a rejeição e o sofrimento de Cristo, sua vida terminada diante dos portões da cidade, sobre o monte da vergonha? Acaso tudo isso é invisível?

Nessa luz é que devem ser vistas as boas obras dos discípulos. Não são os discípulos que devem ser vistos, mas suas boas obras, diz Jesus. O que são essas boas obras que devem ser vistas nessa luz? Nada mais que as obras que o próprio Jesus criou neles ao chamálos para serem a luz do mundo sob a cruz—

pobreza, estranheza, mansidão, paz e, por fim, perseguição e rejeição. Em tudo isso, apenas uma coisa importa: tomar sobre si a cruz de Cristo. A cruz é a luz singular que brilha, e é só nela que todas as boas obras dos discípulos podem ser vistas. Não se está dizendo que, desse modo, Deus se faz visível, mas que as “boas obras” sejam vistas e as pessoas louvem a Deus por causa delas. Tornam-se visíveis a cruz e as obras da cruz, e também a privação e a renúncia dos bem-aventurados. Por causa da cruz e de uma Igreja assim, somente Deus pode ser louvado, e não mais o ser humano. Se as boas obras fossem virtudes do ser humano, os discípulos é que seriam louvados, e não o Pai. Desse modo, porém, nada há que ser louvado nos discípulos que carregam a cruz, nem na Igreja visível edificada sobre o monte, de onde a luz brilha; por causa das “boas obras”, apenas o Pai no céu pode ser louvado. Assim, as pessoas veem a cruz e a Igreja da cruz e creem em Deus. Tal é, porém, a luz da ressurreição.

A justiça de Cristo

Não penseis que vim revogar a Lei ou os Profetas; não vim para revogar, vim para cumprir. Porque em verdade vos digo: até que o céu e a terra passem, nem um i ou um til jamais passará da Lei, até que tudo se cumpra. Aquele, pois, que violar um destes mandamentos, posto que dos menores, e assim ensinar aos homens, será considerado mínimo no reino dos céus; aquele, porém, que os observar e ensinar, esse será considerado grande no reino dos céus. Porque vos digo que, se a vossa justiça não exceder em muito a dos escribas e fariseus, jamais entrareis no reino dos céus.

Mateus 5.17-20

Não é nada surpreendente que os discípulos, tendo recebido as promessas de seu Senhor, nas quais tudo que tinha valor para o povo era desvalorizado e tudo que não tinha valor era declarado bem-aventurança,

considerassem que a lei houvesse sido revogada. Jesus se dirigira a eles e os designara como aqueles a quem tudo fora concedido pela livre graça de Deus, aqueles que agora tudo possuíam e que certamente herdariam o reino dos céus. Desfrutavam a comunhão completa e pessoal com Cristo, que renovara todas as coisas. Eram o sal, a luz, a cidade edificada sobre o monte. Assim, tudo que era antigo havia passado e sido substituído. Aproximava-se, portanto, o tempo em que Jesus romperia definitivamente com tudo que era antigo, revogando a lei da antiga aliança e, na liberdade do Filho, declarando-a inválida para sua Igreja. Depois de tudo, afinal, talvez os discípulos viessem mesmo a pensar como Marcião, que, alegando uma falsificação judaísta do texto, assim o alterou: “Pensais que vim cumprir a Lei ou os Profetas? Eu vim para revogar, não para cumprir”. Muitos, desde então, leram e interpretaram as palavras de Jesus na mesma linha de Marcião. Jesus, porém, diz: “Não penseis que vim revogar a Lei ou os Profetas...”. Portanto, Cristo cumpre a lei da antiga aliança.

Como entender isso? Sabemos que Jesus está se dirigindo aos discípulos, aos que têm compromisso exclusivo com ele. Lei nenhuma poderia impedir a comunhão de Jesus com seus seguidores, como ficou claro na leitura de Lucas 9.57ss. O discipulado é compromisso direto com Jesus Cristo, somente. Mesmo assim, surge aqui o inesperado compromisso dos discípulos com a lei do Antigo Testamento. Jesus diz duas coisas diferentes a seus seguidores: a primeira é que o compromisso com a lei ainda não se caracteriza como discipulado; a segunda é que o compromisso com a pessoa de Jesus Cristo, sem lei, não pode ser considerado discipulado. Ele compromete com a lei aqueles a quem concedeu sua promessa e comunhão completas. E, porque é a ele que os discípulos seguem, a lei vigora para eles. Vem, então, a pergunta: o que é válido, Cristo ou a lei? Com que estou comprometido? Somente com ele ou de novo com a lei? Cristo tinha dito que lei nenhuma deveria se pôr entre ele e os discípulos. Agora, porém, afirma que a revogação da lei significaria separação dele. O que isso quer dizer?

A lei, no caso, é a da antiga aliança, não uma nova, mas aquela mesma antiga lei, à qual são remetidos também o jovem rico e o ardiloso intérprete da lei, como sendo a vontade revelada de Deus. Somente porque Cristo compromete seus discípulos com essa lei é que ela se torna novo mandamento. Não se trata, portanto, de uma “lei melhor” que a dos fariseus; é a mesma e única lei, que deve ser cumprida até o final dos tempos, sem deixar passar nem uma letra, nem um i ou um til. Trata-se, isto sim, de uma justiça melhor, “justiça que excede” a dos fariseus. Quem não tem essa justiça que excede não entrará no reino dos céus, exatamente porque se afastou do discipulado de Jesus que o comprometera com a lei.

Contudo, ninguém alcançará essa justiça senão aquele a quem Cristo se dirige, a quem ele chama. A condição para a justiça que excede é o chamado de Cristo, é o próprio Cristo.

Pode-se compreender, portanto, o fato de Cristo, nesse ponto do Sermão do Monte, falar pela primeira vez a respeito de si mesmo. Ele próprio se interpõe entre os discípulos e a justiça que excede e que exige deles. Ele veio para cumprir a lei da antiga aliança; esse é o pressuposto para tudo o mais. Jesus está em pleno acordo com a vontade de Deus no Antigo Testamento, “na Lei e nos Profetas”. Com efeito, nada tem a acrescentar aos mandamentos de Deus; ele os cumpre. Na verdade, isto ele acrescenta: o cumprimento dos mandamentos. Cumpre a lei, e afirma isso a seu próprio respeito; por isso é verdade.

Ele a cumpre sem deixar passar nem um i sequer. Com isso, porém, “tudo se cumpriu”, isto é, tudo que

deve acontecer para seu cumprimento. Jesus fará o que a lei exige, por isso terá de morrer; pois somente ele entende essa lei como a lei de Deus, ou seja, nem a lei é Deus, nem Deus é a lei, como se Deus pudesse ser substituído pela lei. Foi assim que Israel entendeu a lei equivocadamente. O pecado de Israel, portanto, foi a divinização da lei e a legalização de Deus. Por sua vez, o mal-entendido pecaminoso dos discípulos teria sido a negação da natureza divina da lei e a separação de Deus de sua lei. Nos dois casos, ou Deus e a lei foram separados, ou foram identificados como sendo uma só coisa, o que dá no mesmo. Os judeus identificaram Deus com a lei e, assim, visavam controlar Deus com a lei. Deus e a lei se tornaram um só; não havia mais o Senhor acima da lei. Os discípulos, por sua vez, imaginaram equivocadamente que podiam separar Deus de sua lei e, assim, visavam também controlar Deus, como se fossem donos da salvação. Em ambas as situações, confundiam-se dádiva e doador, e Deus era negado com a ajuda da lei ou com a promessa de salvação.

A fim de evitar os dois equívocos, Jesus restabelece a lei como sendo a lei de Deus. Deus é o doador e Senhor da lei, e ela só é cumprida na comunhão pessoal com ele. É impossível o cumprimento da lei sem a comunhão com Deus. A primeira condição é válida para os judeus, e a segunda, para o iminente mal-entendido dos discípulos.

Jesus, o Filho de Deus, o único que vive em completa comunhão com Deus, faz a lei vigorar novamente, porque vem para cumprir a lei da antiga aliança. Só ele pode ensinar a lei e seu cumprimento correto, ele que foi o único capaz de fazê-lo. Quando Jesus lhes disse isso, os discípulos tinham de saber e entender, pois tinham ciência de quem ele era. Os judeus, por sua vez, não poderiam entender enquanto não cressem nele. Assim, rejeitavam sua doutrina da lei como blasfêmia contra Deus, ou melhor, blasfêmia contra a lei de Deus. Por isso Jesus teve de sofrer, nas mãos dos advogados da falsa lei, por causa da verdadeira lei de Deus. Morre na cruz como blasfemo, como transgressor da lei, porque fez vigorar a lei verdadeira em oposição à lei falsificada e mal entendida.

O cumprimento da lei a que Jesus se refere não pode ocorrer de outra forma senão pela crucificação de Jesus como pecador. Sua própria crucificação é o cumprimento perfeito da lei.

Isso equivale a dizer que apenas Jesus Cristo pode cumprir a lei, porque só ele está em comunhão completa com Deus. Ele mesmo se interpõe entre seus discípulos e a lei, enquanto a lei não se interpõe entre ele e seus discípulos. O caminho dos discípulos até a lei passa pela cruz de Cristo. É dessa maneira que Jesus une os discípulos a si próprio, remetendo-os à lei, que só é cumprida por ele. O compromisso sem lei é rejeitado, pois é puro entusiasmo e não é mais compromisso; antes, é total libertinagem. É

desfeita, porém, a preocupação dos discípulos de que o compromisso com a lei os separaria de Jesus.

Essa preocupação só podia ser resultado do mal-entendido a respeito da lei, equívoco que, de fato, separa os judeus de Deus. Em vez disso, fica claro que o compromisso verdadeiro com Jesus só pode se dar no compromisso com a lei de Deus.

Jesus, portanto, se interpõe entre os discípulos e a lei, mas isso não significa que os discípulos estejam isentos de cumprir a lei; ao contrário, Jesus está ali para restabelecer a exigência de seu cumprimento. E, justamente o compromisso com ele exige dos discípulos o cumprimento da lei. Eles se veem na necessidade de cumprir a lei rigorosamente, cada i e cada til. Deve ser cumprida, e isso é tudo. Por isso

mesmo ela só agora vigora plenamente, e é por isso que grande será o reino dos céus para quem cumpre e ensina a lei. “Pratique e ensine” — pode-se até levantar a possibilidade de uma doutrina da lei que não exija sua própria prática, que sirva apenas para ensinar que seu cumprimento é impossível. Uma doutrina tal, porém, não pode ser evocada a partir de Jesus. A lei deve ser praticada como de fato ele a praticou.

Quem permanece com ele no discipulado, com ele que cumpriu a lei, pratica e ensina a lei no discipulado. Na comunhão com Jesus, só pode permanecer aquele que cumpre a lei.

Não é lei, mas a “justiça que excede”, o que distingue o discípulo do judeu. A justiça dos discípulos excede a dos fariseus. Ela a supera, é algo extraordinário, especial. Pela primeira vez aparece o termo perisseuein [exceder], que virá a ter enorme importância no versículo 47. Devemos perguntar: em que consiste a justiça dos fariseus? Em que consiste a dos discípulos? Certamente os fariseus jamais incorreram no erro, contrário às Escrituras, de afirmar que bastava ensinar a lei sem ter de praticá-la.

Eles queriam praticar a lei. Sua justiça consistia no cumprimento direto e ao pé da letra do que a lei ordenava. Sua justiça era sua prática. Seu objetivo era a conformidade completa de suas ações com o que era ordenado na lei. No entanto, sempre restava algo que tinha de ser resolvido pelo perdão. Sua justiça era imperfeita. A justiça dos discípulos poderia, também, consistir apenas no cumprimento da lei. Só poderia ser considerado justo quem praticasse a lei. A prática dos discípulos, porém, supera a dos fariseus porque, na verdade, é justiça perfeita se comparada à dos fariseus. Como isso é possível? O

mérito da justiça do discípulo consiste em que, entre ele e a lei, está aquele que cumpriu a lei inteiramente, aquele com quem o discípulo está em completa comunhão. Ele não viu diante de si uma lei a ser cumprida, mas uma lei já cumprida. Antes mesmo que comece a praticar a lei, ela já foi cumprida, sua exigência já foi satisfeita. A justiça que a lei exige já está ali; é a justiça de Jesus, que vai à cruz por causa da lei. Uma vez que essa justiça não consiste apenas em fazer o bem, mas na comunhão pessoal, verdadeira e completa com Deus, Jesus não apenas tem a justiça, mas é também a própria justiça. Ele é a justiça dos discípulos. Com seu chamado, Jesus tornou os discípulos participantes de si próprio, concedeu-lhes sua comunhão; assim, fez que tomassem parte de sua justiça. A justiça dos discípulos é a justiça de Cristo. Para explicar isso, as palavras de Jesus sobre a “justiça que excede” já começam chamando a atenção para o cumprimento da lei. A justiça de Cristo é, de fato, a justiça dos discípulos. No sentido exato, é sempre justiça que se oferece, que se dá pelo chamado ao discipulado. É a justiça que consiste exatamente no discipulado, a justiça que, já nas bemaventuranças, tem a promessa do reino dos céus. A justiça dos discípulos é justiça sob a cruz. É a justiça dos pobres, dos tentados, dos famintos, dos mansos, dos pacificadores, dos perseguidos por causa do chamado de Jesus. É a justiça visível daqueles que, por causa de Jesus, são a luz do mundo e a cidade edificada sobre o monte. Por isso a justiça dos discípulos “excede” a dos fariseus, já que somente ela se apoia sobre o chamado de Jesus à comunhão, o chamado do único que cumpre a lei. E, por estar fundamentada no chamado de Jesus, a justiça dos discípulos é verdadeira justiça, porque eles próprios cumprem a vontade de Deus praticando a lei.

Também a justiça de Cristo não deve ser apenas objeto de ensino, mas deve ser praticada. Do contrário, não é melhor que a lei apenas ensinada, mas não praticada. A seguir, trataremos dessa prática da justiça

de Cristo pelos discípulos. Para tanto, basta uma única palavra: discipulado. É a prática real e simples na fé na justiça de Cristo. A justiça de Cristo é a nova lei, a lei de Cristo.

O irmão

Ouvistes que foi dito aos antigos: Não matarás; e: Quem matar estará sujeito a julgamento. Eu, porém, vos digo que todo aquele que [sem motivo] se irar contra seu irmão estará sujeito a julgamento; e quem proferir um insulto a seu irmão estará sujeito a julgamento do tribunal; e quem lhe chamar: Tolo, estará sujeito ao inferno de fogo. Se, pois, ao trazeres ao altar a tua oferta, ali te lembrares de que teu irmão tem alguma coisa contra ti, deixa perante o altar a tua oferta, vai primeiro reconciliar-te com teu irmão; e, então, voltando, faze a tua oferta.

Entra em acordo sem demora com o teu adversário, enquanto estás com ele a caminho, para que o adversário não te entregue ao juiz, o juiz, ao oficial de justiça, e sejas recolhido à prisão. Em verdade te digo que não sairás dali, enquanto não pagares o último centavo.

Mateus 5.21-26

“Eu, porém, vos digo” — com essas palavras, Jesus resume tudo que já foi dito sobre a lei. Pelo que vimos antes, não se pode ver em Jesus um revolucionário nem aceitá-lo como alguém que vive contrapondo opiniões, na linha dos rabinos. Continuando o que começáramos a explicar, Jesus não só expressa sua unidade com a lei da aliança mosaica, mas também deixa claro, em verdadeira unidade com a lei de Deus, que ele é o Filho de Deus, o Senhor e doador da lei. Apenas quem aceita a lei como palavra de Cristo pode cumpri-la. Não deve haver lugar para o mal-entendido pecaminoso em que caíram os fariseus. É só no reconhecimento de Cristo como Senhor e cumpridor da lei que reside o verdadeiro conhecimento da lei. Cristo tomou a lei para si e, ao reivindicá-la, cumpre o objetivo dela. Nessa unidade com a lei, contudo, contrapõe-se à interpretação equivocada da lei. Ao honrar a verdadeira lei, fica à mercê de seus falsos defensores.

A primeira lei que Jesus recomenda a seus discípulos é a que lhes proíbe o assassinato e lhes encarrega o cuidado com a vida do irmão. A vida do irmão é dada por Deus e está nas mãos dele; somente Deus tem poder sobre a vida e a morte. O assassino não pode ter lugar na comunidade de Deus.

Está sujeito ao mesmo julgamento com o qual julgou. O irmão que está sob a proteção da lei divina já não é apenas irmão na fé, pois agora as ações do discípulo não se baseiam no que o outro é, mas nos mandamentos de Jesus, a quem seguimos e obedecemos. O discípulo de Jesus é proibido de cometer assassinato, sob ameaça de julgamento divino. A vida do irmão é, para o discípulo de Jesus, limite que não se pode atravessar. Esse limite, porém, não se restringe ao assassinato; irar-se já é ultrapassá-lo. A palavra raivosa ( Raca) e a ofensa deliberada (“tolo”) já são transgressões desse limite. Todo ato de ira é agressão à vida do outro, porque nega-lhe o direito de vida visando à sua destruição. Também não adianta procurar diferenças entre ira justificada e ira injustificada. 6 O discípulo não pode conhecer a ira, do contrário peca contra Deus e contra seu irmão. A palavra leviana à qual não damos grande importância revela que não honramos o outro, que não o respeitamos, que estimamos mais a nossa vida que a dele. Tais palavras são um golpe contra o irmão, uma punhalada em seu coração. Sua intenção é atingir, machucar, destruir. A ofensa deliberada ataca a honra pública do irmão, intenta torná-lo desprezível diante dos outros, almeja odiosamente a destruição de sua existência íntima e externa. Estou executando nele a sentença. Isso é assassinato. O assassino está sujeito ao mesmo julgamento.

Quem se irar contra seu irmão, quem lhe dirigir palavras ofensivas, quem o difamar e o caluniar em público já não tem lugar diante de Deus, pois é assassino. Separando-se do irmão, separou-se também de Deus; não tem mais acesso a ele. Seu sacrifício, sua adoração, suas orações já não agradarão a Deus. O

discípulo de Jesus não pode separar adoração e serviço ao irmão, como acontece entre os rabinos. O

desprezo ao irmão invalida a adoração e priva o discípulo de toda promessa divina. Tanto o indivíduo como a Igreja que pretendem apresentar-se diante de Deus com o coração cheio de desprezo e não reconciliado estão brincando com um falso deus. A oferta não deve ser aceita enquanto ao irmão forem negados serviço e amor, enquanto ele for objeto de desprezo, enquanto ele tiver algo contra mim ou contra a Igreja de Jesus. Não é apenas a minha ira que se interpõe entre mim e Deus; basta haver um irmão magoado, ultrajado ou desonrado “que tenha algo contra mim”. A Igreja dos discípulos de Jesus deve avaliar se, em algum lugar, não errou em relação aos irmãos, se não é culpada, com o mundo, pelo ódio, pelo desprezo, pela difamação e, portanto, pelo assassinato do irmão. Sim, a Igreja dos discípulos de Jesus deve investigar se, ao apresentar-se diante de Deus para orar e adorar, também não se interpõem entre ela e Deus muitas vozes acusadoras, impedindo-lhe a oração. A Igreja dos discípulos de Jesus deve verificar se mostrou o amor de Jesus àqueles que o mundo rejeitou e desonrou, amor que visa proteger, conservar e sustentar a vida. Do contrário, de nada adiantará a adoração mais correta, a oração mais piedosa ou a confissão mais corajosa; isso será usado contra ela, porque abandonou o discipulado de Jesus. Deus não quer se separar de nosso irmão; não quer ser honrado enquanto um irmão é desonrado.

Ele é o Pai. Sim, é o Pai de Jesus Cristo, que se fez irmão de todos nós. Nisso se baseia o motivo último por que Deus não quer mais ser separado do irmão. Seu Filho Unigênito foi desonrado e difamado por honra ao Pai. O Pai, porém, não se deixa separar do Filho e, portanto, também não quer se separar daqueles dos quais seu Filho se tornou irmão, por amor aos quais suportou a vergonha. Por causa da encarnação do Filho de Deus, não se pode mais separar adoração e serviço ao irmão. “Se alguém disser: Amo a Deus, e odiar a seu irmão, é mentiroso” (1Jo 4.20).

Assim, aos que querem participar da verdadeira adoração no discipulado de Cristo, resta apenas um caminho: o da reconciliação com o irmão. Quem vem ouvir a palavra e receber a comunhão, sem ter o coração reconciliado, recebe, em lugar, juízo. Aos olhos de Deus, é um assassino. Por isso, “vai primeiro reconciliar-te com teu irmão; e, então, voltando, faze a tua oferta” (Mt 5.24). É um duro caminho esse que Jesus exige de seus discípulos. É um caminho de humilhação e vergonha, mas é o caminho a ele, o Irmão Crucificado, e por isso é caminho da graça. Em Jesus, a adoração e o serviço ao irmão são uma coisa só.

Ele foi e reconciliou-se com o irmão e, desse modo, ofereceu ao Pai o único e verdadeiro sacrifício, o sacrifício de si mesmo.

Ainda vivemos no tempo da graça, pois ainda há um irmão ao nosso lado, ainda estamos “com ele a caminho”. Diante de nós está o juízo. Ainda podemos buscar o acordo, ainda podemos pagar a dívida a quem somos devedores. Chegará a hora em que seremos julgados. Então será tarde, pois aí haverá justiça e punição até o último centavo. Será que entendemos que, para o discípulo de Jesus, o irmão não é lei, mas graça? É graça poder entrar em acordo com o irmão e fazer-lhe justiça, e também é graça poder reconciliar-se com ele. O irmão é a nossa graça diante do juízo.

O único que pode falar assim conosco é aquele que, como nosso Irmão, tornou-se para nós graça, reconciliação e salvação do juízo. Na humanidade do Filho de Deus, foi-nos dada a graça do Irmão. Que os discípulos de Jesus a considerem acertadamente!

Servir ao irmão, entrar em acordo com ele, fazer-lhe justiça e conceder-lhe o direito à vida é o caminho da abnegação, o caminho à cruz. “Ninguém tem amor maior do que este: de dar alguém a própria vida em favor dos seus amigos” (Jo 15.13). Assim é o amor do Crucificado. Portanto, essa lei só se cumpre na cruz de Jesus.

A mulher

Ouvistes que foi dito: Não adulterarás. Eu, porém, vos digo: qualquer que olhar para uma mulher com intenção impura, no coração, já adulterou com ela. Se o teu olho direito te faz tropeçar, arranca-o e lança-o de ti; pois te convém que se perca um dos teus membros, e não seja todo o teu corpo lançado no inferno. E, se a tua mão direita te faz tropeçar, corta-a e lança-a de ti; pois te convém que se perca um dos teus membros, e não vá todo o teu corpo para o inferno. Também foi dito: Aquele que repudiar sua mulher, dê-lhe carta de divórcio. Eu, porém, vos digo: qualquer que repudiar sua mulher, exceto em caso de relações sexuais ilícitas, a expõe a tornar-se adúltera; e aquele que casar com a repudiada comete adultério.

Mateus 5.27-32

O compromisso com Jesus não admite o desejo sem amor; tal desejo é proibido aos discípulos. Não se pode permitir que a vontade própria dos discípulos, não importando a circunstância, seja dominada pelo desejo, pois discipulado é abnegação e compromisso total com Jesus. Ainda que seja um breve olhar de sedução, tal desejo afasta do discipulado de Jesus e lança todo o corpo no inferno. Por causa dele, o ser humano vende o direito da primogenitura celestial por um prato de lentilhas. Não acredita que Deus pode recompensá-lo com centenas de alegrias por não ter sucumbido à paixão. Não se contenta em buscar o invisível; prefere agarrar o fruto visível da cobiça. Com isso, desvia-se do caminho do discipulado e separa-se de Jesus. A impureza da cobiça é a falta de fé; só por isso já deve ser rejeitada. Nenhum sacrifício que o discípulo faça para livrar-se do desejo que o separa de Jesus é grande demais. O próprio olho é menos que Cristo, a própria mão é menos que Cristo. Se estiverem a serviço do desejo, o olho e a mão devem ser sacrificados, e não Jesus Cristo, a fim de que não ponham em risco a pureza do corpo no discipulado. O que se ganha com o desejo é mínimo em comparação com o dano que causa — desfruta-se por instantes do desejo do olho e da mão, mas perde-se todo o corpo para a eternidade. O olho que serve à cobiça impura não consegue ver a Deus.

Será que não é o momento de questionar, em definitivo, se esse mandamento de Jesus deve ser entendido ao pé da letra ou em sentido figurado? Acaso nossa vida não depende de uma resposta clara a esse respeito? A resposta já não foi dada pela atitude dos discípulos? Diante de tal dilema, nossa vontade é evitar qualquer decisão. Mas a própria pergunta é falsa e maliciosa. Não há resposta para ela. Se disséssemos que, de fato, esse mandamento não deve ser entendido literalmente, já estaríamos nos desviando de sua gravidade; se, ao contrário, disséssemos que, sim, deve ser levado a sério, já ficaria evidente o absurdo da existência cristã, e o mandamento perderia sua validade. Estamos, portanto, totalmente presos ao mandamento de Jesus, justamente por não haver resposta a essa pergunta tão fundamental. Não há como fugirmos para nenhum dos dois lados; estamos numa posição onde não resta

alternativa senão obedecer. Jesus não impõe a seus discípulos restrições que não possam suportar; não os proíbe de olharem, mas atrai o olhar sobre si, sabendo que assim o olhar se manterá puro, mesmo quando se dirige à mulher. Portanto, não submete os discípulos a um jugo da lei impossível de suportar, mas os ajuda com a graça do evangelho.

Jesus não aconselha o casamento a seus discípulos. Contudo, santifica-o de acordo com a lei, estabelecendo que o matrimônio não pode ser desfeito e proibindo novo casamento àquele que, por adultério, separou-se de seu cônjuge. Com esse mandamento, Jesus liberta o casamento do desejo egoísta a fim de colocá-lo a serviço do amor, de forma só possível no discipulado. Jesus não repreende o corpo e sua necessidade natural, mas rejeita a falta de fé que nele se esconde. Por isso, não dissolve o casamento, mas o fortalece e o santifica pela fé. Assim, o discípulo tem de preservar seu compromisso total com Cristo também no casamento, por meio da disciplina e da renúncia. Cristo é Senhor também no casamento. O fato de o matrimônio do discípulo ser algo diferente do matrimônio do mundo não significa desprezo ao casamento, mas justamente sua santificação.

Pode parecer que, ao exigir que o casamento não pode se desfazer, Jesus se põe contra a lei do Antigo Testamento. Mas ele próprio explica estar de acordo com a lei mosaica. “Por causa da dureza de vosso coração é que Moisés vos permitiu repudiar vossa mulher...” (Mt 19.8) Por isso permitiu-se aos israelitas a possibilidade da “carta do divórcio”, para impedir que o coração cometesse excessos ainda maiores. A intenção da lei do Antigo Testamento, porém, está em pleno acordo com a intenção da lei de Jesus, que é sustentar a pureza do casamento, para que este seja exercido na fé em Deus. Essa pureza, isto é, a castidade, é preservada na comunhão com Jesus e em seu discipulado.

Porque Jesus se preocupa unicamente com a pureza completa, a castidade de seus discípulos, deve afirmar também que a renúncia ao casamento, por causa do reino de Deus, é sagrada. O casamento ou o celibato, para Jesus, não é um programa de vida; ao contrário, Jesus livra os discípulos da porneia

[relações sexuais ilícitas] dentro e fora do casamento, livra-os da prostituição, que não é apenas um pecado contra o próprio corpo, mas um pecado contra o corpo de Cristo (1Co 6.13-15). O corpo do discípulo pertence a Cristo e ao discipulado, e nosso corpo é membro do corpo dele. A prostituição é, assim, pecado contra o próprio corpo de Jesus, porque ele, o Filho de Deus, portou um corpo humano e porque nós temos comunhão com o corpo dele.

O corpo de Jesus foi crucificado. A respeito dos que pertencem a Cristo, o apóstolo afirma que

“crucificaram a carne, com as suas paixões e concupiscências” (Gl 5.24). Ou seja, é somente no corpo martirizado e crucificado de Jesus Cristo que se cumpre essa lei do Antigo Testamento. É pela contemplação do corpo de Jesus e pela comunhão desse corpo que os discípulos têm a força para a castidade exigida por Jesus.

A verdade

Também ouvistes que foi dito aos antigos: Não jurarás falso, mas cumprirás rigorosamente para com o Senhor os teus juramentos. Eu, porém, vos digo: de modo algum jureis; nem pelo céu, por ser o trono de Deus; nem pela terra, por ser estrado de seus pés; nem por Jerusalém, por ser cidade do grande Rei; nem jures pela tua cabeça, porque não podes tornar um cabelo branco ou preto. Seja, porém, a tua palavra: Sim, sim; não, não. O que disto passar vem do maligno.

Mateus 5.33-37

A interpretação dessa passagem permanece, ainda hoje, em discussão no seio da Igreja cristã. Já os estudiosos da Igreja primitiva se desentendiam sobre as possibilidades de interpretá-la. Vão desde a rejeição total a qualquer juramento como pecado até à simples advertência ao juramento irresponsável e ao falso testemunho. Na Igreja primitiva, a interpretação mais aceita era a seguinte: o juramento é terminantemente proibido para o cristão “perfeito”, mas aceitável em determinadas situações para os mais fracos na fé. O próprio Agostinho defendia essa interpretação. Sua opinião em relação ao juramento era a mesma de filósofos pagãos como Platão, Pitágoras, Epíteto e Marco Aurélio. Na visão deles, o juramento era indigno de um homem nobre. As igrejas que surgiram na esteira da Reforma consideravam, em suas confissões de fé, os juramentos exigidos pelas autoridades governamentais como não inseridos nessas palavras de Jesus. Os argumentos principais eram que, desde o início, no Antigo Testamento, o juramento era obrigatório; o próprio Jesus, em seu julgamento, jurou diante do tribunal; o apóstolo Paulo recorre diversas vezes a fórmulas de juramento. Para os reformadores, a separação entre reino divino e secular tinha importância decisiva, além de basear-se no testemunho direto das Escrituras. O que é juramento? É a invocação pública do nome de Deus como testemunha de uma afirmação que faço a respeito de algo que ocorreu no passado ou no presente ou que ocorrerá no futuro. Deus, que é onisciente, vingará a mentira. Por que Jesus considera tal juramento um pecado de natureza satânica e maligna? Porque, para Jesus, o que importa é a verdade total.

O juramento é a comprovação de que existe mentira no mundo. Se o ser humano não fosse capaz de mentir, não haveria necessidade de juramento. Embora seja um obstáculo para a mentira, o juramento pode até estimular os mentirosos, pois, na reivindicação de ser a última instância da verdade, confirma a possibilidade de haver espaço para a mentira, ou seja, a mentira obtém certo direito de existir. A lei do Antigo Testamento recusa a mentira por meio do juramento. Jesus, por sua vez, recusa a mentira proibindo o juramento. Num e noutro caso, trata-se de encontrar um meio para a destruição total da mentira na vida dos crentes. O juramento, que no Antigo Testamento era usado para combater a mentira, tornou-se refém da própria mentira e passou a servir ao mentiroso. Por meio do juramento, a mentira estabelece seu direito de existir. De seu modo, portanto, Jesus, aprisiona a mentira no lugar mesmo onde ela se esconde, isto é, atrás do juramento. O juramento deve desaparecer, pois se tornou proteção da mentira.

O ataque da mentira contra o juramento podia ter êxito de duas maneiras. Primeiro, por meio do próprio juramento tornando-se falso testemunho. Segundo, disfarçando-se na forma do juramento, isto é, não como invocação pública do nome do Deus vivo, mas a algum outro poder mundano ou divino. Nesse caso, porque a mentira se infiltrou profundamente no juramento, só a proibição do juramento garante a verdade total.

“Seja, porém, a tua palavra: Sim, sim; não, não.” Isso não quer dizer que os discípulos não são responsáveis diante do Deus onisciente pelo que dizem. Ao contrário, exatamente porque o nome de Deus não é invocado de forma solene no juramento, cada palavra do discípulo é expressa na presença do Deus onisciente. Não há necessidade de o discípulo jurar, pois não existe palavra que não seja dita diante de

Deus. Cada palavra sua deve expressar nada mais que a verdade, não necessitando, assim, de confirmação mediante juramento. O juramento poria sob suspeita todas as outras palavras. Por isso dizse que o juramento “vem do maligno”. O discípulo, porém, deve ser luz sempre, com todas as suas palavras.

O juramento é, assim, recusado, e isso deve ficar muito claro, pois para Jesus o objetivo é somente a verdade. É evidente que o mandamento de Jesus não admite exceção em nenhuma instância. Deve-se dizer, porém, que a rejeição ao juramento não pode servir para esconder a verdade. Se isso ocorrer, isto é, se em prol da verdade for necessário o juramento, não se deve generalizar, pois isso deve ser decidido caso a caso. As igrejas procedentes da Reforma consideram exemplos dessa natureza todo juramento exigido pelas autoridades. É de questionar se tal generalização é possível.

O que não deve ser questionado, porém, é que, caso isso ocorra, o juramento só pode ser feito havendo total clareza e transparência sobre seu conteúdo; também, deve-se diferenciar o juramento referente a fatos do passado ou do presente e que são de nosso inteiro conhecimento do juramento que nos diz respeito e que visa a um voto a ser cumprido no futuro. Uma vez que o cristão nunca está isento de cometer erros sobre o passado, a invocação pública do nome do Deus onisciente não poderá servir para confirmar uma afirmação sujeita a erro, mas para confirmar a pureza de sua sabedoria e consciência.

Uma vez, porém, que o cristão também nunca tem o poder de saber o que acontecerá no futuro, o voto juramentado é sempre algo arriscado. E, não sendo ele capaz de controlar o próprio futuro, muito menos tem o poder de controlar o futuro daquele a quem faz o voto de fidelidade. Assim, por causa da verdade e do discipulado de Jesus, é impossível fazer o juramento sem antes condicioná-lo à vontade de Deus. Para o cristão, não existe compromisso terreno absoluto. Um voto de fidelidade que queira comprometer integralmente o cristão se tornará uma mentira e, portanto, “vem do maligno”. A invocação do nome de Deus para tal juramento jamais poderá servir para confirmar o voto para algo que só ocorrerá no futuro, mas apenas como testemunho de que, no discipulado de Jesus, estamos comprometidos com a vontade de Deus e que qualquer outro compromisso está, por causa de Jesus, assim condicionado. Se, em casos de dúvida, essa condição não for expressamente afirmada nem reconhecida, o julgamento não poderá ser feito, justamente porque estou enganando aquele a quem faço o voto. Seja, porém, a sua palavra: Sim, sim; não, não.

O mandamento da verdade total é apenas um sinônimo para a totalidade do discipulado. Apenas quem, no discipulado, está comprometido com Cristo está na verdade completa. Nada tem a esconder de seu Senhor. Vive completamente aberto diante dele. É reconhecido por Jesus e colocado na verdade. É

revelado a Jesus como pecador. Não foi ele que se revelou para Jesus, mas, quando Jesus se lhe revelou em seu chamado, já soube que Jesus o reconhecera como pecador. A verdade total só existe quando o pecado é revelado e também é perdoado por Jesus. Quem, na confissão de seu pecado, está na verdade diante de Jesus não se envergonha da verdade, onde quer que ela seja dita. A verdade que Jesus exige de seus discípulos consiste na abnegação que não oculta o pecado. Tudo é revelado, tudo é trazido à luz.

Do princípio ao fim, a questão da verdade consiste na revelação do ser humano em todo o seu ser, em toda a sua maldade, diante de Deus. Por isso a verdade provoca a resistência do pecador, por isso é perseguida e crucificada. A verdade do discípulo baseia-se unicamente no discipulado de Jesus, no qual

ele nos revela na cruz nosso pecado. Só a cruz como verdade de Deus a nosso respeito nos torna verdadeiros. Quem conhece a cruz já não teme a verdade. O juramento como meio de confirmação da verdade não se faz mais necessário, pois quem vive sob a cruz está na verdade completa de Deus. Só há verdade em relação a Jesus quando há verdade em relação aos seres humanos. A mentira destrói a comunhão. A verdade, porém, destrói a falsa comunhão e cria no lugar fraternidade verdadeira. Não há discipulado de Jesus sem uma vida na verdade revelada diante de Deus e dos seres humanos.

A vingança

Ouvistes que foi dito: Olho por olho, dente por dente. Eu, porém, vos digo: não resistais ao perverso; mas, a qualquer que te ferir na face direita, volta-lhe também a outra; e, ao que quer demandar contigo e tirar-te a túnica, deixa-lhe também a capa. Se alguém te obrigar a andar uma milha, vai com ele duas. Dá a quem te pede e não voltes as costas ao que deseja que lhe emprestes.

Mateus 5.38-42

Jesus relaciona o provérbio “olho por olho, dente por dente” não só com os mandamentos do Antigo Testamento, comentados anteriormente, mas também com a proibição do assassinato nos Dez Mandamentos. Reconhece-o, portanto, como mandamento incontestável de Deus, tanto quanto o “Não matarás”. Da mesma maneira que este mandamento, aquele não deve ser eliminado da lei, mas ser cumprido de forma completa. Jesus não aceita nossa prática de conferir maior importância aos Dez Mandamentos que a esses outros. Para ele, existe apenas “o mandamento” do Antigo Testamento e, por isso, requer de seus discípulos que todos sejam igualmente cumpridos.

Os discípulos de Jesus, por causa dele, vivem na renúncia aos próprios direitos. Jesus os declara bem-aventurados porque são mansos. Se ainda fizessem questão, mesmo depois de terem abandonado tudo por causa dele, de continuar apegados a essa posse, isto é, a seu direito individual, já teriam abandonado o discipulado. Portanto, o que vemos aqui nada mais é que o desdobramento das bem-aventuranças. Na lei do Antigo Testamento, o direito está sob proteção divina da vingança. Toda maldade deve ser vingada. É o meio de estabelecer a comunhão adequada, para que o mal seja acusado, vencido e, consequentemente, eliminado da comunidade do povo de Deus. Para isso serve a lei que permanece em vigor por meio da vingança. Jesus valida essa sabedoria divina e reafirma o poder da vingança para acusar o mal e vencê-lo visando ao fortalecimento da comunidade dos discípulos como o verdadeiro Israel. Para garantir a permanência do discípulo no discipulado, a injustiça deve ser eliminada mediante a justa vingança.

De acordo com Jesus, a vingança, para ser justa, consiste em não resistir ao mal.

Com essas palavras, Jesus remove sua Igreja da esfera políticojurídica, da estrutura de Israel como nação, que até então vigorava, e a transforma no que de fato é: uma comunidade de crentes desvinculada de uma ordem político-nacional. Se, no povo de Israel, eleito por Deus como estrutura política, a vingança assume, segundo a sabedoria divina, a forma de revide do golpe recebido, na comunidade dos discípulos de Jesus, que não exige para si direitos jurídico-nacionais, a vingança passa a consistir no sofrimento paciente do golpe recebido, de modo que o mal não seja respondido com outro mal. Só assim a comunidade poderá ser estabelecida e preservada.

Desse modo, fica claro que o discípulo de Jesus, contra quem é cometida a injustiça, já não se agarra a seu direito de vingança, como se fosse uma propriedade que ele tivesse de defender a qualquer custo. Por meio desse desprendimento, mostra que está livre de qualquer posse e comprometido apenas com Jesus Cristo. Então, à medida que testemunha seu compromisso exclusivo com Jesus, pode criar a única base segura para a vida em comunhão, entregando o pecador às mãos de Jesus.

A maldade do outro é vencida, portanto, quando ela não encontra o que procura, isto é, a reação que poderia criar um novo encadeamento de maldades, com as quais se tornaria cada vez mais inflamada e poderosa. Não sendo correspondida, a maldade se torna impotente, já que não encontra um objeto sobre o qual agir, não encontra reação, mas é suportada e sofrida paciente e firmemente. Assim, o mal depara com um oponente ao qual não é páreo. Claro que isso só ocorrerá quando o último posto de resistência tiver sido abandonado, quando a renúncia à vingança for total. Desse modo, o mal não conseguirá atingir seu objetivo, que é recriar o mal, e ficará isolado.

O sofrimento passa quando é tolerado. O mal encontra seu fim quando não lhe é imposto resistência.

Ao abrir mão de revidar o golpe do inimigo com a mesma moeda da violência, não impondo qualquer resistência, o discípulo demonstra que são pecados a desonra e a difamação que o outro comete contra ele. A violência é julgada quando não consegue provocar a reação violenta. A falsa pretensão sobre minha túnica será exposta se, em vez de me defender, eu der também a capa. A exploração de minha disposição de servir torna-se visível quando eu não defino limites para ela. A disposição de renunciar tudo que nos é pedido é a disposição de satisfazer-se tão somente por estar junto de Jesus Cristo e segui-lo. Na renúncia voluntária à defesa, confirma-se e declara-se o compromisso incondicional com Jesus, com a liberdade e com o desprendimento do próprio eu. É somente a exclusividade desse compromisso com Jesus que pode vencer o mal.

Não se trata aqui apenas do mal como algo abstrato, mas também a pessoa má. Jesus chama abertamente a pessoa má de perverso. Minha atitude não deve ser a de desculpar nem de justificar meu opressor. Não é como se eu quisesse expressar com meu sofrimento paciente o reconhecimento dos direitos que o perverso teria. Jesus nada tem a ver com essas considerações sentimentais. O golpe que desonra, o ato de violência, a exploração do outro continuam sendo maus. O discípulo deve ter consciência disso e dar testemunho, como fez Jesus, mesmo porque de outro modo o mal não será confrontado nem vencido. Mas, exatamente porque não há nada que justifique o mal que atinge o discípulo, este tem de sofrê-lo, sem resistir a ele, para, ao sofrer, anular o mal e, assim, o vencer. O sofrimento suportado com disposição é mais forte que o mal; é a morte do mal.

Não há, na terra, ação tão ultrajante que justifique exigir uma atitude diferente do cristão. Quanto mais terrível o mal, mais disposto ao sofrimento o discípulo deverá estar. O discípulo deve dispor-se a deixar o perverso cair nas mãos de Jesus. Não sou eu, mas é Jesus que lidará com ele.

Nesse ponto, os reformadores introduziram uma interpretação nova e decisiva ao distinguir entre o sofrimento pessoal do discípulo e o sofrimento em decorrência de seu cargo, isto é, das responsabilidades dadas por Deus. No primeiro caso, devo agir conforme ordena Jesus; no segundo, não só estou livre de obedecer, mas também, por causa do verdadeiro amor, devo fazer justamente o

contrário, isto é, opor violência à violência a fim de impedir a invasão do mal. Foi sob tal ponto de vista que os reformadores justificaram a guerra e o uso de recursos públicos legais no combate contra o mal.

Para Jesus, no entanto, é estranha essa divisão, como critério para a ação, entre o indivíduo na vida privada e o indivíduo como detentor de cargo. Sobre isso ele não nos diz uma só palavra. Dirige-se a seus discípulos como aqueles que deixaram tudo para segui-lo. Tanto a vida “privada” como a “pública”

deveriam estar completamente subordinadas ao mandamento de Jesus. Sua palavra exige compromisso completo, obediência incondicional. Na realidade, essa distinção ocasiona uma dificuldade impossível de solucionar: quando é que sou apenas indivíduo na vida privada e quando sou apenas encarregado na vida pública? Não sou sempre pai de meu filho, pastor de minha igreja, representante de meu povo, onde quer que eu seja ofendido? Por isso mesmo, não estou sempre obrigado, por responsabilidade de meu cargo, a me defender de todo ataque? E não sou também um indivíduo, sempre diante de Jesus, mesmo na execução de meus deveres públicos? Não sou, portanto, obrigado a resistir a todo ataque exatamente por responsabilidade de meu cargo? Será que essa distinção não deveria ser esquecida, já que o discípulo de Jesus é sempre o mesmo, que, em última instância, só poderá decidir e agir sendo um? E não é justamente nesse modo de agir que reside minha maior responsabilidade diante dos que estão sob meus encargos?

Como, então, justificar o mandamento de Jesus à luz da experiência? Não está evidente que a violência se volta especialmente contra os mais fracos e incapazes de se defender? Essa ordem de Jesus não é apenas um ideal que nada tem a ver com a realidade, ou seja, com os pecados que reinam no mundo?

Talvez ela tenha razão de ser dentro da Igreja. Mas, em relação ao mundo, parece ser de um fanatismo enganoso, que não leva em conta o pecado. Vivendo no mundo e reconhecendo que ele é mau e cheio de pecado, podemos dizer que isso é impraticável. Mas Jesus diz: Porque vocês vivem no mundo e porque o mundo é mau é que é praticável não resistir ao mal. Claro que não queremos acusar Jesus, que desde o primeiro dia de sua vida já lutava contra o diabo, de não reconhecer o poder do mal. Jesus afirma que o mal é o mal e por isso mesmo dirige-se dessa maneira a seus seguidores. Como isso é possível?

De fato, se considerarmos que o mandamento de Jesus para seus discípulos, isto é, de que o mal será vencido com o bem, é na verdade um projeto ético, sabedoria de vida de aplicação geral, estaríamos cedendo a um entusiasmo sem consistência. Seria realmente uma fantasia irresponsável de leis às quais o mundo jamais obedeceria. Fazer da não resistência princípio da vida mundana é a destruição ímpia da ordem do mundo que Deus sustenta por sua graça. Jesus, porém, não é um criador de projetos políticos, e sim aquele que venceu o mal por meio do sofrimento, que na cruz foi vencido pelo mal mas que, após essa derrota, ressurgiu triunfante. Não pode haver outra justificativa para a obediência a esse mandamento que a própria cruz. Somente quem encontra, na cruz, a fé na vitória sobre o mal é que pode obedecer a seu mandamento, e somente essa obediência tem a promessa. Que promessa? A promessa da comunhão da cruz de Jesus e de sua vitória. A Paixão de Jesus como vitória sobre o mal por meio do amor divino é o único alicerce seguro para a obediência dos discípulos. Com seu mandamento, Jesus mais uma vez chama os discípulos a tomarem parte de sua Paixão. Como poderia a pregação da Paixão de Jesus Cristo tornar-se visível e digna de fé para o mundo, se os próprios discípulos recusassem essa Paixão, se a desprezassem, evitando sofrê-la

em seu próprio corpo? Quando se submete à cruz,7 Jesus cumpre o mandamento que ele mesmo estabeleceu e, assim, por sua misericórdia, preserva os discípulos na comunhão de sua cruz. Somente na cruz torna-se verdadeiro e real que o amor que sofre seja a vingança do mal e a vitória sobre ele. A comunhão da cruz, porém, só é dada pelo chamado de Jesus ao discipulado. Nessa comunhão visível, eles são bem-aventurados.

O inimigo — o “extraordinário”

Ouvistes que foi dito: Amarás o teu próximo e odiarás o teu inimigo. Eu, porém, vos digo: amai os vossos inimigos e orai pelos que vos perseguem; para que vos torneis filhos do vosso Pai celeste, porque ele faz nascer o seu sol sobre maus e bons e vir chuvas sobre justos e injustos. Porque, se amardes os que vos amam, que recompensa tendes? Não fazem os publicanos também o mesmo? E, se saudardes somente os vossos irmãos, que fazeis de mais? Não fazem os gentios também o mesmo? Portanto, sede vós perfeitos como perfeito é o vosso Pai celeste.

Mateus 5.43-48

Pela primeira vez no Sermão do Monte, encontramos a palavra que resume tudo que se disse até agora: amor. E, como se não bastasse, na exata definição como amor ao inimigo. Se Jesus nos tivesse dito que amássemos nossos amigos, haveria aí um mal-entendido sobre o que ele quis dizer com amor; porém, ao determinar que nosso amor fosse dirigido a nosso inimigo, deixa totalmente claro o que quer. A ideia de “inimigo” não era desconhecida dos discípulos. Eles a conheciam bem demais. Deparavam com o inimigo diariamente. Eram os que os amaldiçoavam por estarem destruindo a fé e transgredindo a lei; os que os odiavam por terem abandonado tudo que possuíam por causa de Cristo, valorizando apenas a comunhão com ele; os que os ofendiam e os ridicularizavam por sua fraqueza e humildade; os que os perseguiam e os buscavam destruir por reconhecerem neles uma ameaça revolucionária. Uma parte dos inimigos estava entre os representantes da religião do povo, que não toleravam as reivindicações que Jesus fazia. Eles detinham o poder e o respeito. O outro inimigo que vinha de imediato à mente de qualquer judeu era o adversário político, isto é, Roma. Eles o sentiam como uma poderosa opressão.

Além desses, havia ainda a hostilidade pessoal, dirigida a todo aquele que não segue com a maioria e que atingia os discípulos na forma de difamação, injúria e ameaça.

É bem verdade que nada existe no Antigo Testamento que incite o ódio ao inimigo. Muito mais recorrente é o mandamento de amar o inimigo (Êx 23.4; Pv 25.21s; Gn 45.1ss; 1Sm 24.7; 2Rs 6.22 etc.).

Jesus, porém, não está se referindo à inimizade natural, mas à inimizade do povo de Deus contra o mundo. As guerras de Israel foram as únicas guerras “santas” na história da humanidade. Foram as guerras de Deus contra os falsos deuses. Não era a esse tipo de hostilidade que Jesus se referia; do contrário, teria de condenar toda a história de Deus com seu povo. Em vez disso, confirma a antiga aliança. Trata-se somente da superação do inimigo, da vitória do povo de Deus. Com esse mandamento, porém, ele mais uma vez desvincula a comunidade dos discípulos da estrutura política do povo de Israel.

Assim, já não há guerras que possam ser consideradas santas, pois Deus condicionou a promessa da vitória sobre o inimigo ao amor ao próprio inimigo. Esse mandamento não é apenas um choque para o ser humano; amar o inimigo é algo que contraria sua natureza. Está acima de suas forças e opõe-se a suas noções de bem e mal. Mais importante ainda, o amor ao inimigo, para aquele que está sob a lei, é visto como pecado contra a lei de Deus: a separação entre o inimigo e sua condenação era uma exigência da lei. Jesus, porém, toma a lei de Deus em suas mãos e a interpreta. Surge, então, a ideia de vencer o inimigo por meio do amor ao inimigo; é essa a vontade de Deus em sua lei.

No Novo Testamento, inimigo é sempre aquele que é contra mim. Jesus não conta com a possibilidade de que seu discípulo pudesse ser inimigo de alguém. O amor do discípulo de Jesus cabe tanto ao inimigo como ao irmão. A ação do discípulo não deve ser determinada pela conduta do ser humano, mas pela ação de Jesus para com ele. A resposta do discípulo às ações humanas tem apenas uma origem: a vontade de Jesus.

Fala-se aqui do inimigo, daquele, portanto, que permanece inimigo independentemente de meu amor, daquele que não me perdoa, mesmo que eu o perdoe em tudo; daquele que me odeia, mesmo que eu o ame; daquele que cada vez mais me rejeita quanto mais eu lhe sirvo. “Em paga do meu amor, me hostilizam; eu, porém, oro” (Sl 109.4). O amor não deve perguntar se é correspondido, mas procurar quem carece dele. Quem mais necessita de amor senão aquele que, sem amor, vive no ódio? Quem, portanto, seria mais digno de amor que meu inimigo? Onde seria o amor mais glorificado do que entre seus inimigos?

Esse amor não faz distinção entre os tipos de inimigos; reconhece apenas que, quanto mais inimigo o inimigo é, mais carece de meu amor. Seja qual for o inimigo, político ou religioso, nada tem a esperar do discípulo a não ser o amor integral. Esse amor não me divide em vida privada e vida pública. Nas duas esferas, só posso ser o mesmo, ou então não seria, de modo nenhum, discípulo de Jesus Cristo. E, se perguntam o que fazer com esse amor, Jesus responde: abençoar, fazer o bem, orar, tudo isso incondicionalmente, sem que haja acepção de pessoas. “Amai os vossos inimigos.” Enquanto no mandamento anterior falouse apenas do sofrimento sem resistência diante do mal, neste Jesus vai muito além. Não devemos apenas tolerar o mal e o perverso e não revidar o golpe, mas também fazer o bem ao inimigo com todo amor no coração. Sem fingimento e com pureza, devemos servir ao inimigo e ajudá-lo em tudo que ele precisar. Nenhum sacrifício que se faça à pessoa amada é grande e precioso demais que não se possa fazer ao inimigo. Se, no amor ao irmão, temos de empenhar nossos bens, nossa honra e nossa vida, o mesmo devemos fazer em relação ao inimigo. Será que, com isso, tomamos parte de sua maldade? De maneira nenhuma. Pois como poderia o amor que não vem da fraqueza, mas da força, que não vem do medo, mas da verdade, ser culpado pela maldade do outro? E quem deveria ser objeto desse amor senão aquele cujo coração está sufocado pelo ódio?

“Bendizei aos que vos maldizem.” Quando o inimigo nos amaldiçoa por não suportar nossa presença, levantemos a mão para abençoálo: Vocês, nossos inimigos, abençoados por Deus, sua maldição não pode nos ferir. Que sua pobreza seja substituída pela riqueza de Deus, pela bênção daquele contra quem vocês lutam inutilmente. Suportaremos de bom grado a maldição se, com isso, vocês forem abençoados.

“Fazei o bem aos que vos odeiam.” Não amemos apenas com palavras e pensamentos. Fazer o bem inclui tudo que acontece no dia a dia. “Pelo contrário, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber” (Rm 12.20). Do mesmo modo que um irmão apoia o outro na hora da necessidade, tratando suas feridas e amenizando sua dor, assim seja nosso amor ao inimigo. Onde poderia haver maior necessidade e dores e feridas mais profundas que em nosso inimigo? A quem é mais necessário fazer o bem e dar a bênção do que ao inimigo? “Mais bem-aventurado é dar que receber” (At 20.35).

“Orai pelos que vos caluniam e perseguem.” Eis a exigência máxima. Na oração, aproximamo-nos de nosso inimigo, colocamo-nos ao lado dele, estamos com ele, junto dele, por ele diante de Deus. Jesus não promete que o inimigo que amamos, abençoamos e a quem fazemos o bem deixará de nos caluniar e perseguir. Ele continuará a fazê-lo. Mas, se formos em sua direção e orarmos em seu favor, ele não poderá nos prejudicar nem vencer. Assim, tomemos sua necessidade e sua pobreza, sua culpa e sua perdição e intercedamos por ele diante de Deus. Se ele não pode fazer isso sozinho, façamos em seu lugar. Cada ofensa da parte do inimigo nos compromete cada vez mais com Deus e com ele próprio. Toda perseguição só serve para aproximar o inimigo de Deus e, assim, possibilitar sua reconciliação com ele, para que o amor seja cada vez mais invencível.

Como, porém, o amor se torna invencível? Quando o discípulo jamais se questiona sobre o que o inimigo lhe faz, mas somente pelo que Jesus fez. O amor ao inimigo conduz o discípulo ao caminho da cruz e à comunhão com o Crucificado. Quanto mais seguro estiver nesse caminho, mais invencível permanecerá seu amor, e mais certamente vencerá o ódio do inimigo. Pois não se trata de seu próprio amor; é o amor de Jesus Cristo, que por seus inimigos foi à cruz e nela orou por eles. Em face do caminho de Jesus Cristo para a cruz, perceberam os discípulos que eles também faziam parte dos inimigos que Jesus venceu por seu amor. O amor possibilitou ao discípulo reconhecer o próprio irmão no inimigo e agir em relação a ele como age com o irmão. Por quê? Porque ele mesmo vive do amor daquele que o tratou como se trata um irmão, aceitando-o mesmo quando era seu inimigo e trazendo-o para a comunhão como a seu próximo. Por isso o amor também possibilita ao discípulo ver que o inimigo está incluído no amor de Deus, que o inimigo está sob a cruz de Jesus Cristo. Deus nada pergunta sobre nossas virtudes ou nossos vícios, pois, a seus olhos, mesmo nossa virtude é ímpia. O amor de Deus busca o inimigo, que carece de seu amor, a quem Deus considera digno dele. Com seu amor, abençoa o inimigo.

Essa é a glória do amor, e disso o discípulo sabe, pois participou desse amor por meio de Jesus. Porque Deus “faz nascer o seu sol sobre maus e bons e vir chuvas sobre justos e injustos” (Mt 5.45). Não se trata apenas do sol e da chuva terrena, mas é o “sol da justiça”, o próprio Jesus Cristo, e a chuva da Palavra de Deus que revela a graça do Pai celeste sobre os pecadores. O amor perfeito e integral, além da obra do Pai, é também a obra dos filhos do Pai celeste, como o era a obra do Filho Unigênito.

Os mandamentos de amor ao próximo e de renúncia à vingança se tornarão cada vez mais urgentes na luta sagrada que se aproxima e, na verdade, na qual já estamos, há anos, engajados, pois de um lado está o amor e, do outro, o ódio. É obrigação de toda alma cristã preparar-se para esse combate. Vem chegando o tempo em que aquele que confessar o nome do Deus vivo se tornará, por causa dessa confissão, não apenas objeto de ódio e de fúria do mundo — o que já está acontecendo —, mas será também excluído da assim chamada “sociedade humana”; será caçado de um lugar para outro, maltratado, agredido fisicamente e, por vezes, assassinado. — Vem chegando o tempo de

perseguição generalizada aos cristãos. E é, na verdade, aí que reside o sentido último de todos os movimentos e lutas de nossos dias. Os adversários buscam a destruição de nossa Igreja e de nossa fé cristã porque não conseguem conviver conosco, porque veem em cada palavra que dizemos, em cada ato que praticamos, mesmo quando não dirigido contra eles, uma condenação de suas palavras e atos. E

nisso não estão errados. Suspeitam também que somos indiferentes a suas condenações; na verdade, têm de admitir que a condenação deles contra nós é completamente ineficaz. Não discutimos nem brigamos com eles, embora preferissem que o fizéssemos e, dessa maneira, descêssemos até seu nível. Como travar essa batalha? Logo chegará o tempo em que teremos de orar não mais como indivíduos isoladamente, mas como congregação articulada, como Igreja, em que juntos elevaremos as mãos em oração; ainda que em pequenos grupos, e no meio de milhares e milhares de apóstatas, louvaremos e confessaremos o Senhor que foi crucificado e subiu aos céus e que um dia voltará. E que oração, que confissão, que hino de louvor será? Será justamente a oração do amor mais terno por esses que se perderam, que nos rodeiam e nos miram com olhares cheios de ódio e com as mãos já levantadas para desferir o golpe mortal; será a oração pela paz dessas almas errantes, desoladas, confusas; a oração pelo mesmo amor e pela mesma paz de que usufruímos, que lhes penetrará fundo na alma e lhes despedaçará o coração mais dolorosamente que qualquer coisa que eles, com todo o ódio contra nosso coração, pudessem fazer conosco. Sim, a Igreja que de fato espera seu Senhor, que reconhece os sinais da época em que será necessário tomar decisões, deverá, com toda a força de sua alma, com toda a força de sua vida sagrada, lançar-se na oração do amor. (A. F. C.

Vilmar, 1880)

O que é o amor integral? É o amor que não mostra favorecimento àqueles que retribuem nosso amor.

Quando amamos os que nos amam, nossos irmãos, nosso povo, nossos amigos, sim, até mesmo nossa própria comunidade cristã, não somos melhores que os gentios e publicanos. Tal amor é habitual e normal, e nele não há nada exclusivamente cristão. Podemos amar irmãos e parentes, conterrâneos e amigos, cristãos ou não, e não precisamos que Jesus nos ensine isso. Esse amor os seres humanos já conhecem naturalmente; não é preciso reforçá-lo ou enfatizá-lo. A vida no dia a dia já impõe o exercício desse amor a cristãos e a gentios. Portanto, Jesus não precisava dizer a alguém que ame seu irmão, seu povo, seus amigos; isso todos já sabem. Não acrescentando nada a respeito e apenas ordenando o amor ao inimigo, ele nos mostra o que entende por amor e como devemos agir em relação a ele.

Em que se distingue o discípulo dos gentios? O que realmente significa ser cristão? Nesse trecho está a palavra que determina todo o capítulo e resume tudo que temos comentado até o momento. O que torna o cristão diferente de todos é o “extraordinário”, o perisson, o não usual, não natural. É o que “excede” a justiça do fariseu, que supera em muito, que vai além. O natural é to auto (um e o mesmo), aquilo que é praticado pelo gentio e pelo cristão. O que é exclusivo do cristão começa com o perisson, o extraordinário. É a qualidade que, pela primeira vez, nos capacita a ver o “natural” sob a sua verdadeira luz. Onde não existe o especial, “o extraordinário”, aquilo que é exclusivo do cristão, também não será encontrada a essência cristã. Aquilo que é exclusivo do cristão não pode ocorrer na esfera das possibilidades naturais, mas somente quando elas oferecem algo a mais, algo que excede. O perisson nunca pode ser incorporado pelo to auto. Esse é o grande engano de uma falsa ética protestante, ou seja, supor que o amor cristão se reduz ao amor à pátria, à lealdade aos amigos ou à dedicação ao trabalho, supor que a “justiça que excede” pode ser reduzida à justitia civilis. Não é nesse sentido que Jesus fala.

Qual é a natureza exata do perisson, do extraordinário? É a vida descrita pelas bem-aventuranças, é a vida dos discípulos, é a luz que ilumina a cidade, a cidade edificada sobre o monte, o caminho da renúncia de si mesmo, do amor integral, da pureza absoluta, da verdade total, da não violência completa, é o amor incondicional ao inimigo, o amor àquele que não ama ninguém nem é amado por ninguém, o amor ao inimigo religioso, político e pessoal. Em tudo isso, é o amor que encontrou sua realização na

cruz de Jesus Cristo. O que é o perisson? É o próprio amor de Jesus Cristo, o amor que vai à cruz de modo obediente e paciente; é a cruz. A cruz é o que há de exclusivo do amor cristão, é o poder que possibilita aos cristãos transcenderem o mundo terreno e nele serem vitoriosos. A passio no amor do Crucificado — aí está a expressão suprema do extraordinário na vida cristã.

O extraordinário é, sem dúvida, aquilo que se pode ver, que é visível, pelo qual se glorifica o Pai que está no céu. Isso não pode permanecer oculto; deve ser visto pelas pessoas. A comunhão dos discípulos de Jesus, a Igreja da “justiça que excede” é a Igreja visível, que se separa da ordem do mundo e que abandona tudo para ganhar a cruz de Cristo.

Como essa qualidade funciona na prática? O extraordinário — e isso é o mais escandaloso — é algo que os discípulos de Jesus fazem. Esse extraordinário tem de ser feito — como a justiça que excede — e tem de ser feito de modo que todos possam ver! Não com severidade ética, não com excêntricos estilos de vida, mas com a simplicidade da obediência cristã por amor a Jesus. Esse fazer cotidiano se mostrará

“extraordinário” e nos conduzirá à passio de Cristo. Esse estilo de vida é, ele próprio, Paixão contínua.

Nele, os discípulos suportam o sofrimento de Cristo. Se a vida não for assim, então não é a maneira de fazer de que Jesus fala.

O perisson é, portanto, o cumprimento da lei e o respeito ao mandamento. No Cristo crucificado e em sua Igreja, o “extraordinário” se torna realidade.

Esses seres humanos são os perfeitos, perfeitos no amor integral como é o Pai celeste. O sofrimento da comunhão na cruz é a perfeição dos discípulos de Jesus, pois foi o amor integral e perfeito do Pai que nos deu o Filho para morrer por nós na cruz. Os perfeitos não são outros que os bem-aventurados.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer diz que cada nova bem-aventurança aumenta o abismo entre os discípulos e o mundo: os que choram são os que não dançam segundo a música do mundo, os mansos calam-se quando ofendidos e não movem processos por seus direitos. Em que área concreta da sua vida hoje você percebe que se acomodou à música do mundo em vez de carregar o sofrimento e renunciar ao seu direito por causa de Cristo?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Para Bonhoeffer, o discípulo é o sal e a luz por toda a sua existência, e a fuga para a invisibilidade ('humilde') é, na verdade, negação do chamado e conformação com o mundo disfarçada de teologia da cruz. Onde você tem usado a desculpa da humildade ou da discrição para esconder a luz, e que custo real você teme se ela de fato brilhar diante das pessoas?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$No comentário sobre o irmão, Jesus iguala a ira, a palavra leviana e a ofensa deliberada ao assassinato, e diz para deixar a oferta diante do altar e ir primeiro reconciliar-se. Existe hoje um irmão que 'tem algo contra você' — alguém magoado, desprezado ou difamado por você — cuja reconciliação você vem adiando enquanto continua orando e adorando como se nada estivesse interposto entre você e Deus?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 7 — Sobre a invisibilidade da vida cristã  (aula ordem = 9)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 9;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 7 — Sobre a invisibilidade da vida cristã$t$,
      9,
$conteudo$Mateus 6

A justiça oculta

Guardai-vos de exercer a vossa justiça diante dos homens, com o fim de serdes vistos por eles; doutra sorte, não tereis galardão junto de vosso Pai celeste. Quando, pois, deres esmola, não toques trombeta diante de ti, como fazem os hipócritas, nas sinagogas e nas ruas, para serem glorificados pelos homens. Em verdade vos digo que eles já receberam a recompensa. Tu, porém, ao dares a esmola, ignore a tua mão esquerda o que faz a tua mão direita; para que a tua esmola fique em secreto; e teu Pai, que vê em secreto, te recompensará.

Mateus 6.1-4

No capítulo 5 de Mateus, tratamos da visibilidade da Igreja dos discípulos, culminando no conceito de perisson, o estilo de vida cristão que se destaca do mundo, que vai além do mundo justamente pelo que apresenta de extraordinário. Agora, o capítulo 6 retoma o conceito de perisson e mostra sua ambiguidade. De fato, é demasiado grande o perigo de uma compreensão equivocada do significado de perisson, isto é, de os discípulos entenderem que têm de começar a trabalhar de imediato para levantar na terra o reino dos céus, desprezando e até derrubando a ordem estabelecida, mostrando fanática indiferença ao tempo em que vivemos, na tentativa de realizar o extraordinário do novo mundo, de torná

lo visível, separando-se radical e definitivamente deste mundo para, assim, impor o que é extraordinário, o que é cristão, o que é adequado ao discipulado. É compreensível que pudesse haver um mal-entendido sobre o significado de perisson, de que mais uma vez estivesse sendo pregada aqui uma forma de vida piedosa, ainda que livre, nova e entusiástica. A carne piedosa estaria mais que disposta a submeter-se ao extraordinário, à pobreza, à verdade, ao sofrimento, disposta até mesmo a buscá-los, se isso enfim satisfizesse o desejo do coração, o desejo de ver algo com os próprios olhos, e não apenas com a fé.

Sim, haveria a vontade de mudar ligeiramente o limite entre a forma de vida piedosa e a obediência à Palavra até que tanto se aproximassem uma da outra a ponto de não ser mais possível distingui-las.

Afinal, poderiam argumentar, isso seria feito em prol daquele objetivo máximo, isto é, a realização do extraordinário.

Outros, por sua vez, estariam só esperando as palavras de Jesus acerca do extraordinário para lançar-se sobre ele com furor ainda maior. Enfim estaria desmascarado o fanático, o revolucionário entusiasta que quer desestabilizar o mundo, que exorta seus discípulos a abandonarem este mundo e construírem um novo. Isso ainda é obediência à palavra do Antigo Testamento? Acaso não se trata de pura justiça própria, escolha pelo indivíduo mesmo? Será que Jesus nada sabe sobre o pecado do mundo, que levará ao fracasso tudo que ele ordena? Desconhece os mandamentos revelados de Deus, dados para banir o

pecado? Não é esse extraordinário exigido justamente a demonstração de arrogância espiritual, que é a origem de todo fanatismo? Não, ao contrário, não é o extraordinário, mas são as coisas normais do dia a dia, que passam despercebidas, o sinal da obediência e da humildade verdadeiras. Se Jesus ordenasse a seus discípulos que assumissem seu lugar junto ao povo, em sua profissão, em sua responsabilidade, na obediência à lei, como os escribas ordenavam ao povo, ele teria se mostrado um homem piedoso, um ser humano realmente humilde, um obediente. Assim, teria dado incentivos a uma devoção mais séria, uma obediência mais rígida. Teria ensinado o que os mestres da lei já sabiam, mas que gostavam de ouvir proclamado com entusiasmo, isto é, que a piedade e a justiça verdadeiras não consistem apenas no ato externo, mas também na disposição do coração, e não apenas na disposição do coração, mas também na ação concreta. Isso teria sido de fato a “justiça que excede” como o povo precisava e da qual ninguém poderia se esquivar. Agora, porém, tudo tinha ido por água abaixo. Em lugar do humilde mestre da lei, reconhecia-se nele o entusiasta arrogante, o fanático. Sem dúvida, a pregação entusiasta sempre soube arrebatar o coração do ser humano, e sobretudo o coração mais nobre. Mas será que os mestres da lei não sabiam que, nesse coração, com toda a sua bondade e nobreza, falava a voz da carne? Acaso não conheciam, eles próprios, a violência da carne piedosa sobre os seres humanos? Jesus sacrificava os melhores filhos do povo, os verdadeiramente piedosos, numa luta inútil por uma ilusão. O extraordinário

— na verdade, não passava de obra voluntária, nascida no próprio coração piedoso. Era a afirmação da liberdade humana contra a obediência simples ao mandamento de Deus. Era a justificação do ser humano pelo próprio ser humano, que a lei não permite. Era a ilegítima autossantificação, que a lei condena. Era a obra escolhida por vontade própria, em oposição à obediência dentro dos limites. Era a destruição da Igreja de Deus, a negação da fé, o insulto à lei, a blasfêmia contra Deus. O extraordinário que Jesus ensinava era digno de morte perante a lei.

O que diz Jesus sobre isso tudo? “Guardai-vos de exercer a vossa justiça diante dos homens, com o fim de serdes vistos por eles” (Mt 6.1). O chamado ao extraordinário é o grande e inevitável perigo do discipulado. Portanto, atenção com esse extraordinário, com essa visibilidade do discipulado. Jesus contrapõe a essa alegria autêntica, corajosa, direta em relação ao visível um sonoro “Alto lá!”. Ele estabelece um limite ao extraordinário. Jesus chama à reflexão.

Os discípulos só terão esse extraordinário na reflexão. Devem tomar cuidado com isso. O

extraordinário, na verdade, não deve ocorrer a fim de ser visto, o extraordinário em nome do extraordinário, o visível apenas para se tornar visível. A “justiça que excede” dos discípulos não pode ser um fim em si mesma. Sim, ela deve se tornar visível, mas é preciso cuidado para que não aconteça com o objetivo de se tornar visível. É certo que a visibilidade do discipulado tem uma razão de ser, que é o chamado de Jesus Cristo, mas jamais é um alvo a ser buscado, pois aí novamente se perderia de vista o discipulado, aí haveria um instante de relaxamento e o discipulado seria interrompido, e não poderia mais continuar do ponto onde paramos para descansar, pois então teríamos de voltar ao início. Assim, iríamos nos dar conta de que já não estamos no discipulado. Portanto, algo deve se tornar visível, mas aí está o paradoxo: “Guardai-vos de exercer a vossa justiça [...] a fim de serdes vistos por eles”, mas

“Assim brilhe também a vossa luz diante dos homens...” (Mt 5.16)! Há um violento contraste entre os

capítulos 5 e 6. O visível deve permanecer invisível, e o visível não deve ser visto. A reflexão a que nos referíamos não deve nos remeter à reflexão sobre o nosso extraordinário. O cuidado com nossa justiça deve servir exatamente para que não precisemos ter cuidado com ela. Do contrário, o extraordinário não será mais o extraordinário do discipulado, mas o da vontade e do desejo próprios.

Como entender essa contradição? Façamos a primeira pergunta: de quem se deve esconder o visível do discipulado? Não de outros seres humanos; ao contrário, eles, mais que ninguém, devem ver brilhar a luz dos discípulos de Jesus. É ao próprio discípulo que a luz deve ficar oculta. Deve permanecer no discipulado e, em vez de olhar para si mesmo ou para o que faz, deve olhar para aquele que vai adiante dele. O discípulo tem de ficar oculto a si mesmo em sua justiça. Claro que ele também vê o extraordinário, mas a si mesmo permanece oculto nele; vê-o apenas ao olhar para Jesus, já não o vendo como extraordinário, mas como o natural, o habitual. Desse modo, para ele o visível está oculto, isto é, na obediência à palavra de Jesus. Se o extraordinário se lhe tornasse importante como tal, ele estaria agindo de maneira entusiástica e por vontade própria, segundo a carne. Mas, por ser discípulo de Jesus, age na obediência simples a seu Senhor; só pode ver o extraordinário como ato natural da obediência. De acordo com a palavra de Jesus, não pode ser diferente, já que o discípulo é a luz que ilumina; o discípulo em si nada faz para iluminar, ele está no discipulado, e apenas olha para seu Senhor. Justamente porque a essência cristã é necessariamente, isto é, indicativamente, o que é extraordinário, é, ao mesmo tempo, o normal, o oculto. Do contrário, não é o que constitui o cristão, ou seja, a obediência à vontade de Jesus Cristo.

Façamos a segunda pergunta: em que consiste a unidade do que é visível e do que fica oculto no que diz respeito ao conteúdo da ação no discipulado? Como pode algo ser visível e oculto simultaneamente?

Para responder a essa questão, retornemos ao que foi discutido no capítulo 5. O extraordinário, o visível, é a cruz de Cristo, sob a qual estão os discípulos. A cruz é, ao mesmo tempo, o necessário, o oculto, e o visível, o extraordinário.

A terceira pergunta a ser colocada: o que pode resolver o paradoxo entre os capítulos 5 e 6? O próprio conceito do discipulado resolve essa oposição. O discipulado é um compromisso exclusivo com Jesus Cristo. Desse modo, o discípulo sempre vê apenas seu Senhor e segue somente a ele. Se olhasse apenas para o extraordinário, já não estaria no discipulado. Para o discípulo, o extraordinário consiste unicamente na obediência simples à vontade do Senhor, ciente de que não há alternativa e que, portanto, o que ele faz é o natural a fazer.

A única reflexão que se ordena ao discípulo deve ser de natureza totalmente inconsciente, irrefletida na obediência, no discipulado e no amor. Se fizer o bem, que a mão esquerda ignore o que faz a mão direita.

Você não deve ter consciência do próprio bem que faz. Do contrário, é realmente o seu bem, e não o bem de Cristo. O bem de Cristo, o bem no discipulado, ocorre de modo inconsciente. A verdadeira obra do amor é sempre a obra que me fica oculta. Cuidado para que não saiba dela! Somente assim será o bem de Deus. Quando quero conhecer meu bem, meu amor, então já não é amor. Também o amor extraordinário ao inimigo fica oculto ao discípulo. Quando ele o ama, o inimigo deixa de ser o inimigo! Essa cegueira,

ou melhor, essa visão do discípulo, iluminada por Cristo, é sua certeza. A invisibilidade de sua vida diante de si mesmo é sua promessa.

À invisibilidade corresponde o reconhecimento. Não há nada oculto que não venha a ser revelado. Isso vem de Deus, diante do qual tudo está revelado, nada permanece oculto. Deus quer nos mostrar o que está oculto, quer torná-lo visível. O reconhecimento é a recompensa da invisibilidade ordenada por Deus. A pergunta que resta é: onde e de quem o ser humano recebe esse reconhecimento como recompensa? Se ele a deseja diante dos seres humanos, então essa já é sua recompensa. Não faz diferença se o indivíduo a procura na forma grosseira do reconhecimento público ou na forma sutil, para si mesmo. Quando a mão esquerda sabe o que a direita faz, quando exponho a meus próprios olhos o bem que faço, quando quero tomar conhecimento dele, é então que ofereço a mim mesmo a recompensa que Deus me reservava. Sou eu mesmo que revelo os bens que me deveriam permanecer ocultos. Não espero que Deus o revele a mim. Assim, já tenho minha recompensa. Quem, porém, persiste até o fim na invisibilidade perante si próprio, esse receberá a recompensa da revelação do próprio Deus. Mas quem consegue viver mantendo o extraordinário na invisibilidade, de modo que a mão esquerda ignore o que a mão direita faz? Que tipo de amor é esse que não sabe de si próprio, mas que pode permanecer invisível até o dia do juízo? É

evidente: por ser amor oculto, não pode ser uma virtude visível, um hábito do ser humano. Guardem-se, é o que se diz, para não confundirem o verdadeiro amor com alguma virtude amável ou com alguma

“qualidade” humana. É o amor que se esquece de si próprio, no sentido exato da palavra. Nesse amor, deve morrer aquele velho ser humano, com todas as suas virtudes e qualidades. Sim, nesse amor, no amor do discípulo, comprometido apenas com Cristo, morre o velho Adão. Com o enunciado “que a tua mão esquerda ignore o que faz a tua mão direita” está sendo proclamada a morte do velho ser humano.

Repetindo, por fim: quem consegue viver de modo a conciliar o capítulo 5 com o 6? Ninguém, senão aquele cujo velho ser humano morreu por causa de Cristo e que, na comunhão do discipulado, encontrou nova vida. O amor como ação da obediência simples é a morte do velho ser humano, que agora se reencontrou na justiça de Cristo e no irmão. Já não é ele quem vive, mas é Cristo quem vive nele. O amor do Cristo crucificado que entrega à morte o velho ser humano é o que vive no discípulo. De agora em diante, ele se encontra apenas em Cristo e no irmão.

A invisibilidade da oração

E, quando orardes, não sereis como os hipócritas; porque gostam de orar em pé nas sinagogas e nos cantos das praças, para serem vistos dos homens. Em verdade vos digo que eles já receberam a recompensa. Tu, porém, quando orares, entra no teu quarto e, fechada a porta, orarás a teu Pai, que está em secreto; e teu Pai, que vê em secreto, te recompensará. E, orando, não useis de vãs repetições, como os gentios; porque presumem que pelo seu muito falar serão ouvidos. Não vos assemelheis, pois, a eles; porque Deus, o vosso Pai, sabe o de que tendes necessidade, antes que lho peçais.

Mateus 6.5-8

Jesus ensina os discípulos a orar. O que significa isso? Que tenhamos o direito a orar, não é assim tão óbvio. Embora a oração seja uma necessidade natural do coração humano, não significa que qualquer tipo de oração seja válido diante de Deus. Mesmo quando praticada com disciplina e experiência, ainda pode ser inútil e vazia da promessa. Os discípulos podem orar porque Jesus, que conhece o Pai, assim lhes diz. Ele lhes promete que o Pai os ouvirá. Por isso mesmo os discípulos oram, porque estão em comunhão com Cristo, em seu discipulado. Quem estiver comprometido com Jesus no discipulado tem acesso ao Pai por intermédio dele. Assim, toda oração verdadeira é oração mediada por Jesus.

Tampouco há acesso direto ao Pai por meio da oração. É só por meio de Jesus Cristo que podemos encontrar o Pai na oração. O pressuposto da oração é a fé, a comunhão com Cristo. Ele é o único Mediador de nossa oração. Oramos com base em sua palavra. Portanto, nossa oração é sempre oração compromissada com sua palavra.

Oramos a Deus, em quem cremos por meio de Jesus Cristo. Por isso nossa oração jamais pode ser uma rogação a Deus; não precisamos mais nos apresentar diante dele. Podemos ter a certeza de que ele sabe do que necessitamos antes mesmo de pedir. Isso dá à oração grande esperança e alegre certeza. Não é a fórmula, nem a quantidade de palavras, mas a fé que alcança o coração paternal de Deus, que há muito nos conhece.

A oração verdadeira não é uma obra, um exercício, uma atitude piedosa, mas o pedido de um filho ao coração do Pai. Por isso, a oração nunca é demonstrativa, nem perante Deus, nem perante nós mesmos, nem perante os outros. Se Deus já não soubesse do que preciso, então eu teria de refletir sobre como dizê-lo a Deus, sobre o que dizer a ele e se devo dizê-lo. A fé, portanto, exclui de minha prece qualquer reflexão, qualquer demonstração.

A oração é absolutamente secreta. Ela se opõe a qualquer forma de reconhecimento público. Quem ora já não conhece a si próprio, mas apenas a Deus, a quem invoca. Uma vez que a oração não opera no mundo, mas é dirigida somente a Deus, é o exemplo perfeito de ação não demonstrativa. Contudo, também existe a oração transformada em demonstração, na qual o oculto é trazido à luz. Isso não ocorre apenas na oração pública, aquela que às vezes cai em vãs repetições — o que ocorre raramente, hoje em dia. Contudo, não há diferença; ao contrário, é muito mais perigoso quando eu me torno o próprio espectador de minha oração, quando oro diante de mim mesmo, seja porque tenho prazer na condição de espectador satisfeito, seja porque me surpreenda orando e me sinta estranho e envergonhado. O reconhecimento público é apenas uma forma ingênua da visibilidade que eu mesmo preparo para mim. Posso fazer uma encenação e tanto até mesmo sozinho em meu quarto. Chega a esse nível a possibilidade de deturparmos a palavra de Jesus. O reconhecimento público que procuro consiste em que eu seja ao mesmo tempo aquele que ora e aquele que ouve. Sou meu próprio espectador, ouço a mim mesmo. Por não querer esperar até que Deus ouça meu pedido, por não querer esperar até que Deus revele ter ouvido minhas preces, respondo eu mesmo à oração. Constato que orei adequadamente, e nessa constatação reside a satisfação de ser atendido. Minha oração foi respondida. Já tenho minha recompensa. Porque atendi a mim mesmo, Deus já não me atenderá. Porque eu mesmo me preparei a recompensa do reconhecimento público, Deus já não me recompensará.

O que é o quarto pequeno a que Jesus se refere, se não estou seguro nem diante de mim mesmo? Como fechá-lo de modo que nenhum espectador estrague a invisibilidade de minha oração e não me roube a recompensa da oração em secreto? Como me proteger de mim mesmo, de minha própria reflexão? Como

matar a reflexão enquanto reflito? A palavra já foi dita: a vontade de me impor por meio da oração deve morrer, deve ser destruída. Quando apenas a vontade de Jesus reinar sobre mim, e toda a minha vontade for a vontade dele, então minha vontade morrerá na comunhão com Jesus, no discipulado. Então posso orar para que se faça a vontade daquele que sabe do que preciso antes mesmo que eu o peça. Somente assim minha oração será certeira, forte e pura. Assim a oração de fato será pedir. O filho pede ao pai, que ele conhece. A prece, e não a adoração geral, é a essência da oração cristã. Isso corresponde à atitude do ser humano diante de Deus, pedindo de mãos estendidas, por saber que ele tem um coração de Pai.

Ainda que a oração verdadeira seja de natureza secreta, isso não quer dizer que a comunhão de oração não seja possível, mesmo que saibamos os perigos que se correm nesse caso. Seja uma oração feita na rua ou na solidão do quarto, seja longa ou curta, seja na litania da oração na Igreja ou o suspiro daquele que não sabe o que pedir, seja individual ou congregacional, o que importa é o reconhecimento: o Pai de vocês sabe do que precisam. Isso remete a oração exclusivamente ao Pai e liberta o discípulo da falsa confiança nas obras.

Portanto, vós orareis assim: Pai nosso, que estás nos céus, santificado seja o teu nome; venha o teu reino; faça-se a tua vontade, assim na terra como no céu; o pão nosso de cada dia dános hoje; e perdoa-nos as nossas dívidas, assim como nós temos perdoado aos nossos devedores; e não nos deixes cair em tentação; mas livra-nos do mal [pois teu é o reino, o poder e a glória para sempre. Amém]! Porque, se perdoardes aos homens as suas ofensas, também vosso Pai celeste vos perdoará; se, porém, não perdoardes aos homens [as suas ofensas], tampouco vosso Pai vos perdoará as vossas ofensas.

Mateus 6.9-15

Jesus não disse aos discípulos apenas como orar, mas também o que orar. O Pai-nosso não é somente um exemplo de oração para os discípulos, mas o modo como devem orar, conforme Jesus lhes ensinou. É

certo que, com essa oração, serão atendidos por Deus. O Pai-nosso é a oração por excelência. Nela está a essência e os limites de toda oração dos discípulos. Mais uma vez, Jesus não deixa os discípulos na incerteza; no Pai-nosso ele os conduz a uma clareza total da oração.

“Pai nosso, que estás nos céus.” Juntos, os discípulos invocam o Pai celestial que já sabe de tudo que seus filhos precisam. O chamado de Jesus os une e os torna irmãos. Em Jesus, reconheceram a amorosa bondade do Pai. Em nome do Filho de Deus, podem chamá-lo de Deus, o Pai. Estão na terra, e seu Pai está no céu. Do alto ele os vê, e eles levantam os olhos a ele.

“Santificado seja o teu nome.” O nome paternal de Deus, como foi relevado aos discípulos em Jesus Cristo, deve ser santificado entre eles; pois nesse nome está contido todo o evangelho. Que não seja a vontade de Deus permitir que seu santo evangelho seja obscurecido e corrompido por falsa doutrina e impiedade de vida. Ao contrário, que seja a vontade de Deus sempre revelar aos discípulos seu santo nome em Jesus Cristo. Que ele capacite todos os pregadores a proclamarem o evangelho de salvação em toda a sua pureza, que afaste os tentadores e converta os inimigos de seu nome.

“Venha o teu reino.” Em Jesus Cristo, os discípulos presenciaram o reino de Deus irrompendo na terra.

Aqui Satanás foi vencido, e foram quebrados o poder do mundo, do pecado e da morte. Mas o reino de Deus continua sofrendo e lutando. Também, a pequena comunidade dos que foram chamados participa

dessa luta e desse sofrimento. Está sob o poder do reino de Deus em sua nova justiça, mas em plena perseguição. Que seja a vontade de Deus promover o crescimento do reino de Jesus Cristo em sua Igreja.

Que bem depressa ele acabe com os outros reinos deste mundo e estabeleça seu reino com poder e glória. “Faça-se a tua vontade, assim na terra como no céu.” Na comunhão com Jesus Cristo, os discípulos fizeram da vontade de Deus a vontade deles. Oram para que a vontade de Deus seja feita em toda a terra.

Nenhuma criatura deverá se pôr contra ele. Mas, porque a vontade do mal continua a viver no discipulado, e continua a querer separálos da comunhão de Jesus, eles oram para que a vontade de Deus reine cada vez mais sobre eles e destrua toda resistência. No final, todos se dobrarão diante da vontade de Deus, em adoração e ação de graças, na alegria ou na adversidade. O céu e a terra se submeterão a Deus.

Mais que tudo, os discípulos de Jesus devem orar pelo nome de Deus, pelo reino de Deus e pela vontade de Deus. É bem verdade que Deus não necessita dessa oração, mas é por meio dela que os próprios discípulos participam dos bens celestiais, pelos quais oram. Por meio dessa oração, os discípulos podem ajudar a apressar o final.

“O pão nosso de cada dia dá-nos hoje.” Enquanto os discípulos estiverem na terra, não têm de se envergonhar de pedir ao Pai celestial o sustento do corpo. Aquele que criou os seres humanos na terra quer conservar e proteger a vida. Não é da vontade dele que sua criação seja desprezada. Os discípulos oram pelo pão coletivo. Ninguém deverá possuir o pão só para si. Pedem a Deus que dê o pão a todos os seus filhos sobre a terra, pois todos eles são seus irmãos segundo a carne. Os discípulos sabem que o pão que nasce na terra vem do alto e nos é dado por Deus somente. Por isso, não tomam simplesmente o pão, mas rogam por ele. O pão é renovado dia a dia, porque vem de Deus. Os discípulos não pedem mais pão do que necessitam, mas pedem a dádiva divina para hoje, o suficiente para viverem na comunhão de Jesus, e por isso louvam a amorosa bondade de Deus. Com essa oração, comprova-se a fé dos discípulos na ação viva de Deus na terra para o bem deles.

“E perdoa-nos as nossas dívidas, assim como nós temos perdoado aos nossos devedores.” O reconhecimento de suas dívidas é o lamento diário dos discípulos. Os que poderiam viver sem pecado na comunhão de Cristo pecam diariamente por toda espécie de descrença, preguiça para orar, indisciplina do corpo, vaidade, inveja, ódio e ambição. Por isso, devem pedir perdão a Deus todos os dias. No entanto, Deus só atende à sua oração se eles estiverem dispostos a perdoar uns aos outros de bom grado e fraternalmente. Assim, juntos, levam suas dívidas até Deus e suplicam por sua graça. Deus não quer perdoar apenas as minhas dívidas, mas as nossas.

“E não nos deixes cair em tentação.” As tentações dos discípulos são inúmeras. Satanás os ataca de todos os lados, na tentativa de fazêlos cair. A falsa segurança e a dúvida ímpia investem duramente contra eles. Os discípulos, cientes de sua fraqueza, não procuram despertar a tentação a fim de, com isso, provar a força de sua fé. Ao contrário, pedem a Deus que não ponha à prova sua frágil fé e que os proteja na hora da tentação.

“Mas livra-nos do mal.” Por último, os discípulos oram para ser libertos deste mundo mau e herdar o reino dos céus. É a oração por uma morte abençoada e pela salvação da Igreja no final dos tempos deste

mundo.

“Pois teu é o reino!” Tal certeza renovada os discípulos recebem diariamente na comunhão com Jesus Cristo, do qual depende o cumprimento de todas as suas orações. Nele o nome de Deus é santificado; nele vem o reino de Deus; nele é feita a vontade de Deus. Por causa dele, a vida física dos discípulos é preservada, por causa dele, recebem o perdão dos pecados; em sua força, são salvos para a vida eterna.

Dele é o reino, o poder e a glória para todo o sempre, na comunhão do Pai. Os discípulos têm total certeza disso.

Para resumir o que se falou sobre a oração, Jesus diz mais uma vez que tudo depende de que eles recebam o perdão e que esse perdão só lhes será concedido se eles tomarem parte da fraternidade dos pecadores.

A invisibilidade das práticas piedosas

Quando jejuardes, não vos mostreis contristados como os hipócritas; porque desfiguram o rosto com o fim de parecer aos homens que jejuam. Em verdade vos digo que eles já receberam a recompensa. Tu, porém, quando jejuares, unge a cabeça e lava o rosto, com o fim de não parecer aos homens que jejuas, e sim ao teu Pai, em secreto; e teu Pai, que vê em secreto, te recompensará.

Mateus 6.16-18

Jesus vê como natural que seus discípulos guardem a prática piedosa do jejum. O rigoroso exercício da abstinência faz parte da vida dos discípulos. Essa prática tem o propósito de torná--los mais dispostos e alegres para seguir o caminho e realizar a obra que lhes foi confiada. Assim, é disciplinada a vontade própria e preguiçosa que recusa empenhar-se no serviço, e a carne é humilhada e castigada. Na prática da abstinência revela-se o grau de diferença de minha vida cristã com relação ao mundo. A pessoa que não se dedica ao ascetismo, que desfruta de todos os desejos da carne, desde que “autorizados” pela justitia civilis, dificilmente se dedicará a servir a Cristo. A carne satisfeita não tem prazer na oração e não se mostra disposta ao serviço abnegado.

Por isso, a vida do discípulo precisa de rigorosa disciplina externa. Não porque seja possível, por meio da disciplina, destruir o desejo da carne ou sepultar o velho ser humano; isso só se realiza pela fé em Jesus Cristo. Mas é justamente o discípulo, o cristão autêntico, que teve a vontade quebrada e o velho ser humano morto em Cristo, que conhece a rebeldia e a arrogância diária de sua carne. Conhece sua preguiça e indisciplina e reconhece nelas a fonte do orgulho que tem de ser destruído. Isso será alcançado pelo exercício diário e extraordinário da disciplina. Com relação ao discípulo, pode-se dizer que o espírito está pronto, mas a carne é fraca. Por isso, “vigiai e orai”. O espírito reconhece o caminho do discipulado e está disposto a segui-lo, mas a carne é temerosa, o caminho lhe parece árduo, tortuoso, demasiado trabalhoso. Assim, o espírito é silenciado. O espírito aceita o mandamento de Jesus de amor incondicional ao inimigo, mas a carne e o sangue são muito fortes, de modo que o mandamento não consegue se concretizar. Portanto, a carne tem de compreender, no exercício diário e extraordinário da disciplina, que não tem direitos próprios. Nisso a prática diária e regrada da oração nos auxilia, e também a meditação diária na Palavra de Deus. Em suma, toda prática que discipline o corpo e vise à abstinência nos serve de ajuda.

A princípio, a carne resiste frontalmente a essa humilhação diária, depois essa resistência aparece mascarada nas palavras do espírito, isto é, em nome da liberdade evangélica. A oposição à palavra de Jesus se manifesta quando a liberdade evangélica da imposição da lei, do autoflagelo e do castigo substitui, por princípio, o verdadeiro uso evangélico da disciplina, da ascese; assim são justificadas, em nome da liberdade cristã, a indisciplina e a irregularidade na oração, no estudo da Palavra e na vida corporal. Então já não se reconhece a estranheza da vida diária do discipulado em relação ao mundo, tampouco a alegria e a verdadeira liberdade que resultam da disciplina correta na vida do discípulo.

Sempre que o cristão reconhece que fracassou no serviço, que está menos disposto, que se tornou culpado em relação à vida do outro, em relação à culpa do outro, que sua alegria em Deus vem se esvaindo, que já não tem forças para orar, sempre que o cristão reconhece isso, deve atacar a própria carne, a fim de, com exercício, jejum e oração (Lc 2.37; 4.2; Mc 9.29; 1Co 7.5), estar ainda mais preparado para servir. Qualquer objeção de que o cristão deve procurar sua proteção na fé, na Palavra, e não na ascese, não é válida. É uma objeção cruel, que de nada nos ajuda a buscar uma nova maneira de ser. O que é mesmo a vida de fé senão a luta múltipla e sem fim do espírito contra a carne? Como alguém pode querer viver na fé, se a oração o aborrece, se não tem prazer na Palavra das Escrituras, se o sono, a comida e o desejo sexual sempre lhe roubam a alegria em Deus? A ascese é sofrimento por vontade própria, é passio activa, e não passio passiva, e justamente por isso é muito perigosa. Na ascese, existe sempre o desejo ímpio de estar em pé de igualdade com Jesus Cristo por meio do sofrimento. Como se não bastasse, há ainda o desejo de tomar o lugar do sofrimento de Cristo, de realizar, ela própria, a obra do sofrimento de Cristo, isto é, de matar o velho ser humano.

Desse modo, a ascese atribui a si mesma a seriedade amarga e última da obra salvadora de Cristo. Aqui, a prática da ascese se revela terrivelmente. O sofrimento voluntário que, baseado no sofrimento de Cristo, deveria apenas preparar para melhor serviço e maior humilhação, transforma-se em terrível caricatura do próprio sofrimento de Cristo. Agora, ele quer ser visto; é a acusação cruel e vívida ao próximo, pois se tornou caminho de salvação. Assim apresentando-se ao “público”, já recebeu a recompensa que os seres humanos buscam.

“Unge a cabeça e lava o rosto” poderia ser, novamente, uma oportunidade para uma forma mais sutil de prazer ou glória própria. Mas isso seria uma interpretação equivocada e mero fingimento. Jesus diz aos discípulos que sejam bem despretensiosos nos exercícios voluntários da humildade, que não imponham a ninguém essas práticas como se fossem repreensão ou lei, mas que sejam agradecidos e alegres por terem a oportunidade de permanecer no serviço ao Senhor. Não estamos nos referindo à aparência alegre do discípulo como cristão típico, mas à verdadeira invisibilidade da ação cristã, à humildade que não tem consciência de si mesma, assim como o olho não vê a si mesmo, mas apenas ao outro. Um dia, essa invisibilidade será revelada, mas somente por Deus, jamais por ela mesma.

A simplicidade da vida despreocupada

Não acumuleis para vós outros tesouros sobre a terra, onde a traça e a ferrugem corroem e onde ladrões escavam e roubam; mas ajuntai para vós outros tesouros no céu, onde traça nem ferrugem corrói, e onde ladrões não escavam, nem roubam; porque, onde está o teu tesouro, aí estará também o teu coração. São os olhos a lâmpada do corpo. Se os teus olhos forem bons, todo o teu corpo será luminoso; se,

porém, os teus olhos forem maus, todo o teu corpo estará em trevas. Portanto, caso a luz que em ti há sejam trevas, que grandes trevas serão! Ninguém pode servir a dois senhores; porque ou há de aborrecer-se de um e amar ao outro, ou se devotará a um e desprezará ao outro. Não podeis servir a Deus e às riquezas.

Mateus 6.19-24

A vida do discípulo só se sustenta enquanto não houver obstáculo algum entre ele e Cristo, nem a lei, nem a piedade, nem o mundo. O discípulo sempre vê somente a Cristo. Não vê Cristo e a lei, Cristo e a piedade, Cristo e o mundo. Não se perde nessas reflexões. Ao contrário, em tudo segue somente a Cristo.

Seu olhar está fixado única e totalmente na luz que vem de Cristo, luz que não tem escuridão, nem ambiguidade. Assim como o olho deve ser claro, puro, voltado para uma só direção, para que o corpo continue na luz; assim como o pé e a mão não devem receber luz de outra parte senão do olho; assim como o pé tropeça e a mão erra quando o olho se embaça; assim como o corpo todo está na escuridão quando se apaga a luz dos olhos, assim também é com o discípulo, que só permanece na luz enquanto olha unicamente para Cristo, e para nada mais; portanto, o coração do discípulo deve se orientar somente para Cristo. Se o olho enxergar outra coisa além do real, o corpo todo é enganado. Se o coração se apegar à ilusão do mundo, à criatura em vez de ao Criador, o discípulo está perdido.

São os bens do mundo que querem desviar o coração do discípulo da direção de Jesus. Para onde se volta o coração do discípulo? Eis a questão. Dirige-se às riquezas do mundo ou a Cristo e às riquezas do mundo? Ou dirige-se somente a Cristo? A luz do corpo são os olhos, e a luz do discípulo é o coração. Se os olhos estão embaçados, então o corpo deve estar na escuridão! Se o coração é escuridão, que grandes trevas haverá no interior do discípulo! Pois o coração se cobre de trevas quando se apega às riquezas do mundo. Nesse caso, por mais insistente que seja o chamado de Jesus, não será ouvido, não encontrará acesso ao ser humano, pois o coração está fechado e pertence a outro. Assim como a luz não entra no corpo quando o olho é mau, a palavra de Jesus também não é mais ouvida pelo discípulo quando o coração se fecha. A palavra foi sufocada como a semente entre os espinhos “com os cuidados, riquezas e deleites da vida” (Lc 8.14).

A direção única do olho e do coração é como a invisibilidade que nada sabe senão a palavra e o chamado de Cristo, invisibilidade que consiste na completa comunhão com Jesus. Como o discípulo poderá lidar com as riquezas deste mundo de modo unidirecional? Jesus não proíbe os discípulos de possuírem e usarem bens. Ele foi ser humano, comia e bebia, como seus discípulos. Ao fazer isso, santificou o uso desses bens. Agradecido, o discípulo pode usar os bens que depressa se consomem para a alimentação e para a necessidade diária do corpo.

Andemos como peregrinos,

Vazios e de tudo desprovidos; O muito acumular

Só faz a jornada pesar.

Quem quiser, acumule até morrer;

andamos sem nada ter,

com pouco nos saciamos;

só do necessário precisamos.

(Tersteegen)

É para isso que nos servem os bens, para que façamos uso deles; não, ao contrário, para serem acumulados. Assim Israel, no deserto, recebia todos os dias o maná das mãos de Deus e não precisava se preocupar com comida e bebida; e assim como o maná se estragava quando era guardado para o dia seguinte, também o discípulo receberá diariamente sua parcela das mãos de Deus. Mas, se quiser acumular como posse, corrompe a dádiva e a si mesmo. O coração se apega ao tesouro guardado. Os bens acumulados se tornam obstáculos entre mim e Deus. Onde está meu tesouro, ali está minha confiança, minha segurança, meu consolo, meu deus. Tesouro é idolatria.1

Onde, porém, traçar a linha que delimita entre os bens para uso próprio e o tesouro que não devo possuir? Se invertermos o enunciado e dissermos: “Onde o coração se apega, ali está seu tesouro”, já sabemos a resposta. Pode ser um tesouro pequeno e insignificante; o tamanho não importa, o que importa é o coração, é você. E, se eu continuar perguntando como posso saber a que se apega meu coração, a resposta também é simples e clara: tudo que o impede de amar a Deus acima de todas as coisas, tudo que serve de obstáculo entre você e a obediência a Jesus, aí está o tesouro a que se apega seu coração. Contudo, já que o coração do ser humano precisa de um tesouro a que se apegar, ele pode ter um que seja de acordo com a vontade de Jesus; 2 mas não é um tesouro na terra, onde se deterioraria, e sim no céu, onde dura para sempre. Os “tesouros” no céu aos quais Jesus se refere não são aquele tesouro, isto é, o próprio Jesus, mas, na verdade, os tesouros acumulados pelos discípulos. Assim, há a grande promessa de que, no discipulado de Jesus, o discípulo acumula tesouros celestiais, tesouros que não se corroem, que aguardam o discípulo e aos quais ele se juntará. Que tesouros poderiam ser esses senão aquele extraordinário, o secreto da vida do discípulo? Que tesouros poderiam ser senão os frutos do sofrimento de Cristo, que sustentam a vida dos discípulos?

Se o discípulo dedicar seu coração totalmente a Deus, ficará claro que não poderá servir a dois senhores. Isso ele não pode fazer. No discipulado, é simplesmente impossível. Seria, de fato, uma tentativa natural querer comprovar a sabedoria e a experiência cristãs justamente na demonstração de que é possível servir a dois senhores, às riquezas e a Deus, concedendo a cada um seu direito correspondente. Por que não sermos, como filhos de Deus, também filhos alegres deste mundo, filhos que se alegram nas boas dádivas de Deus e veem suas riquezas como bênção dele? Deus e o mundo, Deus e as riquezas são opostos entre si, pois o mundo e as riquezas querem conquistar nosso coração e só se revelam após terem alcançado o que pretendiam. Sem nosso coração, as riquezas e o mundo nada são.

Dele se alimentam; portanto, são opostos a Deus. Só podemos dar nosso coração a um deles em devoção total, e só podemos servir totalmente a um senhor. O que impedir essa devoção deve ser desprezado. De acordo com a palavra de Jesus, há somente dois sentimentos em relação a Deus: devoção ou desprezo. Se não amarmos a Deus, o odiaremos. Não existe meio-termo. Deus é assim, e por isso mesmo ele é Deus; só pode ser amado ou odiado. Existe somente esta opção: amamos a Deus ou os bens do mundo. Se você ama o mundo, odeia a Deus; se você ama a Deus, odeia o mundo. Isso não depende de sua vontade nem de sua ação. Com toda a certeza, você não quererá isso nem terá consciência do que faz; ao contrário, não quer que isso aconteça, pois seu desejo é exatamente servir a dois senhores. Quer amar a Deus e os bens

e, portanto, jamais admitirá que odeia a Deus. Você ama a Deus nos seus próprios termos. Se amar a Deus e também os bens deste mundo, a devoção a Deus é desprezo, o olhar já não se volta para uma única direção, o coração já não está em comunhão com Jesus. Queiramos ou não, não pode ser diferente.

Não podem servir a dois senhores, vocês que estão no discipulado.

Por isso, vos digo: não andeis ansiosos pela vossa vida, quanto ao que haveis de comer ou beber; nem pelo vosso corpo, quanto ao que haveis de vestir. Não é a vida mais do que o alimento, e o corpo, mais do que as vestes? Observai as aves do céu: não semeiam, não colhem, nem ajuntam em celeiros; contudo, vosso Pai celeste as sustenta. Porventura, não valeis vós muito mais do que as aves? Qual de vós, por ansioso que esteja, pode acrescentar um côvado ao curso da sua vida? E por que andais ansiosos quanto ao vestuário? Considerai como crescem os lírios do campo: eles não trabalham, nem fiam. Eu, contudo, vos afirmo que nem Salomão, em toda a sua glória, se vestiu como qualquer deles. Ora, se Deus veste assim a erva do campo, que hoje existe e amanhã é lançada no forno, quanto mais a vós outros, homens de pequena fé? Portanto, não vos inquieteis, dizendo: Que comeremos? Que beberemos? Ou: Com que nos vestiremos? Porque os gentios é que procuram todas estas coisas; pois vosso Pai celeste sabe que necessitais de todas elas; buscai, pois, em primeiro lugar, o seu reino e a sua justiça, e todas estas coisas vos serão acrescentadas. Portanto, não vos inquieteis com o dia de amanhã, pois o amanhã trará os seus cuidados; basta ao dia o seu próprio mal.

Mateus 6.25-34

Não andem ansiosos! As riquezas parecem dar segurança e conforto ao coração humano, mas na verdade são a causa da ansiedade. O coração que se apega às riquezas recebe com elas o pesado fardo da ansiedade. A ansiedade acumula tesouros, e os tesouros produzem a ansiedade. Queremos assegurar a vida por meio das riquezas; queremos tranquilidade por meio das preocupações; na verdade, porém, ocorre justamente o contrário. As correntes que nos prendem às riquezas, que seguram as riquezas, são elas próprias ansiedade.

A má utilização das riquezas consiste na tentativa de garantirmos, por meio delas mesmas, o amanhã. A ansiedade está sempre voltada para o futuro. Os bens materiais, porém, no sentido mais estrito, são destinados ao hoje. É a própria tentativa de garantir o amanhã que torna o hoje tão intranquilo. Basta ao dia o seu próprio mal. Aquele que deposita o amanhã totalmente nas mãos de Deus e recebe, hoje, o que precisa para viver é o que está realmente tranquilo. O que recebo diariamente me livra do amanhã. A preocupação com o futuro é o que me traz o desassossego sem fim. “Não vos inquieteis com o dia de amanhã” poderia ser interpretado como cruel desprezo aos pobres e miseráveis, justamente aos quais Jesus se dirige, aqueles que, do ponto de vista humano, amanhã mesmo podem morrer de fome se, hoje, não tomarem providências. Mas pode também ser entendido como lei que o ser humano não suporta e que afasta de si com ódio, ou ainda pode se tratar da mensagem excepcional do próprio evangelho da liberdade dos filhos de Deus, dos filhos que têm um Pai no céu e que lhes deu seu Filho amado. Acaso não nos dará generosamente todas as coisas aquele que nos deu seu próprio Filho?

“Não vos inquieteis com o dia de amanhã.” Isso não deve ser compreendido como sabedoria de vida, nem como lei. Isso é única e exclusivamente o evangelho de Jesus Cristo. Só o discípulo que reconheceu a Jesus pode receber nessa palavra e por meio dela a garantia do amor do Pai de Jesus Cristo e a liberdade de todas as coisas. Não é a ansiedade que livra o discípulo da ansiedade, mas a fé em Jesus Cristo. Agora ele sabe: nem sequer é possível andarmos ansiosos (v. 27). O dia de amanhã e a hora seguinte não estão sob nosso controle. Não faz sentido fingir que podemos tomar providências para o dia seguinte. Afinal, nada podemos mudar nas circunstâncias deste mundo. Só Deus pode tomar providências, porque é ele que governa o mundo. Porque não podemos providenciar o amanhã, porque não temos esse poder, não devemos ficar ansiosos. Se o fizermos, estaremos nos colocando no lugar de Deus.

Além disso, porém, o discípulo também sabe que não só não pode nem deve se preocupar, mas que não há necessidade de se preocupar. Não se ganha o pão de cada dia com ansiedade nem com trabalho, pois quem o providencia é Deus, o Pai. Os pássaros e os lírios não trabalham nem fiam; ainda assim, são alimentados e vestidos e recebem sua parcela sem nenhuma ansiedade. Usam os bens deste mundo apenas para as necessidades do dia; não acumulam e por isso mesmo glorificam o Criador, e não por meio de seu esforço, trabalho e preocupação, mas porque recebem todos os dias, com simplicidade, as dádivas que Deus dá. Por isso, pássaros e lírios servem de exemplo para os discípulos. Jesus dissolve a suposta relação necessária entre trabalho e subsistência que não leva Deus em conta. Deus não glorifica o pão de cada dia como sendo a recompensa do trabalho, mas refere-se, por outro lado, à simplicidade despreocupada daqueles que andam nos caminhos de Jesus e tudo recebem como dádivas de Deus.

Nenhum animal trabalha para sobreviver, mas cada um tem sua função; depois, procura e encontra alimento. O passarinho voa e canta, faz o ninho e gera os filhotes; esse é seu trabalho, mas não é dele que se alimenta. Os bois tiram o arado, os cavalos servem de transporte e nas lutas, as ovelhas fornecem lã, leite e queijo, e isso é o que fazem, mas não é daí que obtêm o alimento, e sim da terra que faz brotar a grama que a todos alimenta pela bênção de Deus. Assim, o ser humano também deve e tem de trabalhar e fazer algo, mas não pode esquecer que seu alimento não vem de seu trabalho, mas de outro lugar, a saber, da rica bênção de Deus — ainda que possa parecer que é de seu trabalho que provém o alimento, já que Deus nada lhe dará se ele não trabalhar. De igual modo, o passarinho, que não semeia nem colhe, também morreria de fome se não voasse em busca de alimento. Que ele encontre alimento não é, contudo, mérito seu, mas bondade de Deus. Pois quem põe o alimento onde ele pode encontrá-lo? Se Deus nada puser, nada se encontrará, mesmo que o mundo se mate de trabalhar e procurar. (Lutero)

E, se o Criador assim sustenta pássaros e lírios, acaso o Pai deixaria de alimentar seus filhos que todos os dias lhe suplicam? Acaso não poderia ele dar o que precisam para as necessidades do dia a dia, se a ele pertencem todas as riquezas da terra, as quais pode distribuir conforme lhe agrada?

Diariamente Deus me dê

tanto quanto para a vida eu precisar.

Aos pássaros ele sempre provê:

como não iria de mim cuidar?

(Claudius)

A ansiosa preocupação com a vida é própria dos gentios, que não têm fé, que preferem confiar em sua força e em seu trabalho a confiar em Deus. Eles vivem ansiosos porque não se dão conta de que o Pai já sabe que precisamos de todas essas coisas. Por isso querem fazer, eles mesmos, o que não esperam de Deus. Mas, para o discípulo, o que vale é: “Busquem, pois, em primeiro lugar, o seu reino e a sua justiça, e todas estas coisas lhes serão acrescentadas”. É evidente, portanto, que a preocupação com alimento e vestuário ainda não é a busca pelo reino dos céus, como tanto gostamos de dizer, como se o trabalho em prol da família e de nós mesmos, como se a preocupação pelo pão e pela morada já fossem a busca pelo reino de Deus, como se essa busca se realizasse simplesmente em nossas preocupações cotidianas. O reino de Deus e a justiça divina são algo totalmente diferente daquilo que nos seria acrescentado em dádivas deste mundo. O reino de Deus nada mais é que a justiça sobre a qual falam os capítulos 5 e 6, a justiça da cruz de Cristo e do discipulado sob a cruz. A comunhão de Jesus e a obediência a seu mandamento vêm em primeiro lugar, e tudo o mais vem na sequência. Não são coisas que acontecem ao mesmo tempo, mas umas após as outras. Antes, portanto, da preocupação pela vida, pela comida e pelo vestuário, pelo emprego e pela família, vem a busca pela justiça de Cristo.

Aí está um resumo breve e claro de tudo que foi dito anteriormente. Essa palavra de Jesus também pode ser interpretada como um fardo que não se pode suportar, que não permite aos pobres e miseráveis subsistirem — mas também pode ser entendida como o próprio evangelho que promete alegria e liberdade completa. Jesus não fala de coisas que o ser humano deve, mas não pode; fala do que Deus nos deu e ainda nos dará. Uma vez que Cristo nos foi dado, e como fomos chamados ao discipulado, tudo, mas tudo mesmo, nos é dado com ele. Todas as outras coisas nos serão depois acrescentadas. Quem está no discipulado de Jesus e olha somente para a justiça de Cristo, esse é discípulo nas mãos de Jesus Cristo e do Pai e está sob sua proteção; nada pode acontecer com quem está na comunhão do Pai, e já não pode duvidar de que o Pai alimentará seus filhos e não os deixará morrer de fome. Na hora certa, Deus nos ajudará. Ele sabe do que precisamos.

Depois de um longo período no discipulado, à pergunta “Alguma vez vocês passaram necessidade?”, o discípulo responderá “Nunca, Senhor”. Como alguém, mesmo faminto e nu, perseguido e em perigo, mas com a certeza da comunhão com Jesus Cristo, pode sentir necessidade de algo?$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer afirma que o reconhecimento público que buscamos pode ser sutil: na oração eu me torno meu próprio espectador, respondo a mim mesmo e constato que orei bem, e nessa constatação já recebo minha recompensa, de modo que Deus já não me recompensa. Em que momentos a sua oração ou o seu serviço deixaram de ser um pedido de filho ao Pai e viraram uma encenação diante de si mesmo?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O capítulo ensina que a verdadeira obra do amor é a que me fica oculta — 'que a mão esquerda ignore o que faz a mão direita' — a ponto de, quando amo o inimigo, ele deixar de ser inimigo. Há algum bem que você fez recentemente sobre o qual ficou consciente e satisfeito demais, e o que mudaria na sua vida prática se você buscasse que esse bem permanecesse invisível até para você mesmo?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer defende o jejum e a disciplina externa não como modo de matar o velho homem (isso só a fé faz), mas como ataque diário à carne preguiçosa que recusa o serviço — e adverte que a ascese pode virar caricatura, querendo ser vista e acusando o próximo. Onde sua carne 'satisfeita' anda sem prazer na oração e na Palavra, e que disciplina concreta e secreta você precisaria retomar para estar mais disposto ao serviço, sem transformá-la em vitrine?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 8 — A separação da comunidade dos discípulos  (aula ordem = 10)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 10;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 8 — A separação da comunidade dos discípulos$t$,
      10,
$conteudo$Mateus 7

Os discípulos e os descrentes

Não julgueis, para que não sejais julgados. Pois, com o critério com que julgardes, sereis julgados; e, com a medida com que tiverdes medido, vos medirão também. Por que vês tu o argueiro no olho de teu irmão, porém não reparas na trave que está no teu próprio? Ou como dirás a teu irmão: Deixa-me tirar o argueiro do teu olho, quando tens a trave no teu? Hipócrita! Tira primeiro a trave do teu olho e, então, verás claramente para tirar o argueiro do olho de teu irmão. Não deis aos cães o que é santo, nem lanceis ante os porcos as vossas pérolas, para que não as pisem com os pés e, voltandose, vos dilacerem. Pedi, e dar-se-vos-á; buscai e achareis; batei, e abrir-se-vos-á.

Pois todo o que pede recebe; o que busca encontra; e, a quem bate, abrir-se-lhe-á. Ou qual dentre vós é o homem que, se porventura o filho lhe pedir pão, lhe dará pedra? Ou, se lhe pedir um peixe, lhe dará uma cobra? Ora, se vós, que sois maus, sabeis dar boas dádivas aos vossos filhos, quanto mais vosso Pai, que está nos céus, dará boas coisas aos que lhe pedirem? Tudo quanto, pois, quereis que os homens vos façam, assim fazei-o vós também a eles; porque esta é a Lei e os Profetas.

Mateus 7.1-12

Uma necessária conexão nos leva dos capítulos 5 e 6 aos versículos acima e, depois, ao glorioso final do Sermão do Monte. O capítulo 5 trata do extraordinário no discipulado ( perisson); o capítulo 6, da justiça simples e secreta dos discípulos ( haplous). Nos dois casos, os discípulos são retirados da comunidade a que pertenciam e se comprometem unicamente com Jesus. Foi claramente traçado um limite. Daí vem a questão sobre o relacionamento dos discípulos com os demais seres humanos: essa separação lhes confere direitos singulares? Podem reivindicar autoridade especial sobre os outros porque receberam poderes, critérios e talentos para distinguir o verdadeiro do falso? Era de imaginar que os discípulos de Jesus decidissem se livrar do mundo ao redor com uma sentença definitiva, convencidos de ser essa a vontade de Deus. Por isso, Jesus teve de esclarecer que esses mal-entendidos ameaçariam seriamente o discipulado. Os discípulos estão proibidos de julgar. Se o fizerem, eles próprios serão julgados por Deus. A espada com que condenam seu irmão recairá sobre eles mesmos. O golpe com que se separam do outro, como que separando os justos dos injustos, separa-os de Jesus.

Por que é assim? O discípulo vive totalmente da comunhão com Jesus Cristo. Sua justiça está apenas nessa comunhão e nunca fora dela. Jamais pode usá-la como medida, como se a tivesse a seu dispor. O

que faz dele um discípulo não é uma nova medida para sua vida, mas unicamente o próprio Jesus Cristo, o Mediador, o Filho de Deus. Por isso, sua própria justiça lhe deve permanecer oculta na comunhão com Jesus. Já não pode ver, observar nem julgar a si mesmo; vê somente Jesus, é visto somente por Jesus, é julgado e agraciado somente por Jesus. Não há, portanto, uma medida de vida correta que separa os discípulos dos outros, mas somente Jesus Cristo é a medida; o discípulo sempre vê o outro somente como

alguém de quem Jesus está se aproximando. O discípulo se encontra com o outro somente porque vai ao encontro dele na companhia de Jesus. Jesus vai ao encontro do outro à frente do discípulo, que o segue.

Portanto, o encontro do discípulo com o outro nunca é o encontro livre entre duas pessoas que possuem opiniões, medidas e juízos totalmente diferentes. Ao contrário, o discípulo pode se encontrar com o outro somente como alguém ao encontro de quem o próprio Jesus está indo. O que vale aqui é apenas a luta pelo outro, sua reputação, seu amor, sua graça e seu juízo. Portanto, o discípulo não se posiciona num lugar de onde atacará o outro; antes, aproxima-se dele na verdade do amor de Jesus, com a oferta incondicional da comunhão.

Quando julgamos o outro, tomamos uma posição de distanciamento, para observar e refletir. O amor, porém, não deixa espaço e tempo para isso. Para o que ama, o outro jamais poderá ser objeto de contemplação desinteressada; o outro é, a qualquer momento, reivindicação viva de meu amor e meu serviço. Mas será que o mal do outro não me obriga necessariamente a condená-lo, justamente em favor dele, por amor a ele? Reconhecemos que a linha divisória é delicada. Um equivocado amor ao pecador está bem próximo do amor ao pecado. Mas o amor de Cristo ao pecador é a própria condenação do pecado, é a expressão mais aguda do ódio ao pecado. É exatamente o amor incondicional no qual devem viver os discípulos de Jesus no discipulado que resulta naquilo que jamais alcançariam com o amor dividido ou concedido segundo medidas pessoais e sob condições próprias, a saber, a condenação radical do mal.

Ao julgarem, os discípulos estabelecem critérios para distinguir entre o bem e o mal. Jesus Cristo, porém, não é um critério que eu possa aplicar aos outros. É ele mesmo que me julga e que me revela meu bem como sendo totalmente mau. Assim, estou proibido de aplicar ao outro o que não vale para mim.

Sim, com o julgamento para distinguir entre o bom e o mau, confirmo o outro exatamente em seu mal, pois ele também julga segundo seu conceito de bem e mal. Contudo, ele não conhece a maldade de seu bem, mas justifica-se com ele. Se ele for julgado por mim em seu mal, será confirmado em seu bem, mas esse bem jamais será o bem de Jesus Cristo; por isso, em lugar do julgamento de Cristo, será entregue a um julgamento humano. Mas eu trago sobre mim mesmo o julgamento de Deus, pois já não vivo pela graça de Jesus Cristo, e sim pelo conhecimento do bem e do mal, e fico sujeito ao julgamento a que me apego. Para cada um, Deus é o Deus no qual o indivíduo crê.

O julgamento é a reflexão proibida sobre o outro. Ele destrói o amor unidirecional. Embora esse amor não me proíba de pensar no outro, de conhecer seus pecados, as duas ações podem se realizar sem que haja uma reflexão porque são simplesmente oportunidades para o perdão e para o amor incondicional que Jesus me demonstra. Se não me permito julgar o outro, não significa que estou caindo no tout comprende cest tout pardonner [tudo compreender é tudo perdoar], nem que estou justificando o outro de alguma maneira. Nem eu nem o outro temos razão; é somente a Deus que damos razão, e proclamamos sua graça e seu juízo.

Enquanto o julgamento nos torna cegos, o amor ilumina nossa visão. Quando eu julgo, estou cego para o meu próprio mal e também para a graça que é direito do outro. No amor de Cristo, porém, o discípulo toma ciência de todo tipo de culpa e pecado, pois conhece o sofrimento de Jesus Cristo; ao mesmo

tempo, o amor reconhece o outro como alguém que foi perdoado sob a cruz. O amor vê o outro sob a cruz, por isso o amor consegue ver com clareza. Se, ao julgar, meu objetivo fosse de fato a destruição do mal, eu o procuraria ali onde ele realmente me ameaça, isto é, em mim mesmo. Mas, enquanto procuro o mal no outro, é evidente que, ao julgar, procuro justificar a mim mesmo e quero permanecer impune em meu próprio mal enquanto julgo o outro. Por trás de todo julgamento está o perigoso autoengano, que acha que a Palavra de Deus vale para mim de modo diferente do que para o outro. Afirmo possuir um direito especial: para mim vale o perdão, para o outro, a condenação. No entanto, uma vez que os discípulos não recebem de Jesus direitos especiais ou medidas de julgamento que pudessem impor aos outros, uma vez que nada recebem exceto a comunhão de Jesus, esse julgamento é como atribuir-se um falso direito sobre o outro, o que é, com efeito, totalmente proibido.

Não é somente o julgamento, porém, que é proibido aos discípulos; a palavra redentora do perdão que se anuncia ao outro também tem seus limites. O discípulo de Jesus não tem o poder nem o direito de impor a palavra da graça, quando e a quem quiser. Insistir, correr atrás do outro, fazer proselitismo, toda tentativa de convencer o outro pela própria força é inútil e perigoso. É inútil porque os porcos não reconhecem as pérolas que lhes são jogadas; perigoso porque assim não só a palavra do perdão é profanada, mas também o outro, a quem quero servir, será levado a pecar contra o que é sagrado. Além disso, os discípulos que assim pregam correm o risco, sem necessidade e sem benefício, de sofrerem danos por parte da fúria cega de pessoas endurecidas e obstinadas. O desperdício da graça barata aborrece o mundo. Assim, as pessoas acabam, por fim, voltando-se violentamente contra os que lhes querem impor o que eles não desejam. Para o discípulo, isso significa uma séria limitação de sua atuação, o que corresponde às instruções de Mateus 10: sacudir dos pés o pó onde a palavra da paz é rejeitada. A implacável energia dos discípulos que não querem reconhecer limites para sua atuação, o fervor que não leva em conta a resistência, confunde a palavra do evangelho com uma ideia de vitória.

Essa ideia requer fanáticos que não conhecem nem respeitam qualquer resistência. É uma força potente. A Palavra de Deus, porém, é tão fraca que se deixa sujeitar ao desprezo e à rejeição humanos. Para a Palavra, há corações endurecidos e portas fechadas. Ela reconhece essa resistência com que depara e a suporta. É duro de reconhecer isto: para a ideia, não existe o impossível, mas para o evangelho existem diversas impossibilidades. A Palavra é mais fraca que a ideia. As testemunhas da Palavra, portanto, também são mais fracas que os propagandistas da ideia. Mas, nessa fraqueza, os discípulos estão livres da inquietação doentia dos fanáticos, pois sofrem com a Palavra. Os discípulos podem desistir e fugir, desde que desistam e fujam com a Palavra, desde que sua fraqueza seja a fraqueza da própria Palavra, desde que não abandonem a Palavra nessa fuga. Porque nada são senão servos e instrumentos da Palavra e não podem querer ser fortes onde a Palavra quer ser fraca. Se quisessem impor a Palavra ao mundo a qualquer custo e com todos os meios, transformariam a Palavra viva de Deus em uma ideia, e o mundo se oporia a uma ideia que em nada lhe ajudaria. Por vezes, porém, os discípulos não cedem nem fogem, mas permanecem — isto é, permanecem apenas onde a Palavra está. Os discípulos que desconhecem a fraqueza da Palavra não reconheceram ainda o mistério da humildade de Deus. Essa Palavra fraca, que sofre a oposição dos pecadores, é a Palavra forte e misericordiosa que converte pecadores do fundo do

coração. Sua força está oculta na fraqueza; se a Palavra viesse até nós com todo o seu poder, estaríamos diante do juízo final. Esta é a grande tarefa dos discípulos: reconhecer o limite de sua missão. Mas, se abusarem da Palavra, ela se voltará contra eles.

O que os discípulos farão diante de corações fechados? Que farão onde não encontrarem acesso ao outro? Devem reconhecer que não têm, de maneira alguma, direito ou poder sobre o outro, que não possuem acesso imediato ao outro, de modo que só lhes resta o caminho àquele em cujas mãos estão eles próprios tanto como os outros. É disso que trataremos a seguir. Os discípulos são levados a orar. É-lhes dito que não há caminho ao outro a não ser a oração a Deus. Juízo e perdão continuam na mão de Deus.

Ele fecha e abre. Os discípulos devem pedir, procurar, bater, e então serão ouvidos. Precisam saber que a ansiedade e a inquietação pelos outros devem levá-los a orar. A promessa concedida à sua oração é seu maior poder.

Aí está a diferença entre a busca dos discípulos por Deus e a busca dos gentios por Deus: aqueles sabem o que buscam. Só quem já conhece a Deus pode buscá-lo. Como procurar o que não se conhece?

Como achá-lo se nem mesmo se sabe o que procura? Assim, os discípulos buscam Deus, a quem encontraram na promessa que receberam de Jesus Cristo.

Em suma: com base no que foi exposto, ficou claro que o discípulo não dispõe de direito próprio, de poder próprio em seu relacionamento com as outras pessoas. Ele vive exclusivamente da força da comunhão com Jesus Cristo. Jesus dá aos discípulos uma regra muito simples, por meio da qual até mesmo o mais simples dos discípulos pode verificar se seu trato com os outros está certo ou errado; para isso, basta inverter os papéis, basta pôr-se no lugar do outro e o outro pôr-se no lugar dele. “Tudo quanto, pois, quereis que os homens vos façam, assim fazei-o vós também.” No mesmo instante, o discípulo perde qualquer direito especial sobre o outro, e assim não pode ser indulgente consigo naquilo que condena no outro. A partir daí, torna-se tão rigoroso contra o mal que existe nele próprio como costumava ser contra o mal no outro, e tão tolerante com o mal no outro como o é consigo. Pois nosso mal em nada é diferente do mal do outro. Há somente um juízo, uma lei, uma graça. Portanto, o discípulo tratará o outro sempre como alguém que recebeu o perdão dos pecados e que passa a viver somente do amor de Deus. “Esta é a Lei e os Profetas” — pois nada mais é que o maior mandamento: amar a Deus acima de todas as coisas e ao próximo como a si mesmo.

A grande separação

Entrai pela porta estreita (larga é a porta, e espaçoso, o caminho que conduz para a perdição, e são muitos os que entram por ela), porque estreita é a porta, e estreito, o caminho que conduz para a vida, e são poucos os que acertam com ela. Acautelai-vos dos falsos profetas, que se vos apresentam disfarçados em ovelhas, mas por dentro são lobos roubadores. Pelos seus frutos os conhecereis. Colhem-se, porventura, uvas dos espinheiros ou figos dos abrolhos? Assim, toda árvore boa produz bons frutos, porém a árvore má produz frutos maus.

Não pode a árvore boa produzir frutos maus, nem a árvore má produzir frutos bons. Toda árvore que não produz bom fruto é cortada e lançada ao fogo. Assim, pois, pelos seus frutos os conhecereis. Nem todo o que me diz: Senhor, Senhor! entrará no reino dos céus, mas aquele que faz a vontade de meu Pai, que está nos céus. Muitos, naquele dia, hão de dizer-me: Senhor, Senhor! Porventura, não temos nós profetizado em teu nome, e em teu nome não expelimos demônios, e em teu nome não fizemos muitos milagres? Então, lhes direi explicitamente: nunca vos conheci. Apartai-vos de mim, os que praticais a iniquidade. Mateus 7.13-23

A Igreja de Jesus não pode se separar por vontade própria da comunhão com aqueles que não ouvem o chamado de Jesus. Ela é chamada ao discipulado por seu Senhor por meio da promessa e do mandamento. Isso é suficiente. A Igreja deixa todo julgamento e a separação por conta daquele que a escolheu segundo seu propósito, não por mérito de obras, mas por sua graça. Não é a Igreja a responsável pela separação, mas a palavra de seu chamado.

Um grupo pequeno, os discípulos, é separado do resto do mundo. Os discípulos são e sempre serão poucos. Qualquer falsa esperança em relação à sua atividade já é eliminada previamente com essa palavra de Jesus. O discípulo jamais deve depositar sua esperança em números. “São poucos os que...”

Os outros, porém, são e sempre serão muitos. No entanto, a perdição os espera. Como consolar os discípulos numa situação dessas senão unicamente na promessa de vida, a eterna comunhão de Jesus?

O caminho dos discípulos é apertado. Passa-se facilmente despercebido por ele, sem saber se é o certo, e muitas vezes perdemos a direção mesmo quando já estamos nele. É difícil encontrá-lo. É

caminho realmente apertado, e os abismos, dos dois lados, são ameaçadores: ser chamado ao extraordinário, aceitar o chamado sem ver nem saber o que estamos fazendo — esse é um caminho apertado! Testemunhar e confessar a verdade de Jesus e, ao mesmo tempo, amar o inimigo que não crê nessa verdade, o inimigo de Jesus e o nosso inimigo, com o amor incondicional de Jesus — esse é um caminho apertado. Crer na promessa de Jesus de que os discípulos possuirão a terra e, ao mesmo tempo, enfrentarão indefesos o inimigo, preferindo sofrer injustiças a cometê-las — esse é um caminho apertado. Ver e reconhecer o outro em sua fraqueza, em sua injustiça, sem nunca julgá-lo, ter de entregar-lhe a mensagem sem jogar as pérolas aos porcos — esse é um caminho apertado. É um caminho que não se pode suportar. Em todo momento, paira a ameaça da apostasia. Será, de fato, um caminho impossível enquanto eu o considerar somente uma ordem à qual devo obedecer e andar nele com medo de mim mesmo. Mas, se eu conseguir ver Jesus Cristo à minha frente, passo a passo, então estarei protegido nesse caminho. Se eu me concentrar no perigo de minha ação, se olhar para o caminho em vez de olhar para aquele que está à frente, certamente tropeçarei. Ele próprio é o caminho. Ele é o caminho apertado e a porta estreita. Nosso único interesse é encontrá-lo. Sabendo disso, seguiremos o caminho apertado e passaremos pela porta estreita da cruz de Jesus Cristo para a vida, pois é exatamente o aperto do caminho que se tornará nossa certeza. Como poderia ser largo o caminho do Filho de Deus na terra, o caminho que temos de trilhar como cidadãos de dois mundos, no limite entre o mundo e o reino dos céus?

O caminho apertado tem de ser o caminho certo.

Versículos 15-20. A separação entre Igreja e mundo já se completou. Agora, porém, a palavra de Jesus avança sobre a própria Igreja, trazendo julgamento e separação. Essa separação tem de acontecer continuamente entre os discípulos. Não devem eles imaginar que poderiam simplesmente fugir do mundo e permanecer, sem perigo, no caminho apertado com o pequeno grupo. Entre eles surgirão falsos profetas, e a confusão aumentará o isolamento. Pode haver alguém ao meu lado, aparentemente um membro da Igreja, um profeta, um pregador, a julgar pela aparência, pelas palavras e pelas obras, um cristão; no íntimo, porém, motivos obscuros o trouxeram até nós, por dentro é um lobo voraz, suas palavras são

mentiras, e suas obras, uma grande ilusão. Sabe bem como manter o segredo, realizando sua obra de trevas sem que ninguém perceba. Está em nosso meio não porque a fé em Jesus Cristo o tenha atraído até nós, mas porque Satanás o enviou. Talvez procure poder e influência, dinheiro e fama por ideias e profecias que ele mesmo criou. Procura o mundo, e não o Senhor Jesus. Oculta seu objetivo obscuro sob a máscara da religiosidade, porque sabe que os cristãos são um povo crédulo. Confia que não será desmascarado por vestirse de modo inocente. Sabe também que os cristãos estão proibidos de julgar, e sempre que precisar os lembrará disso! É impossível uma pessoa ver o coração da outra. Assim, desviará muitos do caminho certo. É provável que nem mesmo ele tenha consciência disso tudo; é possível que Satanás, a força que o move, obscureça o conhecimento que ele tem de si mesmo.

Com essa revelação, Jesus poderia deixar os discípulos muito assustados. Quem conhece o outro?

Quem pode dizer se atrás da aparência cristã não se esconde a mentira e o engano? Tudo isso poderia gerar, no meio da Igreja, grande desconfiança, olhares mútuos de suspeita, espíritos inquietantes de julgamento. Tudo isso poderia resultar, com base nas palavras de Jesus, no julgamento insensível de todo irmão que caísse em pecado. Jesus, porém, liberta os discípulos dessa desconfiança que poderia destruir a Igreja. Ele diz: a árvore má produz frutos maus; no devido tempo ela se revelará. Não há necessidade de vermos o coração de ninguém. Tudo que precisamos é esperar até que a árvore produza seus frutos.

Vocês poderão, a seu tempo, pelos frutos, avaliar as árvores. Mas o fruto não poderá demorar. Não se trata de saber diferenciar entre a palavra e a obra dos falsos profetas, mas entre aparência e realidade.

Jesus diz que o ser humano não pode viver de aparência por muito tempo. A época do fruto, a hora do discernimento, chegará. Cedo ou tarde, sua verdadeira natureza se revelará. Ainda que a árvore não queira produzir frutos, não adianta; o fruto aparecerá de qualquer jeito. Portanto, chegará o tempo em que uma árvore será diferenciada da outra, em que os frutos serão produzidos, e tudo se esclarecerá. Quando chegar a hora da decisão entre mundo e Igreja — e ela pode acontecer todos os dias, não apenas em questões importantes, mas também em assuntos menores e cotidianos —, então se tornará muito claro o que é mau e o que é bom. Nesse momento, somente a realidade permanecerá; a aparência desaparecerá.

Jesus exige que seus discípulos consigam, em tais momentos, distinguir claramente, de um lado, a realidade e a aparência e, de outro, fazer a separação entre eles e os cristãos aparentes. Isso os dispensará da curiosidade sobre o outro, mas em contrapartida exigirá fidelidade e determinação para reconhecer a decisão de Deus. Pode acontecer, a qualquer momento, que cristãos aparentes sejam arrancados de nosso meio e que nós sejamos, inclusive, desmascarados como um deles. Apela-se, assim, aos discípulos que estabeleçam uma comunhão mais sólida com Cristo e que sejam mais fiéis no discipulado. A árvore má será cortada e lançada ao fogo. Toda a sua exibição de nada lhe valerá.

Versículo 21. A separação que se dá com o chamado de Jesus ao discipulado aprofunda-se ainda mais.

Depois da separação entre mundo e Igreja, entre cristãos aparentes e verdadeiros, ela continua no meio dos discípulos confessantes. O apóstolo Paulo diz: “Ninguém pode dizer: Senhor Jesus!, senão pelo Espírito Santo” (1Co 12.3), isto é, ninguém pode entregar a vida a Cristo por sua própria razão, força ou decisão e chamá-lo de Senhor. Mas existe aqui a possibilidade de alguém chamar Jesus de Senhor sem o Espírito Santo, isto é, sem ter recebido o chamado de Jesus. Isso é ainda mais difícil de compreender,

uma vez que, naquela época, não era vantagem alguma chamar Jesus de Senhor; ao contrário, tal confissão era altamente arriscada. “Nem todo o que me diz: Senhor, Senhor! entrará no reino dos céus.”

Dizer “Senhor, Senhor!” é a confissão da Igreja. Nem todos os que assim confessam entrarão no reino dos céus. A separação passará pelo meio da Igreja confessante. A confissão não confere ao discípulo direito algum em relação a Jesus. Ninguém poderá, um dia, apelar à sua confissão em razão dela mesma. O fato de sermos membros da Igreja confessante verdadeira não constitui direito perante Deus. Não é por essa confissão que seremos bemaventurados. Se assim pensamos, cometemos o pecado de Israel, que transformou a graça do chamado em direito perante Deus. Com isso, pecamos contra a graça daquele que nos chama. Deus não nos perguntará se fomos evangélicos; a ele interessa se fizemos sua vontade. É isso o que ele a todos perguntará, incluindo a nós. A Igreja não se distingue do mundo por ter privilégios especiais, mas pela graciosa eleição e pelo chamado de Deus.

Pas ho legon e all ho poion — “dizer’” e “fazer” — não se trata apenas da relação entre palavra e prática. Trata-se de duas atitudes diferentes perante Deus. ho legon kyrie — “o que diz Senhor, Senhor!”

é o ser humano que, baseado no seu sim, reivindica direitos; ho poion — o “que pratica” — é o ser humano humilde cuja ação é obediente. O primeiro é o que se justifica pela confissão; o segundo, o que pratica, é o ser humano obediente que confia na graça de Deus. O discurso do ser humano torna-se o correspondente exato de sua justiça própria; a prática, no entanto, o correspondente à graça diante da qual o ser humano nada mais pode senão obedecer humildemente e servir. O que diz “Senhor, Senhor!” a si mesmo se chamou ao discipulado de Jesus, sem o Espírito Santo, ou, de alguma maneira, transformou o chamado de Jesus em privilégio pessoal. O que pratica a vontade de Deus, porém, é chamado, agraciado, e obedece e segue. Compreende seu chamado não como um direito, mas como o juízo e a graça, como a vontade de Deus à qual quer obedecer exclusivamente. A graça de Jesus requer aquele que pratica; portanto, a prática torna-se a humildade verdadeira, a fé autêntica, a confissão sincera da graça do que chama.

Versículo 22. Os que confessam e os que praticam são separados. Agora, a separação é levada às últimas consequências. Aqui, no final, aqueles que foram aprovados até aqui vão falar. Eles pertencem ao grupo dos que praticam, mas, em vez de se basearem em sua confissão, baseiam-se em sua prática.

Fizeram obras em nome de Jesus. Sabem que a confissão não faz a justiça; por isso, foram e, com suas obras, engrandeceram o nome de Jesus entre as pessoas. Nesse momento, apresentam-se a Jesus referindo-se a essas obras.

Jesus, então, mostra aos discípulos a possibilidade de uma fé demoníaca, fé que afirma basear-se nele, que realiza maravilhas totalmente indistinguíveis das obras dos verdadeiros discípulos, obras de caridade, milagres, talvez até mesmo a autossantificação, mas que, não obstante, nega Jesus e o discipulado. É exatamente o que escreve Paulo em 1Coríntios 13, ou seja, que é possível pregar, profetizar, ter todo o conhecimento, tanta fé a ponto de mover montanhas — porém, sem amor, isto é, sem Cristo, sem o Espírito Santo. Além disso, na visão de Paulo, existe a possibilidade de que as próprias obras de caridade cristã, a doação de bens, e até o martírio, sejam realizadas sem amor, sem Cristo, sem o Espírito Santo. Sem amor: isto é, praticar tudo isso sem que a obra do discipulado seja praticada,

aquela prática cujo praticante não é, por fim, outro senão aquele que chama, o próprio Jesus Cristo. Essa é a mais profunda, a mais inacreditável possibilidade da ação satânica na Igreja, é a separação final, que só ocorrerá no último dia. Mas será definitiva.

Todavia, os discípulos precisam perguntar qual seria, afinal, o critério definitivo para saberem quem será aceito por Jesus e quem não. Quem permanece, quem não permanece? A resposta de Jesus aos, por fim, rejeitados esclarece tudo: “Nunca os conheci”. Eis, portanto, o mistério preservado do início do Sermão do Monte até seu final. Esta é a única questão: seremos ou não reconhecidos por Cristo? Em que nos agarraremos ao ouvir como a palavra de Jesus efetua a separação entre mundo e Igreja, e logo depois, na própria Igreja, até o dia final, quando nada nos restará, nem nossa confissão, nem nossa obediência? Portanto, permanecerá ainda e tão somente sua palavra: “Eu o conheço”. Essa é sua palavra eterna, seu eterno chamado. Aqui se encerra o Sermão do Monte remetendo à primeira palavra de Jesus.

Sua palavra no juízo final nos é dirigida em seu chamado ao discipulado. Do princípio até o fim, porém, é sempre sua palavra, seu chamado. Quem, no discipulado, apega-se a essa palavra e a nada mais, quem abre mão de tudo o mais, a esse a palavra fará atravessar o juízo. Sua palavra é sua graça.

O final

Todo aquele, pois, que ouve estas minhas palavras e as pratica será comparado a um homem prudente que edificou a sua casa sobre a rocha; e caiu a chuva, transbordaram os rios, sopraram os ventos e deram com ímpeto contra aquela casa, que não caiu, porque fora edificada sobre a rocha. E todo aquele que ouve estas minhas palavras e não as pratica será comparado a um homem insensato que edificou a sua casa sobre a areia; e caiu a chuva, transbordaram os rios, sopraram os ventos e deram com ímpeto contra aquela casa, e ela desabou, sendo grande a sua ruína. Quando Jesus acabou de proferir estas palavras, estavam as multidões maravilhadas da sua doutrina; porque ele as ensinava como quem tem autoridade e não como os escribas.

Mateus 7.24-29

Acabamos de ouvir o Sermão do Monte, e é possível que o tenhamos até compreendido. Será, porém, que alguém o ouviu de fato? No final, Jesus responde a essa pergunta. Ele não permite simplesmente que seus ouvintes se vão e façam de suas palavras o que quiserem, o que lhes agradar, que escolham o que lhes parecer de valor para a vida deles, que avaliem como se aplicariam em relação à “realidade”. Jesus não permite que se apossem de suas palavras e que abusem livremente delas; ele as oferece de modo que apenas elas exerçam poder sobre eles. Do ponto de vista humano, há inúmeras possibilidades de entender e interpretar o Sermão do Monte. Jesus, porém, só conhece uma: simplesmente seguir e obedecer. Em vez de interpretar e aplicar, fazer e obedecer. Apenas assim as palavras de Jesus serão ouvidas. Mais uma vez, não se trata de falar da prática como um ideal, mas de realmente começar a praticá-la. Essa palavra, cuja reivindicação eu aceito, essa palavra cuja origem está no “eu o conheci”, que me põe de imediato na prática, na obediência, essa palavra é a rocha sobre a qual posso edificar minha casa.

A essa palavra de Jesus vinda da eternidade corresponde simplesmente a prática. Jesus falou, a palavra é dele, a obediência é nossa. Somente na prática a palavra de Jesus guarda sua honra, sua força e seu poder entre nós. Agora, mesmo que a tempestade se volte contra a casa, não poderá destruir a comunhão com Jesus, criada por sua palavra.

Além do fazer, só existe o não fazer. Não existe, porém, o querer fazer e acabar não fazendo. Quem lida com a palavra de Jesus de outra maneira que não a prática está contestando Jesus, rejeitando o Sermão do Monte e, portanto, não pondo em prática sua palavra. Questionar tudo, problematizar, interpretar, tudo isso é deixar de praticar. Vêm à mente mais uma vez o jovem rico e o intérprete da lei de Lucas 10. Por mais que eu reafirme minha fé, meu reconhecimento fundamental de sua palavra, Jesus chama isso de não fazer. A palavra que me recuso a praticar não se torna para mim a rocha sobre a qual posso edificar minha casa. Não existe, nesse caso, unidade com Jesus. Ele ainda não me reconheceu. Por isso, se vier a tempestade, perco a palavra rapidamente e descubro que nunca acreditei de fato. Eu não tinha a palavra de Cristo, mas apenas uma palavra que tomei de suas mãos e dela me apossei, refletindo sobre ela em vez de praticá-la. Assim, minha casa desaba porque não estava alicerçada na palavra de Cristo.

“Estavam as multidões maravilhadas…” O que tinha acontecido? O Filho de Deus havia falado. Ele tinha tomado em suas mãos o juízo sobre o mundo. E seus discípulos estavam a seu lado.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer diz que, ao julgarmos o irmão, ficamos cegos para o nosso próprio mal e procuramos o pecado no outro justamente para nos justificar e permanecer impunes em nós mesmos. Onde, na sua vida ou nos seus relacionamentos na comunidade, você tem percebido a 'trave' no seu próprio olho enquanto se ocupa do 'argueiro' no olho de alguém?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto afirma que o discípulo nunca encontra o outro como duas pessoas livres com medidas e juízos diferentes, mas sempre 'como alguém ao encontro de quem o próprio Jesus está indo'. Como mudaria a sua maneira de tratar uma pessoa difícil hoje se você de fato acreditasse que Jesus está indo ao encontro dela à sua frente?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer fala dos limites da nossa atuação — não jogar as pérolas aos porcos, sacudir o pó dos pés, reconhecer a fraqueza da Palavra em vez de impô-la 'a qualquer custo'. Em que situação você tem confundido fidelidade com insistência, querendo ser forte onde a Palavra escolheu ser fraca?$p$, 'reflexao', null);
