  -- Capítulo 10 — Questões preliminares  (aula ordem = 12)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 12;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 10 — Questões preliminares$t$,
      12,
$conteudo$Jesus estava corporalmente presente quando dirigiu sua palavra aos primeiros discípulos. Esse Jesus, porém, morreu e ressuscitou. Como vem até nós hoje seu chamado ao discipulado? Jesus já não precisa estar fisicamente conosco para nos dizer “Segue-me!”, como quando abordou Levi, o publicano. Mesmo que de todo o coração eu desejasse ouvir o chamado, deixar tudo para trás e segui-lo, que direito eu teria? O que para eles era tão claro, para mim é uma decisão muito duvidosa sobre a qual não tenho controle. O que me garante que o chamado de Jesus a Levi também vale para mim? Não falou Jesus de maneira bem diferente a outras pessoas e em outras circunstâncias? Acaso Jesus amou menos aquele paralítico, de quem perdoou os pecados e a quem curou, ou a Lázaro, a quem ressuscitou dos mortos, do que a seus discípulos, uma vez que não pediu àqueles que abandonassem suas ocupações a fim de segui-lo no discipulado, mas os deixou onde estavam, em casa, com a família, na profissão? Quem sou eu, portanto, para assim me oferecer a realizações tão incomuns e extraordinárias? Quem poderia dizer a mim e aos outros que não estou agindo por vontade própria ou por puro entusiasmo? Isso, certamente, não seria discipulado!

Tais perguntas não são legítimas. Levantamos essas questões com o único intuito de nos retirarmos da presença viva de Cristo. Quem faz essas perguntas não leva em conta que Jesus Cristo não morreu, mas vive e ainda hoje nos dirige a palavra por meio do testemunho das Escrituras. Ele continua presente entre nós, corporalmente e em sua Palavra. Se quisermos ouvir seu chamado ao discipulado, temos de ouvi-lo onde ele se encontra. O chamado de Jesus Cristo se faz ouvir na Igreja por meio de sua Palavra e sacramento. A pregação e os sacramentos da Igreja são o lugar da presença de Jesus Cristo. Quem quiser ouvir o chamado de Jesus ao discipulado não precisa de uma revelação pessoal. Ouça a pregação e receba o sacramento! Ouça o evangelho do Senhor crucificado e ressurreto! É na Igreja que ele está presente por inteiro, o mesmo Jesus que convivia com os discípulos. Ali está o Cristo glorificado, vivo e vitorioso. E só ele pode chamar ao discipulado. A situação do discípulo ou do publicano chamado por Jesus naquela época não era menos duvidosa que a nossa hoje, pois, no discipulado, não se trata, na verdade, de decisões a favor ou contra essa ou aquela ação, mas da simples decisão de ser contra ou a favor de Jesus Cristo. A obediência dos primeiros que se sujeitaram ao chamado tornou-se discipulado simplesmente porque reconheceram o Cristo naquele que chamava. Tanto ontem como hoje, porém, é o Cristo invisível que chama. O chamado em si pode assumir diferentes formas. Tudo depende daquele que chama. Mas Cristo só pode ser reconhecido na fé. Isso vale tanto para os daquela época como para nós.

Aqueles viam o rabino e o milagreiro e criam em Cristo. Nós ouvimos a Palavra e cremos em Cristo.

Não teria sido essa a maior vantagem dos primeiros discípulos, isto é, terem reconhecido Cristo, recebido seu mandamento de maneira muito clara e sido instruídos sobre o que fazer da própria boca dele? Não nos sentimos abandonados exatamente nesse ponto decisivo da obediência cristã? Será que esse mesmo Cristo não fala conosco hoje de maneira diversa? Se isso fosse verdade, nossa situação seria realmente desesperadora. Mas não é verdade, de maneira nenhuma. Cristo não fala conosco hoje de maneira diversa de como falou naquela época. Em relação aos primeiros discípulos, também não é verdade que, primeiramente, reconheceram nele o Cristo e só então receberam seu mandamento. Ao contrário, só o reconheceram por causa de sua palavra e de seu mandamento. Creram em sua palavra e em seu mandamento e, portanto, reconheceram nele o Cristo. Não havia outra maneira de reconhecerem Cristo senão por meio de sua clara palavra. Por outro lado, o contrário também é válido, ou seja, o reconhecimento legítimo de Jesus como o Cristo tinha de incluir ao mesmo tempo o reconhecimento de sua vontade. O reconhecimento da pessoa de Jesus Cristo não impedia a certeza de agir do discípulo, mas sim criava essa certeza. Não existe outro modo de reconhecer Jesus Cristo. Se Cristo é o Senhor vivo de minha vida, experimento, no encontro com ele, sua palavra dirigida a mim, e não o reconhecerei senão por sua palavra clara e seu mandamento. A desculpa de que nosso problema seria exatamente querer conhecer a Cristo e crer nele, sem, no entanto, podermos reconhecer sua vontade, revela um conhecimento obscuro e ilegítimo de Cristo. Reconhecer o Cristo é reconhecê-lo como Senhor e Salvador de minha vida em sua palavra. Isso, porém, inclui o reconhecimento de sua palavra clara dirigida a mim.

Se concluímos, por fim, que o mandamento que Jesus dirigiu aos primeiros discípulos foi claro, mas que nós mesmos temos de decidir qual a palavra dirigida a nós, mais uma vez entendemos equivocadamente a situação tanto daqueles discípulos como a nossa. O mandamento de Jesus visa à fé de coração inteiro, o amor a Deus e ao próximo de todo o coração e de todo o entendimento. Nisso consistia a clareza do mandamento. Toda tentativa de seguir o mandamento de Jesus de outra maneira revelaria um equívoco na interpretação e, consequentemente, uma desobediência à palavra de Jesus. Contudo, não estamos impedidos de conhecer o mandamento concreto. Em cada palavra da pregação, na qual ouvimos Cristo, esse mandamento nos é anunciado, mas de tal modo que aprendemos que seu cumprimento só acontece na fé em Jesus Cristo. Assim, a dádiva de Jesus a seus discípulos nos ficou totalmente preservada. Na verdade, nossa situação é ainda melhor, pois pela ascensão de Jesus estamos mais próximos dela, por causa de nosso conhecimento de sua glorificação e pelo envio do Espírito Santo.

Portanto, é bastante claro que não podemos mais afirmar que as histórias de chamado dos primeiros discípulos sejam totalmente diferentes de outras experiências de chamado ao discipulado hoje. Não se trata de exigir que sejamos iguais aos primeiros discípulos ou a outros personagens do Novo Testamento; o que importa é que Jesus Cristo e seu chamado são os mesmos, ontem e hoje. Sua palavra é única e a mesma, quer tenha sido proferida em sua vida na terra, quer seja proferida hoje, dirigida tanto aos discípulos como ao paralítico. Lá e cá, é o chamado da graça para seu reino e poder. A questão sobre se devo me comparar com o discípulo ou com o paralítico não só é mal formulada, mas também perigosa.

Não devo me comparar a nenhum deles. A única coisa que devo fazer é ouvir e praticar a palavra e a

vontade de Cristo, seja qual for o testemunho pelo qual recebo o chamado. As Escrituras não apresentam vários tipos de cristãos aos quais devemos imitar conforme nossa escolha, mas sim prega, em todas as situações, o mesmo Jesus Cristo. Só a ele devo ouvir. Ele é o mesmo e o único em todo lugar.

À pergunta acerca de onde nós que vivemos hoje poderíamos ouvir o chamado de Jesus ao discipulado, há uma única resposta: Ouça a pregação, receba o sacramento, ouça neles a ele próprio, e ouvirá o chamado!$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer responde à pergunta 'como o chamado de Jesus chega até mim hoje?' dizendo: 'Ouça a pregação, receba o sacramento, ouça neles a ele próprio.' Você tem tratado a pregação e a Ceia como o lugar real onde o Cristo vivo te fala, ou mais como hábito religioso? O que mudaria se você os ouvisse esperando o chamado dele?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto desmonta a ideia de que primeiro reconhecemos Cristo e só depois recebemos sua vontade — para Bonhoeffer, conhecer Jesus como Senhor já inclui reconhecer sua palavra concreta dirigida a mim. Existe alguma área da sua vida em que você diz crer em Cristo, mas evita reconhecer a vontade clara dele para não ter de obedecer?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer adverte que a desculpa 'querer conhecer Cristo sem poder reconhecer sua vontade' revela um conhecimento 'obscuro e ilegítimo' dele. Que pergunta 'aparentemente espiritual' você já usou para, no fundo, se esquivar da presença viva de Jesus e adiar uma decisão?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 11 — O batismo  (aula ordem = 13)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 13;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 11 — O batismo$t$,
      13,
$conteudo$Nos Evangelhos Sinóticos, praticamente todo o conteúdo das relações do discípulo com Jesus Cristo é expresso no conceito do discipulado. Nos escritos de Paulo, porém, esse mesmo conceito aparece em segundo plano. Em sua pregação, Paulo não ressalta tanto a história de Jesus em seu tempo na terra, mas destaca a presença do Cristo ressurreto e glorificado e sua obra em nós. Para isso, Paulo precisa de uma nova terminologia, que nasce da singularidade do objeto e almeja ressaltar o que há em comum na pregação — o Senhor único que viveu, morreu e ressuscitou. Ao testemunho completo de Cristo corresponde uma variação na terminologia. Assim, os novos termos usados por Paulo têm de confirmar os termos dos Sinóticos, e vice-versa; e nenhuma das duas terminologias tem primazia sobre a outra, pois não somos “de Paulo, ou de Apolo, ou de Cefas, ou de Cristo”; antes, cremos na unidade do testemunho das Escrituras sobre Jesus Cristo. Afirmar que Paulo prega o Cristo que ainda estaria presente para nós e que os Sinóticos anunciavam uma presença de Jesus Cristo que não conhecemos mais significaria a destruição dessa unidade das Escrituras. Embora o assunto seja amplamente abordado hoje dessa maneira como legítima doutrina histórico-crítica reformada, o que ocorre, na verdade, é o contrário, e tais considerações não passam de perigoso entusiasmo. Quem nos garante que ainda hoje Cristo está presente conforme Paulo pregava? Quem senão as próprias Escrituras? Ou será que deveríamos falar de uma experiência da presença e da realidade de Cristo livre e desvinculada da Palavra? Uma vez que só as Escrituras nos testemunham a presença de Cristo, elas claramente o fazem como sendo um todo coeso, o que inclui, portanto, o modo como os Sinóticos apresentam a presença de Jesus Cristo. O Cristo dos Sinóticos não está nem mais perto nem mais longe de nós que o Cristo de Paulo. O que nos é apresentado é o Cristo testemunhado pelas Escrituras como um todo único. É o Cristo encarnado, crucificado, ressurreto e glorificado, e nós o encontramos em sua Palavra. As diferentes terminologias adotadas nos escritos de Paulo e nos Sinóticos em nada prejudicam a unidade do testemunho das Escrituras.1

Nos escritos de Paulo, o chamado e a entrada no discipulado correspondem ao batismo.

O batismo não é oferta do ser humano, mas oferta de Jesus Cristo. Ele se fundamenta totalmente na vontade de Jesus Cristo conforme expressa em seu chamado. Batismo quer dizer ser batizado; é ter de sofrer o chamado de Cristo. No batismo, o ser humano torna-se propriedade de Cristo. O nome de Jesus Cristo é proferido sobre aquele que está sendo batizado. Desse modo, esse nome passa a ser compartilhado por aquele que foi batizado. O ser humano é batizado para dentro de Jesus Cristo ( eis, Rm 6.3; Gl 3.27; Mt 28.19). Daquele momento em diante, passa a pertencer a Cristo. É arrancado do poder do mundo e torna-se propriedade de Cristo.

O batismo, portanto, significa rompimento. Cristo intervém no domínio de Satanás, põe a mão sobre os seus e cria sua Igreja. Passado e presente são separados. As coisas antigas passaram, e tudo se tornou novo. Esse rompimento não ocorre porque o ser humano, no anseio de uma ordem nova e livre em sua vida e nas coisas, destrói as correntes que o prendem. É o próprio Cristo que há muito efetuou o rompimento. No batismo, o rompimento é realizado em minha vida. Sou privado das relações diretas com o mundo, porque Cristo, o Mediador e Senhor, se interpõe entre mim e o mundo. Quem é batizado já não pertence ao mundo, já não serve ao mundo, já não lhe é subordinado. Agora ele pertence somente a Cristo e se relaciona com o mundo apenas por meio de Cristo.

O rompimento com o mundo é completo. A morte do ser humano é requisito e consequência do batismo. 2 No batismo, morre o ser humano com seu antigo mundo. Na concepção exata, essa morte também deve ser compreendida como acontecimento passivo. O indivíduo não deve buscar a própria morte recorrendo a tipos diversos de renúncias ou privações. A morte assim provocada jamais seria a morte do velho ser humano que Cristo exige. O velho ser humano não pode deixar de existir por vontade própria. Ninguém pode desejar a própria morte. O ser humano morre somente em Cristo, por Cristo e com Cristo. Cristo é sua morte. É pela comunhão com Cristo, e somente nessa comunhão, que o ser humano morre. Na comunhão de Cristo, na graça do batismo, o ser humano recebe sua morte. 3 Essa morte é a graça que o ser humano jamais pode criar por conta própria. Embora a morte seja o julgamento do velho ser humano e de seus pecados, é a partir desse julgamento que surge o novo ser humano, morto para o mundo e para o pecado.

Portanto, essa morte não é a rejeição final e furiosa da criatura pelo Criador, mas a aceitação graciosa da criatura pelo Criador. Essa morte de batismo é a morte graciosa, quando passamos a ser propriedade de Cristo. É a morte no poder e na comunhão da cruz de Cristo. Quem passa a pertencer a Cristo deve submeter-se à cruz. Tem de sofrer e morrer com ele. Quem recebe a comunhão de Jesus Cristo tem de passar pela graciosa morte do batismo. É nisso que consiste a cruz de Cristo, sob a qual Jesus põe os discípulos. A cruz e a morte de Cristo foram duras e pesadas; o jugo de nossa cruz é suave e leve pela comunhão com ele. A cruz de Cristo é a morte graciosa no batismo; nossa cruz, à qual somos chamados, é o morrer diário no poder da morte consumada de Cristo. Desse modo, ser batizado é ser recebido na comunhão da cruz de Jesus Cristo (Rm 6.3ss; Cl 2.12). O crente vem para debaixo da cruz de Cristo.

A morte no batismo é a justificação do pecado. O pecador tem de morrer para ser liberto do pecado.

Quem morreu está justificado do pecado (Rm 6.7; Cl 2.20). O pecado já não tem direito sobre os mortos; as demandas foram atendidas e encerradas. A justificação do ( apo) pecado só ocorre pela morte. Perdão do pecado não significa fingir que ele não existe e esquecêlo; é a morte real do pecador e separação do ( apo) pecado. O único motivo pelo qual a morte do pecador resulta em justificação, e não em condenação, é que essa morte é sofrida na comunhão da morte de Cristo. O batismo na morte de Cristo produz perdão dos pecados e justificação, e também separação total do pecado. A comunhão na cruz, à qual Jesus chamou os discípulos, é a dádiva da justificação da morte e do perdão dos pecados. O

discípulo que seguia Jesus na comunhão da cruz recebia exatamente a mesma dádiva que o crente que recebia o batismo, conforme o ensino de Paulo.

Embora o batismo seja, para o indivíduo, uma atitude passiva, jamais deve ser entendido como um processo mecânico. A relação entre batismo e o Espírito (Mt 3.11; At 10.47; Jo 3.5; 1Co 6.11-13) deixa isso muito claro. A dádiva do batismo é o Espírito Santo. Este, porém, é o próprio Cristo morando no coração dos crentes (2Co 3.17; Rm 8.9-11,14ss; Ef 3.16s). Os batizados são a casa em que o Espírito Santo fez morada ( oikei). O Espírito Santo nos garante a contínua presença de Cristo e sua comunhão.

Transmite-nos o verdadeiro conhecimento de seu ser (1Co 2.10) e de sua vontade, ensina-nos e lembra-nos tudo que o Cristo nos disse (Jo 14.26), conduz a toda verdade (Jo 16.13), para que não nos falte conhecimento de Cristo, para que possamos saber o que nos é dado por Deus (1Co 2.12; Ef 1.9). Em lugar de incerteza, o Espírito Santo produz em nós certeza e clareza. Por isso, podemos viver e andar no Espírito (Gl 5.16,18,25; Rm 8.1,4). A mesma certeza que os discípulos tinham na comunhão terrena com Jesus, continuaram a ter depois da ascensão. O envio do Espírito Santo ao coração dos batizados não só preserva a certeza do conhecimento de Cristo, mas até mesmo a fortalece e a solidifica pela proximidade da comunhão (Rm 8.16; Jo 16.12s).

No chamado ao discipulado, Jesus exigia um ato visível de obediência. Seguir Jesus era assunto de ordem pública. O batismo, de igual modo, também é um ato público, pois mediante ele realizase a união com a Igreja visível de Jesus Cristo (Gl 3.27s; 1Co 12.13). O rompimento com o mundo, que se realiza em Cristo, não pode mais permanecer oculto; deve tornar-se visível na participação nos cultos e na vida da Igreja. Ao tomar parte da vida da Igreja, o cristão dá um passo para fora do mundo, do trabalho, da família e apresenta-se pública e visivelmente na comunhão de Jesus Cristo. Ele dá esse passo sozinho, porém reencontra o que abandonou: irmãos, irmãs, casas, campos. Aquele que é batizado vive na Igreja visível de Jesus Cristo. Os dois capítulos a seguir, “O corpo de Cristo” e “A Igreja visível”, buscarão explicar o significado pleno disso.

O batismo e sua dádiva são um acontecimento único. Ninguém pode ser batizado duas vezes com o batismo de Cristo. 4 É dessa impossibilidade de ser repetido e dessa singularidade que a epístola aos Hebreus procura tratar naquela passagem obscura onde se nega uma segunda chance de arrependimento aos batizados e convertidos (Hb 6.4ss). Quem foi batizado participa da morte de Cristo. Por essa morte, recebe a sentença de morte e morre, assim como Cristo morreu de uma vez por todas (Rm 6.10), e não há repetição de seu sacrifício. Já está morto. O morrer diário do cristão é apenas o resultado daquela morte de batismo, é um morrer semelhante ao da árvore cujas raízes foram cortadas. Para os batizados, vale o seguinte: “Assim também vós considerai-vos mortos para o pecado, mas vivos para Deus, em Cristo Jesus” (Rm 6.11). Eles só se reconhecem como mortos, aqueles para quem tudo relacionado à salvação já está consumado. Em vez de viver a repetição real da obra graciosa da morte que sempre teria de acontecer de novo, o cristão vive da repetição memorial da fé na obra graciosa da morte de Cristo realizada em nós. Vive da singularidade da morte de Cristo em seu batismo.

Essa inflexibilidade que faz do batismo um acontecimento único esclarece de maneira significativa o batismo infantil. 5 Não se trata de pôr em dúvida se batizar crianças é batismo ou não. Mas, justamente por ser o batismo infantil um acontecimento único, que não se repete, é que necessita de certos limites.

Embora o fato de cristãos do segundo e do terceiro séculos terem se batizado apenas na velhice ou no

leito da morte não ser, certamente, sinal de vida eclesiástica saudável, isso nos leva a uma compreensão clara da graça do batismo, compreensão que já não se encontra em nosso meio. No que diz respeito às crianças, o batismo só poderia ser realizado quando houvesse garantias para a repetição memorial da fé na obra de salvação da morte de Cristo, consumada de uma vez por todas, ou seja, numa Igreja viva.

Batizar as crianças sem Igreja não só é abuso do sacramento, mas também leviandade digna de condenação quando se trata da salvação da alma das crianças, pois o batismo continua sendo um acontecimento único, irrepetível.

Assim como o batismo, o chamado de Jesus era, para o que tinha sido chamado, de importância única e sem repetição. Quando o seguia, o indivíduo morria para a antiga vida. Por isso, Jesus tinha de exigir que os discípulos deixassem para trás tudo que possuíam. A decisão, irrevogável, devia ser muito clara; de igual modo, porém, a grandeza da dádiva que recebiam de seu Senhor também ficava totalmente clara.

“Se o sal vier a ser insípido, como lhe restaurar o sabor?” Essa é a expressão mais significativa da singularidade da dádiva de Jesus. Por um lado, Jesus tirava a vida dos discípulos; por outro, queria conceder-lhes vida plena e perfeita, e assim lhes deu sua cruz. Essa era a dádiva do batismo aos primeiros discípulos.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer descreve o batismo como rompimento: Cristo se interpõe entre mim e o mundo, e eu deixo de me relacionar diretamente com ele, passando a me relacionar com tudo 'apenas por meio de Cristo'. Na prática do seu cotidiano, o que ainda te liga ao mundo de forma 'direta', sem passar por Cristo, e o que significaria deixar isso morrer?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto diz que essa morte do batismo é passiva e graciosa — ninguém pode desejar ou produzir a própria morte por renúncias; só se morre 'em Cristo, por Cristo e com Cristo'. Em que ponto você tem tentado, pela própria força e por privações, matar algo que só morre na comunhão com Cristo?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer insiste que o rompimento realizado no batismo 'não pode mais permanecer oculto' e se torna visível na participação na vida da Igreja — um passo dado sozinho para fora do mundo, mas que reencontra irmãos, casas e campos. De que maneira a sua fé tem sido visível e pública na comunidade, e onde ela ainda permanece escondida?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 12 — O corpo de Cristo  (aula ordem = 14)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 14;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 12 — O corpo de Cristo$t$,
      14,
$conteudo$Os primeiros discípulos viveram na presença e na comunhão corporal de Jesus. O que significa isso e como essa comunhão se nos apresenta hoje? Para Paulo, é por meio do batismo que nos tornamos membros do corpo de Cristo. Esse enunciado, tão estranho e difícil de entender, precisa de maiores elucidações.

O enunciado afirma que os batizados viverão na presença e na comunhão corporal de Jesus também depois da morte e ressurreição do Senhor. A ascensão não significa prejuízo para os discípulos, mas uma nova dádiva. A experiência dos primeiros discípulos na presença corporal de Cristo não era mais rica nem diferente da que temos hoje. Nossa comunhão é, na verdade, mais segura, mais completa, mais certa do que era para eles. Nós vivemos na comunhão plena da presença corporal do Senhor glorificado.

Nossa fé deve estar ciente da grandeza dessa dádiva. O corpo de Jesus Cristo é o fundamento e a certeza de nossa fé; o corpo de Jesus Cristo é a dádiva única e perfeita pela qual nos tornamos participantes da salvação; o corpo de Jesus Cristo é nossa nova vida. No corpo de Jesus Cristo, somos aceitos por Deus na eternidade.

Desde a queda de Adão, Deus enviou aos seres humanos pecadores sua Palavra, para buscá-los e aceitá-los. Sua Palavra está entre nós com o objetivo de aceitar novamente a humanidade perdida. A Palavra de Deus veio em forma de promessa, de lei. Por nossa causa, tornou-se fraca e humilde. Mas os seres humanos rejeitaram a Palavra e não quiseram ser aceitos por ela. Ofereceram sacrifícios e realizaram obras, na tentativa de que Deus aceitasse tudo isso em lugar deles. Assim, queriam pagar para livrar a si mesmos. Então ocorreu o maior dos milagres. O Filho de Deus se fez humano. A Palavra encarnou. O que estava na glória do Pai desde a eternidade, o que existia em forma de Deus, o que, no princípio, era Mediador da criação de tal maneira que o mundo criado somente podia ser reconhecido nele e por meio dele, o próprio Deus (1Co 8.6; 2Co 8.9; Fp 2.6ss; Ef 1.4; Cl 1.16; Jo 1.1ss; Hb 1.1ss) assume a forma humana e vem ao mundo. O próprio Deus aceita a humanidade assumindo a “natureza” humana, a “carne pecadora”, a figura humana (Rm 8.3; Gl 4.4; Fp 2.6ss). Deus aceita a humanidade não mais apenas pela palavra pregada, mas no corpo de Jesus. A misericórdia de Deus envia o Filho à carne, para, assim, com a carne, tomar a humanidade e trazê-la a ele. O Filho de Deus assume em seu corpo toda a humanidade, isto é, a mesma humanidade que, no ódio a Deus, no orgulho da carne, rejeitou a Palavra de Deus, invisível e não corporal. Agora, a humanidade, em toda a sua fraqueza, está aceita no corpo de Jesus Cristo em verdadeira forma corporal, e só é assim pela misericórdia de Deus.

Ao meditarem nesse milagre, os Pais da Igreja defendiam apaixonadamente a necessidade de ressaltar que foi Deus que assumiu a natureza humana, e não, como outros poderiam argumentar, que Deus escolhera um ser humano perfeito para nele se fazer humano. Foi o próprio Deus que se tornou humano.

Ou seja, Deus assumiu toda a natureza doente e pecadora dos seres humanos; Deus aceitou toda a humanidade decaída. Isso não significa, porém, que Deus tenha aceitado o ser humano Jesus. A compreensão correta de toda a mensagem de salvação depende dessa diferença. O corpo de Jesus Cristo, no qual somos aceitos com toda a humanidade, tornou-se agora a razão de nossa salvação.

É a carne pecaminosa que ele carrega — porém sem pecado (2Co 5.21; Hb 4.15). Onde estiver seu corpo humano, ali haverá aceitação para toda carne. “Certamente ele tomou sobre si as nossas enfermidades, e as nossas dores levou sobre si” (Is 53.4). Porque levava sobre seu próprio corpo todas as enfermidades e dores da natureza humana, Jesus pôde curar todas elas (Mt 8.15-17). “Mas ele foi traspassado pelas nossas transgressões e moído pelas nossas iniquidades” (Is 53.5). Tomou sobre si nossos pecados — e porque nossa carne pecaminosa foi “aceita” em seu corpo, ele pode perdoar. Por isso Jesus recebia os pecadores (Lc 15.2), porque os carregava no próprio corpo. Com Jesus o

“agradável [ dektón] ano do Senhor” (Lc 4.19) havia começado.

Portanto, o Filho de Deus que se fez humano era as duas coisas: ele próprio e a nova humanidade. O

que fazia para si fazia-o também para a nova humanidade que carregava em seu próprio corpo. Portanto, ele é o segundo Adão, o “último” Adão (1Co 15.45). Também em Adão havia cada ser humano e toda a humanidade. Adão também tinha em si toda a humanidade. A queda de Adão foi a queda de toda a humanidade; em Adão (“ser humano”) pecou “o homem” (Rm 5.19). Cristo é o segundo ser humano (1Co 15.47), no qual a nova humanidade é criada. Ele é o “novo ser humano”.

A partir daí, compreendemos a essência da comunhão corporal que os discípulos tinham com Jesus.

Não foi por acaso a ligação dos discípulos no discipulado ter sido corporal; foi algo necessário em decorrência da encarnação. Um profeta e mestre não teria precisado de discípulos; precisaria de alunos e ouvintes. O Filho de Deus que se fez humano, porém, precisa de uma comunidade de discípulos que compartilhem não apenas seu ensinamento, mas seu corpo. É no corpo de Jesus Cristo que os discípulos têm a comunhão, e é na comunhão corporal de Cristo que eles vivem e sofrem. A cruz lhes é imposta na comunhão do corpo de Jesus. Pois é nela que todos são carregados e aceitos.

O corpo terreno de Jesus é crucificado e morre. Em sua morte, a nova humanidade é crucificada e morre com ele. Cristo não assumiu um ser humano, mas a “forma” e a “natureza” humana, a carne pecaminosa; portanto, tudo que ele carregava em seu corpo sofre e morre com ele. São todas as nossas enfermidades e todos os nossos pecados que ele carrega para a cruz, somos nós os que são crucificados e mortos com ele. Embora o corpo humano de Jesus tenha morrido, ele ressuscita como corpo incorruptível e glorificado. É o mesmo corpo — a sepultura estava vazia! —, mas é também um novo corpo. Assim, carrega com ele para a ressurreição a humanidade que com ele morreu. De igual modo, carrega, em seu corpo glorificado, a humanidade que ele assumira na terra.

Como podemos participar verdadeiramente desse corpo de Cristo que fez tudo por nós? Pois de uma coisa temos certeza: não existe comunhão com Jesus Cristo que não seja a comunhão em seu corpo, no

qual somos recebidos, no qual está nossa salvação. Tornamo-nos participantes da comunhão do corpo de Cristo por meio dos dois sacramentos do corpo de Cristo, o batismo e a Ceia do Senhor. Numa alusão que muitas vezes passa despercebida, o evangelista João refere-se aos elementos dos dois sacramentos, a água e o sangue, que jorram do corpo crucificado de Jesus Cristo (Jo 19.34- 35). Paulo confirma esse testemunho ao vincular totalmente a participação no corpo de Cristo aos dois sacramentos.1 O corpo de Cristo é tanto o fim como a origem dos sacramentos. Só existe sacramento porque existe o corpo de Cristo. Não é a palavra da pregação apenas que nos torna parte da comunhão com o corpo de Jesus Cristo; deve haver também o sacramento. O batismo é a incorporação na unidade do corpo de Cristo; a Ceia é a conservação da comunhão no corpo ( koinonia). O batismo nos torna membros do corpo de Cristo. Somos batizados em Cristo (Gl 3.27; Rm 6.3), somos batizados “num só corpo” (1Co 12.13).

Assim, na morte no batismo, tornamo-nos participantes, pelo Espírito Santo, daquilo que Cristo nos conquistou em seu corpo. A comunhão do corpo de Jesus que recebemos como a receberam os primeiros discípulos quer dizer que agora estamos “com Cristo”, “em Cristo” e que “Cristo está em nós”. Tais expressões ganham claro sentido a partir do conceito correto de “corpo de Cristo”.

Todos os seres humanos estão “com Cristo” no poder da encarnação. Jesus assumiu toda a natureza humana. Por isso, sua vida, sua morte e sua ressurreição são acontecimentos reais em relação a todos os seres humanos (Rm 5.18ss; 1Co 15.22; 2Co 5.14). Os cristãos, porém, estão “com Cristo” de maneira especial. O que para os outros significa a morte, para eles significa a graça. No batismo, têm a promessa de que “morreram com Cristo” (Rm 6.8), foram “crucificados com ele” (Rm 6.6; Cl 2.20), “sepultados com ele” (Rm 6.4; Cl 2.12), “unidos com ele na semelhança da sua morte” (Rm 6.5) e que, por isso mesmo, viverão com ele (Rm 6.8; Ef 2.5; Cl 2.12; 2Tm 2.11; 2Co 7.3). “Nós com Cristo” se fundamenta no fato de Cristo ser o Emanuel, o “Deus conosco”. Somente para aquele que conhece Cristo como o Emanuel o “estar com Cristo” é motivo de graça. Ele será batizado em ( eis) Cristo, para dentro da comunhão de sua Paixão. Assim, torna-se membro desse corpo, e a comunhão dos batizados torna-se o corpo único, o próprio corpo de Cristo. Desse modo, eles estão “em Cristo” ( en), e “Cristo neles”. Já não estão “na lei” (Rm 2.12; 3.19), nem “na carne” (Rm 7.5; 8.3; 2Co 10.3), nem “em Adão” (1Co 15.22); agora, estão “em Cristo” na totalidade de sua existência e em todas as expressões da vida.

O apóstolo Paulo possui uma interminável variedade de relações para expressar o milagre da encarnação de Cristo. Tudo, porém, pode ser resumido neste único enunciado: Cristo é “por nós” não apenas em palavra e sentimento, mas com sua vida corporal. Com seu corpo, ele está onde nós deveríamos estar diante de Deus. Ele se colocou em nosso lugar. Ele sofre e morre por nós. E ele pode fazer isso porque tomou sobre si nossa carne (2Co 5.21; Gl 3.13; 1.4; Tt 2.14; 1Ts 5.10 etc.). O corpo de Jesus Cristo é “por nós”, no sentido exato da palavra, na cruz, na Palavra, no batismo, na Ceia. É nisso que se fundamenta toda a comunhão corporal com Jesus Cristo.

O corpo de Jesus Cristo é a própria nova humanidade que ele assumiu. Jesus Cristo é, ao mesmo tempo, ele próprio e também a Igreja (1Co 12.12). Desde o Pentecoste, Jesus Cristo vive na terra na forma de seu corpo, na forma da Igreja. Esse é seu corpo, o corpo crucificado e ressurreto, essa é a humanidade que ele assumiu. Ser batizado, portanto, significa tornar-se membro da Igreja, membro do corpo de Cristo (Gl 3.28; 1Co 12.13). Estar em Cristo quer dizer estar na Igreja. Assim, se estamos na Igreja, estamos corporal e verdadeiramente em Jesus Cristo. O conceito do corpo de Cristo se revela por completo.

Desde a ascensão, o lugar que Jesus Cristo ocupava no mundo passou a ser ocupado por seu corpo, a Igreja. A Igreja é a própria presença de Cristo. Com isso em vista, recuperamos um aspecto muito negligenciado no conceito de Igreja. Estamos acostumados a entender a Igreja como uma instituição. A Igreja, no entanto, deve ser entendida como uma pessoa; é claro, uma pessoa extremamente singular.

A Igreja é “um”. Todos os batizados são “um em Cristo” (Gl 3.28; Rm 12.5; 1Co 10.17). A Igreja é

“ser humano”. É o “novo ser humano” ( kainos anthropos). Assim sendo, a Igreja foi criada pela morte de Cristo na cruz. Nela a inimizade entre judeus e gentios foi abolida, a inimizade que separava a humanidade, “para que dos dois criasse, em si mesmo, um novo homem” (Ef 2.15). O “novo ser humano”

é um, e não muitos. Fora da Igreja, fora do novo ser humano, há apenas o velho, o ser humano dividido.

Esse “novo ser humano”, a Igreja, é “criado segundo Deus, em justiça e retidão procedentes da verdade” (Ef 4.24). Ele é “revestido para o pleno conhecimento, segundo a imagem daquele que o criou”

(Cl 3.10). A passagem se refere simplesmente a Jesus Cristo, a imagem de Deus. Adão foi o primeiro ser humano criado segundo a imagem do Criador, mas perdeu essa imagem quando pecou. Assim, um

“segundo ser humano”, um “último Adão”, é criado segundo a imagem de Deus; este é Jesus Cristo (1Co 15.47). Portanto, o “novo ser humano” é, ao mesmo tempo, Cristo e a Igreja. Cristo é a nova humanidade em novos seres humanos. Cristo é a Igreja. O indivíduo se relaciona com o novo ser humano de tal forma que “se reveste” dele. 2 O novo ser humano é como uma veste que cobre o indivíduo. O indivíduo deve revestir-se da imagem de Deus, que é Cristo e a Igreja. Quem é batizado reveste-se de Cristo (Gl 3.27), o que, por sua vez, deve ser entendido como incorporação no corpo, naquele um ser humano no qual não há judeu nem grego, nem livre nem escravo, isto é, na Igreja. Ninguém se tornará novo ser humano senão na Igreja, pelo corpo de Cristo.

Quem quiser tornar-se novo ser humano por conta própria continuará sendo o velho ser humano de antes.

Tornar-se novo ser humano significa entrar na Igreja, tornar-se membro do corpo de Jesus Cristo. O novo ser humano não é o indivíduo santificado e justificado; o novo ser humano é a Igreja, o corpo de Cristo, é Cristo.

Por meio do Espírito Santo, o Cristo crucificado e ressurreto existe como Igreja, como “novo ser humano”. De igual modo, é verdade que Cristo é e será para todo o sempre a encarnação de Deus, como também é verdade que seu corpo é a nova humanidade. “Porquanto, nele, habita, corporalmente, toda a plenitude da divindade”, assim também seus discípulos estão cheios de Cristo (Cl 2.9; Ef 3.19). Os próprios discípulos tornaram-se a plenitude da divindade na medida em que são seu corpo, porém somente ele preenche tudo em todos.

Para que haja a unidade de Cristo com sua Igreja, seu corpo, exigese ao mesmo tempo que Cristo seja reconhecido como Senhor de seu corpo. Por isso Paulo, desenvolvendo o conceito de “corpo de Cristo”, diz que Cristo é o cabeça do corpo (Ef 1.22; Cl 1.18; 2.19). Torna-se clara, assim, a posição superior de Cristo em relação ao corpo. Dois fatos da história da salvação tornam tal distinção necessária e não

permitem que haja uma compreensão de associação mística da Igreja com Cristo: a ascensão e a volta de Cristo. É o mesmo Senhor, tanto cá como lá, é a mesma Igreja, tanto cá como lá, é o mesmo e único corpo daquele que está presente aqui e retornará sobre as nuvens. Não obstante, é uma diferença importante, se estamos aqui ou lá. Portanto, é necessário que unidade e diferença estejam lado a lado.

A Igreja é um, é o corpo de Cristo; ao mesmo tempo, porém, é a diversidade e a comunhão dos membros (Rm 12.5; 1Co 12.12ss). O corpo tem muitos membros, e cada qual — olho, mão ou pé — é e continua sendo o que é — eis o sentido da comparação feita por Paulo! A mão nunca será olho, e o olho nunca será orelha. Sim, cada qual continua sendo o que é. Contudo, só são o que são como membros de um só corpo, como comunhão que se serve na unidade. Indivíduo e comunhão só são o que são a partir da unidade da Igreja; da mesma maneira, a Igreja só é o que é a partir de Cristo e de seu corpo. Nesse sentido, fica clara a função do Espírito Santo. É ele quem leva Cristo aos indivíduos (Ef 3.17; 1Co 12.3).

É ele quem congrega os indivíduos para edificar sua Igreja, cuja estrutura global, porém, já está completa em Cristo (Ef 2.22; 4.12; Cl 2.2). Ele cria a comunhão (2Co 13.13) dos membros do corpo (Rm 15.30; 5.5; Cl 1.8; Ef 4.3). O Senhor é o Espírito (2Co 3.17). A Igreja de Cristo é o Cristo presente no Espírito Santo. Assim, a vida do corpo de Cristo tornou-se nossa vida. Em Cristo já não vivemos nossa vida, mas Cristo vive sua vida em nós. A vida dos crentes na Igreja é, na verdade, a vida de Cristo Jesus neles (Gl 2.20; Rm 8.10; 2Co 13.5; 1Jo 4.15).

Na comunhão do corpo de Cristo crucificado e glorificado, participamos da Paixão e glorificação de Jesus Cristo. A cruz de Cristo está sobre o corpo da Igreja. O que a Igreja sofre sob a cruz é sofrimento de Cristo. O primeiro sofrimento é a morte de cruz no batismo; depois, o “morrer diário” dos cristãos (1Co 15.31) no poder do batismo. Mas, além disso, esse sofrimento ainda é sofrimento de promessa inexplicável: embora seja verdade que só o sofrimento de Cristo tem poder de reconciliação, ele que sofreu “por nós” e venceu “por nós”, no poder de sua Paixão, concede àqueles que não se envergonham de comungar de seu corpo a graça imensa de também poder sofrer “por ele”. Não havia glória maior que Cristo pudesse dar aos que lhe pertencem, não poderia haver honra mais inconcebível para os cristãos do que poder sofrer “por Cristo”. Assim, o que é totalmente contrário à lei torna-se, nesse caso, verdadeiro.

Pela lei, só podemos receber o castigo pelos próprios pecados. Se o ser humano nada pode sofrer nem fazer para seu próprio bem, como o poderia fazer para outro, e muito menos para Cristo? O corpo de Cristo, que nos foi dado, que sofreu o castigo por nossos pecados, nos liberta para viver na morte e no sofrimento “por Cristo”. Pode-se, agora, trabalhar e sofrer por Cristo, a favor dele que tudo fez por nós!

Esse é o milagre e a graça na comunhão do corpo de Cristo (Fp 1.29; 2.17; Rm 8.35ss; 1Co 4.10; 2Co 4.10; 5.20; 13.9). Embora Jesus Cristo tenha cumprido em nosso lugar o sofrimento necessário para nossa redenção, seus sofrimentos na terra ainda não chegaram ao fim. Em sua graça, deixou à sua Igreja um resto ( hysteremata) de sofrimento para os últimos tempos até sua volta, sofrimentos que ainda devem ser cumpridos (Cl 1.24). Esse sofrimento poderá vir a favor do corpo de Cristo, da Igreja. Não é certo se também podemos entender esse sofrimento como sofrimento que tem o poder de reconciliação (cf. 1Pe 4.1). Está claro, porém, que o sofredor sofre, no poder do corpo de Cristo, “pela” Igreja, pelo corpo de Jesus, suportando aquilo de que outros serão poupados. “... levando sempre no corpo o morrer de Jesus,

para que também a sua vida se manifeste em nosso corpo. Porque nós, que vivemos, somos sempre entregues à morte por causa de Jesus, para que também a vida de Jesus se manifeste em nossa carne mortal. De modo que, em nós, opera a morte, mas, em vós, a vida” (2Co 4.10-12; cf 1.5-7; 13.9; Fp 2.17). Há uma quantidade de sofrimento reservada ao corpo de Cristo. Deus concede a alguns a graça de suportar de maneira especial o sofrimento dos outros. Sofrimento tem de ser sentido, suportado e superado. Feliz é aquele que Deus considera digno de sofrer pelo corpo de Cristo. Esse sofrimento é alegria (Cl 1.24; Fp 2.17). Nesse sofrimento, o crente pode gloriar-se de carregar em seu corpo as chagas de Cristo (2Co 4.10; Gl 6.17). O crente servirá para que “Cristo seja engrandecido no meu corpo, quer pela vida, quer pela morte” (Fp 1.20). Essa ação e esse sofrimento substitutivo dos membros em relação ao corpo de Cristo é a própria vida do Cristo que quer tomar forma em seus membros (Gl 4.19).

Em tudo isso, porém, estamos na comunhão dos primeiros discípulos e seguidores de Jesus.

O final desta reflexão deve consistir na confirmação de que encontraremos esse testemunho de Cristo ao longo de toda a mensagem da Bíblia. E constataremos que a grande profecia do Antigo Testamento sobre o templo de Deus se cumpre no corpo de Cristo.

O conceito de corpo de Cristo não pode ser entendido no uso helenístico dessa imagem, mas a partir da profecia do Antigo Testamento em relação ao templo. Davi quer construir um templo ao Senhor. Ele consulta o profeta, que lhe revela a Palavra de Deus a respeito de seus planos: “Vai e dize a meu servo Davi: Assim diz o SENHOR: Edificar-me-ás tu casa para minha habitação? [...] Também o SENHOR te faz saber que ele, o SENHOR, te fará casa” (2Sm 7.5,11). O templo de Deus só pode ser construído pelo próprio Deus. Ao mesmo tempo, em singular contradição com o que antes se dissera, Davi recebe a promessa de que alguém de sua descendência construirá a casa de Deus, e que seu reinado permanecerá para sempre (v. 12-13). “Eu lhe serei por pai, e ele me será por filho” (v. 14). Salomão, o filho da paz de Deus com a casa de Davi, reivindica para si a promessa. Constrói o templo, e nisso recebe a confirmação de Deus. A profecia, porém, não se concretiza com a construção desse templo, pois era construído por mãos humanas e iria ser destruído. Portanto, a profecia não se cumprira. O povo de Israel continua esperando pelo templo que será construído pelo filho de Davi, cujo reino permanecerá para sempre.

Várias vezes o templo de Jerusalém foi destruído, comprovando que não era o templo da profecia. Onde estava o templo verdadeiro? Cristo nos dá a resposta ao associar a profecia do templo a seu corpo. Replicaram os judeus: Em quarenta e seis anos foi edificado este santuário, e tu, em três dias, o levantarás? Ele, porém, se referia ao santuário do seu corpo. Quando, pois, Jesus ressuscitou dentre os mortos, lembraram-se os seus discípulos de que ele dissera isto; e creram na Escritura e na palavra de Jesus.

João 2.20-22

O templo que Israel continua a esperar é o corpo de Cristo (Cl 2.17; Hb 10.1; 8.5). Jesus se referia a seu próprio corpo humano. Ele sabe que o templo de seu corpo terreno será destruído, mas ressuscitará, e o novo templo, o templo da eternidade, será seu corpo ressurreto e glorificado. Essa é a casa que Deus constrói para o Filho, a mesma casa que, por sua vez, o Filho constrói para o Pai. Nessa casa, habitam tanto Deus como a nova humanidade, a Igreja de Cristo. O Cristo que se fez humano é o templo da

profecia que se realizou. Isso corresponde ao que está escrito em Apocalipse sobre a nova Jerusalém, quando diz que nela não há templo, “porque o seu santuário é o Senhor, o Deus Todo-Poderoso, e o Cordeiro” (Ap 21.22).

O templo é o lugar da graciosa presença e da habitação de Deus entre os seres humanos. É também o lugar onde a Igreja é aceita por Deus. Essas duas coisas só se realizaram no Jesus Cristo que se fez humano. É nele que a presença de Deus é verdadeira e corporal, e é nele que a humanidade é verdadeira e corporal, pois ele a assumiu em seu próprio corpo. Portanto, o corpo de Cristo é o lugar da aceitação, da reconciliação e da paz entre Deus e os seres humanos. Deus encontra o ser humano no corpo de Cristo, e o ser humano se vê aceito por Deus no corpo de Cristo. O corpo de Cristo é a casa espiritual ( oikos pneumatikos), feita de pedras vivas (1Pe 2.5ss). Só Cristo é o fundamento e a pedra angular desse edifício (Ef 2.20; 1Co 3.11) e é, ao mesmo tempo, o templo ( oikodome, Ef 2.21) onde habita o Espírito Santo, que enche e santifica o coração dos crentes (1Co 3.16; 6.19). O templo de Deus é a Santa Igreja em Jesus Cristo. O corpo de Cristo é o templo vivo de Deus e da nova humanidade.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer diz que a comunhão que temos hoje com Cristo, pela Palavra e pelos sacramentos, é 'mais segura, mais completa, mais certa' do que a dos primeiros discípulos que andaram fisicamente com Jesus. Onde, na sua vida de fé, você ainda age como se ter visto e tocado Jesus fosse uma vantagem que lhe falta, em vez de descansar na presença real dele no batismo e na Ceia?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto afirma que Cristo não assumiu 'um ser humano' isolado, mas toda a humanidade caída em seu corpo, de modo que 'onde estiver seu corpo, ali haverá aceitação para toda carne'. O que muda na maneira como você se enxerga nos seus piores dias ao saber que foi sua carne concreta, e não uma versão idealizada de você, que Cristo carregou para a cruz?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer escreve que sofrer 'por Cristo' e 'pelo corpo da Igreja' não é castigo, mas a maior honra e até alegria que pode ser concedida a um cristão. Você consegue se lembrar de algum sofrimento que carregou por causa de um irmão ou da comunidade, e como seria revisitá-lo enxergando-o como participação na Paixão de Cristo, e não como peso injusto?$p$, 'reflexao', null);
  end if;

