  -- Capítulo 13 — A Igreja visível  (aula ordem = 15)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 15;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 13 — A Igreja visível$t$,
      15,
$conteudo$O corpo de Jesus Cristo ocupa espaço na terra. Com a encarnação, Cristo exige um lugar entre as pessoas, pois “ele veio para o que era seu” (Jo 1.11). Mas, ao nascer, deram-lhe um estábulo, “porque não havia lugar para eles na hospedaria” (Lc 2.7). Foi rejeitado na morte, e seu corpo pendia entre o céu e a terra. A encarnação, porém, implica a exigência de um espaço próprio na terra. O que ocupa espaço é visível. Portanto, ou o corpo de Jesus Cristo é um corpo visível, ou então não é um corpo. Aquele que se vê é o homem Jesus Cristo; aquele em que se crê é o Filho de Deus. O que se vê é o corpo de Jesus Cristo; aquilo em que se crê é o corpo de Deus encarnado. O que se vê é que Jesus estava na carne; aquilo em que se crê é que ele tomou sobre si nossa carne. “Apontarás para esse ser humano e dirás: este é Deus” (Lutero).

Uma verdade, uma doutrina, uma religião não exigem espaço próprio. Elas não têm corpo. Podem ser ouvidas, estudadas e entendidas. Nada mais que isso. O Filho de Deus, porém, não precisa somente de ouvidos ou corações, mas de seres humanos verdadeiros que o sigam. Por isso, Jesus chamava os discípulos ao discipulado corporal, e sua comunhão com eles era visível a todos. Essa comunhão se fundamentava e se sustentava no próprio Jesus Cristo encarnado; a Palavra que se fez carne tinha chamado, tinha criado a comunhão corporal e visível. Os que eram chamados já não podiam viver na invisibilidade. Eram a luz que tem de brilhar, a cidade edificada sobre o monte que tem de ser vista. A cruz e o sofrimento de Jesus Cristo pairavam, visíveis, sobre os que comungavam com ele. Por causa da comunhão, os discípulos tinham de abandonar tudo, tinham de sofrer e ser perseguidos, mas era justamente por esse amor que ganhavam de novo o que tinham perdido — irmãos e irmãs, campos e casas, tudo isso de maneira que todos pudessem ver. A comunidade dos discípulos era visível perante o mundo. Nela havia corpos que agiam, trabalhavam e sofriam na comunhão de Jesus.

O corpo do Senhor glorificado também é corpo visível na forma da Igreja. Como esse corpo se torna visível? Em primeiro lugar, na pregação da Palavra. “E perseveravam na doutrina dos apóstolos” (At 2.42). Cada termo desse versículo tem uma importância especial. Ao contrário dos discursos religiosos de qualquer tipo, a doutrina ( didache) é a pregação. É o ato de comunicar fatos que realmente aconteceram. O conteúdo do que se deve dizer está objetivamente determinado; é preciso apenas comunicá-lo pela “doutrina”. Mas, por natureza, a comunicação se limita a coisas que não conhecemos.

Quando passam a ser conhecidas, não faz mais sentido querer comunicá-las; portanto, é da essência da

“doutrina” tornar-se supérflua com o tempo. Em contradição a isso, lemos que a Igreja antiga

“perseverava” na doutrina, e ela não se tornava supérflua; em vez disso, exigia perseverança. Deve haver alguma necessidade inerente a essa relação entre “doutrina” e “perseverança”. Chama a atenção o fato de

se tratar aqui da “doutrina dos apóstolos”. Mas o que quer dizer “doutrina dos apóstolos”? Os apóstolos são os escolhidos de Deus para testemunhar sua revelação em Jesus Cristo. Eles viveram com Jesus na comunhão corporal, contemplaram com os próprios olhos o Cristo encarnado, crucificado e ressurreto e tocaram seu corpo com as próprias mãos (1Jo 1.1). Os apóstolos são as testemunhas empregadas por Deus e o Espírito Santo para pregar a palavra. A pregação dos apóstolos é o testemunho vivo da revelação de Deus em Jesus Cristo. A Igreja está edificada sobre o fundamento dos apóstolos e dos profetas, cuja pedra angular é Jesus Cristo (Ef 2.20). Toda pregação posterior aos apóstolos deve ser igualmente pregação apostólica, isto é, baseada nesse fundamento. Assim, a unidade entre nós e a Igreja original é estabelecida pela palavra dos apóstolos. Até que ponto a doutrina dos apóstolos torna necessário o “ouvir” contínuo? A palavra apostólica é verdadeiramente a Palavra de Deus expressa pela palavra dos seres humanos (1Ts 2.13). É, portanto, uma palavra que quer acolher os seres humanos e tem poder para fazê-lo. A Palavra de Deus procura uma Igreja para aceitá-la. Ela é essencial na Igreja. Vai à Igreja por livre iniciativa, num movimento dela própria. O que não podemos é supor isto: de um lado, existe uma Palavra, uma verdade; do outro, uma Igreja, e o papel do pregador seria tomar essa palavra em suas mãos e trabalhar nela para, assim, levá-la para dentro da Igreja e aplicá-la à Igreja. Ao contrário, a Palavra segue o caminho por iniciativa própria; o pastor nada pode nem deve fazer senão sujeitar-se a esse movimento próprio da Palavra sem colocar-lhe obstáculos no caminho. A Palavra sai em busca de seres humanos para acolher. Os apóstolos sabiam disso, e essa era sua pregação. Tinham visto com os próprios olhos a Palavra de Deus, tinham visto como a Palavra viera e assumira a carne e, nessa carne, toda a humanidade. Tudo que podiam fazer era testemunhar o que tinham visto: que a Palavra de Deus se fizera carne, que viera para aceitar os pecadores, para perdoar e santificar. Essa é a Palavra que adentra a Igreja, a Palavra que se fez carne e que carrega toda a humanidade, que já não pode existir sem a humanidade que assumiu; é essa a Palavra que vem à Igreja. Nela, porém, vem o próprio Espírito Santo, que revela ao indivíduo e à Igreja o que há muito já foi dado em Cristo. O Espírito produz nos que o ouvem a fé de que, na palavra da pregação, o próprio Jesus Cristo está entre nós no poder de seu corpo, que vem para dizer-me que me aceitou e que hoje quer aceitar-me novamente.

A palavra da pregação dos apóstolos é a Palavra que tomou sobre seu corpo os pecados de todo o mundo, é o Cristo presente no Espírito Santo. A “doutrina dos apóstolos”, a pregação dos apóstolos, é Cristo em sua Igreja. Essa doutrina jamais será supérflua; ela cria a Igreja que nela persevera, pois foi aceita pela Palavra e é diariamente confirmada em sua fé. Essa doutrina cria para si uma Igreja visível.

Além da visibilidade do corpo de Cristo na pregação da Palavra, existe ainda a visibilidade no batismo e na Ceia do Senhor. Ambos procedem do fato de ser verdadeira a humanidade de nosso Senhor Jesus Cristo. Tanto no batismo como na Ceia, ele se encontra conosco corporalmente e divide conosco a comunhão de seu corpo. A pregação faz parte dos dois atos. No batismo e na Ceia, a pregação diz respeito à morte de Cristo por nós (Rm 6.3ss; 1Co 11.26).

Nos dois sacramentos, a dádiva é o corpo de Cristo. No batismo, recebemos a dádiva de ser membros do corpo; na Ceia, a comunhão ( koinonia) corporal com o corpo do Senhor e, em consequência disso, a comunhão corporal com os membros desse corpo. Assim, passamos a ser com ele um único corpo por

meio da dádiva de seu corpo. A dádiva do batismo e da Ceia não é totalmente compreendida quando a consideramos apenas como perdão dos pecados. A dádiva do corpo ministrada nos sacramentos dá-nos o próprio corpo do Senhor em sua Igreja. O perdão dos pecados, no entanto, está incluído na dádiva do corpo de Cristo como Igreja. Daí pode-se compreender que, ao contrário do que ocorre hoje, antigamente a ministração do batismo e da Ceia não estava vinculada à pregação dos apóstolos, mas era exercida pela própria Igreja (1Co 1.1,14ss; 11.17ss). O batismo e a Ceia pertencem exclusivamente à Igreja do corpo de Cristo. A Palavra dirige-se a todos, a crentes e descrentes. Os sacramentos pertencem somente à Igreja. Assim, a Igreja cristã é, no sentido verdadeiro, Igreja do batismo e da Ceia e, somente a partir daí, Igreja da pregação.

Evidenciou-se que a Igreja de Jesus Cristo reivindica espaço de pregação no mundo. O corpo de Cristo é visível na Igreja que se une em torno da Palavra e dos sacramentos.

Essa Igreja é um todo articulado. O corpo de Cristo como Igreja implica articulação e estruturação da igreja. Essas são partes inerentes ao corpo. Um corpo desarticulado está em estado de decomposição.

Segundo a doutrina de Paulo, o corpo vivo de Cristo tem forma articulada (Rm 12.5; 1Co 12.12ss). É impossível perceber as diferenças entre conteúdo e forma, essência e aparência. O contrário seria negar o corpo de Cristo, do Cristo que se fez carne (1Jo 4.3). Portanto, além de querer espaço de pregação, o corpo de Cristo precisa de espaço de articulação da Igreja.

A origem e a natureza da articulação da Igreja são divinas. Essa articulação, porém, existe para servir, e não para dominar a Igreja. As funções na Igreja são “serviços” ( diakoniai, 1Co 12.5). Quem cria tais funções na Igreja é Deus (1Co 12.28), Cristo (Ef 4.11) e o Espírito Santo (At 20.28); não são, portanto, determinadas pela Igreja. Ao distribuir funções, a Igreja segue a orientação do Espírito Santo (At 13.2

etc.). A origem da função e da Igreja é a mesma: o Deus triúno. As funções estão a serviço da Igreja e só são espiritualmente legítimas quando servem. Por isso deve haver funções diferentes — diaconias — em igrejas diferentes. Por exemplo, as funções nas igrejas missionárias de Paulo devem ser diferentes das funções na igreja em Jerusalém. Embora a articulação seja estabelecida por Deus, a forma pode variar e está sujeita apenas à decisão espiritual da própria Igreja, que ordena qual serviço cabe a cada membro.

Os dons que o Espírito Santo concede aos indivíduos também estão sujeitos à rigorosa disciplina da diaconia em relação à Igreja, “porque Deus não é de confusão, e sim de paz” (1Co 14.33). É exatamente aí que o Espírito Santo se faz visível ( phanerosis, 1Co 12.7), a fim de que tudo ocorra para o benefício da Igreja. Apóstolos, profetas, mestres, supervisores (bispos), diáconos, presbíteros, presidentes e dirigentes (1Co 12.28ss; Ef 2.20; 4.11), todos estão a serviço da Igreja, do corpo de Cristo. Por serem ordenados para servir à Igreja, sua missão é de origem e de natureza divinas. Somente a Igreja poderá desligá-los do serviço. Portanto, a Igreja é livre para articularse de acordo com sua necessidade; mas, se sua estrutura é violada por alguém de fora, o que se violenta é a forma visível do próprio corpo de Cristo. Entre todas as funções da Igreja, merece atenção especial, em qualquer época, a preocupação com o não desvirtuamento da palavra e o cuidado na ministração dos sacramentos. Em relação a essas duas atividades, temos de refletir da seguinte maneira: a pregação deve variar de acordo com a missão e os

dons do pregador. Qualquer que seja a pregação, no entanto, baseada em Paulo, Pedro, Apolo ou Cristo, deve sempre reconhecer o Cristo uno e indivisível (1Co 1.11). Um deve cooperar com o outro (1Co 3.6).

Diferentes linhas de pensamento levam a disputas acadêmicas em que cada grupo busca os próprios interesses (1Tm 6.5,20; 2Tm 2.10; 3.8; Tt 1.10). A “piedade” se transforma facilmente em lucro, seja de honra, poder ou dinheiro. A disposição para discutir só pela discussão pode depressa inflamar, desviando a mente da verdade simples e clara (2Tm 3.7). Levará ao egoísmo e à desobediência ao mandamento de Deus. Em oposição a isso, o objetivo da pregação será sempre a doutrina sã e sadia (2Tm 4.3; 1Tm 1.10; 4.16; 6.1; Tt 1.9,13; 2.1; 3.8) e a manutenção da ordem e da unidade.

Nem sempre é fácil distinguir um legítimo pensamento acadêmico de uma heresia. Por isso, é possível que, numa igreja, uma doutrina ainda seja tolerada como opinião acadêmica, enquanto noutra a mesma doutrina tenha sido condenada como falsa (Ap 2.6,15ss). Mas, se a heresia é desmascarada, é necessário separação total. O falso pregador é expulso da Igreja e da comunhão pessoal (Gl 1.8; 1Co 16.22; Tt 3.10; 2Jo 10ss). Portanto, a palavra da pregação verdadeira deve juntar e separar de maneira bem visível. Com isso, torna-se bem evidente o espaço da pregação e da ordem da Igreja em sua necessidade estabelecida por Deus.

A pergunta agora é se, dessa maneira, já temos uma definição da forma visível da Igreja do corpo de Cristo ou se ela ainda reivindica outros espaços no mundo. A resposta do Novo Testamento não deixa qualquer dúvida: a Igreja não só precisa de lugar para seu culto e organização, mas também para a vivência diária de seus membros. Nosso tema, portanto, passa a ser agora o espaço de vida da Igreja visível.

A comunhão de Jesus com seus seguidores era uma comunhão total, em todos os aspectos da vida. A vida individual se desenvolvia na convivência dos discípulos. Essa comunhão é testemunho vivo da natureza humana corporal do Filho de Deus. A dedicação corporal por Jesus e com Jesus no dia a dia é uma exigência da presença física do Filho de Deus. Com toda a energia de sua vida corporal, os seres humanos pertencem a Jesus, que, por causa deles, assumiu forma humana. No discipulado, o discípulo está inseparavelmente unido ao corpo de Jesus.

Tudo isso está testemunhado no primeiro relato sobre a Igreja em Atos dos Apóstolos: “Perseveravam na doutrina dos apóstolos e na comunhão, no partir do pão e nas orações”. “Todos os que creram estavam juntos e tinham tudo em comum” (At 2.42ss; 4.32ss). Observar que a comunhão ( koinonia) encontra seu lugar entre a palavra e a Ceia pode nos ensinar algo. Não é por acaso essa definição de sua natureza, pois sua origem deve estar sempre na palavra, e seu objetivo e realização, na Ceia. Toda comunhão cristã se move entre palavra e sacramento, começa e termina no culto. Ela espera a última Ceia na companhia do Senhor, no reino de Deus. A comunhão que tem essa origem e esse fim é a comunhão perfeita. A essa comunhão, devem subordinar-se também as coisas e os bens desta vida. Foi estabelecida em liberdade, alegria e no poder do Espírito Santo. Nessa comunhão, ninguém passava necessidade e tudo se distribuía

“à medida que alguém tinha necessidade”; nela “ninguém considerava exclusivamente sua nenhuma das coisas que possuía”. No dia a dia desses acontecimentos está expressa a total liberdade evangélica que não necessita de pressão, pois “da multidão dos que creram era um o coração e a alma”.

Essa jovem Igreja estava bem visível para quem quisesse ver, e — muito singularmente! — seus membros “contavam com a simpatia de todo o povo” (At 2.47). Seria isso a cegueira do povo de Israel que já não consegue ver a cruz de Jesus atrás dessa comunhão total? Seria isso uma forma de antecipar o dia em que todos os povos prestarão honras ao povo de Deus? Ou seria a bondade de Deus cercando a comunidade com a bondade humana justamente na época de crescimento, de luta árdua e de separação entre crentes e inimigos, um cerco de participação humana nos destinos da Igreja? Ou seria esse povo entre o qual a Igreja encontra simpatia aquele que cantou Hosana, e não o que clamava “Crucifica-o!”?

“Enquanto isso, acrescentava-lhes o Senhor, dia a dia, os que iam sendo salvos.” Essa Igreja visível da comunhão de vida perfeita irrompe sobre o mundo e lhe arrebata os filhos. O crescimento diário da Igreja comprova o poder do Senhor que nela habita.

O que vale para os primeiros discípulos é: onde estiver seu Senhor, ali eles estarão; onde estiverem eles, também estará seu Senhor, até o fim dos tempos. Tudo que o discípulo fizer, tem de fazê-lo na comunhão da Igreja de Jesus, na condição de membro. As ações mais profanas também passam a acontecer na Igreja. Para o corpo de Cristo, portanto, o que vale é: onde estiver um só membro, ali estará o corpo todo; onde estiver o corpo, também ali estará o membro. Não há área na vida da qual o membro pudesse ou quisesse afastar-se do corpo. Onde quer que esteja, o que quer que faça, tem de fazê-lo “no corpo”, na Igreja, “em Cristo”. Todos os espaços da vida estão “em Cristo”. O cristão tanto é forte como é fraco “em Cristo” (Fp 4.13; 2Co 13.4); ele trabalha, se esforça e se alegra “no Senhor” (Rm 16.9,12; 1Co 15.58; Fp 4.4), fala e exorta em Cristo (2Co 2.17; Fp 2.1), é hospitaleiro em Cristo (Rm 16.2), seu casamento é no Senhor (1Co 7.39), é prisioneiro no Senhor (Fp 1.13,23) e escravo de Cristo (1Co 7.22).

Cristo e a Igreja envolvem toda a gama de relações humanas que podem existir entre os cristãos.

O que garante ao cristão a vida plena em Cristo, na Igreja, é o ingresso no corpo de Cristo pelo batismo. Limitar a dádiva do batismo à participação na pregação e na Ceia, isto é, à participação nos bens da salvação e talvez nas funções e serviços da Igreja, é uma restrição nociva e oposta ao Novo Testamento. Ao contrário, o batismo confere a todo batizado, sem reservas, a participação na vida da comunidade dos membros do corpo de Cristo em todos os aspectos da vida. Garantir ao irmão batizado a participação no culto, mas recusar-lhe a comunhão na vida cotidiana, é maltratá-lo e desprezá-lo; quem faz isso torna-se culpado em relação ao próprio corpo de Cristo. Conferir ao irmão batizado as dádivas da salvação, mas recusar-lhes as dádivas da vida terrena ou permitir conscientemente que o irmão passe necessidade ou dificuldades, é ridicularizar a dádiva da salvação; quem faz isso torna-se mentiroso.

Quem ainda dá ouvidos à voz de seu sangue, de seu temperamento, de suas simpatias e antipatias, mesmo depois de o Espírito Santo ter falado, esse profana o sacramento. O batismo para dentro do corpo de Cristo não só muda o estado do indivíduo em relação à salvação, mas também a todos os aspectos de sua vida.

Após o batismo, Filemom deverá “receber para sempre” o escravo Onésimo, que tinha fugido e lhe causado grande prejuízo, “não como escravo; antes, muito acima de escravo, como irmão caríssimo, [...]

quer na carne, quer no Senhor” (Fm 16). Um irmão “na carne”, ressalta o apóstolo Paulo, advertindo assim todos os cristãos “privilegiados” de um mal--entendido, isto é, tolerar a comunhão com cristãos de

classes inferiores no culto, mas não desejá-la na vida fora da igreja. Na carne, um irmão de Filemom!

Como a um irmão, Filemom deverá receber o escravo, como se fosse o próprio Paulo (v. 17), sem lhe cobrar os danos causados, pois ele é como um irmão (v. 18). Assim deve proceder Filemom espontaneamente, mesmo que Paulo tenha a liberdade de ordená-lo (v. 8-14), e sem dúvida Filemom fará mais do que se pede a ele (v. 21). Um irmão na carne pelo fato de ser batizado! A relação dos dois será outra, mesmo que Onésimo volte a ser escravo de seu senhor Filemom. De que modo será outra? O livre e o escravo tornaram-se membros do corpo de Cristo. Em sua comunhão, vive o corpo de Cristo, a Igreja, como se fosse uma pequena célula. “Todos quantos fostes batizados em Cristo de Cristo vos revestistes.

Dessarte, não pode haver judeu nem grego; nem escravo nem liberto; nem homem nem mulher; porque todos vós sois um em Cristo Jesus” (Gl 3.27-28; cf. Cl 3.11).

Na Igreja, ninguém fica observando se o outro é livre ou escravo, homem ou mulher; a única coisa que interessa é que o outro é membro do corpo de Cristo. Isso não significa, certamente, que o escravo deixa de ser escravo e que o homem deixa de ser homem. Também não quer dizer que, na Igreja, cada um será tratado conforme sua situação, se é judeu ou grego, se é livre ou escravo. É justamente isso que deve acabar. Olhamos uns para os outros apenas como membros do corpo de Cristo, como sendo todos um só nele. Judeu e grego, livre e escravo, homem e mulher, todos estão em comunhão como parte da Igreja do corpo de Cristo. Onde quer que convivam, falem uns com os outros, atuem em conjunto, ali está a Igreja, ali estão em Cristo. É isso que transforma todo o caráter da comunhão. A mulher submete-se ao marido

“no Senhor”, o escravo serve a Deus ao servir a seu senhor, e o senhor sabe que acima dele há um Senhor no céu (Cl 3.18—4.1), mas agora são irmãos “quer na carne, quer no Senhor”.

É assim que a Igreja invade a vida do mundo e conquista espaço para Cristo, pois o que está “em Cristo” não está mais sob o jugo do mundo, do pecado ou da lei. Nessa nova comunhão, nenhuma lei do mundo pode determinar o que quer que seja. O espaço do amor fraternal cristão está sob o poder de Cristo, e não sob o poder do mundo. A Igreja nunca deixará que sua missão a favor do amor fraterno e da misericórdia seja limitada. Pois onde estiver o irmão, ali está o próprio corpo de Cristo, e onde estiver o corpo de Cristo, também ali está sempre sua Igreja, e é nesse lugar que eu também devo estar.

Quem pertence ao corpo de Cristo está liberto do mundo e foi chamado para fora do mundo, e isso deve tornar-se visível a todos, não apenas pela participação no culto e na ordem da Igreja, mas também pela nova comunhão da vida fraternal. Se o mundo odeia o irmão em Cristo, o cristão o ama e serve a ele; se o mundo lhe é violento, o cristão o socorre e lhe alivia a dor; se o mundo o desonra e ofende, o cristão arrisca a própria honra pela vergonha do irmão. Se o mundo busca o lucro, o cristão renuncia a ele; se o mundo explora o próximo, o cristão esvazia-se a si mesmo; se o mundo é opressor, o cristão se levanta a favor do oprimido. Se o mundo é injusto, o cristão é misericordioso; se o mundo se envolve em mentiras, o cristão fala pelos mudos e dá testemunho da verdade. Pelo irmão, seja ele judeu ou grego, escravo ou livre, forte ou fraco, nobre ou plebeu, o cristão renuncia a toda comunhão do mundo, pois está a serviço da comunhão do corpo de Jesus Cristo. Assim, ao servir a essa comunhão, não pode ficar invisível para o mundo. Ele foi escolhido e obedece ao chamado.

Porém,

cada um permaneça na vocação em que foi chamado. Foste chamado sendo escravo? Não te preocupes com isso; mas, se ainda podes tornar-te livre, aproveita a oportunidade. Porque o que foi chamado no Senhor, sendo escravo, é liberto do Senhor; de maneira semelhante, o que foi chamado, sendo livre, é escravo de Cristo. Por preço fostes comprados; não vos torneis escravos de homens. Irmãos, cada um permaneça diante de Deus naquilo em que foi chamado.

1Coríntios 7.20-24

Não é uma diferença e tanto em relação ao primeiro chamado de Jesus ao discipulado? Naquela ocasião, os discípulos tinham de abandonar tudo para seguir Jesus. Agora, porém, temos: “Cada um permaneça na vocação em que foi chamado”. Como desfazer essa contradição? A única resposta é que devemos reconhecer que, tanto no chamado de Jesus como nas advertências dos apóstolos, o que se quer é apenas que o ouvinte venha para a comunhão do corpo de Cristo. Os primeiros discípulos tinham de andar com Jesus para estar em sua comunhão corporal. Agora, uma vez que a comunhão se dá por meio da palavra e dos sacramentos, o corpo de Cristo já não está limitado a um único lugar da terra. O Cristo ressurreto e glorificado está mais próximo do mundo, o corpo de Cristo se espalhou por todo o mundo — na forma da Igreja. Quem foi batizado está batizado para dentro do corpo de Cristo. Cristo veio a ele e aceitou sua vida, tomando do mundo o que ao mundo pertencia.

Se alguém foi batizado como escravo, passa a ser membro da comunhão de Jesus Cristo na condição de escravo. Como escravo ele foi retirado do mundo, tornando-se livre em Cristo. Então, que o escravo permaneça escravo! Como membro da Igreja de Cristo, alcançou uma liberdade que nenhuma rebelião ou revolução lhe poderia tirar. Na realidade, Paulo não adverte o escravo a permanecer escravo para que ele melhor se adapte ao mundo, para “consolidar religiosamente” ainda mais sua vida no mundo ou para transformá-lo em um cidadão melhor. Paulo tampouco quer justificar ou encobrir uma ordem social sombria. Não que a estrutura social do mundo fosse tão boa e divina que não devesse ser derrubada, mas esse não é o objetivo de Paulo. Para ele, a obra de Jesus Cristo já transformou o mundo, e essa mudança se dá pela liberdade que tanto o escravo como o livre podem experimentar em Cristo.

Será que uma ruptura da ordem social não serviria apenas para obscurecer a percepção da nova ordem divina de todas as coisas estabelecida por Jesus Cristo e que continuou a partir da fundação de sua Igreja? Acaso essas tentativas de rompimento não seriam obstáculos impedindo ou retardando o romper do reino de Deus? Certamente não porque o cumprimento dos deveres profissionais já seja a realização da vida cristã, mas porque abrir mão de resistir à ordem estabelecida no mundo é a expressão mais adequada para o que se apresenta aqui, ou seja, que o cristão nada deve esperar do mundo, mas tudo de Cristo e de seu reino — então, que o escravo permaneça escravo! Porque este mundo não precisa ser reformado, mas estar maduro para ser destruído — então, que o escravo permaneça escravo! Ele tem uma promessa melhor. Saber que o Filho de Deus veio a este mundo “assumindo a forma de servo” (Fp 2.7) já não é juízo sobre o mundo e alívio para o escravo? Não está o cristão, chamado na condição de escravo, afastado do amor e da cobiça ao mundo e da preocupação com ele justamente em sua condição de escravo? Que o escravo, portanto, não sofra em silenciosa rebeldia, mas sofra como membro da comunhão do corpo de Cristo! Assim o mundo amadurecerá para ser destruído.

“Não vos torneis escravos de homens.” Isso poderia acontecer de duas maneiras. Por um lado, pela desobediência ou subversão da ordem estabelecida; por outro, pelo desejo de mistificar religiosamente essa mesma ordem. “Irmãos, cada um permaneça diante de Deus naquilo em que foi chamado” (1Co 7.24). “Diante de Deus” — e por isso: “Não vos torneis escravos de homens”, nem por desobediência nem por falsa obediência. Permanecer naquilo em que foi chamado diante de Deus significa viver em meio ao mundo e, ao mesmo tempo, permanecer no corpo de Cristo na Igreja visível, participar do culto e da vida no discipulado, dando o testemunho vivo da vitória sobre o mundo.

Por isso, “todo homem esteja sujeito às autoridades superiores” (Rm 13.1ss). Não se exige do cristão que se volte para cima, para os poderosos; é embaixo que deve permanecer. As autoridades estão acima ( hyper) dele; o cristão permanece debaixo ( hypo). O mundo governa e o cristão serve, e é no serviço que ele tem comunhão com seu Senhor que se tornou escravo.

Mas Jesus, chamando-os para junto de si, disselhes: sabeis que os que são considerados governadores dos povos têm-nos sob seu domínio, e sobre eles os seus maiorais exercem autoridade. Mas entre vós não é assim; pelo contrário, quem quiser tornar-se grande entre vós, será esse o que vos sirva. [...] Pois o próprio Filho do Homem não veio para ser servido, mas para servir e dar a sua vida em resgate por muitos.

Marcos 10.42-43,45 “Porque não há autoridade que não proceda de Deus.” Isso é dirigido aos cristãos, e não às autoridades!

Os cristãos devem saber que é exatamente lá embaixo, para onde as autoridades os mandam, que eles reconhecerão a Deus e farão sua vontade. Os cristãos devem ficar consolados, pois a autoridade é instrumento de Deus para o bem deles; ele é Senhor também sobre as autoridades. Mas isso não deve se limitar a uma consideração e percepção geral sobre a natureza da autoridade ( exousia — singular!); ao contrário, o cristão deve aplicar isso de acordo com sua posição em relação às autoridades de fato instituídas ( hai de ousai). Quem se opõe a elas resiste à ordem de Deus ( diatache tou theou), pois foi Deus que quis que o mundo governasse, que Cristo vencesse servindo e que os cristãos vencessem com Cristo. “E os que resistem trarão sobre si mesmos condenação” (Rm 13.2), pois estariam agindo novamente como o mundo. O que leva os cristãos tão facilmente a se oporem às autoridades?

Provavelmente, por se ofenderem com os erros e injustiças cometidos pelas autoridades. Mas, pensando assim, os cristãos correm o risco de se aterem a outras coisas em vez de cumprir a vontade de Deus. Se só quiserem e só fizerem o bem como ordena Deus, podem viver “sem temer” a autoridade, “porque os magistrados não são para o temor, quando se faz o bem, e sim quando se faz o mal” (Rm 13.3). O que temeria o cristão que permanece fiel a seu Senhor e só faz o bem? “Queres tu não temer a autoridade?

Faze o bem” (v. 3). “Faze o bem”! É isso que interessa. O importante para você é o que você faz, não o que os outros fazem. Faça o bem sem medo, sem restrição, sem condição! Como pode querer censurar a autoridade por fazer algo errado quando você próprio não faz o bem? Como pode querer condenar os outros quando você é que merece ser julgado pelo que está condenando? “Queres tu não temer a autoridade? Faze o bem e terás louvor dela, visto que a autoridade é ministro de Deus para teu bem” (v. 3-4). Não que receber louvor seja o motivo para fazer o bem; na verdade, nem poderia ser o objetivo para fazer o bem. O louvor é consequência, e virá onde houver verdadeira autoridade. O pensamento de

Paulo sempre parte da Igreja cristã, e sua preocupação é tão exclusivamente o bem-estar e o comportamento da Igreja que ele chega a advertir aos cristãos que não cometam injustiças e maldades, sem, no entanto, fazer qualquer censura à autoridade. “Entretanto, se fizeres o mal, teme; porque não é sem motivo que ela traz a espada; pois é ministro de Deus, vingador, para castigar o que pratica o mal”

(v. 4). O que importa é que nada de mal aconteça na Igreja cristã. Mais uma vez, a palavra se dirige aos cristãos, e não às autoridades. Para Paulo, mais importante que justificar ou condenar uma autoridade perante o mundo é que os cristãos continuem a viver em arrependimento e em obediência, independentemente de onde estejam ou dos conflitos que os ameacem. Nenhuma autoridade pode deduzir dessas palavras uma justificação divina de sua existência. Se, ao contrário, essa palavra realmente atingisse uma autoridade, seria para ela um chamado ao arrependimento assim como de fato o é para a Igreja. Ao ouvir essa palavra, um poderoso ( archon) não poderia deduzir dela uma autorização divina para o exercício de seu governo, mas reconheceria nela sua missão para servir a Deus em benefício dos cristãos que fazem o bem. E, diante dessa missão, teria de se arrepender. Paulo certamente se dirige dessa maneira aos cristãos não porque a ordem do mundo fosse tão boa, mas porque importa unicamente que a vontade de Deus seja obedecida na Igreja, independentemente da bondade ou da maldade da ordem do mundo. O apóstolo não está ensinando aos cristãos as obrigações da autoridade; ele fala apenas sobre as obrigações dos cristãos para com as autoridades.

O cristão receberá louvor da autoridade! Mas que culpa ele tem se, em lugar de louvor, receber castigo e perseguição? Afinal, o que ele fez para receber castigo não foi feito com a intenção de receber louvor. Também não fez o bem por medo do castigo. Se em lugar de receber louvor ele for castigado, ainda assim o cristão estará livre diante de Deus e sem medo, e a Igreja não sentirá nenhuma vergonha. O cristão não obedece às autoridades para obter alguma vantagem, mas “por dever de consciência” (v. 5). Portanto, o erro da autoridade não lhe fere a consciência. Ele continua livre e sem medo e continua a obedecer devidamente à autoridade, mesmo sofrendo ciente de que é inocente. Sabe ele que, de fato, é Deus que governa, e não a autoridade; a autoridade é ministro de Deus. “A autoridade é ministro de Deus” —

assim fala o apóstolo que tantas vezes foi preso inocentemente por ordem da autoridade, que por três vezes foi cruelmente açoitado, que sabia da extradição de todos os judeus de Roma pelo imperador Cláudio (At 18.1ss). “A autoridade é ministro de Deus” — assim, portanto, fala aquele que sabe que há muito todo poder e toda autoridade do mundo foram destituídos, que Cristo os levou em triunfo para a cruz e que breve tudo isso será revelado.

Tudo que se disse, porém, está associado à advertência que o apóstolo faz antes do capítulo 13: “Não te deixes vencer do mal, mas vence o mal com o bem” (Rm 12.21). Não se trata, portanto, de saber se a autoridade é boa ou má, mas da vitória dos cristãos sobre o mal.

Enquanto para os judeus a questão sobre o pagamento de tributos ao imperador era foco de tentação, por sua esperança de destruir o Império Romano e estabelecer o próprio império, essa questão não despertava nenhuma paixão nos discípulos de Jesus. “Dai, pois, a César o que é de César” (Mt 22.21), diz Jesus. “Por esse motivo, também pagais tributos” (Rm 13.6), e assim Paulo encerra sua preleção.

Essa obrigação não põe os cristãos em conflito com o mandamento de Jesus, pois eles só devolvem a

César o que já é de César. Os cristãos devem ver aqueles que lhes cobram impostos como “ministros de Deus” ( leitourgoi, v. 6). Não nos confundamos, porém: para Paulo, os cristãos não estão realizando o culto ao pagar impostos. Contudo, os que cobram impostos realizam, ao fazê-lo, seu culto. Paulo não exige que os cristãos participem desse culto, mas recomenda que sejam submissos e nada fiquem devendo a ninguém (v. 7-8). Qualquer oposição ou resistência nesse sentido apenas revelaria a confusão dos cristãos entre o reino de Deus e os reinos deste mundo.

Por isso, que o escravo permaneça escravo, que o cristão permaneça submisso às autoridades, que o cristão não fuja do mundo (1Co 5.11). Mas que, sendo escravo, viva como liberto em Cristo; sujeito à autoridade, viva para fazer o bem; no mundo, viva como membro do corpo de Cristo da humanidade renovada. Que faça tudo isso sem reservas, vivendo no mundo de tal forma que dê testemunho da perdição do mundo e da nova criação na Igreja. Que sofra apenas por ser membro do corpo de Cristo.

Que o cristão permaneça no mundo não por causa das boas dádivas da criação, nem pela responsabilidade pelo andamento do mundo, mas por causa do corpo de Cristo, que se fez carne, por causa da Igreja. Que o cristão permaneça no mundo por causa do confronto direto com o mundo, que viva sua “vida profissional no interior do mundo”, para assim tornar visível sua “estranheza no mundo”. Nada disso pode ser feito senão através da filiação visível à Igreja. A contradição com o mundo deve ser confirmada no mundo. Por isso Cristo se fez humano e morreu no meio de seus inimigos. Por tudo isso —

e só por isso! —, que o escravo permaneça escravo, e que o cristão esteja sujeito à autoridade.

Foi exatamente essa a conclusão de Martinho Lutero sobre a vocação profissional no mundo nos anos decisivos em que voltou as costas para o mosteiro. Na visão dele, o problema não consistia nas exigências extremas da vida monástica, mas na ideia de que a obediência ao mandamento de Jesus era missão para poucos. Lutero não questionou a “estranheza ao mundo” nos conventos, mas o fato de essa estranheza ter se tornado uma nova acomodação espiritual ao mundo. Para Lutero, isso era a perversão mais vergonhosa do evangelho. Ele acreditava que a “estranheza ao mundo” da vida cristã tinha de ser vivida no mundo, na Igreja, no dia a dia. Por isso os cristãos devem exercitar a vida cristã na própria profissão cotidiana e, assim, morrer para o mundo. Nisso consiste o valor da profissão para o cristão: em poder exercitar sua profissão pela bondade de Deus e atacar mais vigorosamente os fundamentos do mundo. Lutero não voltou para o mundo por ter um “conceito mais positivo do mundo”, nem por ter renunciado à esperança da Igreja primitiva pela volta próxima de Cristo. Ao contrário, a volta de Lutero significava a mais pura crítica e o maior protesto contra a secularização do cristianismo na vida monástica. Ao chamar os cristãos de volta ao mundo, Lutero está chamando à verdadeira “estranheza ao mundo”. Ele mesmo experimentou essa mudança no próprio corpo. Seu chamado ao mundo era sempre um chamado à Igreja visível do Senhor que se fez humano. Em nada diferente dos ensinamentos de Paulo.

Por isso, também fica claro que, para o cristão, a vida profissional no mundo tem limites bem determinados; pode acontecer de, eventualmente, após o chamado à vida profissional no mundo, acontecer o chamado para fora dela. É esse o ponto de vista tanto de Paulo como de Lutero. Os limites são dados pela própria filiação à Igreja visível de Cristo, isto é, quando a reivindicação e a ocupação do espaço do culto, das funções na Igreja e da vida de cidadão se chocam com a exigência de espaço do

mundo. Torna-se evidente que o limite foi alcançado no momento em que há a necessidade de o cristão membro da Igreja fazer uma confissão clara e pública de Jesus e o mundo se vir obrigado a uma saída estratégica ou uma reação violenta. Aí tem início o sofrimento público do cristão. Ele que morreu com Cristo no batismo, com seu sofrimento invisível, não percebido pelo mundo, é expulso publicamente de sua profissão neste mundo. Ingressa então na comunhão visível do sofrimento de seu Senhor. Agora, precisa mais que nunca da comunhão plena e da ajuda fraternal da Igreja. Nem sempre, porém, é o mundo que expulsa o cristão da vida profissional. Desde os primeiros séculos da Igreja, já havia profissões consideradas incompatíveis com a filiação à Igreja cristã. O ator teatral que representa deuses e heróis pagãos, o professor que ensina mitologia em escolas pagãs, o gladiador que tira vidas humanas como passatempo e o soldado que leva a espada, o policial, o juiz — todos esses tinham de renunciar à profissão pagã se quisessem ser batizados. Mais tarde, a Igreja — ou melhor, “o mundo” — consentiu em que os cristãos trabalhassem na maioria dessas profissões. Mais e mais a defesa passava da Igreja para o mundo.

Quanto mais o mundo envelhecia, quanto mais aumentava a luta entre Cristo e o anticristo, tanto mais o mundo buscava livrar-se dos cristãos. Para os primeiros cristãos, o mundo ainda garantia um espaço onde podiam obter o sustento com trabalhos manuais. Contudo, um mundo completamente anticristão já não poderá permitir aos cristãos nem mesmo a esfera privada do exercício da profissão e do trabalho para poderem ganhar o pão. Exige-se deles a negação de seu Senhor para cada pedaço de pão que quiserem comer. Portanto, a única solução que restará aos discípulos será fugir do mundo ou ir para a prisão. Quando o último espaço de terra for tirado dos cristãos, o fim estará próximo.

Assim, embora o corpo de Cristo invada profundamente certos espaços da vida secular, em outros a separação total é sempre visível, e ficará cada vez mais visível. Estar no mundo ou separado dele, porém, acontece em obediência à palavra: “E não vos conformeis com este século, mas transformai-vos ( metamorphousthe) pela renovação da vossa mente, para que experimenteis qual seja a boa, agradável e perfeita vontade de Deus” (Rm 12.2). Existe um conformar-se-com-o-mundo no mundo, mas também existe o “mundo” espiritual do convento escolhido por vontade própria. Existe tanto a permanência proibida no mundo como a fuga proibida do mundo. Nos dois casos, estamos nos conformando com o mundo. A Igreja de Cristo, porém tem uma “forma” diferente da do mundo. E a Igreja tem de transformar-se cada vez mais nessa forma. A forma é o próprio Cristo, que veio ao mundo e aceitou os seres humanos com misericórdia sem fim e, no entanto, não se conformou com o mundo, mas foi rejeitado e expulso por ele. Ele não era deste mundo. No verdadeiro encontro com o mundo, a Igreja visível assumirá cada vez mais a forma do Senhor sofredor.

Por isso os irmãos devem saber:

O tempo se abrevia; o que resta é que não só os casados sejam como se o não fossem; mas também os que choram, como se não chorassem; e os que se alegram, como se não se alegrassem; e os que compram, como se nada possuíssem; e os que se utilizam do mundo, como se dele não usassem; porque a aparência deste mundo passa. O que realmente eu quero é que estejais livres de preocupações.

1Coríntios 7.29-32a

Assim é a vida da Igreja de Cristo no mundo. Os cristãos vivem como as outras pessoas. Casam-se, choram e alegram-se, fazem compras e usam o mundo para os propósitos da vida diária. Tudo que possuem, porém, eles o têm somente por Cristo e em Cristo e por amor a Cristo e, por isso, o que possuem não os prende. Têm o que têm, mas é como se não o tivessem. O coração não está preso a essas coisas. São totalmente livres. Por isso, podem usar o mundo e não precisam retirar-se dele (1Co 5.13).

Também, por serem livres, podem abandonar o mundo caso ele seja um obstáculo ao discipulado de seu Senhor. Podem se casar, embora o apóstolo pense que seriam mais abençoados sendo livres, se isso for possível na fé (1Co 7.7,33-40). Compram e negociam, mas apenas para o sustento das necessidades diárias. Não juntam riquezas nas quais poderiam apegar o coração. Trabalham, pois não devem ficar ociosos. O trabalho, porém, não é uma finalidade em si. Trabalhar pelo trabalho em si é conceito alheio ao Novo Testamento. Cada um deve trabalhar para obter seu sustento. Além disso, deve ter algo para doar aos irmãos (1Ts 4.11s; 2Ts 3.11s; Ef 4.28). Deve ser independente dos “de fora”, dos gentios (1Ts 4.12), como era o próprio Paulo, que se orgulhava de obter o sustento com o trabalho de suas mãos, para ser independente inclusive de suas igrejas (2Ts 3.8; 1Co 9.15). Essa independência serve de argumento ao pastor para comprovar que o alvo de sua pregação não é o lucro. Tudo está a serviço da igreja. Ao lado do mandamento do trabalho, há outro: “Não andeis ansiosos de coisa alguma; em tudo, porém, sejam conhecidas diante de Deus, as vossas petições, pela oração e pela súplica, com ações de graças” (Fp 4.6). Os cristãos sabem:

De fato, grande fonte de lucro é a piedade com o contentamento. Porque nada temos trazido para o mundo, nem coisa alguma podemos levar dele. Tendo sustento e com que nos vestir, estejamos contentes. Ora, os que querem ficar ricos caem em tentação, e cilada, e em muitas concupiscências insensatas e perniciosas, as quais afogam os homens na ruína e perdição.

1Timóteo 6.6-9

Assim, os cristãos usam as riquezas do mundo, sabendo que essas coisas “com o uso, se destroem” (Cl 2.22). Fazem tudo com ação de graças e oração ao Criador por todas as coisas boas que ele criou (1Tm 4.4). O tempo todo, porém, são livres. Sabem o que é estar saciado e ter fome, o que é ter fartura e escassez. “Tudo posso naquele que me fortalece” (Fp 4.13s).

Os cristãos estão no mundo, precisam do mundo, pois são carne, e foi por amor de sua carne que Cristo veio ao mundo. Eles fazem coisas mundanas. Eles se casam, mas seu casamento é diferente do casamento do mundo. Será casamento “no Senhor” (1Co 7.39). Será santificado no serviço do corpo de Cristo e na disciplina da oração e do domínio próprio (1Co 7.5). Nesse sentido, o casamento é uma parábola do amor de Cristo à Igreja. Sim, o casamento do cristão será parte do corpo de Cristo. Seu casamento será Igreja (Ef 5.32). Os cristãos compram e vendem, dedicam-se ao comércio e à indústria, mas seu modo de fazê-lo também é diferente da maneira mundana. Não apenas não tomarão proveito uns dos outros (1Ts 4.6), mas — por incrível que pareça aos olhos do mundo — preferirão sofrer prejuízo e injustiça a lutar por seus direitos por “bens terrenos” em tribunais pagãos. Caso haja conflitos, resolvem suas disputas no interior da Igreja, diante de tribunal próprio (1Co 6.1-8).

Assim é a vida da comunidade cristã no mundo, testemunhando, por sua maneira de ser e de agir, que a

“aparência deste mundo passa” (1Co 7.31), que “o tempo se abrevia” (1Co 7.29), que “perto está o Senhor” (Fp 4.5). Por tudo isso, ela se enche da maior alegria (Fp 4.4). O mundo se torna pequeno para ela, e a volta de Jesus lhe é o mais importante. Ainda vive na carne, mas seu olhar se dirige para o céu, de onde virá aquele a quem esperam. A Igreja cristã é, em terra estrangeira, uma colônia longe da pátria, uma Igreja de estrangeiros. Desfruta a hospitalidade desta terra, obedece a suas leis e honra suas autoridades. Agradecida, usa o que é necessário para o sustento do corpo e da vida. Mostra-se honesta, justa, pura, agradável, tranquila e pronta para servir em todas as coisas. Manifesta o amor de seu Senhor a todos os seres humanos, “mas principalmente aos da família da fé” (Gl 6.10; 2Pe 1.7). É paciente e alegre no sofrimento, gloriando-se nas tribulações. Vive sua própria vida sob autoridade e justiça estranhas. Acima de tudo, oram em favor de todas as autoridades, prestando-lhes assim o melhor serviço (1Tm 2.1). No entanto, está apenas seguindo seu caminho. O sinal de partida pode soar a qualquer momento. Então se levantará, rompendo com todas as amizades e relações mundanas para seguir unicamente a voz daquele que chamou. Deixam para trás a terra estrangeira e marcham em direção à pátria que está no céu.

São pobres e sofridos, famintos e sedentos, mansos, misericordiosos e pacificadores, perseguidos e caluniados pelo mundo, mas é por eles que o mundo continua a existir. Eles protegem o mundo da ira e do juízo de Deus. Sofrem para que o mundo possa continuar a viver sob a paciência de Deus. São estrangeiros e peregrinos sobre a terra (Hb 11.13; 13.14; 1Pe 2.1). Pensam “nas coisas lá do alto, não nas que são aqui da terra” (Cl 3.2), pois sua vida verdadeira ainda não foi revelada, mas está “oculta juntamente com Cristo, em Deus” (Cl 3.3). Assim têm sempre diante dos olhos a imagem do que serão.

Na terra, a única coisa visível é sua morte, esse morrer secreto e diário do velho ser humano, e o morrer público diante do mundo. Também continuam invisíveis a si próprios. A mão esquerda não sabe o que a direita faz. Permanecem totalmente desconhecidos de si mesmos, exatamente como a Igreja visível. Veem somente seu Senhor. Ele está no céu, e com ele está a vida que esperam. “Quando Cristo, que é a nossa vida, se manifestar, então, vós também sereis manifestados com ele, em glória” (Cl 3.4).

Na terra andam, no céu vivem,

Força não têm, mas o mundo protegem;

Gozam paz em meio ao tumulto,

São pobres, mas desfrutam de tudo.

Plenos de alegria, embora sofram

E mortos para o mundo pareçam;

No íntimo, porém, a fé praticam.

Quando Cristo, sua vida, revelar-se

E, em glória, manifestar-se,

Príncipes da terra eles serão,

Em glória, a todos maravilharão.

Assim, reinando com ele, triunfantes,

O céu adornarão como luzes cintilantes; Para todos, júbilos constantes.

(C. F. Richter)

Essa é a Igreja dos que foram separados, dos chamados, a Ecclesia, o corpo de Cristo na terra, os seguidores e discípulos de Jesus.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$O capítulo insiste que o corpo de Cristo 'ocupa espaço na terra' e que uma fé invisível, sem comunhão visível, contradiz a encarnação. Em que pontos a sua fé tem ficado confortavelmente invisível, vivida só por dentro, sem corpo, sem rosto, sem custo diante das pessoas?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Bonhoeffer denuncia o cristão que aceita comungar com irmãos 'de classes inferiores' no culto, mas recusa essa comunhão na vida cotidiana, usando o exemplo de Onésimo e Filemom como irmãos 'quer na carne, quer no Senhor'. Existe alguém que você trata como irmão no domingo, mas mantém à distância na vida concreta, nas finanças, na mesa, na amizade real?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O texto sustenta o paradoxal 'que o escravo permaneça escravo' não para acomodar o cristão ao mundo, mas porque tudo deve ser esperado de Cristo e nada do mundo. Onde você tem confundido fé com vontade de reformar ou dominar suas circunstâncias externas, em vez de viver livre 'em Cristo' exatamente dentro delas?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 14 — Os santos  (aula ordem = 16)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 16;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 14 — Os santos$t$,
      16,
$conteudo$A Ecclesia de Cristo, a Igreja dos discípulos, foi arrebatada das forças do mundo. Sim, ainda vive no mundo, mas transformou-se em um corpo único, com sua própria esfera de ação, um espaço para si. É a santa Igreja (Ef 5.27), a comunhão dos santos (1Co 14.34), e seus membros são chamados para serem santos (Rm 1.7), santificados em Jesus Cristo (1Co 1.2), separados e escolhidos antes da fundação do mundo, para serem santos e irrepreensíveis (Ef 1.4). Cristo entregou seu corpo à morte, para apresentar os seus diante de si mesmo, santos, inculpáveis e irrepreensíveis (Cl 1.22). Este é o fruto da libertação do pecado pela morte de Cristo: aqueles que antes ofereciam seus membros para a escravidão da impureza e da maldade oferecem-nos agora para o serviço à justiça para a santificação (Rm 6.19-22).

Só Deus é santo. Ele é santo tanto na separação total do mundo pecaminoso como no estabelecimento de seu santuário em meio ao mundo. Por isso, Moisés e os filhos de Israel, depois da destruição dos egípcios, entoaram este cântico de louvor ao Senhor que os libertara da escravidão do mundo: Ó SENHOR, quem é como tu entre os deuses? Quem é como tu, glorificado em santidade, terrível em feitos gloriosos, que operas maravilhas? Estendeste a destra; e a terra os tragou. Com a tua beneficência guiaste o povo que salvaste; com a tua força o levaste à habitação da tua santidade. [...] Tu o introduzirás e o plantarás no monte da tua herança, no lugar que aparelhaste, ó SENHOR, para tua habitação, no santuário, ó Senhor, que as tuas mãos estabeleceram.

Êxodo 15.11-13,17

A santidade de Deus consiste na construção de sua morada entre nós, seu santuário, de onde nascem o juízo e a salvação (Sl 99 etc.). No santuário, porém, o Santo entra em comunhão com seu povo. Isso se dá na reconciliação que só pode ser efetuada no santuário (Lv 16.16ss). Deus faz uma aliança com seu povo.

“Santos sereis, porque eu, o SENHOR, vosso Deus, sou santo” (Lv 19.2) e “eu, o SENHOR que vos santifico, sou santo” (Lv 21.8). Esse é o fundamento da aliança. Todas as outras leis dadas ao povo, leis que deverão ser cumpridas em justiça, têm por pressuposto e por finalidade a santidade de Deus e de sua Igreja.

Assim como o próprio Deus, a Igreja de seu santuário também está separada das coisas imundas e do pecado. Ele próprio a escolheu. Fez dela a Igreja de sua aliança. No santuário, ele a reconciliou e a purificou. O santuário, porém, é o templo, e o templo é o corpo de Cristo. Assim, no corpo de Cristo cumpriu-se a vontade de Deus por uma Igreja santa. Separado do mundo e do pecado, e feito propriedade de Deus, o corpo de Cristo é o santuário de Deus no mundo. Nele Deus habita com o Espírito Santo.

Como isso acontece? Como é que Deus cria, de seres humanos pecadores, uma Igreja santa, totalmente separada do pecado? Como Deus se defenderá da acusação de tornar-se injusto ao fazer aliança com

pecadores? Como o pecador pode tornar-se justo sem que a justiça de Deus seja comprometida?

Deus justifica a si mesmo. Ele apresenta a prova de sua justiça. O milagre da autojustificação de Deus diante de si mesmo e de toda a humanidade acontece na cruz de Jesus Cristo (Rm 3.21ss). O pecador deve ser separado do pecado e, ainda assim, viver perante Deus. Mas o pecador só pode ser separado do pecado através da morte. Em sua vida há tanto pecado que ele precisa morrer se quiser separar-se do pecado. Só assim Deus poderá ser justo: se matar o pecador. Deus, porém, quer que o pecador viva e seja santo diante dele. Como isso será possível? O próprio Deus se faz humano, assume nossa carne em Jesus Cristo, seu Filho, e, na cruz, leva em seu corpo nossa carne à morte. Deus mata seu Filho que leva nossa carne e, com ele, mata tudo que é carne sobre a terra. Está claro, portanto, que ninguém é bom a não ser Deus somente, e ninguém é justo a não ser Deus somente. Foi assim que Deus apresentou a horrível prova de sua própria justiça ( endeixis thes dikaiousynes autou, Rm 3.26) por meio da morte do Filho. Era necessário que Deus entregasse à morte toda a humanidade no juízo de sua ira, para que apenas ele seja justo. A justiça de Deus revela-se na morte de Jesus Cristo. A morte de Jesus Cristo é o lugar onde Deus apresenta a prova da graça de sua justiça, o lugar exato onde a justiça de Deus passará a habitar. Quem participasse dessa morte teria também parte na justiça de Deus. Mas o fato é que Cristo tomou sobre si nossa carne, “carregando ele mesmo em seu corpo, sobre o madeiro, os nossos pecados” (1Pe 2.24). O que aconteceu com ele aconteceu com todos nós. Ele participou de nossa vida e morte para que pudéssemos participar de sua vida e morte. Se a justiça de Deus tinha de se revelar na morte de Cristo, então nós estamos com ele no lugar onde habita a justiça de Deus, isto é, em sua cruz, porque ele tomou sobre si nossa carne. Portanto, tornamo-nos participantes da justiça de Deus na morte de Cristo, como os que foram mortos. A própria justiça de Deus que nos mata, os pecadores, é sua justiça para nós na morte de Jesus. Uma vez que a justiça de Deus é restaurada na morte de Jesus, a justiça de Deus também é restaurada para nós que estamos incluídos na morte de Cristo. Deus comprova sua justiça “para ele mesmo ser justo e o justificador daquele que tem fé em Jesus” (Rm 3.26). A justificação do pecador, portanto, consiste no fato de somente Deus ser justo, e o pecador, totalmente injusto; não que seja possível o pecador justificar a si mesmo em lugar de Deus. Qualquer desejo de justiça própria separa-nos totalmente da justificação, uma vez que só Deus pode justificar. Só Deus é justo. Isso se reconhece na cruz como a sentença proferida a nós, pecadores. Aquele, porém, que na fé se reconhece na morte de Jesus Cristo na cruz, alcança ali, onde como pecador recebe a sentença de morte, a justiça de Deus, que triunfa na cruz. E é exatamente na condição de alguém que jamais pode nem pretende tornar-se justo por vontade própria, alguém que sabe que só Deus é justo e que o crente recebe a justificação. Pois o ser humano não pode tornar-se justo aos olhos de Deus senão ao reconhecer que só Deus é justo e o ser humano é pecador por natureza. A pergunta sobre como nós, pecadores, poderíamos ser justos diante de Deus é, essencialmente, a pergunta sobre como somente Deus é justo para conosco. Nossa justificação fundamentase unicamente na justificação de Deus, “para seres [Deus] justificado nas tuas palavras e venhas a vencer quando fores julgado” (Rm 3.4).

Trata-se, nesse caso, apenas da vitória de Deus sobre nossa injustiça, do fato de Deus permanecer justo diante de si mesmo, de somente ele ser justo. Essa vitória de Deus foi conquistada na cruz. Por isso, a cruz não só é juízo, mas também reconciliação ( hilasterion, v. 25) para todos os que creem que, na morte de Jesus, somente Deus é justo e que reconhecem seus pecados. A própria justiça de Deus cria a reconciliação ( proetheto, v. 25). “Deus estava em Cristo reconciliando consigo o mundo, não imputando aos homens as suas transgressões” (2Co 5.19). Ele próprio as carregou e sofreu a morte do pecador. “E

nos confiou a palavra da reconciliação” (2Co 5.19). Essa palavra quer encontrar a fé, fé em que somente Deus é justo e se tornou nossa justiça em Jesus. Mas, entre a morte de Cristo e a mensagem da cruz, está sua ressurreição. A cruz de Jesus tem poder sobre nós porque ele é o ressurreto. A mensagem do crucificado já é e sempre será a mensagem daquele que a morte não reteve. “De sorte que somos embaixadores em nome de Cristo, como se Deus exortasse por nosso intermédio. Em nome de Cristo, pois, rogamos que vos reconcilieis com Deus” (2Co 5.20). A mensagem da reconciliação é a própria palavra de Cristo. Ele é o ressurreto, aquele que se revela a nós como o crucificado; na palavra do apóstolo: reencontrem a si mesmos na morte de Jesus Cristo, na justiça de Deus que ali nos é dada. Quem se encontra na morte de Jesus encontra-se na justiça exclusiva de Deus. “Aquele que não conheceu pecado, ele o fez pecado por nós; para que, nele, fôssemos feitos justiça de Deus” (2Co 5.21). O inocente é morto porque carrega nossa carne pecadora, é odiado e amaldiçoado por Deus e pelo mundo, é feito pecado por causa de nossa carne. Nós, porém, encontramos em sua morte a justiça de Deus.

Estamos nele no poder de sua encarnação. Assim, ele morreu por nós, para que nós, pecadores, nele nos tornássemos justiça de Deus, como pecadores que foram absolvidos do pecado pela justiça exclusiva de Deus. Se, diante de Deus, Cristo é nosso pecado que precisa ser condenado, então somos, nele, a justiça, embora não sejamos, certamente, nossa própria justiça ( idia dikaiosyne, Rm 10.3; Fp 3.9); mas sim, no sentido exato, justiça exclusiva de Deus. Esta, portanto, é a justiça de Deus: que nós, como pecadores, somos feitos sua justiça; e esta é a nossa justiça, ou melhor, a justiça dele (Is 54.7): que somente Deus é justo e nós somos pecadores aceitos por ele. A justiça de Deus é o próprio Cristo (1Co 1.30). Cristo, porém, é “Deus conosco”, “Emanuel” (Is 7.14), “SENHOR, Justiça Nossa” (Jr 33.16).

A proclamação da morte de Cristo por nós é a pregação da justificação. A incorporação no corpo de Cristo, isto é, em sua morte e em sua ressurreição, é o batismo. Assim como Cristo morreu de uma vez por todas, também de uma vez por todas nós recebemos o batismo e a justificação. São, no sentido mais rigoroso, irrepetíveis. A única coisa que se pode repetir é a lembrança do que nos aconteceu de uma vez por todas, e isso não só pode ser repetido, mas tem de ser repetido diariamente. Contudo, a lembrança de algo que nos aconteceu sempre será diferente do que de fato aconteceu. Quem perde o fato já não pode recuperá-lo. A epístola aos Hebreus está certa em relação a isso (6.5s; 10.26s). “Ora, se o sal vier a ser insípido, como lhe restaurar o sabor?” (Mt 5.13). Para os batizados, isso significa: “Ou, porventura, ignorais...?” (Rm 6.3; 1Co 3.16; 6.19) e “assim também vós considerai-vos mortos para o pecado, mas vivos para Deus em Cristo Jesus” (Rm 6.11). Isso tudo aconteceu não só na cruz de Cristo, mas também a vocês. Vocês estão separados do pecado, morreram, estão justificados. Assim, Deus consumou sua obra.

Com a justiça, estabeleceu seu santuário na terra. O nome desse santuário é Cristo, corpo de Cristo. A separação do pecado realizou-se pela morte do pecador em Jesus Cristo. Deus tem uma Igreja justificada do pecado. É a Igreja dos discípulos de Jesus, a comunhão dos santos. São aceitos em seu santuário, eles próprios são seu santuário, seu templo. São retirados do mundo e vivem num espaço novo e próprio em meio ao mundo.

A partir daí, no Novo Testamento, os cristãos passam a ser chamados apenas de “os santos”. Poderiam ser chamados de “os justos”, mas esse nome não consegue descrever toda a grandeza da dádiva recebida.

É um termo relacionado ao acontecimento singular do batismo e da justificação. De fato, a lembrança desse acontecimento deve ser repetida todos os dias. Também é verdade que os santos continuam sendo pecadores justificados. No entanto, juntamente com a dádiva única do batismo e da justificação, com a lembrança diária dessa dádiva, na morte de Cristo nos é garantida a preservação da vida dos justificados até o último dia. Essa vida, assim preservada, é a santificação. As duas dádivas têm o mesmo fundamento, Jesus Cristo, o crucificado (1Co 1.2; 6.11), e o mesmo conteúdo, a comunhão com Cristo.

Ambas estão relacionadas entre si de maneira inseparável. Todavia, não são a mesma coisa. Enquanto a justificação atribui ao cristão a obra consumada de Deus, a santificação lhe é a promessa da ação de Deus hoje e no futuro. Enquanto a justificação integra o crente na comunhão de Jesus Cristo pela morte única, a santificação lhe garante a permanência ali, em Cristo, na Igreja. Enquanto na justificação o que está em primeiro plano é a posição do ser humano em relação à lei, na santificação o que é decisivo é o rompimento com o mundo, até a volta de Cristo. Enquanto a justificação incorpora o indivíduo à Igreja, a santificação preserva a Igreja com todos os seus membros. A justificação livra o crente de seu passado pecaminoso, a santificação o acolhe em Cristo, para perseverar na fé e crescer em amor. A relação entre justificação e santificação pode ser comparada com a relação entre criação e preservação. A justificação é a nova criação do ser humano, a santificação é sua preservação até o dia de Jesus Cristo. Na santificação cumpre-se a vontade de Deus: “Santos sereis, porque eu, o SENHOR, vosso Deus, sou santo” (Lv 19.2) e “eu, o SENHOR que vos santifico, sou santo” (Lv 21.8). Esse cumprimento se dá por Deus, o Espírito Santo. Nele se consuma a obra de Deus no ser humano. Ele é o “selo” com que os crentes são selados como propriedade de Deus até o dia da redenção. Assim como antes estávamos encerrados sob a lei (Gl 3.23), como que numa prisão, agora os crentes estão resguardados “em Cristo”, selados com o selo de Deus, o Espírito Santo. Ninguém poderá violar esse selo. Foi o próprio Deus que o fechou, e ele tem a chave em suas mãos. Isso significa que Deus tomou posse total daqueles que, em Cristo, conquistou. O círculo se fecha. No Espírito Santo, o ser humano foi feito propriedade de Deus.

Separada do mundo por um selo que não pode ser quebrado, a Igreja dos santos espera a libertação final.

Como trem fechado viajando por terras estrangeiras, assim a Igreja percorre o mundo. Como a arca de Noé tinha de ser calafetada “com betume por dentro e por fora” (Gn 6.14), assim o caminho da Igreja selada se assemelha à viagem da arca pelas águas do dilúvio. O alvo do selo é a salvação, a redenção (Ef 4.30; 1.14; 1Ts 5.23; 1Pe 1.5 etc.) na vinda de Cristo. O penhor que garante aos que estão selados esse alvo é o próprio Espírito Santo.

A fim de sermos para louvor da sua glória, nós, os que de antemão esperamos em Cristo; em quem também vós, depois que ouvistes a palavra da verdade, o evangelho da vossa salvação, tendo nele também crido, fostes selados com o Santo Espírito da promessa; o qual é o

penhor da nossa herança, até ao resgate da sua propriedade, em louvor da sua glória.

Efésios 1.12-14 É isto a santificação da Igreja: estar separada por Deus do que não é santo, do que é pecado. É assim que é santificada: pelo selo que nela é colocado, tornando-se propriedade de Deus, a morada de Deus na terra, o lugar de onde emanam juízo e reconciliação para todo o mundo. Este é o alvo da santificação: que os cristãos sejam orientados e guardados exclusivamente para a volta de Cristo, sempre indo ao encontro dela.

Para a Igreja dos santos, isso tem tríplice significado: primeiro, sua santificação será comprovada numa clara separação do mundo; segundo, sua santificação consistirá num andar de modo digno do santuário de Deus; terceiro, sua santificação ficará oculta na espera pelo dia de Jesus Cristo.

Em primeiro lugar, portanto, a santificação só existe na Igreja visível. A visibilidade da Igreja é característica decisiva da santificação. A reivindicação de espaço no mundo e a consequente separação entre mundo e Igreja confirmam que a Igreja está no estado de santificação. O selo do Espírito Santo sela a Igreja para fora do mundo. No poder desse selo, a Igreja deve pôr em prática a reivindicação de Deus sobre o mundo inteiro e, ao mesmo tempo, exigir para si um espaço no mundo, estabelecendo limites claros entre ela e o mundo. Uma vez que a Igreja é a cidade edificada sobre o monte — pólis (Mt 5.14)

— pelo próprio Deus nesta terra e, por isso, é a propriedade selada de Deus, seu caráter “político” é aspecto inerente à sua santificação. A “ética política” da Igreja se fundamenta unicamente na santificação, isto é, no fato de o mundo ser mundo, e a Igreja, Igreja, e todavia também no fato de a Palavra de Deus partir da Igreja para o mundo, proclamando que a terra e tudo que nela há pertencem ao Senhor. Reside aí o caráter “político” da Igreja. A santificação pessoal que não leva em conta essa separação entre Igreja e mundo, que não torne isso publicamente visível, confunde a santificação da Igreja conquistada na morte de Cristo pelo selo de Deus com os desejos piedosos da carne religiosa. É o orgulho enganador e a falsa ambição espiritual do velho ser humano que busca a santificação fora da comunhão visível dos irmãos. É o desprezo ao corpo de Cristo como Igreja visível dos pecadores justificados, escondido atrás da humildade da espiritualidade individual. É o desprezo ao corpo de Cristo, porque Cristo de bom grado toma sobre si minha carne de maneira visível e a leva para a cruz. É o desprezo à comunidade, por querer ser santo só para si, sem a comunhão dos irmãos. É o desprezo aos pecadores, pois, de forma pecaminosa, afasto-me de minha Igreja na busca de uma santidade escolhida por minha própria vontade.

Buscar a santificação fora da Igreja visível é declarar a si mesmo santo.

A santificação pelo selo do Espírito Santo sempre põe a Igreja em estado de luta. Trata-se, em essência, da luta por esse selo, para que ele não seja quebrado nem pelos de fora nem pelos de dentro, para que o mundo não queira ser Igreja, nem a Igreja queira ser mundo. A luta da Igreja pelo espaço na terra concedido ao corpo de Cristo é sua santificação. A separação entre mundo e Igreja e entre Igreja e mundo é a luta santa da Igreja pelo santuário de Deus na terra.

O santuário só existe na Igreja visível. Contudo — e aqui se trata do segundo ponto da santificação —, a Igreja vive no santuário de Deus exatamente por estar separada do mundo, e na Igreja ainda vive um pedaço do mundo. Por isso os cristãos devem andar de modo digno de sua vocação e do evangelho em

todos os aspectos da vida (Ef 4.1; Fp 1.27; Cl 1.10; 1Ts 2.12); contudo, só serão dignos se lembrarem diariamente do evangelho do qual vivem. “Mas vós vos lavastes, mas fostes santificados, mas fostes justificados” (1Co 6.11). A santificação é isto: viver dessa lembrança todos os dias. Esta é a mensagem, portanto, da qual devem ser dignos: o mundo e a carne morreram, foram crucificados e mortos com Cristo na cruz e no batismo; o pecado já não pode governar, pois seu poder já está destruído; por isso, não é mais possível que o cristão peque. “Todo aquele que é nascido de Deus não vive na prática de pecado” (1Jo 3.9).

O rompimento já se realizou. A vida “passada” chegou ao fim (Ef 4.22). “Pois, outrora, éreis trevas, porém, agora, sois luz no Senhor” (Ef 5.8). Antes praticavam as obras vergonhosas e infrutíferas da carne e das trevas; agora, o Espírito produz o fruto da santificação.

Por isso os cristãos já não podem ser chamados de “pecadores”, isto é, pessoas que vivem sob o poder do pecado ( hamartoloi — cf. como única exceção e testemunho pessoal 1Tm 1.15); ao contrário, no passado, eram pecadores, ímpios, inimigos (Rm 5.8,19; Gl 2.15,17), mas agora são os santos por causa de Cristo. Como santos, são sempre lembrados e encorajados a serem o que são. Não se exige deles o impossível, ou seja, que pecadores sejam santos — isso seria um retorno às obras e uma blasfêmia contra Cristo —, mas que os santos sejam santos, pois são santificados em Jesus Cristo pelo Espírito Santo.

A vida dos santos se destaca de um cenário sombrio. As obras obscuras da carne são totalmente expostas pela clara luz da vida no Espírito. “Prostituição, impureza, lascívia, idolatria, feitiçarias, inimizades, porfias, ciúmes, iras, discórdias, dissensões, facções, inveja, bebedices, glutonarias e coisas semelhantes” (Gl 5.19-21). Isso tudo não tem mais lugar na Igreja de Cristo. Isso tudo está abolido, julgado na cruz e acabado. Desde o princípio, os cristãos recebem esta advertência: “não herdarão o reino de Deus os que tais coisas praticam” (Gl 5.21; Ef 5.5; 1Co 6.9; Rm 1.32). Esses pecados nos separam da salvação eterna. Se um desses vícios for descoberto no seio da Igreja, será motivo para exclusão da comunhão da Igreja (1Co 5.1ss).

É fácil perceber a concordância na enumeração de pecados nos chamados catálogos de vícios. Quase sem exceção, a prostituição ( porneia) aparece em primeiro lugar como sendo incompatível com a nova vida do cristão. Em seguida, geralmente vem a avareza ( pleonexia, 1Co 5.10; 6.10; Ef 4.19; 5.3; Cl 3.5; 1Ts 4.4ss), que pode ser resumida junto com a prostituição nos termos “impureza” e “idolatria” (1Co 5.10; 6.9; Gl 5.3,19; Cl 3.5,8). Seguem, então, os pecados contra o amor ao próximo e da bebedice e glutonaria.1 Sem dúvida, não é por acaso que a prostituição está no topo da lista. A causa disso não está nas circunstâncias específicas da época, mas na natureza especial desse pecado. Na prostituição, o pecado de Adão é revivido: querer ser como Deus, querer ser criador da vida, querer governar, e não servir. Na prostituição, o ser humano ultrapassa os limites estabelecidos por Deus e atenta contra as criaturas de Deus. Esse era o pecado de Israel, que repetidas vezes negava a fidelidade de seu Senhor, prostituindo-se com os ídolos (1Co 10.7), agarrando-se a eles. A prostituição é, antes de tudo, um pecado contra Deus, o Criador. Para o cristão, porém, a prostituição é, de modo especial, pecado contra o próprio corpo de Cristo, pois o corpo do cristão é membro de Cristo e pertence apenas a ele. A união corporal com a prostituta desfaz a comunhão com Cristo. Quem rouba seu corpo de Cristo para oferecê

lo ao pecado separou-se de Cristo. A prostituição é pecado contra o próprio corpo. O cristão deve saber que seu corpo também é santuário do Espírito Santo que nele habita (1Co 6.13ss). A comunhão do corpo do cristão com Cristo é tão estreita que o cristão não pode igualmente pertencer ao mundo com seu corpo.

A comunhão do corpo de Cristo proíbe o pecado contra o próprio corpo. A ira de Deus recai sobre aquele que se prostitui (Rm 1.29; 1Co 1.5s; 7.2; 10.7; 2Co 12.11,21; Hb 12.16; 13.4). O cristão é casto e dedica seu corpo inteiramente ao serviço do corpo de Cristo. Sabe que seu corpo também sofreu e morreu com a Paixão e a morte do corpo de Cristo na cruz. A comunhão com o corpo crucificado e glorificado de Cristo livra o cristão da indisciplina da vida corporal. Nessa comunhão, os ardentes desejos corporais vão desaparecendo diariamente. Na prática da castidade e da abstinência, o cristão dispõe de seu corpo exclusivamente para a edificação do corpo de Cristo, a Igreja. Ele também faz isso no casamento e, assim, transforma seu matrimônio numa parte do corpo de Cristo.

A prostituição está intimamente associada à cobiça. As duas têm em comum a insaciabilidade do desejo, o que também leva o cobiçoso a se entregar ao mundo. “Não cobiçarás”, diz o mandamento de Deus. O que se prostitui e o que cobiça nada mais são que concupiscência. O desejo do prostituto é a posse do outro. O desejo do cobiçoso é a posse das riquezas do mundo. O cobiçoso quer dominar e ter poder, mas torna-se escravo do mundo ao qual se apegou seu coração. A prostituição e a cobiça levam o ser humano a se relacionar com o mundo de tal maneira que se torna impuro e imundo. A prostituição e a cobiça são idolatria, pois nelas o coração do indivíduo já não pertence a Deus e a Cristo, mas aos objetos de desejo do próprio mundo.

Aquele, porém, que cria seu próprio Deus e seu próprio mundo, que faz de seus desejos o seu deus, terá de odiar o irmão que está obstruindo o caminho de suas vontades. Brigas, ódio, inveja e homicídio nascem todos da própria cobiça. “De onde procedem guerras e contendas que há entre vós? De onde, senão dos prazeres que militam na vossa carne?” (Tg 4.1). O prostituto e o cobiçoso não podem conhecer o amor fraternal. Vivem das trevas de seu próprio coração. Se pecam contra o corpo de Cristo, pecam contra o irmão. A prostituição e o amor fraternal não podem conviver por causa do corpo de Cristo. O

corpo que não está mais em comunhão com o corpo de Cristo não poderá servir ao próximo. A orgia em bebedices e glutonarias é consequência do desprezo ao próprio corpo e ao corpo do irmão. Aqueles que desprezam o corpo entregam-se à carne, e o “deus deles é o ventre” (Fp 3.19; Rm 16.18). A feiura desse pecado consiste em que a carne morta quer cuidar de si mesma, envergonhando o ser humano inclusive em sua aparência externa. Quem comete esse pecado não tem parte no corpo de Cristo.

Para a Igreja, o mundo e todos os seus vícios pertencem ao passado. Ela se separou dos que praticam tais coisas, e deve continuar separada (1Co 5.9ss). Pois que comunhão pode haver entre a luz e as trevas?

(2Co 6.14). Lá estão “as obras da carne” (Gl 5.19ss); aqui, “o fruto da luz” (Ef 5.9). O que é o “fruto”? Há muitas “obras” da carne, mas um só “fruto” da luz. As obras são feitas por mãos humanas; o fruto nasce e cresce sem que a árvore se dê conta. As obras são coisas mortas; o fruto está vivo e contém sementes que produzirão novos frutos. As obras podem existir por si sós; o fruto não existirá sem a árvore. O fruto é sempre o que existe de mais maravilhoso, é algo já realizado, que não resulta da vontade, mas que sempre cresce. O fruto do Espírito é dádiva realizada exclusivamente por

Deus. Quem o carrega sabe tão pouco dele quanto a árvore sabe de seu fruto. Conhece tão somente a força daquele do qual ele vive. Aqui não há glória, mas apenas a união cada vez mais íntima com a origem, com Cristo. Os próprios santos não conhecem o fruto da santificação que carregam. A mão esquerda não sabe o que a direita faz. Se quisessem saber algo, se quisessem cair na autocontemplação, já teriam se desligado da raiz, e o tempo de frutificar já seria passado. “Mas o fruto do Espírito é: amor, alegria, paz, longanimidade, benignidade, bondade, fidelidade, mansidão, domínio próprio” (Gl 5.22-23). Junto com a santificação da Igreja, ocorre, em plena luz, a santificação do indivíduo. A fonte, no entanto, é uma só: a comunhão com Cristo, a comunhão no mesmo corpo. Assim como a separação do mundo só se torna visível na luta contínua, também com a santificação pessoal consiste na luta do espírito contra a carne. Os santos veem, em sua vida, apenas conflito, pobreza, fraqueza e pecado, e quanto mais amadurecem na santificação, mais se reconhecem como derrotados, como os que estão morrendo para a carne. “E os que são de Cristo Jesus crucificaram a carne, com as suas paixões e concupiscências” (Gl 5.24). Ainda vivem na carne e, por isso mesmo, toda a vida deles deve ser uma fé no Filho de Deus que neles iniciou sua vida (Gl 2.20). O cristão morre dia após dia (1Co 15.31), e mesmo que sua carne sofra e venha a perecer, “contudo, o nosso homem interior se renova de dia em dia” (2Co 4.16). O morrer dos santos para a carne tem como único fundamento o fato de a vida de Cristo ter se iniciado neles por meio do Espírito Santo. Os santos morrem de Cristo e da vida dele. Já não precisam procurar seus próprios sofrimentos, com os quais iriam novamente confirmar-se em sua carne. Cristo é seu morrer e viver diários. Por isso, eles podem alegrar-se plenamente no fato de a pessoa nascida de Deus não mais poder pecar, de o pecado já não ter domínio sobre eles e de terem morrido para o pecado e viverem no Espírito. 2

“Agora, pois, já nenhuma condenação há para os que estão em Cristo Jesus” (Rm 8.1). Em seus santos Deus se agrada, pois ele próprio é a força que move a luta e o morrer deles, fazendo brotar o fruto da santificação, e da existência desse fruto os santos devem ter certeza, ainda que lhes permaneça bem oculto. Todavia, não é possível que, encobertos pela mensagem do perdão, a prostituição, a cobiça, o homicídio e o ódio ao irmão continuem a atuar na Igreja. Também não é possível que o fruto da santificação permaneça oculto. Mas, quando ele for visível para todos, quando o mundo, ao olhar para a Igreja de Cristo, surpreender-se como nos primeiros anos da cristandade e disser: “Vejam como se amam uns aos outros!”, então os santos contemplarão unicamente, sem desviar o olhar, aquele a quem pertencem e, alheios a qualquer bem que façam, pedirão perdão por seus pecados. Esses mesmos cristãos, que a si mesmos afirmaram que o pecado já não tem poder sobre eles e que os crentes já não pecam, confessarão: Se dissermos que não temos pecado nenhum, a nós mesmos nos enganamos, e a verdade não está em nós. Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça. Se dissermos que não temos cometido pecado, fazemo-lo mentiroso, e a sua palavra não está em nós. Filhinhos meus, estas coisas vos escrevo para que não pequeis. Se, todavia, alguém pecar, temos Advogado junto ao Pai, Jesus Cristo, o Justo.

1João 1.8—2.1

Pois foi assim que o próprio Senhor os ensinou a orar: “E perdoa-nos as nossas dívidas” (Mt 6.12). Ele os exortou a jamais se cansarem de perdoar uns aos outros (Ef 4.32; Mt 18.21ss). À medida que se perdoam mutuamente em amor fraternal, os cristãos criam espaço para o perdão de Cristo em sua comunhão. Não veem mais o outro como aquele que os ofendeu, mas como aquele para quem Cristo conquistou o perdão na cruz. Eles se reconhecem na condição de santificados pela cruz de Jesus. Sob essa cruz, pensamentos, palavras e corpo são santificados por meio de seu morrer diário. Sob essa cruz, cresce o fruto da santificação.

A comunhão dos santos não é a comunhão “ideal” de pessoas perfeitas e sem pecado. Não é a comunhão dos puros que já não dão ao pecador a oportunidade de se arrepender. Ao contrário, é a comunhão que se mostra digna do evangelho do perdão proclamando verdadeiramente o perdão de Deus, que nada tem a ver com perdão autoministrado; é a comunhão dos que de fato experimentaram a graça preciosa de Deus e que andam de modo digno do evangelho, não desperdiçando nem descartando essa graça.

Em outras palavras, na comunhão dos santos o perdão só pode ser pregado quando também o arrependimento é pregado, quando o evangelho é pregado junto com a lei, quando os pecados não apenas são perdoados, mas são perdoados sob a condição de serem retidos. Esta, portanto, é a vontade do Senhor: que o santuário do evangelho não seja lançado aos cães, mas que o evangelho somente possa ser pregado sob a proteção da pregação para o arrependimento. A Igreja que não reconhece o pecado como pecado não terá credibilidade quando for perdoar pecados. Tal Igreja comete pecado contra o santuário e vive de modo indigno do evangelho. É ímpia, pois desperdiça o perdão precioso do Senhor. Não basta lamentar genericamente a pecaminosidade dos seres humanos, mesmo nas boas obras. Esse tipo de pregação não abre espaço para o arrependimento. O que se deve fazer é apontar, punir e julgar o pecado concreto. Esse é o uso correto do poder das chaves (Mt 16.19; 18.18; Jo 20.23) concedido à Igreja pelo Senhor e tão enfatizado pelos reformadores. Essa chave de ligar e reter pecados também deve ser usada na Igreja, em favor do santuário, dos pecadores e da própria Igreja. A prática da disciplina eclesiástica pertence a esse andar de modo digno da Igreja em nome do evangelho. Assim como a santificação produz a separação da Igreja em relação ao mundo, também deve causar o afastamento do mundo em relação à Igreja. Uma coisa sem a outra não seria legítimo nem verdadeiro. A Igreja separada do mundo tem de praticar a disciplina de seus membros em seu interior.

O propósito da disciplina eclesiástica não é a criação de uma Igreja de indivíduos perfeitos, mas unicamente a construção de uma Igreja de pessoas que, de fato, vivem sob a misericórdia perdoadora de Deus. A disciplina no interior da Igreja está a serviço da graça preciosa de Deus. O pecador que é membro da Igreja deve ser exortado e punido, para que ele não perca a salvação e o evangelho não caia em descrédito. Assim, apenas quem se arrepende e confessa sua fé em Jesus Cristo pode receber a graça do batismo. Também, apenas quem “sabe discernir” (1Co 11.29) o verdadeiro corpo e sangue de Jesus Cristo para perdão dos pecados de outra ceia simbólica qualquer é que pode receber a graça da comunhão. Além disso, tem de prestar conta de seu conhecimento da fé, tem de “examinar” a si mesmo ou submeter-se ao exame de um irmão, para que se possa comprovar se ele, de fato, deseja receber o corpo

e sangue de Cristo. Depois do interrogatório sobre a fé vem a confissão, na qual o cristão busca e encontra a certeza de que seus pecados foram perdoados. A confissão é o auxílio que Deus concede ao pecador para preveni-lo do perigo do autoengano e da autoministração do perdão. Na confissão dos pecados perante o irmão, a carne morre e, com ela, o orgulho. Com Cristo a carne é entregue à vergonha e à morte, e pela palavra do perdão emerge um novo ser humano, que passa a viver sob a misericórdia de Deus. O ato da confissão, portanto, é parte integrante da vida dos santos. É uma dádiva graciosa de Deus, e seu mau uso será punido. Na confissão, o cristão recebe a graça preciosa de Deus. Nela o cristão é conformado com a morte de Cristo. “Portanto, quando lhes recomendo a confissão, nada mais faço que exortá-los a serem cristãos” (Lutero, Catecismo Maior).

A disciplina se faz presente em todos os espaços da vida eclesiástica. Na Igreja, há uma série bem fundamentada de etapas no serviço da misericórdia. A origem de qualquer exercício disciplinar é a pregação da palavra de acordo com as duas chaves. Ela não se limita às reuniões formais da Igreja, pois em nenhum momento o ministro está dispensado de suas tarefas. “Prega a palavra, insta, quer seja oportuno, quer não, corrige, repreende, exorta com toda a longanimidade e doutrina” (2Tm 4.2). Esse é o início da disciplina eclesiástica. Aqui, porém, é preciso levar em conta que apenas os pecados públicos podem ser punidos. “Os pecados de alguns homens são notórios e levam a juízo, ao passo que os de outros só mais tarde se manifestam” (1Tm 5.24). Com isso, a disciplina eclesiástica nos poupa da punição do juízo final.

Se, porém, o exercício da disciplina fracassar já nessa primeira etapa, isto é, no serviço pastoral diário do encarregado dessa tarefa, tudo o mais será posto em dúvida. Até porque a segunda etapa diz respeito exatamente ao aconselhamento fraternal dos membros da igreja: “Instruí-vos e aconselhai-vos mutuamente” (Cl 3.16; 1Ts 5.11,14). A esse aconselhamento também pertence a consolação dos desanimados, o amparo aos fracos, a longanimidade para com todos (1Ts 5.14). Só assim é possível proteger a Igreja das tentações diárias e da apostasia.

Onde não houver esse serviço fraternal mútuo, dificilmente se alcançará a terceira etapa. Se, porém, um irmão cometer pecado público de palavra ou de ação, a Igreja deve ser forte para abrir contra ele processo disciplinar formal. Esse também é um longo caminho. De imediato, é necessário que a Igreja se separe do pecador. “Nem vos associeis com ele” (2Ts 3.14), “afastai-vos deles” (Rm 16.17), “com esse tal, nem ainda comais” (a Ceia do Senhor?, 1Co 5.11), “foge também destes” (2Tm 3.5; 1Tm 6.4). “Nós vos ordenamos, irmãos, em nome do Senhor Jesus Cristo [!], que vos aparteis de todo irmão que ande desordenadamente e não segundo a tradição que de nós recebestes” (2Ts 3.6). O objetivo é que o pecador

“fique envergonhado” (2Ts 3.14), de modo que a Igreja possa reconquistá-lo. Sem dúvida, esse afastamento do pecador implica também a suspensão temporária de suas atividades na Igreja. Tal afastamento, porém, não significa a exclusão imediata de qualquer comunhão com esse pecador notório. Ao contrário, a Igreja, mesmo afastando-se do pecador, deve continuar a aconselhá-lo: “Todavia, não o considereis por inimigo, mas adverti-o, como irmão” (2Ts 3.15). O pecador continua nosso irmão, única razão pela qual ele será disciplinado e aconselhado pela Igreja. É a misericórdia fraternal que motiva o exercício da disciplina. Com mansidão devem ser punidos os que mostram resistência, e com bondade

devem ser suportados os que praticam o mal, “na expectativa de que Deus lhes conceda não só o arrependimento para conhecerem plenamente a verdade, mas também o retorno à sensatez, livrandose eles dos laços do diabo, tendo sido feitos cativos por ele para cumprirem a sua vontade” (2Tm 2.25-26).

O método de aplicação da disciplina deve variar, mas o objetivo será sempre o mesmo: levar o pecador ao arrependimento e à reconciliação. Se for possível manter o pecado em segredo entre você e o pecador, não deve ser exposto publicamente. Assim, você pode puni-lo em particular e chamá-lo ao arrependimento, e assim “ganhaste a teu irmão”. Mas, se ele não o ouvir e permanecer endurecido, ainda não deve tornar público o pecado dele. Em vez disso, procure uma ou duas testemunhas (Mt 18.15s).

Esse testemunho é necessário por dois motivos: primeiro, para comprovar se de fato houve pecado —

isto é, se não houver provas e o membro negar o fato, o caso será decidido por Deus; pois os irmãos são testemunhas, e não inquisidores! —; segundo, para se comprovar que o pecador endureceu o coração e não quis se arrepender. A finalidade de manter o exercício da disciplina em segredo é facilitar o arrependimento do pecador. Se ainda assim ele não ouvir, ou acontecer de seu pecado tornar-se público na Igreja, então toda a Igreja deve chamá-lo ao arrependimento e aconselhá-lo (Mt 18.17; cf. 2Ts 3.14).

Se o pecador exerce cargo eclesiástico, só deverá ser acusado sob o depoimento de duas ou três testemunhas (1Tm 5.19). “Quanto aos que vivem no pecado, repreende-os na presença de todos, para que também os demais temam” (1Tm 5.20). Nesse caso, cabe à Igreja juntar-se ao encarregado na administração das chaves. É necessário que a sentença pública seja executada por representantes da Igreja e pelo encarregado. “Conjuro-te, perante Deus, e Cristo Jesus, e os anjos eleitos, que guardes estes conselhos, sem prevenção, nada fazendo com parcialidade” (1Tm 5.21), pois é a sentença do próprio Deus que é imposta ao pecador. Se o pecador se arrepender com sinceridade e confessar seu pecado publicamente, recebe o perdão de todos os seus pecados em nome de Deus (cf. 2Co 2.6ss); mas, se persistir no pecado, a Igreja deve, em nome de Deus, reter-lhe o perdão. Isso, no entanto, significa a exclusão de qualquer comunhão da Igreja. “Considera-o como gentio e publicano” (Mt 18.17). “Em verdade vos digo que tudo o que ligardes na terra terá sido ligado nos céus, e tudo o que desligardes na terra terá sido desligado nos céus. [...] Porque, onde estiverem dois ou três reunidos em meu nome, ali estou no meio deles” (Mt 18.18,20). A exclusão da Igreja apenas confirma o que já é realidade, isto é, que a pessoa que não se arrepende “por si mesma está condenada” (Tt 3.11). Não é a Igreja que condena esse pecador, é ele mesmo que anuncia a própria sentença. Paulo chama essa exclusão total de “entregar-se a Satanás” (1Co 5.5; 1Tm 1.20). O culpado é devolvido ao mundo onde Satanás reina e promove a morte (é possível deduzir de 1Tm 1.20; 2Tm 2.17; 4.15 que, ao contrário de At 5, não se trata de pena de morte). O culpado é excluído da comunhão do corpo de Cristo, porque ele mesmo se separou. Já não tem direito algum na Igreja. Contudo, mesmo essa atitude extrema ainda está a serviço da salvação do pecador, “a fim de que o espírito seja salvo no Dia do Senhor [Jesus]” (1Co 5.5), “para serem castigados, a fim de não mais blasfemarem” (1Tm 1.20). O objetivo da disciplina eclesiástica é a volta do pecador à Igreja ou a própria salvação. É uma ação de efeito pedagógico. Assim como certamente a sentença da Igreja tem validade eterna se o pecador não se arrepender, também é certo que essa sentença,

que toma do pecador a salvação, nada mais é que a última oferta possível de comunhão com a Igreja e de salvação. 3 4 Assim, a santificação da Igreja é comprovada em seu andar de modo digno do evangelho. Ela produz o fruto do Espírito e vive sob a disciplina da Palavra. Em tudo, porém, continua a ser a Igreja daqueles cuja santificação está somente em Cristo (1Co 1.30) e que seguem ao encontro do dia de sua volta.

Com isso chegamos à terceira condição da santificação verdadeira. Toda a santificação visa à sobrevivência no dia de Jesus Cristo. “Segui a paz com todos e a santificação, sem a qual ninguém verá o Senhor” (Hb 12.14). A santificação está sempre relacionada com o fim. Seu objetivo não é habilitar a existência perante o juízo do mundo ou do próprio juízo, mas perante o Senhor. Aos próprios olhos e aos olhos do mundo, talvez sua santidade pareça pecado, sua fé pareça falsa, seu amor pareça endurecimento, e sua disciplina pareça fraca. Sua verdadeira santidade permanece oculta. O próprio Cristo, porém, prepara para si uma Igreja que possa existir diante dele.

Maridos, amai vossa mulher, como também Cristo amou a igreja e a si mesmo se entregou por ela, para que a santificasse, tendo-a purificado por meio da lavagem de água pela palavra, para a apresentar a si mesmo igreja gloriosa, sem mácula, nem ruga, nem coisa semelhante, porém santa e sem defeito.

Efésios 5.25-27 (cf. Cl 1.22; Ef 1.4)

Somente a Igreja santificada pode permanecer perante Cristo; aquele que reconciliou os inimigos de Deus e que deu sua vida pelo ímpios o fez para que sua Igreja fosse santa até sua volta. Isso acontece pelo selo do Espírito Santo, pelo qual os santos são selados no santuário da Igreja e guardados até o dia de Jesus Cristo. Naquele dia, não serão encontrados impuros e envergonhados diante dele, mas, em espírito, alma e corpo, santos e irrepreensíveis (1Ts 5.23). Ou não sabeis que os injustos não herdarão o reino de Deus? Não vos enganeis: nem impuros, nem idólatras, nem adúlteros, nem efeminados, nem sodomitas, nem ladrões, nem avarentos, nem bêbados, nem maldizentes, nem roubadores herdarão o reino de Deus. Tais fostes alguns de vós; mas vós vos lavastes, mas fostes santificados, mas fostes justificados em o nome do Senhor Jesus Cristo e no Espírito do nosso Deus.

1Coríntios 6.9-11

Ninguém desafia, portanto, a graça de Deus, querendo permanecer no pecado! Apenas a Igreja santificada escapará da ira no dia do Senhor Jesus Cristo, e ele julgará de acordo com as obras, sem fazer acepção de pessoas. A obra de cada um será revelada, e a cada um ele retribuirá “segundo o bem ou o mal que tiver feito por meio do corpo” (2Co 5.10; Rm 2.6ss; Mt 16.26). O que não tiver sido julgado aqui na terra não ficará oculto no dia do juízo; tudo virá à luz. Quem permanecerá? Aquele que for encontrado em boas obras. Não são os ouvintes que serão justificados, mas os que praticam a lei (Rm 2.13). Conforme a palavra do Senhor, só os que fazem a vontade de seu Pai no céu entrarão em seu reino.

Porque seremos julgados de acordo com nossas obras, o mandamento é façamos a “boa obra”. O medo das boas obras, com o qual queremos justificar nossas obras más, é alheio à Bíblia. Também não existe na Bíblia a oposição entre fé e boas obras, como se as boas obras destruíssem a fé; ao contrário, é a obra

má que impede e destrói a fé. A graça e a prática andam juntas. Não há fé sem boas obras, como não há boas obras sem fé.5 Pela salvação, o cristão precisa praticar boas obras, pois quem for encontrado em obras más não verá o reino de Deus. Por isso, a boa obra é o alvo do cristão. Pois nesta vida a única coisa que importa é como o ser humano permanecerá no juízo final. E, uma vez que cada um será julgado de acordo com suas obras, é essencial a preparação do cristão para as boas obras. Assim, a nova criação do ser humano em Cristo também tem as boas obras por propósito. “Porque pela graça sois salvos, mediante a fé; e isto não vem de vós; é dom de Deus; não de obras, para que ninguém se glorie. Pois somos feitura dele, criados em Cristo Jesus para boas obras, as quais Deus de antemão preparou para que andássemos nelas” (Ef 2.8-10; cf. 2Tm 2.21; 3.17; Tt 1.16; 3.1,8,14). Tudo está muito claro. O alvo é a produção da boa obra exigida por Deus. A lei de Deus continua válida e tem de ser cumprida (Rm 3.31). Ela é cumprida por meio das boas obras. Existe, todavia, apenas uma boa obra, a obra de Deus em Jesus Cristo. Somos salvos pela obra do próprio Deus em Cristo Jesus, e não por nossas obras. Por isso, jamais poderemos nos gloriar por obras nossas, pois nós mesmos somos obra dele. Para isso, porém, somos feitos novas criaturas em Cristo, para que nele alcancemos as boas obras.

Contudo, todas as nossas boas obras são apenas as obras do próprio Deus, para as quais ele nos preparou de antemão. Portanto, boas obras são ordenadas por causa da salvação, e boas obras são sempre apenas as obras que o próprio Deus realiza em nós. São dádiva dele. Somos nós, porém, que devemos andar em boas obras e praticá-las a todo instante, sabendo que nunca poderemos subsistir ao juízo de Deus com nossas obras, mas que, na fé, nos agarramos a Cristo somente e à sua obra. Pois Deus promete aos que estão em Cristo Jesus boas obras, com as quais poderão subsistir, preservando-os na santificação até o dia de Jesus. Mas só podemos crer nessa promessa de Deus por meio de sua Palavra, e podemos andar e viver nas boas obras que ele nos preparou.

Assim, nossas boas obras ficam totalmente ocultas aos nossos próprios olhos. Nossa santificação nos permanecerá invisível até o dia em que tudo será revelado. Quem quer ver alguma coisa aqui, quem já quer ser revelado a si mesmo e não quer esperar com paciência, esse já tem sua recompensa.

Especialmente quando pensamos estar visivelmente progredindo na santificação, quando queremos avançar ainda mais, faz-se ainda mais necessário o chamado ao arrependimento e o reconhecimento de que nossas obras são inteiramente pecaminosas. Contudo, somos sempre chamados a uma alegria cada vez maior no Senhor. Só Deus conhece nossas boas obras; nós conhecemos apenas a boa obra dele, ouvimos seu mandamento, vivemos em sua graça, andamos em seu mandamento e — pecamos. E assim deve ser, de modo que a nova justiça, a santificação, a luz que deve brilhar, tudo nos permaneça oculto. A mão esquerda não sabe o que a direita faz. Cremos nisso, e estamos convictos de que “aquele que começou boa obra em vós há de completá-la até ao Dia de Cristo Jesus” (Fp 1.6). Naquele dia, o próprio Cristo nos revelará as boas obras que não conhecíamos. Mesmo sem saber, nós lhe demos comida, bebida e roupas e o visitamos; mesmo sem saber, nós o rejeitamos. Haverá grande espanto, e reconheceremos que não são nossas obras que aí subsistem, mas a obra que Deus, a seu tempo, realizou através de nós, sem qualquer esforço ou vontade de nossa parte (Mt 25.31ss). Mais uma vez, portanto, só nos resta desviar o olhar de nós mesmos e contemplar aquele que tudo realizou por nós e segui-lo.

O crente será justificado, o justificado será santificado, o santificado será salvo no juízo, não porque nossa fé, nossa justiça, nossa santificação, quanto ao que depende de nós, fosse algo que não pecado, mas sim porque Jesus Cristo “se nos tornou, da parte de Deus, sabedoria, e justiça, e santificação, e redenção, para que, como está escrito: aquele que se gloria, glorie-se no Senhor” (1Co 1.30).$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Bonhoeffer afirma que 'buscar a santificação fora da Igreja visível é declarar a si mesmo santo', e chama isso de orgulho disfarçado de humildade espiritual. De que forma a sua busca de uma vida santa às vezes vira um projeto particular, escondido da comunhão dos irmãos, em vez de algo vivido dentro e a favor da Igreja?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O capítulo descreve o fruto do Espírito como algo que cresce sem que a árvore perceba — 'os próprios santos não conhecem o fruto da santificação que carregam' — e diz que querer contemplar o próprio progresso já é desligar-se da raiz. Como você lida com a tentação de medir e admirar o seu próprio crescimento espiritual, e o que mudaria se simplesmente fixasse o olhar em Cristo?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Bonhoeffer defende a disciplina da Igreja como serviço da 'graça preciosa', em que o pecador disciplinado 'continua nosso irmão' e o alvo é sempre o arrependimento e a reconciliação, nunca a expulsão fria. Quando você precisa confrontar o pecado de alguém próximo, sua postura tende mais à condenação que rotula ou ao amor fraterno que busca restaurar?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 15 — A imagem de Cristo  (aula ordem = 17)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 17;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 15 — A imagem de Cristo$t$,
      17,
$conteudo$Porquanto aos que de antemão conheceu, também os predestinou para serem conformes à imagem de seu Filho, a fim de que ele seja o primogênito entre muitos irmãos.

Romanos 8.29

Esta é a grande e inacreditável promessa dada àqueles que ouviram o chamado ao discipulado de Jesus Cristo: eles serão iguais a Cristo. Serão conformes à sua imagem, como irmãos do Primogênito de Deus.

É o destino último do discípulo, que será conforme à imagem de Cristo. A imagem de Jesus Cristo que o discípulo sempre tem diante dos olhos e que ofusca todas as outras imagens penetra nele e o preenche, moldando-o de modo que o discípulo torna-se cada vez mais semelhante ao Mestre, e até igual a ele. A imagem de Jesus Cristo imprime a si mesma, na comunhão diária, na imagem dos discípulos. O discípulo não pode contemplar a imagem de Jesus de maneira distante e vazia, pois essa imagem irradia uma força transformadora. Quem se entrega por completo a Jesus Cristo deve e sempre quer carregar sua imagem.

Ele se torna filho de Deus ao lado de Cristo, o irmão invisível portador da mesma forma, da imagem de Deus.

Deus criou Adão à sua imagem. Em Adão, como ápice de sua criação, Deus buscava o prazer em sua própria imagem: “e eis que era muito bom”. Em Adão, Deus reconhecia a si mesmo. Esse é o mais indecifrável mistério do ser humano, desde o princípio. Ele é criatura e, ao mesmo tempo, deverá ser igual a seu Criador. O ser humano criado deve levar a imagem do Deus que não é criado. Adão é “como Deus”. Ele deve carregar consigo esse mistério — ser criatura de Deus e igual a Deus — em gratidão e obediência. Foi a mentira da serpente que chamou a atenção de Adão para o fato de que ele ainda teria de tornar-se igual a Deus, e isso por iniciativa e decisão próprias. Assim, Adão rejeitou a graça e escolheu agir por conta própria. Queria ele mesmo solucionar o mistério de sua existência — ser criatura de Deus e igual a Deus. Queria tornar-se, pela própria ação, aquilo que ele já era a partir de Deus. Foi essa a queda do homem. Adão tornou-se “como Deus” — sicut Deus — à sua própria maneira. Fez de si mesmo deus, e então já não tinha Deus. Dominava sozinho como deus-criador num mundo subjugado e sem Deus.

O enigma de sua existência, porém, continuou sem solução. O ser humano perdeu sua própria essência, a imagem de Deus, que lhe tinha sido dada pelo próprio Deus. Agora, vive alienado do destino de sua existência, isto é, ser criatura de Deus e igual a Deus. Em suma, o ser humano deixou de ser humano. Tem de viver sem poder viver. Essa é a contradição de nossa existência e a fonte de todas as nossas aflições.

Desde então, os orgulhosos filhos de Adão buscam reconstruir em si mesmos, pelos próprios esforços, a imagem perdida de Deus. No entanto, quanto mais se dedicam e se esforçam para reaver a imagem

perdida, quanto mais se convencem e se orgulham de um sucesso ilusório, mais se afastam de Deus. A forma disforme que imprimem a si mesmos, com base na imagem do deus que eles próprios inventaram, assume cada vez mais, sem que o saibam, a imagem de Satanás. A imagem que Deus, em sua graça, concedeu ao ser humano permanece perdida na terra.

Deus, no entanto, não desvia os olhos da criatura perdida. Quer, pela segunda vez, criar nela sua imagem. Quer, novamente, sentir prazer em sua criatura. Busca nela sua própria imagem, para poder amála. Contudo, não a encontrará de outra maneira senão assumindo ele próprio, por pura misericórdia, a imagem e a forma dos seres humanos perdidos. Deus terá de tornar-se igual à imagem do ser humano, porque o ser humano já não pode ser igual à imagem de Deus.

A imagem de Deus terá de ser recriada no ser humano. Trata-se aí de um todo. O propósito e a finalidade do ser humano não é que ele recupere conceitos corretos sobre Deus, nem que ele submeta suas ações à palavra de Deus, mas que seja restaurado, como um todo vivo, à imagem de Deus. Corpo, alma e espírito, toda a forma do ser humano deve carregar a imagem de Deus na terra. Deus só se agrada em sua imagem perfeita.

A imagem tem sua origem na vida, na viva imagem original. A forma se conforma à forma. Ou ela se conforma à forma do deus inventado pelo próprio ser humano, ou a viva e verdadeira forma de Deus conforma a forma humana à imagem de Deus. Deve haver uma transformação, uma “metamorfose” (Rm 12.1; 2Co 3.18), uma mudança de forma, para que o ser humano caído possa reaver a imagem de Deus. A pergunta é: como essa transformação do ser humano em imagem de Deus será possível?

Uma vez que o ser humano caído não pode reencontrar e reassumir a imagem de Deus, só há um caminho: o próprio Deus assume a forma humana e vem até o ser humano. O Filho de Deus, que subsiste em forma de Deus junto ao Pai, esvazia-se de sua forma e assume a forma de servo tornando-se semelhante aos seres humanos (Fp 2.5ss). A metamorfose da forma, impossível nos seres humanos, ocorre no próprio Deus. A imagem de Deus, que desde a eternidade ficara com Deus, assume a forma do ser humano caído e pecador. Deus envia seu próprio Filho em semelhança da carne pecaminosa (Rm 8.2s).

Deus envia seu Filho — aí está a única solução. Não bastava uma nova ideia nem uma religião melhor. Um Ser Humano vem ao ser humano. Cada ser humano carrega uma imagem. Seu corpo e sua vida manifestam-se visivelmente. Um ser humano não é uma simples palavra, um pensamento, uma vontade, mas sobretudo e sempre um ser humano, uma forma, uma imagem, um irmão. Assim, com ele não surge apenas uma nova maneira de pensar, querer e agir, mas uma nova imagem, uma nova forma. Em Jesus Cristo se fez presente, entre nós, a imagem de Deus, na forma de nossa vida humana perdida, em semelhança da carne pecaminosa. Em seu ensino, em suas ações, em seu viver e em seu morrer, sua imagem se revela. Nele Deus recriou sua imagem na terra. A encarnação, a palavra e a ação de Jesus, sua morte na cruz, tudo isso é parte inseparável dessa imagem. É uma imagem bem diferente da de Adão na glória original do paraíso. É a imagem daquele que se coloca no meio do mundo do pecado e da morte, que toma sobre si a angústia da carne humana, que se sujeita humildemente à ira e ao juízo de Deus contra os pecadores, que permanece em obediência à vontade de Deus no sofrimento e na morte, que nasceu na

pobreza, que convivia e fazia amizade com publicanos e pecadores, que na cruz foi rejeitado e abandonado por Deus e pela humanidade — esse é Deus na forma de ser humano, esse é o ser humano na nova imagem de Deus!

Sabemos, com certeza, que as marcas do sofrimento e as feridas da cruz são agora os sinais da graça no corpo do Cristo ressurreto e glorificado, que a imagem do crucificado vive para sempre na glória do eterno Sumo Sacerdote, que no céu intercede por nós diante de Deus. Da forma de servo de Jesus ressurgiu, na Páscoa, um novo corpo em forma e luz celestial. Mas quem quiser, segundo a promessa de Deus, participar da luz e da glória de Jesus deve, antes, ser conformado à imagem do Servo de Deus obediente e sofredor na cruz. Quem quiser carregar a imagem da glória de Jesus precisa, primeiro, ter carregado a imagem do Crucificado rejeitado no mundo. Ninguém reencontrará a imagem perdida de Deus senão tomando parte da forma do Jesus encarnado e crucificado. Deus só se agrada nessa imagem. Apenas quem for encontrado na conformidade a essa imagem viverá sob o agrado de Deus.

Ser conformado à imagem de Jesus Cristo não é um ideal a ser buscado, uma exigência à realização de uma semelhança com Cristo. Não somos nós que nos tornamos à imagem de Cristo, mas é a própria imagem de Cristo que quer tomar forma em nós (Gl 4.19) e manifestar-se em nós. Cristo não encerrará seu trabalho em nós até que nos tenha aperfeiçoado à sua imagem. Precisamos nos conformar à forma completa do Encarnado, Crucificado e Glorificado.

Cristo assumiu essa forma humana. Ele se fez humano como nós. Em sua humanidade e pequenez, reconhecemos nossa própria forma. Ele se tornou igual aos seres humanos para que os seres humanos se tornassem iguais a ele. Na encarnação de Cristo, toda a humanidade reencontra a dignidade da imagem de Deus. Assim, quem peca contra o menor dos seres humanos peca contra Cristo, que assumiu a forma humana e, em si, restaurou a imagem de Deus em todos que têm feição humana. Na comunhão do Encarnado, recuperamos nossa verdadeira humanidade. Somos libertos do isolamento resultante do pecado e, ao mesmo tempo, restabelecidos à humanidade plena. Por participar do Cristo encarnado, tomamos parte em toda a humanidade que ele tomou sobre si. Sabemos que, na humanidade de Cristo, fomos aceitos; por isso, nossa nova natureza consiste em que também carreguemos a angústia e a culpa dos outros. Aquele que se fez humano faz de seus discípulos irmãos de todos os seres humanos. A

“filantropia” de Deus (Tt 3.4) revelada na encarnação de Cristo é o fundamento do amor fraternal dos cristãos para com todos os seres humanos da terra. É a forma do Cristo encarnado que faz da Igreja o corpo de Cristo, sobre o qual recaem o pecado e a angústia de toda a humanidade e que os leva sobre si.

A forma terrena de Cristo é a forma da morte do Crucificado. A imagem de Deus é a imagem de Jesus Cristo na cruz. Nessa imagem a vida do discípulo deve ser transformada. É uma vida em conformidade com a morte de Cristo (Fp 3.10; Rm 6.4s). É uma vida crucificada (Gl 6.14). Cristo imprime, no batismo, a forma de sua morte na vida de seus discípulos. Morto para a carne e para o pecado, o cristão está morto para o mundo, e o mundo está morto para ele (Gl 6.14). Quem vive a partir do batismo vive a partir de sua morte. Cristo marca a vida dos discípulos pelo morrer diário na luta do espírito contra a carne, pelo sofrer diário das dores da morte que o diabo inflige ao cristão. Essa é a própria Paixão de Jesus Cristo, que todos os seus devem suportar na terra. Só a alguns poucos Cristo concede o privilégio do martírio,

que é a comunhão mais íntima de sua Paixão. Nesse caso, a vida do discípulo revela a mais profunda conformidade com a morte de Jesus Cristo. Na humilhação pública, no sofrimento e na morte por causa de Cristo, o próprio Cristo assume forma visível em sua Igreja. Contudo, é o mesmo sofrimento, a mesma morte, desde o batismo até o martírio. É a recriação da imagem de Deus por meio do Crucificado.

Quem permanece na comunhão do Cristo encarnado e crucificado, no qual tomou forma, também será igual ao Cristo ressurreto e glorificado. “Devemos trazer também a imagem do celestial” (1Co 15.49).

“Seremos semelhantes a ele, porque haveremos de vê-lo como ele é” (1Jo 3.2). Assim como se dá com a imagem do Crucificado, também a contemplação da imagem do Ressurreto nos transforma. Quem vê Cristo será atraído para sua imagem, se conformará a ela, se tornará espelho da imagem de Deus. Ainda nesta vida, a glória de Jesus Cristo se refletirá em nós. Desse corpo de morte do Crucificado, no qual vivemos em angústia e em cruz, brilharão a luz e a vida do Ressurreto, e cada vez mais se manifestará em nós a transformação na imagem de Deus, e cada vez mais a imagem de Cristo em nós ganhará nitidez. A vida será um progredir de conhecimento em conhecimento, de glória em glória, até chegar à conformidade cada vez mais completa com a imagem do Filho de Deus. “E todos nós, com o rosto desvendado, contemplando, como por espelho, a glória do Senhor, somos transformados, de glória em glória, na sua própria imagem, como pelo Senhor, o Espírito” (2Co 3.18).

Assim é a morada de Jesus Cristo em nosso coração. A vida terrena de Jesus Cristo ainda não acabou.

Cristo continua a viver na vida de seus discípulos. Portanto, em vez de falar de nossa vida cristã, tratemos da verdadeira vida de Jesus Cristo em nós. “Já não sou eu quem vive, mas Cristo vive em mim”

(Gl 2.20). O Encarnado, o Crucificado, o Glorificado fez morada em minha vida e nela habita.

“Porquanto, para mim, o viver é Cristo” (Fp 1.21). Com Cristo, o Pai mora em mim, e Pai e Filho por meio do Espírito Santo. É a própria Santíssima Trindade que fez morada no coração do cristão, preenchendo-o e moldando-o à sua imagem. O Cristo encarnado, crucificado e glorificado toma forma em cada cristão, porque são todos membros de seu corpo, a Igreja. A Igreja carrega a forma dos seres humanos, a forma da morte e da ressurreição de Cristo. Ela é, em primeiro lugar, sua imagem (Ef 4.24; Cl 3.10), e por meio dela também o são todos os seus membros. No corpo de Cristo nos tornamos “como Cristo”.

Agora é possível entender por que o Novo Testamento sempre volta a falar que devemos ser “como Cristo” ( kathos Christos). Porque somos feitos à imagem de Cristo, iguais a Cristo devemos ser. Porque já carregamos a imagem de Cristo, só Cristo pode ser o modelo que temos de seguir. Porque ele mesmo vive sua verdadeira vida em nós, podemos “andar assim como ele andou” (1Jo 2.6), fazer como ele fez (Jo 13.15), amar como ele amou (Ef 5.2; Jo 13.34; 15.12), perdoar como ele perdoou (Cl 3.13), ter “o mesmo sentimento que houve também em Jesus Cristo” (Fp 2.5), imitar os exemplos que ele nos deixou, dar a vida pelos irmãos como ele deu a vida por nós (1Jo 3.16). Só podemos ser como ele porque ele foi como nós. Só podemos ser “como Cristo”, porque fomos conformados à sua imagem. Agora que nos tornamos imagem de Cristo, podemos viver de acordo com seu exemplo. Aqui de fato obras são praticadas, aqui, na simplicidade do discipulado, a vida igual à de Cristo é vivida. Aqui ocorre a obediência simples à Palavra. Sobre a minha própria vida, sobre a minha nova imagem, não recai mais

nenhum olhar. Eu a perderia no mesmo momento em que a desejasse ver. Ela é apenas o espelho para a imagem de Jesus Cristo, na qual fixo meu olhar. O discípulo vê apenas aquele a quem segue. Aquele que, no discipulado, carrega a imagem do Cristo encarnado, crucificado e ressurreto, que foi feito imagem de Deus, dele pode-se finalmente dizer que foi chamado para ser “imitador de Deus”. O discípulo de Jesus é o imitador de Deus. “Sede, pois, imitadores de Deus, como filhos amados” (Ef 5.1).$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$O capítulo recusa a ideia de que ser conformado à imagem de Cristo seja um ideal que conquistamos: 'não somos nós que nos tornamos à imagem de Cristo, mas é a própria imagem de Cristo que quer tomar forma em nós'. Em que áreas você ainda tenta esculpir sozinho a sua própria semelhança com Cristo, pelo esforço, repetindo o gesto de Adão de querer ser 'como Deus' por conta própria?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Bonhoeffer afirma que ninguém carregará a imagem do Cristo glorificado sem antes ter carregado a imagem do 'Crucificado rejeitado no mundo', com suas marcas de sofrimento e humilhação. Que sofrimento, fraqueza ou rejeição que você gostaria de evitar pode estar sendo justamente o lugar onde a imagem de Cristo está sendo formada em você?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O texto diz que, porque Cristo assumiu a forma humana e nela restaurou a imagem de Deus, 'quem peca contra o menor dos seres humanos peca contra Cristo', e que nossa nova natureza é carregar 'a angústia e a culpa dos outros'. Quem são as pessoas 'menores' diante de quem você tem dificuldade de reconhecer a imagem de Cristo, e o que significaria carregar o peso delas como Cristo carregou o seu?$p$, 'reflexao', null);
  end if;

end $migration$;
